// Content for Mind & Belonging (node g49, ages 18-22, Chapter 6): NEW v2 build to GDD 49 (mechanic-embodying),
// the College wellbeing anchor (Thread C · Feelings & Life Skills). Reworks the old ModesEngine build onto the
// shared v2 engine. "Leaving home is exciting and lonely and hard; look after your mind, find your people, and
// know that asking for help is the strong move." 84 researched, India-grounded scenarios across settling-in →
// find-your-people → cope-well → mind-and-self-worth → reach-out → tools-and-help, each encoded as one of the
// shared v2 play actions (branch / strike-rewrite / sort / reflect / role-play / spot / match): no binary "tap
// the right card". Lead: branch (your move), strike-rewrite (bust the myth), sort. Five themes: settling in
// (homesickness/loneliness normalised), find your people (belonging is built), cope well (HEALTHY coping ONLY,
// body image & self-worth), reach out (help = strength; UN&RE), tools & crisis routing. HIGH-CARE: any sign of
// distress is met with warmth and an immediate route to help, never assessment questions; only healthy coping (no
// strategy using pain, restriction or shock; nothing reinforcing self-harm); anti-stigma, NOT therapy; persistent
// or serious distress is pointed to professionals. Even-handed; stigma is especially heavy on young men. India:
// academic pressure, hostel isolation, far from home, family expectations; Tele-MANAS 14416 (primary),
// campus counsellors, a trusted person. Builds on g39 (Bounce), continues g42 (Life Ready); pairs
// g48 and g52; underpins every College node. gameId "mind-belonging".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"mb-001","cat":"settling-in","type":"strike-rewrite","hook":"\"Feeling homesick and lonely means something's wrong with me.\"","myth":{"un":"Homesickness and loneliness mean something's wrong with me.","re":"They're common, normal reactions to a big change, not weakness.","why":"Almost everyone feels this leaving home."},"relearn":"Homesickness and loneliness are normal reactions to a big change, not weakness.","persona":"any","source":"normalising"},
  {"id":"mb-002","cat":"settling-in","type":"reflect","hook":"Lensy: the first months after leaving home are bumpy for almost everyone. Does knowing that ease it a bit?","prompt":"What do you think?","options":["Yes","I'm not alone","It eases it"],"affirm":"You're far from alone in finding it hard; that shared truth makes it lighter.","relearn":"The first months after leaving home are bumpy for almost everyone.","persona":"any","source":"shared experience"},
  {"id":"mb-003","cat":"settling-in","type":"branch","persona":"Deepak","source":"early wobble","hook":"You're a few weeks into college in a new city, and you feel low and out of place.","steps":[{"prompt":"Walking back alone after class, you wonder if coming here was a mistake. What do you tell yourself?","options":[{"text":"I've failed. I should just go home","then":"The thought sits heavy all evening, and you start looking at bus times."},{"text":"Everyone else fits in. It's only me","then":"You watch groups laughing in the corridor and feel smaller."},{"text":"It's early. Weeks like this are part of settling","then":"The knot loosens a little. You decide to give it more time.","best":true},{"text":"Push it down and stay busy so I don't feel it","then":"You fill the evening with reading. The low feeling waits for bedtime."}],"why":"A hard first month is common. Giving it time keeps you from deciding in the low."},{"prompt":"Seniors from your department host a chai meet for first-years on Saturday. What do you do?","options":[{"text":"Skip it. You'll only feel even more out of place there","then":"Saturday passes in your room, and the out-of-place feeling grows."},{"text":"Go, and ask a senior how their first month went","then":"A senior laughs. \"I nearly went home in week three. Now look at me.\"","best":true},{"text":"Go, but leave before anyone talks to you","then":"You slip out after ten minutes, chai half-drunk."},{"text":"Go only if a classmate comes with you","then":"No one else is going, so you stay back."}],"why":"Hearing that others found it hard too loosens the 'only me' feeling."},{"prompt":"Your first test marks come back lower than you hoped. What do you tell yourself?","options":[{"text":"People like me don't belong here","then":"The thought follows you into every class that week."},{"text":"Hide the marks and never mention them","then":"The marks stay secret, and so does the worry."},{"text":"I'll just study much harder, alone, until it's fixed","then":"You study late every night, and the same topics still confuse you."},{"text":"It's a first test in a new place. I'll ask for help","then":"Your tutor offers a Friday doubt session, and three others turn up too.","best":true}],"why":"One low mark doesn't prove you don't belong. Asking for help is how you catch up."},{"prompt":"The weekend stretches empty ahead of you. What do you plan?","options":[{"text":"A call home, and a walk with a classmate","then":"The call steadies you, and the walk ends at a samosa stall.","best":true},{"text":"Nothing. Just see how you feel","then":"The weekend drifts, and Monday arrives heavy."},{"text":"Study every hour to prove you belong","then":"You finish two chapters and feel lonelier than ever."},{"text":"A long call home, then stay in the rest of the time","then":"You feel close to home for an hour, then far from everyone again."}],"why":"A routine that mixes home and new people helps you settle."},{"prompt":"A month later, the pull to go home comes back on a bad day. What do you do?","options":[{"text":"Take it as proof that you just don't belong here","then":"The thought follows you around all week."},{"text":"Pack a bag and leave that night","then":"You're on the night bus before you've talked it over with anyone."},{"text":"Tell a friend it's a bad day, and keep your routine","then":"Your friend walks with you to the mess. The bad day stays a bad day, not a verdict.","best":true},{"text":"Ignore it and bury yourself in extra study all week","then":"You study till 2 a.m. The pull home is still there at breakfast."}],"why":"A bad day is part of settling. Routine and connection carry you through it."}],"debrief":"A rough early patch is part of settling in. Routine and connection usually turn it around.","relearn":"Give settling time. Build routine and reach out before you quit."},
  {"id":"mb-004","type":"sort","hook":"Sort: a normal part of settling in, or a real signal to reach for help?","items":[{"id":"a","text":"Missing home and family"},{"id":"b","text":"Low mood that's heavy for weeks"},{"id":"c","text":"Taking time to make friends"},{"id":"d","text":"Losing all interest in everything"},{"id":"e","text":"A few homesick evenings"},{"id":"f","text":"Can't sleep or eat for weeks"}],"bins":[{"id":"normal","label":"Normal-ish","valence":"pos"},{"id":"act","label":"Reach for help","valence":"tell"}],"key":{"a":"normal","b":"act","c":"normal","d":"act","e":"normal","f":"act"},"relearn":"Missing home and slow friend-making are normal; weeks of heavy low mood or losing all interest is a signal to reach for help.","persona":"any","source":"normal vs signal","cat":"settling-in"},
  {"id":"mb-005","type":"spot","hook":"Spot the two unhealthy ways through a homesick evening.","relearn":"Ease homesickness by connecting and planning one small next thing.","persona":"any","source":"homesickness","scene":[{"id":"a","text":"Calling someone from home","trick":false},{"id":"b","text":"Sitting alone with it all night","trick":true},{"id":"c","text":"Planning one small thing for tomorrow","trick":false},{"id":"d","text":"Skipping dinner and the group plan","trick":true},{"id":"e","text":"Stepping out for a short walk","trick":false}],"why":"Connecting, a walk and a small next step ease homesickness; sitting alone all night or skipping food and people don't.","cat":"settling-in"},
  {"id":"mb-006","cat":"settling-in","type":"reflect","hook":"Lensy: it's okay to find this hard and exciting at the same time. Can both be true for you?","prompt":"What do you think?","options":["Yes","Both at once","That's me"],"affirm":"Big transitions are usually both hard and exciting; holding both is completely normal.","relearn":"Leaving home can be hard and exciting at once, and that's normal.","persona":"any","source":"both true"},
  {"id":"mb-007","cat":"settling-in","type":"strike-rewrite","hook":"\"Everyone else has settled in fine; only I'm struggling.\"","myth":{"un":"Everyone else has settled in fine; only I'm struggling.","re":"Most people are finding it hard too, quietly; the confident faces hide it.","why":"You're comparing your insides to their outsides."},"relearn":"Most people are quietly struggling with the transition too; you're not alone in it.","persona":"any","source":"comparison"},
  {"id":"mb-008","type":"sort","hook":"Sort: helps you settle, or deepens the slump?","items":[{"id":"a","text":"A daily rhythm and some structure"},{"id":"b","text":"Staying in your room for days"},{"id":"c","text":"One small social step a day"},{"id":"d","text":"Doomscrolling till dawn"},{"id":"e","text":"A regular sleep and meal time"},{"id":"f","text":"Skipping every invite that comes"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"deepens","label":"Deepens it","valence":"neg"}],"key":{"a":"helps","b":"deepens","c":"helps","d":"deepens","e":"helps","f":"deepens"},"relearn":"Routine and small social steps help you settle; isolating and doomscrolling deepen the slump.","persona":"any","source":"settling habits","cat":"settling-in"},
  {"id":"mb-009","cat":"settling-in","type":"reflect","hook":"Lensy: settling in is a process, not a switch; you're allowed to find your feet slowly. Okay?","prompt":"What do you think?","options":["Yes","Slowly is fine","A process"],"affirm":"Finding your feet at your own pace is completely valid; there's no deadline on belonging.","relearn":"Settling in is a gradual process; finding your feet slowly is fine.","persona":"any","source":"your pace"},
  {"id":"mb-010","cat":"settling-in","type":"branch","persona":"any","source":"catching isolation","hook":"Between classes and a pile of reading, you realise you've barely spoken to anyone in days.","steps":[{"prompt":"You notice it on Sunday night, alone in your room. What do you tell yourself?","options":[{"text":"I'm just not a people person. Fine","then":"The label feels final. You put your phone face down."},{"text":"I've drifted a bit. That's fixable","then":"The thought feels lighter than you expected. You pick up your phone.","best":true},{"text":"Something must be wrong with me","then":"Your chest tightens, and the room feels quieter than before."},{"text":"It's only a busy patch. It'll sort itself out","then":"You nod to yourself and open the reading again. The silence carries on."}],"why":"Noticing it kindly makes the next small step feel possible."},{"prompt":"On Monday, Nisha from your class is in the mess queue behind you. What do you do?","options":[{"text":"Put your earphones in and wait quietly","then":"The queue moves. You eat alone again, a table apart."},{"text":"Smile, then look at your phone so it's not awkward","then":"Nisha smiles back, then turns to her friend."},{"text":"Ask her how the reading's going for her","then":"Nisha groans. \"Terrible. Want to sit together and moan about it?\"","best":true},{"text":"Wait for her to talk to you first","then":"She doesn't. She's scrolling, as quiet as you."}],"why":"A small, simple opener is often all it takes to break a quiet stretch."},{"prompt":"It's Thursday, and your evenings are still mostly quiet. What's your next step?","options":[{"text":"Plan to fix your social life over the break","then":"The break is weeks away. The quiet settles in again."},{"text":"Join three clubs at once to make up for it","then":"The first meeting is fun. By the third, you're too tired to go."},{"text":"Decide this is just how college is for you","then":"The days blur together, and you stop noticing the quiet."},{"text":"Text one person to grab tea this week","then":"The friend you text replies within a minute: \"Tomorrow, 5? Canteen.\"","best":true}],"why":"Catching the drift early and acting small keeps isolation from settling in."}],"debrief":"Catching isolation early and taking a small step protects your wellbeing.","relearn":"If you've gone quiet for days, notice it kindly and take one small step to connect."},
  {"id":"mb-011","cat":"find-your-people","type":"strike-rewrite","hook":"\"You either click with people or you don't; belonging just happens.\"","myth":{"un":"Belonging just happens or it doesn't.","re":"Belonging is built, by reaching out, joining things and showing up, not waiting.","why":"Connections grow from small, repeated effort."},"relearn":"Belonging is built by reaching out and showing up, not waiting for it to happen.","persona":"any","source":"belonging is built"},
  {"id":"mb-012","cat":"find-your-people","type":"branch","persona":"any","source":"showing up","hook":"The photography club meets on Thursday. You'd love to go, but going alone feels scary.","steps":[{"prompt":"Thursday comes, and none of your friends want to go with you. What do you do?","options":[{"text":"Skip it to avoid the awkwardness","then":"The evening is easy and empty. Later you scroll the club's page, wondering."},{"text":"Go anyway. Most people there once felt the same","then":"Your stomach flips at the door. Inside, three others are hovering awkwardly too.","best":true},{"text":"Wait until a friend is free to come with you","then":"Two weeks pass. Nobody's free, and the club feels harder to walk into."},{"text":"Check their Instagram first to see if you'd fit","then":"Everyone looks close already. Going feels even scarier now."}],"why":"Showing up despite the nerves is how belonging starts. Most people there felt the same once."},{"prompt":"A few days later Anjali, a classmate in the club, mentions their Sunday photo walk. What do you do?","options":[{"text":"Say you're busy. Maybe next time","then":"Anjali nods. \"Sure. It's open to anyone, any week.\""},{"text":"Ask if everyone there already knows each other","then":"\"Some do,\" Anjali says. You still haven't said whether you'll come."},{"text":"Say \"cool\" and hurry off to class","then":"Anjali waves. You're round the corner before she can say more."},{"text":"Say you'd like to come, and ask the time","then":"\"Seven, at the main gate,\" Anjali says. \"Bring any phone.\"","best":true}],"why":"Saying yes and asking a practical question turns a mention into a real invitation."},{"prompt":"On Sunday morning the club posts that the walk starts in an hour, and your stomach knots. What do you do?","options":[{"text":"Go, and tell someone it's your first walk","then":"People show you their favourite spots. The nerves fade by the second street.","best":true},{"text":"Stay in bed. You'll try another week","then":"The morning is cosy. The club's photos go up that evening without you."},{"text":"Go, but leave if nobody talks to you in five minutes","then":"You watch the clock more than the street and slip away early."},{"text":"Send an excuse and go back to sleep","then":"You feel relief, then a small, familiar ache."}],"why":"Going, and being honest that it's your first time, lets people welcome you in."},{"prompt":"A month later, you still feel like an outsider at college sometimes. What do you tell yourself?","options":[{"text":"I'm just not a club person","then":"The thought closes a door. The noticeboard stops catching your eye."},{"text":"Almost everyone feels this at first. Keep showing up","then":"The feeling doesn't vanish, but it stops deciding for you.","best":true},{"text":"Everyone else fits in, so it must be me","then":"You hang back a little more each week."},{"text":"I'll try properly next semester, when I'm less busy","then":"Next semester feels safely far away. So does belonging."}],"why":"Almost everyone feels like an outsider at first. Showing up again is how it changes."}],"debrief":"Showing up to things, even nervously, is the main way belonging gets built.","relearn":"Show up to groups even when it's scary. That's how belonging grows."},
  {"id":"mb-013","cat":"find-your-people","type":"role-play","persona":"any","source":"reaching out first","hook":"Tara from your tutorial seems like someone you'd get on with, but you've never really talked.","setup":"Today she's alone in the canteen queue, just ahead of you.","steps":[{"prompt":"Tara turns and says: \"This queue is endless. Is it always like this?\"","options":[{"text":"\"Ha, yeah. We should hang out sometime.\"","then":"\"Sure, sometime!\" She takes her tray to a table of friends."},{"text":"\"Always. Mind if I sit with you? I'm new here.\"","then":"\"Oh, same! Yes, please.\" She waits while you get your plate.","best":true},{"text":"\"Always. Anyway, I'll let you get your food.\"","then":"\"Oh. Okay, bye.\" She finds a seat by the window, alone."},{"text":"\"Honestly, this whole college is a mess.\"","then":"Tara laughs uncertainly. \"Ha. I guess.\""}],"why":"A simple, warm ask to sit together turns a queue chat into a real start."},{"prompt":"At the next tutorial, Tara says: \"Did you get question three? I'm totally lost.\"","options":[{"text":"\"Easy. It's the formula on page ten.\"","then":"\"Oh. Right.\" She scribbles it down and turns back to her notes."},{"text":"\"No idea either. All the best!\"","then":"Tara laughs. \"Thanks, I'll need it.\" The chat ends there."},{"text":"\"Partly. Want to work it out together?\"","then":"\"Yes! Library at four?\" She writes it on her hand.","best":true},{"text":"\"I'm not really a study-with-people person.\"","then":"\"Fair enough,\" she says, and asks the person behind her."}],"why":"Suggesting something together gives a new connection a reason to keep going."},{"prompt":"A week later, Tara says: \"I'm going to the film club screening tonight. Ever been?\"","options":[{"text":"\"Maybe. Text me if you remember.\"","then":"\"Sure, if I remember,\" she says. She doesn't."},{"text":"\"No. Films with strangers aren't really my thing.\"","then":"\"Fair,\" Tara says. \"Next time, maybe.\""},{"text":"\"Never. Could I come with you?\"","then":"\"Of course! Meet at the gate at seven.\"","best":true},{"text":"\"I'd love to, but I'd just be tagging along.\"","then":"\"Oh, okay,\" Tara says, not sure whether to insist."}],"why":"Asking to come along is a small, direct step from classmate to friend."}],"relearn":"A simple, warm opener is enough to start a connection."},
  {"id":"mb-014","cat":"find-your-people","type":"sort","hook":"Sort: builds belonging, or keeps you isolated?","items":[{"id":"a","text":"Saying yes to an invite"},{"id":"b","text":"Turning everything down"},{"id":"c","text":"Joining a shared-interest group"},{"id":"d","text":"Waiting to be chosen"},{"id":"e","text":"Asking someone to grab chai"},{"id":"f","text":"Skipping plans to avoid awkwardness"}],"bins":[{"id":"builds","label":"Builds belonging","valence":"pos"},{"id":"isolates","label":"Isolates","valence":"neg"}],"key":{"a":"builds","b":"isolates","c":"builds","d":"isolates","e":"builds","f":"isolates"},"relearn":"Saying yes, joining groups and reaching out build belonging; turning things down, waiting and avoiding isolate.","persona":"any","source":"belonging moves"},
  {"id":"mb-015","cat":"find-your-people","type":"reflect","hook":"Lensy: one or two real connections matter more than a big crowd. Take the pressure off?","prompt":"What do you think?","options":["Yes","Quality over crowd","A relief"],"affirm":"You don't need to be popular; a couple of genuine connections is what really helps.","relearn":"One or two real connections matter more than a big crowd.","persona":"any","source":"quality not quantity"},
  {"id":"mb-016","cat":"find-your-people","type":"branch","persona":"Deepak","source":"it takes time","hook":"Six weeks into college, you feel like the only one without a friend group yet.","steps":[{"prompt":"Walking past the canteen, you see groups laughing at every table. What do you tell yourself?","options":[{"text":"Everyone's cliqued up already, without me","then":"You walk faster, eyes down, and eat in your room."},{"text":"People like me don't fit in places like this","then":"The thought feels old and familiar. It follows you all afternoon."},{"text":"It takes time. Most of them only just met","then":"The sting eases. You notice two people eating alone as well.","best":true},{"text":"I'll sort out friends once exams are over","then":"It feels like a plan. It also means another month on your own."}],"why":"Friend groups form over time. You're not behind, and you're not the only one."},{"prompt":"In class the next day, Harsh, sitting beside you, sighs at the same confusing slide. What do you do?","options":[{"text":"Stay quiet. He probably has his own friends","then":"Class ends. Harsh leaves, and so does the moment."},{"text":"Smile at him, but say nothing","then":"He smiles back, then packs up and goes."},{"text":"Pretend you've understood it","then":"Harsh nods and turns away. You're both still lost."},{"text":"Say you're lost too, and offer to compare notes","then":"Harsh grins. \"Yes, please. I thought it was just me.\"","best":true}],"why":"A simple, warm opener is enough to start a connection."},{"prompt":"At the weekend, your hostel floor plans a cricket match, and you've barely played. What do you do?","options":[{"text":"Go, and offer to field or keep score","then":"You drop one catch and take one. People start calling you by name.","best":true},{"text":"Stay in. You'd only embarrass yourself","then":"You hear the shouts from your window. On Monday they share a story you weren't in."},{"text":"Go and watch from the steps, not joining in","then":"It's fun to watch. Nobody quite knows you're part of it."},{"text":"Say you have to study","then":"The floor is empty all afternoon, and so is your weekend."}],"why":"Saying yes to shared things is how you go from a face to a friend."},{"prompt":"The next week, you still don't have a set group like others seem to. What do you do?","options":[{"text":"Give up trying. It's not happening","then":"The next few invites go unanswered, and they slowly stop coming."},{"text":"Keep gently saying yes and reaching out","then":"A classmate texts about a movie. Someone from your floor saves you a seat at lunch.","best":true},{"text":"Try to get into the most popular group fast","then":"They're friendly enough, but you feel like you're auditioning."},{"text":"Spend your evenings on calls with school friends only","then":"The calls are warm. The new city stays unfamiliar."}],"why":"Belonging builds slowly through small, repeated contact. Keep going."},{"prompt":"At the end of the semester you count the people you really talk to: two or three. What do you tell yourself?","options":[{"text":"I've failed if I don't have a big group","then":"You scroll other people's group photos and feel small."},{"text":"I need to be more fun to get more friends","then":"You start planning how to act differently. It already feels tiring."},{"text":"I'll wait and see if these ones last first","then":"You hold back a little, and the warmth stays at arm's length."},{"text":"A few real friends is plenty for now","then":"The pressure lifts. You plan chai with them before the break.","best":true}],"why":"One or two real connections matter more than a big crowd."}],"debrief":"Friendships take time to form. Persistence and openness win out.","relearn":"Friend groups take time. Keep gently reaching out: you're not behind."},
  {"id":"mb-017","cat":"find-your-people","type":"role-play","persona":"any","source":"mutual reaching","hook":"In your first week, a classmate, Imran, looks as lost and alone as you feel.","setup":"The orientation talk has just ended.","steps":[{"prompt":"By the notice board, Imran sighs and says: \"I can't even find where my next class is.\"","options":[{"text":"\"Rooms are on the map by the gate.\"","then":"\"Oh, thanks,\" he says, and walks off to look."},{"text":"\"Don't worry. Everyone figures it out eventually.\"","then":"\"Hope so,\" Imran mutters, still staring at the board."},{"text":"\"Same here. Want to figure it out together?\"","then":"His shoulders drop. \"Yes. Please. I've been circling for ten minutes.\"","best":true},{"text":"\"Ha. All the best with that.\"","then":"Imran gives a weak smile and turns back to the board."}],"why":"Naming the shared feeling and offering company helps you both feel less alone."},{"prompt":"Next day, Imran sits beside you and says: \"I thought everyone else already had friends here.\"","options":[{"text":"\"Yeah, people here are pretty cliquey.\"","then":"His face falls. \"Great. So it's not just in my head.\""},{"text":"\"Me too. I think most of us are pretending.\"","then":"Imran laughs, relieved. \"Oh, thank god. I thought it was only me.\"","best":true},{"text":"\"Not me. I've already made loads.\"","then":"\"Oh. Nice.\" Imran goes quiet and looks at his phone."},{"text":"\"Just join a few clubs and you'll be fine.\"","then":"\"Maybe,\" he says, not sounding convinced."}],"why":"Saying honestly that you feel it too tells him he's not the only one."},{"prompt":"Imran says: \"I miss my friends from home so much it's embarrassing.\"","options":[{"text":"\"You'll get over it in a week or two.\"","then":"\"Hope so,\" he says quietly, and changes the subject."},{"text":"\"At least you have friends back home.\"","then":"Imran looks unsure how to answer. \"I guess.\""},{"text":"\"Plan a trip home soon. That'll fix it.\"","then":"\"Maybe,\" he says. \"That's weeks away, though.\" He heads off alone."},{"text":"\"It's not embarrassing. I miss mine too. Chai?\"","then":"Imran grins. \"Chai. Yes. Now.\"","best":true}],"why":"Normalising the feeling and offering chai turns shared homesickness into connection."},{"prompt":"A week later, Imran says: \"There's a hostel quiz on Friday. Want to be a team?\"","options":[{"text":"\"Maybe, if I finish my assignment in time.\"","then":"\"Okay, let me know,\" he says. He sounds like he won't wait long."},{"text":"\"Yes. I'm in.\"","then":"\"Yes! I'll sign us up.\" He's already typing the team name.","best":true},{"text":"\"I'm terrible at quizzes. You go ahead.\"","then":"\"Oh. Okay,\" he says, and asks someone else."},{"text":"\"Only if you're sure I won't slow you down.\"","then":"Imran hesitates. \"Only if you want to.\" It's suddenly unclear."}],"why":"A clear yes when someone reaches back is how a friendship takes root."}],"relearn":"Reaching out to someone else who's struggling helps you both belong."},
  {"id":"mb-018","cat":"find-your-people","type":"sort","hook":"Sort: a genuine way to build connection, or a false shortcut?","items":[{"id":"a","text":"Showing up regularly to something"},{"id":"b","text":"Only connecting online, never in person"},{"id":"c","text":"Being genuinely interested in people"},{"id":"d","text":"Trying to impress with a fake persona"},{"id":"e","text":"Following up after a good chat"},{"id":"f","text":"Chasing a follower count as proof you're liked"}],"bins":[{"id":"genuine","label":"Genuine","valence":"pos"},{"id":"false","label":"False shortcut","valence":"neg"}],"key":{"a":"genuine","b":"false","c":"genuine","d":"false","e":"genuine","f":"false"},"relearn":"Showing up, real interest and following up build connection; online-only, a fake persona or chasing followers don't.","persona":"any","source":"genuine connection"},
  {"id":"mb-019","cat":"find-your-people","type":"branch","persona":"Zoya","source":"investing","hook":"You've found a small writing circle where, for once, you feel really seen.","steps":[{"prompt":"The circle meets again on Friday, the same night as a big hostel party. What do you do?","options":[{"text":"Go to the party. The circle can wait a few weeks","then":"The party's loud and fun. When you return, the circle feels a little less like yours."},{"text":"Go to the circle. It's where you feel like you","then":"Someone has saved you a chair. You stay an hour longer than planned.","best":true},{"text":"Skip both and stay in","then":"The evening is quiet. On Monday the circle's chat is full of jokes you missed."},{"text":"Go, but stay quiet in case it doesn't last","then":"You listen from the edge. Afterwards, nobody quite knows what you think."}],"why":"Showing up consistently where you feel seen is what turns it into real belonging."},{"prompt":"A member, Noor, asks if you'd like to share a piece next week. What do you do?","options":[{"text":"Say no. You're not good enough yet","then":"Noor nods, and the spot goes to someone else."},{"text":"Say maybe, and hope she forgets","then":"Noor doesn't forget. She asks again, and you hedge again."},{"text":"Say yes, even though it feels exposing","then":"Noor beams. \"Lovely. We're gentle, promise.\"","best":true},{"text":"Say yes, then bring something you don't care about","then":"The feedback is polite. It doesn't touch anything real."}],"why":"Letting people see a little more of you is how belonging deepens."},{"prompt":"A month in, the circle feels like a second home, but exams are piling up. What do you do?","options":[{"text":"Drop it until exams are over","then":"Six weeks pass. Coming back feels like starting again."},{"text":"Skip it, then feel guilty all evening","then":"You neither study well nor rest."},{"text":"Quit. It was only a hobby anyway","then":"Fridays go quiet. You miss it more than you expected."},{"text":"Keep going, even if only for an hour","then":"The hour recharges you, and you study better that night.","best":true}],"why":"Keeping up what makes you feel seen, even in small doses, protects your wellbeing."}],"debrief":"When you find your people, showing up consistently is what turns it into real belonging.","relearn":"When you find a community that fits, invest in it and keep showing up."},
  {"id":"mb-020","cat":"find-your-people","type":"reflect","hook":"Lensy: reaching out first is brave, and most people are quietly hoping someone will. Worth being that someone?","prompt":"What do you think?","options":["Yes","I'll reach first","Be that someone"],"affirm":"Being the one who reaches out first is a quiet act of courage that helps everyone.","relearn":"Reaching out first is brave, and most people are hoping someone will.","persona":"any","source":"reach first"},
  {"id":"mb-021","cat":"cope-well","type":"strike-rewrite","hook":"\"Powering through by skipping sleep, food and breaks is coping.\"","myth":{"un":"Powering through by skipping sleep, food and breaks is coping.","re":"That drains you; real coping rests, eats, moves, connects and takes breaks.","why":"You can't pour from an empty cup."},"relearn":"Real coping rests, eats, moves and takes breaks; powering through on empty isn't coping.","persona":"any","source":"healthy coping"},
  {"id":"mb-022","cat":"cope-well","type":"sort","persona":"any","source":"coping toolkit","hook":"Drop each into Healthy coping or Drains you.","items":[{"id":"a","text":"A walk, sleep and talking to someone"},{"id":"b","text":"Numbing it out for hours"},{"id":"c","text":"Breathing and a short break"},{"id":"d","text":"Bottling it all up alone"},{"id":"e","text":"A proper meal and some water"},{"id":"f","text":"Skipping sleep to power through"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"drains","label":"Drains you","valence":"neg"}],"key":{"a":"healthy","b":"drains","c":"healthy","d":"drains","e":"healthy","f":"drains"},"relearn":"Movement, sleep, talking, breathing, meals and breaks are healthy coping; numbing, bottling up and skipping sleep drain you."},
  {"id":"mb-023","cat":"cope-well","type":"branch","persona":"any","source":"stress management","hook":"Your project is due Friday, and the stress has built until it all feels like too much.","steps":[{"prompt":"It's Tuesday night and you can't think where to begin. What do you do?","options":[{"text":"Open everything at once and push through till late","then":"By 2 a.m. you've touched every part and finished none. Your chest feels tight."},{"text":"List the parts and start the smallest one","then":"The project turns into six pieces. The first one looks almost manageable.","best":true},{"text":"Make a detailed colour-coded plan for the whole week","then":"The plan looks beautiful. An hour has gone, and nothing on it is started."},{"text":"Leave it till tomorrow when you'll feel fresher","then":"You sleep badly. Wednesday starts with the same knot and one day less."}],"why":"Small pieces turn one huge task into doable steps, which eases the stress right away."},{"prompt":"Wednesday afternoon, you've been at your desk for three hours and your focus is gone. What do you do?","options":[{"text":"Keep going. Breaks are for after it's done","then":"You reread the same paragraph four times. The words stop meaning anything."},{"text":"Take a quick break scrolling your phone","then":"Ten minutes becomes forty. You come back more scattered than before."},{"text":"Stretch, drink water and walk for ten minutes","then":"You come back to the desk with your head a little clearer.","best":true},{"text":"Switch to a different part of the project","then":"The new part is just as hard. Now two things sit half-done."}],"why":"A short break that moves your body resets focus. Grinding on empty or scrolling doesn't."},{"prompt":"On Thursday a friend says the project is worth more marks than you thought, and your heart starts racing. What do you do first?","options":[{"text":"Work out your marks to see how bad it could get","then":"The sums slide into worst cases. Your heart keeps racing."},{"text":"Tell yourself to stop being dramatic and work","then":"You push the panic down. It hums under every sentence you write."},{"text":"Ask your friend to check your whole project tonight","then":"Your friend can't check a whole project tonight. Your heart is still racing."},{"text":"Slow your breathing for a minute before anything else","then":"Your heartbeat eases. The marks are the same, but you can think again.","best":true}],"why":"A minute of slow breathing calms the stress response so you can act, not spiral."},{"prompt":"It's midnight before the deadline and one section is still rough. What do you do?","options":[{"text":"Stay up all night so every part is perfect","then":"By dawn you're rewriting good parts badly. You submit, foggy and shaky."},{"text":"Sleep, then fix that section in the morning","then":"You wake at seven, fix the section in an hour and submit on time.","best":true},{"text":"Submit it now as it is and stop thinking about it","then":"Relief lands, then regret. The rough section had an easy fix."},{"text":"Make strong coffee and push on till four","then":"You finish at four, wired and unable to sleep. The morning is a blur."}],"why":"Rest makes the last fix faster and better than panicked hours on no sleep."}],"debrief":"Chunking a task, breathing and short breaks calm the stress response and actually help you perform.","relearn":"Manage overwhelm by breaking it down, breathing and taking short breaks."},
  {"id":"mb-024","cat":"cope-well","type":"branch","persona":"any","source":"low mood","hook":"A low mood has settled over you for a few days, and everything feels flat.","steps":[{"prompt":"Your alarm goes off for a morning class you usually like. What do you do?","options":[{"text":"Stay in bed. You'll catch up when you feel better","then":"The day slips past in your room. By evening you feel flatter."},{"text":"Go, but sit at the back and talk to no one","then":"You get through it unseen. On the walk back, the flatness feels heavier."},{"text":"Get up, eat something and go, even slowly","then":"The class is a blur, but being around people takes a small edge off.","best":true},{"text":"Skip class and study alone in your room instead","then":"You read the same page for an hour. The heaviness stays put."}],"why":"Keeping the basics going, even slowly, gives a low mood less room to grow."},{"prompt":"That evening your roommate Kabir asks if you want to get dinner. What do you do?","options":[{"text":"Go, but act cheerful so he doesn't worry","then":"Dinner is easy enough. Pretending leaves you more tired than before."},{"text":"Go, and mention you've been feeling low","then":"Kabir nods. \"Same for me last month. Want to walk after?\"","best":true},{"text":"Say you're not hungry and stay in","then":"Kabir leaves. The room goes quiet, and the evening stretches out."},{"text":"Ask him to bring something back for you","then":"He brings you a plate. You eat alone, grateful and a little lonelier."}],"why":"Eating with someone and letting them in a little keeps you fed and connected."},{"prompt":"A few more days pass. You've been sleeping at odd hours and barely moving. What do you do?","options":[{"text":"Wait for your mood to lift, then fix your routine","then":"The odd hours carry on. Mornings get harder to face."},{"text":"Set a regular bedtime and take a short daily walk","then":"The first two nights are restless. By the fourth, sleep comes a bit easier.","best":true},{"text":"Start an intense daily workout to snap out of it","then":"You manage one hard session, then feel too drained to go back."},{"text":"Nap in the afternoons to make up the sleep","then":"The naps leave you groggy, and your night-time sleep drifts later still."}],"why":"Steady sleep and gentle movement support your mood. You don't need to feel better first."},{"prompt":"Two weeks in, the low feeling is still heavy and constant. What do you do?","options":[{"text":"Keep going quietly. Others have it worse","then":"You carry on. The weight stays, and so does the silence."},{"text":"Search your symptoms online late at night","then":"The results leave you more worried, and still alone with it."},{"text":"Wait until the semester break to deal with it","then":"The weeks until the break start to feel very long."},{"text":"Tell someone you trust and call Tele-MANAS 14416","then":"A calm voice listens without rushing, and you agree on one next step.","best":true}],"why":"When a low mood lasts weeks, reaching real support today is the strong move."}],"debrief":"Holding the basics and reaching out gently are the healthy responses to a low patch.","relearn":"In a low mood, keep up sleep, food and movement, and talk to someone."},
  {"id":"mb-025","cat":"cope-well","type":"spot","persona":"any","source":"healthy strategies","hook":"Spot the two that drain you, not the healthy coping.","scene":[{"id":"a","text":"A few slow breaths and a short walk","trick":false},{"id":"b","text":"Skipping meals to 'save time'","trick":true},{"id":"c","text":"Texting a friend when it's heavy","trick":false},{"id":"d","text":"Pulling an all-nighter to push on","trick":true},{"id":"e","text":"An early night before a big day","trick":false}],"why":"Skipping meals and all-nighters drain you; breathing, walking, reaching out and sleep are healthy coping.","relearn":"Breathing, walking, reaching out and sleep are healthy coping; skipping meals or all-nighters aren't."},
  {"id":"mb-026","cat":"cope-well","type":"sort","persona":"any","source":"wellbeing balance","hook":"Drop each into Tops it up or Runs it down.","items":[{"id":"a","text":"Regular sleep"},{"id":"b","text":"Constant comparison online"},{"id":"c","text":"Moving your body"},{"id":"d","text":"Isolating when low"},{"id":"e","text":"Time with people you like"},{"id":"f","text":"Bottling everything up"}],"bins":[{"id":"tops","label":"Tops it up","valence":"pos"},{"id":"runs","label":"Runs it down","valence":"neg"}],"key":{"a":"tops","b":"runs","c":"tops","d":"runs","e":"tops","f":"runs"},"relearn":"Sleep, movement and time with people top up wellbeing; comparison, isolating and bottling up run it down."},
  {"id":"mb-027","cat":"cope-well","type":"branch","persona":"any","source":"self-compassion","hook":"Lately when things go wrong, you shut yourself away and call yourself useless.","steps":[{"prompt":"You get a lab report back with a low mark. What do you do?","options":[{"text":"Go to your room and list every mistake you made","then":"The list grows. So does the feeling that you're useless."},{"text":"Admit it stings, then message a friend from the lab","then":"Your friend replies fast. Her mark was low too, and she has questions.","best":true},{"text":"Tell yourself you deserve to feel bad about it","then":"The heavy feeling settles in for the night, and the report stays unread."},{"text":"Push it away and act like it doesn't matter","then":"It works for an hour. Then it comes back when you're alone."}],"why":"Naming the sting and reaching out beats hiding away with a harsh inner voice."},{"prompt":"That weekend a friend invites you to a movie, and the old urge to stay in rises. What do you do?","options":[{"text":"Stay in. You'll be better company another time","then":"The weekend passes quietly. Monday feels no lighter."},{"text":"Say yes, then cancel at the last minute","then":"Your friend says no worries. Now you feel guilty on top of low."},{"text":"Go, even though part of you wants to hide","then":"The movie is silly. You laugh twice, and the week loosens its grip.","best":true},{"text":"Stay in and use the time to fix your weak spots","then":"You drill yourself alone all evening and end it drained."}],"why":"Choosing company when you want to hide is how the isolating habit starts to break."},{"prompt":"On Monday you forget a small quiz deadline, and your inner voice starts up. What do you tell yourself?","options":[{"text":"Typical. I can't get anything right","then":"The words sting, and you sit stuck at your desk for an hour."},{"text":"I'll be harder on myself so it never happens again","then":"You feel tense all week, braced for the next mistake."},{"text":"It's fine. I just won't think about it","then":"The thought comes back that night, louder for being ignored."},{"text":"Everyone slips. I'll find one thing to fix","then":"You email to ask about a retake. The voice quietens a little.","best":true}],"why":"Talking to yourself like a friend steadies you. Harshness only drains you."}],"debrief":"Connection and self-compassion are healthier and work better than isolation and self-criticism.","relearn":"Swap isolating and self-criticism for connection and self-kindness."},
  {"id":"mb-028","cat":"cope-well","type":"strike-rewrite","hook":"\"Mental health isn't as real or important as physical health.\"","relearn":"Looking after your mind is as normal and necessary as looking after your body.","persona":"any","source":"mind = health","myth":{"un":"Mental health isn't as real or important as physical health.","re":"Looking after your mind is as normal and necessary as looking after your body.","why":"The mind needs care like the body does."}},
  {"id":"mb-029","cat":"cope-well","type":"spot","persona":"any","source":"the toolkit","hook":"Spot the two that don't belong in a real coping toolkit.","scene":[{"id":"a","text":"Breathe, move, talk, rest","trick":false},{"id":"b","text":"Just hoping you'll cope somehow","trick":true},{"id":"c","text":"A go-to calming step","trick":false},{"id":"d","text":"Numbing it until it passes","trick":true},{"id":"e","text":"A trusted person to call","trick":false}],"why":"Just hoping and numbing aren't a real toolkit; breathe-move-talk-rest, a go-to step and a trusted person are.","relearn":"A real toolkit is breathe-move-talk-rest, a go-to step and a trusted person; just hoping or numbing isn't."},
  {"id":"mb-030","cat":"cope-well","type":"strike-rewrite","hook":"\"Rest is just laziness and a waste of time.\"","relearn":"Rest isn't laziness; it's part of how you cope and keep going.","persona":"any","source":"rest","myth":{"un":"Rest is laziness and a waste of time.","re":"Rest isn't laziness; it's part of how you cope and keep going.","why":"You can't run on empty."}},
  {"id":"mb-031","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"Feeling like a fraud means I don't really belong here.\"","myth":{"un":"Feeling like a fraud means I don't belong.","re":"Impostor feelings are common, especially for first-gen students, and don't reflect reality; you earned your place.","why":"Lots of capable people feel this way."},"relearn":"Impostor feelings are common and don't reflect reality; you earned your place.","persona":"Deepak","source":"impostor syndrome"},
  {"id":"mb-032","cat":"mind-and-self-worth","type":"reflect","hook":"Lensy: nearly everyone secretly feels they're 'winging it' sometimes, even the confident ones. Reassuring?","prompt":"What do you think?","options":["Yes","Everyone winging it","Reassuring"],"affirm":"Almost everyone feels like they're winging it at times; it's human, not a verdict.","relearn":"Nearly everyone feels they're 'winging it' sometimes; it's human.","persona":"any","source":"shared feeling"},
  {"id":"mb-033","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"My worth is my grades and achievements.\"","myth":{"un":"My worth is my grades and achievements.","re":"Your worth isn't your productivity or results; you matter beyond what you produce.","why":"People aren't valued by output alone."},"relearn":"Your worth isn't your grades or output; you matter beyond what you produce.","persona":"any","source":"worth beyond output"},
  {"id":"mb-034","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"My worth depends on how I look.\"","myth":{"un":"My worth depends on how I look.","re":"You are far more than your appearance; worth isn't measured in looks.","why":"Bodies and looks say nothing about your value."},"relearn":"You're far more than your appearance; worth isn't measured in looks.","persona":"any","source":"body image (links g21)"},
  {"id":"mb-035","cat":"mind-and-self-worth","type":"sort","hook":"Sort: protects your self-worth, or erodes it?","items":[{"id":"a","text":"Self-kindness when you slip"},{"id":"b","text":"Harsh self-criticism"},{"id":"c","text":"Valuing who you are, not just results"},{"id":"d","text":"Measuring yourself against edited feeds"},{"id":"e","text":"Letting a compliment land"},{"id":"f","text":"Replaying every mistake at night"}],"bins":[{"id":"protects","label":"Protects","valence":"pos"},{"id":"erodes","label":"Erodes","valence":"neg"}],"key":{"a":"protects","b":"erodes","c":"protects","d":"erodes","e":"protects","f":"erodes"},"relearn":"Self-kindness, valuing who you are and accepting praise protect self-worth; self-criticism, comparison and replaying mistakes erode it.","persona":"any","source":"self-worth"},
  {"id":"mb-036","cat":"mind-and-self-worth","type":"branch","persona":"any","source":"comparison","hook":"Scrolling at night, everyone seems to be doing more than you, and you feel behind.","steps":[{"prompt":"It's midnight and you've been scrolling for an hour, feeling worse. What do you do?","options":[{"text":"Keep scrolling to see who else is ahead","then":"Three more friends' wins later, you feel smaller and wide awake."},{"text":"Close the app. Feeds are highlight reels","then":"The room goes quiet. The ache eases a little, and you sleep.","best":true},{"text":"Post something impressive so you don't look behind","then":"You pick an old photo that looks good. The likes come, and the feeling stays."},{"text":"Switch to a different app for a bit","then":"The new feed has its own highlight reels. It's 1 a.m. now."}],"why":"Stepping away and naming feeds as highlight reels protects your self-worth."},{"prompt":"Next morning, a classmate's internship post pops up before you're even out of bed. What do you do?","options":[{"text":"Compare their profile with yours, line by line","then":"By breakfast, you've listed ten ways you're behind."},{"text":"Tell yourself you're not bothered at all","then":"You say it twice. The sinking feeling stays, just quieter."},{"text":"Notice the sinking feeling and put the phone down","then":"You get up and make tea. By the time it's ready, the feeling has shrunk.","best":true},{"text":"Decide you'll never be good enough","then":"The thought follows you into class and sits beside you all day."}],"why":"Noticing the feeling and stepping back stops one post from setting your mood."},{"prompt":"That week, your friend Tanya admits your posts make her feel behind. What do you say?","options":[{"text":"Say she's doing far better than you, really","then":"Tanya shakes her head. Soon you're competing over who's more behind."},{"text":"Tell her to just stop checking social media","then":"\"Easy to say,\" Tanya mutters, and the chat ends."},{"text":"Say nothing, secretly pleased you look ahead","then":"The small glow fades fast. It doesn't touch how you actually feel."},{"text":"Tell her your posts leave out the hard days too","then":"Tanya laughs, relieved. \"So it's not just me.\" You both feel lighter.","best":true}],"why":"Saying feeds hide the hard days helps you both step out of comparison."}],"debrief":"Curated feeds aren't real life. Breaks and perspective protect your self-worth.","relearn":"Take breaks from comparison; feeds are highlight reels, not real life."},
  {"id":"mb-037","cat":"mind-and-self-worth","type":"reflect","hook":"Lensy: you are enough as you are, before any achievement or look. Can you let that in?","prompt":"What do you think?","options":["Yes","I'm enough","Working on it"],"affirm":"You are enough as you are; your worth was never up for being earned.","relearn":"You are enough as you are, before any achievement or look.","persona":"any","source":"enough"},
  {"id":"mb-038","cat":"mind-and-self-worth","type":"branch","persona":"any","source":"self-compassion","hook":"You emailed the wrong file to your whole class, and your inner voice is being brutal.","steps":[{"prompt":"The voice says you're careless and everyone is laughing at you. What do you do?","options":[{"text":"Agree. You should be more careful","then":"The voice gets louder. You reread the email ten times."},{"text":"Ask what you'd say to a friend who did this","then":"You'd tell a friend it's a tiny slip. Saying it to yourself feels odd, and softer.","best":true},{"text":"Replay it again and again to learn the lesson","then":"An hour later, you've learned nothing new and feel worse."},{"text":"Tell yourself it's nothing and push it down","then":"You get busy. The knot in your stomach stays all afternoon."}],"why":"Speaking to yourself as you would a friend breaks the harsh spiral."},{"prompt":"A classmate replies to everyone: the file is wrong. What do you do?","options":[{"text":"Don't reply and hope people forget","then":"Three more people ask for the right file. Your inbox keeps pinging."},{"text":"Blame a glitch in the email app","then":"Someone replies that it worked fine for them. Your face burns."},{"text":"Send a long apology explaining what happened","then":"Two people reply \"no worries\". You still feel you owe everyone."},{"text":"Resend the right file with a quick \"Oops\"","then":"A couple of thumbs up come back. The thread goes quiet.","best":true}],"why":"Fixing it simply shows a mistake is just a mistake, not a verdict."},{"prompt":"That evening, you keep thinking you always mess things up. What do you do?","options":[{"text":"Go through old mistakes to prove the point","then":"By ten, you have a long list and a heavy chest."},{"text":"Promise yourself you'll never slip up like this again","then":"The promise feels safe for a moment. Then it feels like a trap."},{"text":"Tell yourself one slip doesn't make you careless","then":"You think of the things you got right this week. The \"always\" loosens.","best":true},{"text":"Stay up working to make up for it","then":"You finish at 2 a.m., exhausted, and the voice is still there."}],"why":"Answering 'always' with the facts steadies you. One slip isn't who you are."},{"prompt":"Next day, your friend Zubin says he's still cringing over a wrong answer in class. What do you say?","options":[{"text":"Tell him he should have prepared better","then":"Zubin's face falls. He goes quiet."},{"text":"Tell him one slip isn't who he is","then":"Zubin exhales. \"Okay. Yeah. I needed to hear that.\"","best":true},{"text":"Tell him everyone's forgotten already","then":"\"You don't know that,\" Zubin says, still cringing."},{"text":"Tell him your email disaster was far worse","then":"He laughs, then goes back to replaying his answer."}],"why":"Offering a friend the kindness you gave yourself makes it a habit."}],"debrief":"Self-compassion, treating yourself like a friend, is healthier and helps you recover faster.","relearn":"Talk to yourself like a good friend, not a brutal critic."},
  {"id":"mb-039","cat":"mind-and-self-worth","type":"role-play","persona":"any","source":"supporting a friend","hook":"Ishaan just got back a mid-sem paper he failed, and he's being hard on himself.","setup":"In the hostel mess, he pushes his plate away.","steps":[{"prompt":"Ishaan says: \"I'm so stupid. I can't get anything right.\"","options":[{"text":"\"Come on. You're the smartest person I know!\"","then":"He shakes his head. \"You have to say that. You're my friend.\""},{"text":"\"Yeah, you should've studied more, honestly.\"","then":"His jaw tightens. \"Thanks. I know. That's the whole problem.\""},{"text":"\"You failed one paper. That doesn't make you stupid.\"","then":"He looks up. \"Then why does it feel like it does?\"","best":true},{"text":"\"Forget it. Let's go watch something.\"","then":"\"Maybe later,\" he mutters, still staring at his plate."}],"why":"Separating the setback from who he is answers the real hurt, without arguing or piling on."},{"prompt":"Ishaan says: \"Everyone else seems to manage. What's wrong with me?\"","options":[{"text":"\"Honestly, maybe this course is just too hard for you.\"","then":"\"Maybe. Maybe I should just drop it,\" he says quietly."},{"text":"\"Nothing! You'll top the next one, easily.\"","then":"\"You don't know that,\" he says, and the pressure in his voice climbs."},{"text":"\"I failed two last year, so you're doing better than me.\"","then":"He half-smiles. \"Okay. But it's still me who failed this one.\""},{"text":"\"Nothing's wrong with you. Bad papers happen to people.\"","then":"His shoulders drop a little. \"I did have three deadlines that week.\"","best":true}],"why":"Calling it a normal human setback, not a flaw in him, eases the shame without false promises."},{"prompt":"Ishaan asks: \"So what do I even do now?\"","options":[{"text":"\"Don't think about it at all. It'll pass.\"","then":"\"Sure,\" he says, but he checks the result again before bed."},{"text":"\"Rest tonight. Tomorrow, ask the professor what went wrong.\"","then":"He nods slowly. \"Okay. Sleep first, then office hours.\"","best":true},{"text":"\"Redo the whole syllabus this week so it never happens again.\"","then":"His eyes widen. \"The whole thing? I'm already behind.\""},{"text":"\"Get the topper's notes and copy her method.\"","then":"\"Maybe,\" he says. \"Though I don't even know what I got wrong.\""}],"why":"Rest plus one small step turns a setback into something to learn from, not a verdict."}],"relearn":"Remind a struggling friend that a setback doesn't define them."},
  {"id":"mb-040","cat":"mind-and-self-worth","type":"match","hook":"Match the self-worth truth to what it answers.","pairs":[{"left":"I'm more than my grades","right":"Worth beyond output"},{"left":"I earned my place","right":"Impostor feelings lie"},{"left":"I'm enough as I am","right":"Before any achievement"},{"left":"My body isn't my value","right":"More than appearance"},{"left":"Rest isn't laziness","right":"How I keep going"}],"relearn":"You're more than your grades, you earned your place, you're enough, your body isn't your value, and rest isn't laziness.","persona":"any","source":"consolidation"},
  {"id":"mb-041","cat":"reach-out","type":"strike-rewrite","hook":"\"Asking for help means I'm failing or weak.\"","myth":{"un":"Asking for help means I'm failing or weak.","re":"Reaching out early is the strong, smart move; everyone needs support sometimes.","why":"It takes courage and good sense to ask."},"relearn":"Reaching out early is the strong, smart move, not failure or weakness.","persona":"any","source":"help is strength"},
  {"id":"mb-042","cat":"reach-out","type":"strike-rewrite","hook":"\"Real men don't talk about feelings or get help.\"","myth":{"un":"Real men don't talk about feelings or get help.","re":"Everyone has a mind to look after; reaching out is strength for all genders.","why":"This stigma costs men dearly."},"relearn":"Everyone has a mind to look after; help-seeking is strength for all genders.","persona":"Rohan","source":"men's stigma"},
  {"id":"mb-043","cat":"reach-out","type":"branch","persona":"any","source":"early help","hook":"You've felt stretched thin and low for weeks, and wonder if it's 'bad enough' for help.","steps":[{"prompt":"You pass the campus counselling centre on your way to class. What do you do?","options":[{"text":"Walk past. Others need it more than you","then":"You make it to class. The heavy feeling sits with you through the lecture."},{"text":"Wait and see if it's still bad after exams","then":"Exams are three weeks away. Lasting till then feels tiring just to think about."},{"text":"Step in and book a first chat this week","then":"The receptionist finds you a Thursday slot and doesn't ask why.","best":true},{"text":"Look up tips online to fix it by yourself","then":"You skim a list of tips between classes. They make sense, but you feel just as alone."}],"why":"You don't need to be in crisis to deserve support. Early help is easier help."},{"prompt":"That evening, your roommate Farah asks why you've been so quiet lately. What do you say?","options":[{"text":"Say you're just tired from assignments","then":"She nods and goes back to her laptop. The quiet returns."},{"text":"Say it's nothing compared to what others face","then":"\"If it's bothering you, it's not nothing,\" she says. You change the subject."},{"text":"Tell her you've been low for a while, and it's been hard","then":"Farah sits down on your bed. \"Same last sem. Want to talk?\"","best":true},{"text":"Ask about her day instead","then":"She talks about her day. You nod along, feeling far away."}],"why":"Letting one person in early means you don't carry it alone while it's still small."},{"prompt":"A week later, the low feeling hasn't lifted, though it hasn't got worse either. What do you do next?","options":[{"text":"Decide it's not serious, since it isn't getting worse","then":"The weeks blur together, grey and heavy, and nothing changes."},{"text":"Lean on Farah, and skip counselling for now","then":"Farah listens most nights. It helps, but the low feeling stays."},{"text":"Book a session this week, or call Tele-MANAS 14416","then":"Talking it through, you find a few reasons behind the low feeling that you can work on.","best":true},{"text":"Push through alone till the semester ends","then":"By the end of the semester you're exhausted, and the low feeling is still there."}],"why":"Steady-but-low is reason enough. Support works best early, before things get heavier."}],"debrief":"Early help is easier and works better. You never have to wait for a crisis to deserve it.","relearn":"You don't have to be in crisis to deserve support; reach out early."},
  {"id":"mb-044","cat":"reach-out","type":"role-play","persona":"any","source":"opening up","hook":"You want to tell your elder cousin, Shalini didi, that you haven't been okay.","setup":"She calls on Sunday, as she always does.","steps":[{"prompt":"Shalini asks: \"So, how's hostel life treating you?\"","options":[{"text":"\"All good! Just busy with assignments and stuff.\"","then":"\"Great! Eat properly,\" she says, and chats about the family."},{"text":"\"It's fine. How's everyone at home?\"","then":"She fills you in on everyone. Nothing gets said about you."},{"text":"\"Honestly, I've been struggling. Could we talk?\"","then":"Her voice softens. \"Of course. I'm listening.\"","best":true},{"text":"\"Bit tired, that's all. Exams are coming up.\"","then":"\"Hang in there,\" she says. \"Exams end soon.\""}],"why":"A simple, honest opener is enough to start. You don't need perfect words."},{"prompt":"Shalini says: \"You've gone so quiet in the family group lately.\"","options":[{"text":"\"Sorry. I've just been busy. I'll post more, promise.\"","then":"\"That's not what I meant,\" she says, but lets it go."},{"text":"\"I've been low for a few weeks. It helps to say it.\"","then":"\"Thank you for telling me,\" she says. \"Let's figure out what might help.\"","best":true},{"text":"\"Everyone's busy. It's no big deal.\"","then":"\"Okay,\" she says slowly, not quite convinced."},{"text":"\"Ha, it's all forwards. Did Chintu get his results?\"","then":"She laughs and tells you, then pauses. \"You changed the subject.\""}],"why":"Saying plainly how long it's been lets her understand, and help."},{"prompt":"Shalini asks: \"Before we hang up, what would make this week easier for you?\"","options":[{"text":"\"Nothing. I'll sort it out myself.\"","then":"\"You don't have to,\" she says, but you've already moved on."},{"text":"\"Just tell me what to do, and I'll do it. Anything.\"","then":"\"I'm not sure I know,\" she says. \"But I can listen.\""},{"text":"\"Honestly, stop worrying about me.\"","then":"\"I can't just switch it off,\" she says gently."},{"text":"\"Someone to talk to. Maybe a call every few days?\"","then":"\"Done,\" she says. \"Wednesdays and Sundays, and more if you need.\"","best":true}],"why":"A clear, small ask gives her an easy way to support you."}],"relearn":"A simple 'I'm struggling and could use someone to talk to' is enough to start."},
  {"id":"mb-045","cat":"reach-out","type":"branch","persona":"Mehta","source":"reaching for help","hook":"For weeks your low mood has been heavy and constant, and some days feel hopeless.","steps":[{"prompt":"It's Sunday night and the week ahead feels impossible. What do you do?","options":[{"text":"Tell yourself it'll lift if you just wait","then":"The night stretches on. Monday arrives feeling just as heavy."},{"text":"Call Tele-MANAS 14416 tonight and say how it's been","then":"A calm voice answers, listens, and helps you think about the next few days.","best":true},{"text":"Text a friend 'rough week' and leave it at that","then":"She sends a hug. It's warm, but she has no idea how bad it's been."},{"text":"Remind yourself that others have it much worse","then":"The thought adds guilt on top of the heaviness."}],"why":"Heavy, constant low mood deserves support today. Reaching out is strength, not weakness."},{"prompt":"On Monday you pass the counselling centre, and Dr. Mehta has a free slot. What do you do?","options":[{"text":"Skip it. You don't want to waste a counsellor's time","then":"You walk past. The slot goes to someone else, and the heaviness stays."},{"text":"Take a leaflet and plan to come back some day","then":"The leaflet goes into your bag and stays there, folded."},{"text":"Go in, but say you're mostly fine, just stressed","then":"Dr. Mehta offers some study tips. You leave feeling unseen."},{"text":"Take the slot and tell her how heavy it's been","then":"Dr. Mehta listens without rushing. \"I'm really glad you came in today.\"","best":true}],"why":"A counsellor is exactly who to see when low mood won't lift. Saying it straight gets you real help."},{"prompt":"Your friend Asha notices you've missed the group dinners all week and asks if you're okay. What do you say?","options":[{"text":"Say you're fine, just busy with work","then":"She nods, unsure. The group dinner goes on without you again."},{"text":"Say you've been low, but she shouldn't worry","then":"\"Okay,\" she says, and doesn't ask again, though she clearly wants to."},{"text":"Apologise for being bad company lately","then":"\"You're not bad company,\" she says, confused. You change the subject."},{"text":"Say you've been really low, and ask her to check in","then":"Asha squeezes your arm. \"Of course. I'll message you every evening.\"","best":true}],"why":"Letting a friend in, with a clear ask, builds support around you day to day."},{"prompt":"A few days later you have a slightly better morning, then the heaviness returns. What do you do?","options":[{"text":"Take the good morning as proof you're fine now","then":"The next heavy day hits harder, because you'd stopped expecting it."},{"text":"Contact Dr. Mehta or Tele-MANAS 14416 today","then":"You're reminded that getting better has ups and downs, and you plan the next talk.","best":true},{"text":"Decide you've failed because it came back","then":"The thought makes the day heavier than it needed to be."},{"text":"Wait for another good day before doing anything","then":"Days pass. The good mornings stay rare."}],"why":"Better and harder days mix while things improve. Staying connected to help carries you through."}],"debrief":"When low mood is heavy and constant, reaching out today is the caring step. Help truly works.","relearn":"If heavy and constant, reach for support today (Tele-MANAS 14416)."},
  {"id":"mb-046","cat":"reach-out","type":"sort","hook":"Sort: a real source of support, or not?","items":[{"id":"a","text":"A campus counsellor"},{"id":"b","text":"Just bottling it up"},{"id":"c","text":"Tele-MANAS 14416"},{"id":"d","text":"Hoping it sorts itself out"},{"id":"e","text":"A trusted friend or relative"},{"id":"f","text":"Numbing it and pretending you're fine"}],"bins":[{"id":"real","label":"Real support","valence":"pos"},{"id":"not","label":"Not support","valence":"neg"}],"key":{"a":"real","b":"not","c":"real","d":"not","e":"real","f":"not"},"relearn":"A counsellor, Tele-MANAS 14416 and a trusted person are real support; bottling up, just hoping or numbing aren't.","persona":"any","source":"real support"},
  {"id":"mb-047","cat":"reach-out","type":"role-play","persona":"any","source":"supporting in crisis","hook":"Late in the library, Faiz says he's been in 'a dark place' lately, then laughs it off.","setup":"Everyone else has left for dinner.","steps":[{"prompt":"Faiz says: \"Anyway, ignore me. I'm being dramatic.\"","options":[{"text":"\"Ha, same. This semester is brutal.\"","then":"He nods. \"Yeah. Brutal.\" The moment passes."},{"text":"\"You're not. I'm glad you told me. What's going on?\"","then":"He stops laughing. \"Honestly? Most days I don't want to get up.\"","best":true},{"text":"\"Okay. Want to grab dinner?\"","then":"\"Sure,\" he says, packing up quickly."},{"text":"\"A dark place? Sounds like you should see a psychiatrist.\"","then":"He goes red. \"Forget it. I'm fine.\""}],"why":"Taking his hint seriously, and warmly, tells him it's safe to say more."},{"prompt":"On the walk out, Faiz says: \"I just feel like I'm dragging everyone down.\"","options":[{"text":"\"Don't say that! Everyone here loves you, you know.\"","then":"\"You don't get it,\" he says, looking away."},{"text":"\"Everyone feels like that sometimes.\"","then":"\"Maybe,\" he says. \"But not every day like this.\""},{"text":"\"You're not. And you're not alone in this.\"","then":"He lets out a long breath. \"It helps to hear that.\"","best":true},{"text":"\"Is it because of your results?\"","then":"\"Not really,\" he says, and goes quiet."}],"why":"Answering the 'burden' feeling directly, and saying he's not alone, keeps him talking."},{"prompt":"Faiz asks: \"What am I even supposed to do about it?\"","options":[{"text":"\"Just push through. It'll pass.\"","then":"\"I've been pushing for months,\" he says quietly."},{"text":"\"I don't know. Maybe wait and see?\"","then":"He nods, and neither of you says more."},{"text":"\"Here's the counsellor's number. Call them tomorrow.\"","then":"He takes it, then puts his phone away. \"Maybe later.\""},{"text":"\"Let's find support together. I'll come with you.\"","then":"He hesitates, then nods slowly.","best":true}],"why":"Offering to find support together makes the first step feel possible."},{"prompt":"The next morning, Faiz texts: \"Still feel awful. Was last night weird?\"","options":[{"text":"\"A bit, ha. Let's not talk about it.\"","then":"He sends a thumbs up and doesn't bring it up again."},{"text":"\"Not weird at all. Call Tele-MANAS 14416 together today?\"","then":"\"Okay,\" he replies. \"After lunch? Stay with me?\"","best":true},{"text":"\"No worries at all. Hope you feel better soon!\"","then":"He sends \"thanks\". The chat goes quiet."},{"text":"\"You need to sort it out before it gets any worse.\"","then":"\"I know,\" he replies. \"That's the problem.\""}],"why":"Following up next day, with a real step, keeps support moving."}],"relearn":"Meet a struggling friend with warmth and offer to find support together."},
  {"id":"mb-048","cat":"reach-out","type":"branch","persona":"any","source":"crisis support","hook":"Late at night, your friend Rhea tells you she's been having thoughts of harming herself.","steps":[{"prompt":"She's sitting on the library steps, not looking at you. What do you do first?","options":[{"text":"Tell her she'll feel better soon","then":"\"Maybe,\" she says quietly, and closes up again."},{"text":"Ask her lots of questions about why she feels this way","then":"She shrinks back. \"I don't know. Forget I said anything.\""},{"text":"Sit beside her and say you're glad she told you","then":"Rhea's shoulders loosen a little. \"I didn't know who else to tell.\"","best":true},{"text":"Give her some space and check on her tomorrow","then":"She nods and looks away. Halfway down the path, you feel uneasy, and you turn back."}],"why":"Staying close and thanking her for telling you shows she isn't alone, and that it's safe to talk."},{"prompt":"Rhea asks you to promise you won't tell anyone. What do you say?","options":[{"text":"Promise, so she keeps trusting you","then":"She relaxes. Now it's a secret only the two of you hold."},{"text":"Promise, but plan to quietly tell her parents later on","then":"She believes you. You feel the weight of the lie settle in."},{"text":"Say it's too big to keep secret, and you'll face it together","then":"She looks scared, then nods. \"Only if you stay with me.\"","best":true},{"text":"Say you must tell the warden now, and get up to go","then":"Rhea panics as you start to leave, and calls you back, crying."}],"why":"Some secrets are too heavy to keep. Being honest while staying with her protects her and the trust."},{"prompt":"You're both still on the steps, and it's past midnight. What do you do now?","options":[{"text":"Talk it through yourselves till she feels better","then":"You talk till 3 a.m. She's calmer, but you're both still alone with it."},{"text":"Call Tele-MANAS 14416 together, right now","then":"A counsellor answers, speaks gently to Rhea, and helps you both plan the next hours.","best":true},{"text":"Suggest she sleeps, and calls someone tomorrow","then":"She heads back to her room alone. You lie awake, and tomorrow feels far away."},{"text":"Message a friend group to ask what to do","then":"Three people reply at once with advice, and Rhea feels exposed."}],"why":"Tele-MANAS 14416 is free, open any hour and trained for this. You don't have to handle it alone."},{"prompt":"Next morning, Rhea says she feels a bit calmer and wants to forget last night. What do you do?","options":[{"text":"Agree never to mention it again","then":"She smiles, relieved. What she shared stays unspoken."},{"text":"Make her promise never to feel this way again","then":"\"I can't promise that,\" she says, and pulls away."},{"text":"Check she's okay, then get on with your day","then":"She says she's fine. You spend the day wondering if it's true."},{"text":"Help her reach a counsellor or trusted adult today","then":"She agrees to see the campus counsellor, if you walk her there.","best":true}],"why":"Calmer isn't the same as safe. Linking her to ongoing support keeps the help going."},{"prompt":"A few days on, you feel shaken and can't stop thinking about that night. What do you do?","options":[{"text":"Keep it all in. She's the one who's struggling","then":"You lie awake most nights, jumpy every time your phone buzzes."},{"text":"Check Rhea's messages every hour, just in case","then":"Rhea notices and asks you to ease up. You feel lost."},{"text":"Talk to a counsellor about how you're coping too","then":"Saying it aloud, you feel steadier, and you learn how to keep supporting her.","best":true},{"text":"Tell other friends the whole story to process it","then":"Word spreads, and Rhea hears her story from someone else."}],"why":"Supporting a friend in crisis is heavy. Getting support yourself keeps you both going."}],"debrief":"A friend in crisis: stay warm, take it seriously, and get support from Tele-MANAS 14416, a trusted adult, or 112 if they're in danger now.","relearn":"If a friend mentions self-harm, stay warmly and help them get help."},
  {"id":"mb-049","cat":"reach-out","type":"role-play","persona":"any","source":"encouraging help","hook":"Kavya's panic before exams is getting worse, but she calls herself weak for needing help.","setup":"She tells you while you queue for photocopies.","steps":[{"prompt":"Kavya says: \"Everyone else copes. Needing help just proves I'm weak.\"","options":[{"text":"\"Yeah, maybe just tough it out.\"","then":"She nods, jaw tight. \"Yeah. That's what I've been doing.\""},{"text":"\"Don't be silly. You're the strongest person I know.\"","then":"\"Then why can't I handle this?\" she asks."},{"text":"\"Asking for help is brave. It's not weak.\"","then":"She looks up. \"Brave? It doesn't feel brave.\"","best":true},{"text":"\"Most people who cope are faking it anyway.\"","then":"She half-laughs. \"Great. So we're all faking.\""}],"why":"Reframing help as brave takes away the shame that keeps her stuck."},{"prompt":"Kavya says: \"I wouldn't even know how to ask.\"","options":[{"text":"\"It's easy. Just go and ask.\"","then":"\"Not for me,\" she says, and goes quiet."},{"text":"\"Maybe look it up online first.\"","then":"\"I've read so much already,\" she sighs."},{"text":"\"I'll book the counsellor for you right now, then.\"","then":"\"Wait, not yet,\" she says, flustered. \"I'm not ready.\""},{"text":"\"Want me to come with you to the counsellor?\"","then":"She thinks, then nods. \"Only if you do the talking at the desk.\"","best":true}],"why":"Offering to go with her, while she decides, makes the first step less lonely."},{"prompt":"Kavya asks: \"What if the counsellor thinks I'm overreacting?\"","options":[{"text":"\"Then just don't mention the panic part to them.\"","then":"\"Then what's the point of going?\" she asks."},{"text":"\"They hear this daily. They'll take you seriously.\"","then":"Her shoulders drop. \"Okay. Let's go on Thursday.\"","best":true},{"text":"\"If they do, you can always get up and leave.\"","then":"\"So I'd waste the trip?\" she asks, less sure."},{"text":"\"Maybe you are overreacting a little.\"","then":"Her face falls. \"See? That's exactly what I'm afraid of.\""}],"why":"Knowing counsellors meet worries like hers with care eases the fear of going."}],"relearn":"Reframe asking for help as brave, and offer to help a friend reach out."},
  {"id":"mb-050","cat":"reach-out","type":"branch","persona":"any","source":"non-judgmental help","hook":"You've decided to see the campus counsellor, but you're scared they'll judge you.","steps":[{"prompt":"Your appointment is in an hour and your stomach is in knots. What do you do?","options":[{"text":"Cancel. You'll go when you feel less scared","then":"Relief lasts an hour. Then the worry comes back, and you rebook for Friday."},{"text":"Go, but plan to talk only about exam stress","then":"You head over, rehearsing a safe, small version of your problems."},{"text":"Search online whether counsellors tell your parents","then":"You find mixed answers. You go anyway, the knot tighter than before."},{"text":"Go, and tell the counsellor you're nervous","then":"Ms. D'Souza smiles. \"Lots of people are. Take your time.\"","best":true}],"why":"Saying you're nervous is a fine way to start. Good support meets you with care, not judgement."},{"prompt":"In the session, the counsellor, Ms. D'Souza, asks what's been going on. What do you say?","options":[{"text":"Say you're probably wasting her time","then":"\"You're not,\" she says. \"This time is yours.\" You still hold back."},{"text":"Ask if it stays private, then tell her the real thing","then":"She explains it's confidential. You start talking, and she just listens.","best":true},{"text":"Talk only about exams, to test how she reacts first","then":"The session ends on timetables. The real thing waits for another day."},{"text":"Say a friend has this problem, not you","then":"She answers gently about 'your friend'. It helps a little, from a distance."}],"why":"Checking privacy, then speaking honestly, lets the support reach the real problem."},{"prompt":"Next week, a friend says counsellors 'just judge you and tell your parents.' What do you say?","options":[{"text":"Agree. You're not sure you'll go back","then":"The doubt grows, and your next appointment slides off the calendar."},{"text":"Change the subject, since it's their choice anyway","then":"Your friend's words stay with you, and you wonder about going back."},{"text":"Say yours listened, and they can ask about privacy first","then":"Your friend pauses. \"Really? Maybe I'll try it then.\"","best":true},{"text":"Tell them they're wrong and should go themselves","then":"\"Don't lecture me,\" your friend snaps, and the talk ends."}],"why":"Good support is caring and confidential. Saying so helps you keep going, and helps others try."}],"debrief":"Good mental-health support is non-judgemental and confidential. You're met with care.","relearn":"Good support meets you with care, not judgement; reach out."},
  {"id":"mb-051","cat":"tools-and-help","type":"match","hook":"Match the need to where help lives (India).","pairs":[{"left":"Free 24/7 mental-health line","right":"Tele-MANAS 14416"},{"left":"Danger to life, right now","right":"Emergency 112"},{"left":"Help right on campus","right":"A campus counsellor"},{"left":"Day-to-day support","right":"A trusted person"},{"left":"A steady daily anchor","right":"Routine, sleep and food"}],"relearn":"Tele-MANAS 14416 to talk, 112 for danger, a counsellor or trusted person day-to-day.","persona":"any","source":"help routes"},
  {"id":"mb-052","cat":"tools-and-help","type":"sort","hook":"Sort: a healthy go-to in a hard moment, or not?","items":[{"id":"a","text":"A few slow breaths"},{"id":"b","text":"Anything that uses pain or harm"},{"id":"c","text":"Texting a trusted person"},{"id":"d","text":"Cutting everyone off completely"},{"id":"e","text":"Stepping outside for a short walk"},{"id":"f","text":"Numbing out till it all blurs"}],"bins":[{"id":"healthy","label":"Healthy go-to","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"healthy","b":"not","c":"healthy","d":"not","e":"healthy","f":"not"},"relearn":"Breathing, walking and reaching out are healthy go-tos; harm, isolating or numbing are not.","persona":"any","source":"healthy go-tos"},
  {"id":"mb-053","cat":"tools-and-help","type":"spot","hook":"Spot the two that AREN'T a healthy in-the-moment reset.","relearn":"A slow breath or stepping outside is a healthy in-the-moment reset; bottling up or numbing isn't.","persona":"any","source":"breathing space","scene":[{"id":"a","text":"A slow breath and a short pause","trick":false},{"id":"b","text":"Bottling it up even tighter","trick":true},{"id":"c","text":"Stepping outside for fresh air","trick":false},{"id":"d","text":"Numbing out to blur the feeling","trick":true},{"id":"e","text":"Texting one trusted person","trick":false}],"why":"Bottling up and numbing don't reset you; breathing, fresh air and reaching out do."},
  {"id":"mb-054","cat":"tools-and-help","type":"match","hook":"Match the support to when you'd reach for it.","relearn":"Know the helpline, a coping step and a trusted person for hard moments.","persona":"any","source":"being ready","pairs":[{"left":"A 24/7 helpline","right":"Tele-MANAS 14416"},{"left":"A quick coping step","right":"Breathe, move, talk, rest"},{"left":"Someone who knows you","right":"A trusted person"},{"left":"Help on campus","right":"A campus counsellor"},{"left":"Someone in danger right now","right":"Emergency 112"}]},
  {"id":"mb-055","cat":"tools-and-help","type":"reflect","hook":"Lensy: this builds skills and points to help; for anything heavy or lasting, a professional is the right call. Clear?","prompt":"What do you think?","options":["Yes","See a professional","Makes sense"],"affirm":"For persistent or serious distress, a professional is exactly the right next step; this game points the way.","relearn":"For heavy or lasting distress, a professional is the right call; this points the way.","persona":"any","source":"not therapy"},
  {"id":"mb-056","cat":"tools-and-help","type":"match","hook":"Match the coping tool to the moment.","pairs":[{"left":"Breathing & grounding","right":"A stress spike"},{"left":"Reaching out","right":"A heavy, lonely patch"},{"left":"Routine & rest","right":"Keeping steady day to day"},{"left":"A short walk outside","right":"A foggy, stuck afternoon"},{"left":"Calling a helpline","right":"A night it feels too big"}],"relearn":"Breathing for spikes, reaching out for heavy patches, routine for steady days, a walk to unstick.","persona":"any","source":"the toolkit"},
  {"id":"mb-057","cat":"tools-and-help","type":"match","hook":"Match a struggling friend's need to what you can offer.","relearn":"Offer presence, share help routes, and connect a friend to support.","persona":"any","source":"sharing routes","pairs":[{"left":"They feel alone","right":"Your steady presence"},{"left":"They don't know help exists","right":"Share Tele-MANAS 14416"},{"left":"They're in real crisis","right":"Stay and help them reach support now"},{"left":"They just need to vent","right":"Listening without fixing"},{"left":"They want a campus route","right":"Walk with them to the counsellor"}]},
  {"id":"mb-058","cat":"tools-and-help","type":"reflect","hook":"Lensy: cope well, find your people, and reach out, you can look after your mind through all of this. Feel it?","prompt":"What do you think?","options":["Yes","I can do this","I've got tools"],"affirm":"Coping well, building belonging and reaching out are exactly the tools to carry you through.","relearn":"Cope well, find your people and reach out: you can look after your mind.","persona":"any","source":"equipped"},
  {"id":"mb-059","cat":"tools-and-help","type":"spot","hook":"Spot the two messages that make reaching out HARDER.","scene":[{"id":"a","text":"\"Asking for help is strong\"","trick":false},{"id":"b","text":"\"You should be able to cope alone\"","trick":true},{"id":"c","text":"\"You're not alone, support is there\"","trick":false},{"id":"d","text":"\"Real men just tough it out\"","trick":true},{"id":"e","text":"\"No problem is too small to share\"","trick":false}],"why":"\"Cope alone\" and \"tough it out\" shame help-seeking; the others make reaching out easier.","relearn":"'Asking for help is strong' and 'you're not alone' open the door; 'cope alone' shuts it.","persona":"any","source":"helpful messages"},
  {"id":"mb-060","cat":"tools-and-help","type":"match","hook":"Match each Mind & Belonging truth to its theme.","relearn":"Struggle is normal, belonging is built, cope healthily, and reaching out is strength.","persona":"any","source":"carry forward","pairs":[{"left":"Struggle is normal","right":"Settling in"},{"left":"Belonging is built","right":"Find your people"},{"left":"Reaching out is strength","right":"Help-seeking"},{"left":"Cope without harm","right":"Healthy coping"},{"left":"You're more than grades","right":"Self-worth"}]},
  {"id":"mb-061","cat":"settling-in","type":"role-play","persona":"Deepak","source":"family pressure","hook":"Your family calls every day for updates and keeps asking about top results.","setup":"Tonight your mother calls, on speaker.","steps":[{"prompt":"Your mother asks: \"Beta, did you top the test? Everyone is asking.\"","options":[{"text":"\"Yes, almost. Tell everyone I'm doing great.\"","then":"Your uncle cheers in the background. Your stomach sinks."},{"text":"\"Why does the whole family need my marks?\"","then":"\"Because we're proud of you,\" she says, hurt."},{"text":"\"No, Ma. I'm doing my best and still settling.\"","then":"A pause. \"Okay, beta. As long as you're trying.\"","best":true},{"text":"\"I'll definitely top the next one, Ma. I promise.\"","then":"\"That's what we want to hear,\" she says. The pressure doubles."}],"why":"Honest and warm keeps them close without promising what you can't control."},{"prompt":"Your mother says: \"Call us every day after class so we know you're fine.\"","options":[{"text":"\"Of course, every single day. Whatever you want.\"","then":"She sounds relieved. You picture every evening spent on the phone."},{"text":"\"I'll call every few days, and share when I can.\"","then":"\"Every few days?\" she says slowly. \"Okay. But tell us if something's wrong.\"","best":true},{"text":"\"I'm an adult now. You can't keep checking on me.\"","then":"The line goes quiet. Then your uncle takes the phone."},{"text":"\"Just check my WhatsApp last seen. That shows I'm fine.\"","then":"\"Last seen?\" she says. \"That's not the same as hearing your voice, beta.\""}],"why":"A kind boundary with a clear plan is easier for family to accept than a flat no."},{"prompt":"Your uncle says: \"We've all sacrificed for this. Don't waste the chance.\"","options":[{"text":"\"Then maybe I shouldn't have come at all.\"","then":"Everyone talks at once, and the call ends in a tangle of worry."},{"text":"\"I won't waste it. I'll study every waking hour, Chacha.\"","then":"\"That's the spirit!\" he says. You look at your untouched dinner."},{"text":"\"Mm. I know. I have to go now, Chacha.\"","then":"\"Go, go,\" he says. The call ends, and the weight of it follows you to bed."},{"text":"\"I know. I'm grateful and working hard. Love you all.\"","then":"Your uncle clears his throat. \"Good. Take care of yourself too.\"","best":true}],"why":"You can honour their sacrifice warmly without promising to burn yourself out."},{"prompt":"After the call, your roommate Harish asks: \"Rough call? You look wiped.\"","options":[{"text":"\"Nah, all good. Families, you know.\"","then":"He nods and goes back to his laptop."},{"text":"\"Yeah. Family pressure. Can I vent for a minute?\"","then":"Harish pulls up a chair. \"Go on. Mine are the same.\"","best":true},{"text":"\"Doesn't matter. You wouldn't get it.\"","then":"\"Try me,\" he says, but you've already turned away."},{"text":"\"It's fine. I'll just study more so they're happy.\"","then":"He shrugs. You open your books, too tired to read."}],"why":"Leaning on a friend as well as family widens your support."}],"relearn":"Set gentle boundaries with family pressure and widen your support."},
  {"id":"mb-062","cat":"find-your-people","type":"branch","persona":"Meena","source":"language barrier","hook":"You've moved to a new city for work, and you don't speak the local language well yet.","steps":[{"prompt":"In the factory canteen, women chat in the local language at every table. What do you do?","options":[{"text":"Eat outside alone until you're fluent enough","then":"The bench is quiet. The canteen noise feels further away each day."},{"text":"Sit at a busy table and nod along","then":"You laugh when they laugh. You leave not knowing anyone's name."},{"text":"Sit near a woman who looks new too, and smile","then":"She smiles back. Her name is Lakshmi, and she's from another state too.","best":true},{"text":"Wait for someone to invite you over","then":"Lunch ends. Nobody noticed you were waiting."}],"why":"Others in a similar spot are often your first people. Connection doesn't wait for fluency."},{"prompt":"A few days later a co-worker asks you something quickly, and you don't catch it. What do you do?","options":[{"text":"Nod and hope it wasn't important","then":"It was about a shift change. You find out the next morning, the hard way."},{"text":"Say you're still learning, and ask her to repeat it","then":"She repeats it slowly, with a gesture. You both laugh when you get it.","best":true},{"text":"Walk off, embarrassed","then":"She looks puzzled. The next day, she doesn't ask you anything."},{"text":"Apologise again and again for your language","then":"She waves it off, but the talk ends before it starts."}],"why":"Asking plainly and learning as you go builds connection and confidence."},{"prompt":"On your day off, you hear about a weekly meet-up for workers from your home state. What do you do?","options":[{"text":"Wait until you know someone who's going","then":"Weeks pass. You still don't know anyone who goes."},{"text":"Stay in. You're too tired to meet new people","then":"The day passes quietly. The loneliness is still there on Monday."},{"text":"Go for an hour, then rest the afternoon","then":"Familiar food and voices. Someone offers to help you find a cheaper room.","best":true},{"text":"Skip it. You should only mix with locals now","then":"You spend Sunday alone, practising words to an empty room."}],"why":"People in the same boat can become your first circle, and rest still fits around it."},{"prompt":"A month on, work still feels lonely, and the language is coming slowly. What do you do?","options":[{"text":"Stick only with people who share your language","then":"Evenings feel warm. At work, you still feel like a visitor."},{"text":"Decide you'll never really belong here","then":"You keep to yourself, and the city stays strange."},{"text":"Wait until you can speak it well before trying","then":"Months go by. The words stay locked in your head."},{"text":"Learn a few words a week from co-workers","then":"Your clumsy greetings make people smile. Someone teaches you a joke.","best":true}],"why":"Learning as you go, with real people, builds belonging now."}],"debrief":"Connection doesn't wait for fluency. Others in a similar spot are often your first people.","relearn":"Build belonging now with others in the same boat. Don't wait to be 'fluent enough'."},
  {"id":"mb-063","cat":"cope-well","type":"branch","persona":"any","source":"exam anxiety","hook":"Exams start in ten days, and your anxiety is spiking hard.","steps":[{"prompt":"You open your notes for all five papers. How do you plan the days?","options":[{"text":"Study every waking hour until the first paper","then":"By day two you're exhausted, and the plan has no room to recover."},{"text":"Copy a topper's timetable exactly","then":"Their plan starts at 5 a.m. You're behind before breakfast."},{"text":"Daily study blocks with breaks and proper sleep","then":"Seeing it on paper, the ten days start to look possible.","best":true},{"text":"Stay on your weakest paper until it's fully done","then":"Three days go into one subject. The others start to loom."}],"why":"A steady plan with breaks and sleep keeps anxiety workable and recall sharp."},{"prompt":"Four days in, a friend says she's already revised everything twice. What do you do?","options":[{"text":"Add a night session to catch up with her","then":"You get four hours of sleep. The next morning nothing sticks."},{"text":"Quiz her for an hour on how she did it","then":"Her method sounds great for her. You've lost an hour and feel behind."},{"text":"Decide you're going to fail anyway","then":"The thought follows you through the afternoon, and your focus slips."},{"text":"Let her pace be hers, and carry on","then":"The pang fades within the hour. You tick off the day's work.","best":true}],"why":"Comparing pace feeds anxiety. Your own steady pace is what works for you."},{"prompt":"The night before the first paper, you're lying awake going over formulas. What do you do?","options":[{"text":"Put the notes away and breathe out slowly","then":"Your shoulders drop. After a while, sleep comes.","best":true},{"text":"Switch the light on and revise till you feel ready","then":"It's 3 a.m. and you don't feel ready. You feel exhausted."},{"text":"Scroll your phone until you get sleepy","then":"The screen keeps you alert. You drift off close to dawn."},{"text":"Lie still and order yourself to fall asleep","then":"The harder you try, the more awake you feel."}],"why":"Letting the notes go and breathing slowly gives your brain the rest it needs to recall."},{"prompt":"In the exam hall, you read the first question and your mind goes blank. What do you do?","options":[{"text":"Stare at the question until the answer comes","then":"Minutes tick by. The blank grows each time you glance at the clock."},{"text":"Breathe out slowly, then start with one you know","then":"The easier answer gets your pen moving. The blank slowly fills in.","best":true},{"text":"Rush through every question to save time","then":"You write fast and loose. Later you spot marks you dropped."},{"text":"Tell yourself you've messed up the whole exam","then":"Your hands start shaking, and the next question blurs too."}],"why":"A slow breath and an easy start calm the panic and get your memory working again."}],"debrief":"Steady, rested study beats frantic cramming for both anxiety and performance.","relearn":"Manage exam anxiety with steady study, breaks and sleep, not non-stop cramming."},
  {"id":"mb-064","cat":"mind-and-self-worth","type":"sort","hook":"Sort: a kind, true thing to tell yourself, or a harsh untruth?","items":[{"id":"a","text":"\"I'm learning and that's enough\""},{"id":"b","text":"\"I'm a failure\""},{"id":"c","text":"\"One bad day isn't my whole story\""},{"id":"d","text":"\"Everyone's better than me\""},{"id":"e","text":"\"I'm allowed to find this hard\""},{"id":"f","text":"\"I'll never be good enough\""}],"bins":[{"id":"kind","label":"Kind & true","valence":"pos"},{"id":"harsh","label":"Harsh untruth","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"'I'm learning' and 'one bad day isn't my story' are kind and true; 'I'm a failure' and 'everyone's better' are harsh untruths.","persona":"any","source":"self-talk"},
  {"id":"mb-065","cat":"reach-out","type":"reflect","hook":"Lensy: in India especially, the stigma is heavy, and choosing to reach out anyway is real courage. Honour that?","prompt":"What do you think?","options":["Yes","Brave to ask","Beat the stigma"],"affirm":"Reaching out against the stigma is genuinely brave, and it can change, even save, a life.","relearn":"Reaching out despite stigma is real courage, and it matters.","persona":"any","source":"beating stigma"},
  {"id":"mb-066","cat":"cope-well","type":"strike-rewrite","hook":"\"If I'm anxious or low, I'm broken.\"","myth":{"un":"If I'm anxious or low, I'm broken.","re":"Anxiety and low mood are common human experiences, not a sign you're broken, and they're workable with support.","why":"Struggling is part of being human."},"relearn":"Anxiety and low mood are common and workable, not a sign you're broken.","persona":"any","source":"not broken"},
  {"id":"mb-067","cat":"find-your-people","type":"role-play","persona":"any","source":"hope","hook":"Your school friend Sneha started college in another city a month ago.","setup":"She calls you late on Sunday, sounding flat.","steps":[{"prompt":"Sneha says: \"Everyone here already has their people. I'll never fit in.\"","options":[{"text":"\"You're overthinking it. It's only been a month.\"","then":"\"Right,\" Sneha says flatly. \"Forget I said anything.\""},{"text":"\"That sounds really lonely. What's it been like?\"","then":"Sneha sighs. \"Honestly? I eat lunch alone most days.\"","best":true},{"text":"\"Then come home more often. We're all here.\"","then":"\"Not every weekend,\" she says. \"And I still live here.\""},{"text":"\"Maybe you're just not a people person.\"","then":"Sneha goes quiet. \"Yeah. Maybe.\""}],"why":"Listening first shows her the feeling makes sense before you offer hope."},{"prompt":"Sneha says: \"I went to one club meeting and nobody talked to me.\"","options":[{"text":"\"Ugh, people can be so rude.\"","then":"\"Right? So what's the point?\" she says, more deflated."},{"text":"\"Did you actually talk to anyone yourself?\"","then":"Sneha bristles. \"So it's my fault now?\""},{"text":"\"One meeting is a start. Most people need a few.\"","then":"\"Really?\" She sounds a little lighter. \"I thought it was just me.\"","best":true},{"text":"\"Then that club isn't for you. Try another one.\"","then":"\"Maybe,\" she says. \"It'll probably go the same way.\""}],"why":"Seeing one quiet meeting as a start keeps her going instead of giving up."},{"prompt":"Sneha says: \"What if I keep trying and it's always like this?\"","options":[{"text":"\"It won't be. Trust me.\"","then":"\"You can't know that,\" she says, but softer."},{"text":"\"Then just focus on studies. Friends aren't everything.\"","then":"\"I guess,\" she says. The loneliness stays unspoken."},{"text":"\"Your people are out there too. Keep showing up.\"","then":"Sneha is quiet a moment. \"Okay. I can do that.\"","best":true},{"text":"\"Then transfer somewhere else. Life's too short.\"","then":"\"It's not that easy,\" she says. \"Fees, family, everything.\""}],"why":"Hope plus a nudge to keep showing up is what helps her find her people."},{"prompt":"Before hanging up, Sneha says: \"Thanks. I just feel so far from everyone.\"","options":[{"text":"\"Let's video call every night so you're never lonely.\"","then":"\"Every night?\" She laughs a little. \"You'll get sick of me.\""},{"text":"\"Anytime. Try not to think about it too much.\"","then":"\"Okay,\" she says. The call ends a little flat."},{"text":"\"You'll be fine. You always are.\"","then":"\"I suppose,\" Sneha says. She doesn't sound fine."},{"text":"\"Call me after the next meeting. Tell me how it goes.\"","then":"\"Deal,\" Sneha says. \"Thursday's meeting, then.\"","best":true}],"why":"Checking back in keeps her going and shows she's not alone while she settles."}],"relearn":"Remind a lonely friend their people are out there; encourage them to keep showing up."},
  {"id":"mb-068","cat":"reach-out","type":"role-play","persona":"Zoya","source":"paying it forward","hook":"You're steadier now, and notice first-year Ananya eating alone each night, like you once did.","setup":"Tonight you carry your tray to her table.","steps":[{"prompt":"Ananya says: \"Oh. You can sit, I guess.\"","options":[{"text":"\"You should really join a club, you know.\"","then":"\"Maybe,\" she says, and goes back to her food."},{"text":"\"Why do you always eat alone?\"","then":"She reddens. \"I don't know anyone yet.\""},{"text":"\"Thanks. My first year was rough. How's yours?\"","then":"She looks surprised. \"Honestly? Harder than I thought.\"","best":true},{"text":"\"Don't mind me. I just needed a seat.\"","then":"She nods, and you both eat in silence."}],"why":"Sharing your own rough start makes it easier for her to be honest about hers."},{"prompt":"Ananya says: \"Everyone else seems to have their group already.\"","options":[{"text":"\"Yeah. The first month is when groups form.\"","then":"Her face falls. \"Great. So I missed it.\""},{"text":"\"You'll find yours. Don't worry about it.\"","then":"\"Easy for you to say,\" she says, with a small smile."},{"text":"\"It looks that way. Most are still finding theirs.\"","then":"\"Really?\" she asks. \"It feels like I'm the only one.\"","best":true},{"text":"\"Groups are overrated. You're better off alone.\"","then":"\"I don't want to be alone, though,\" she says quietly."}],"why":"Busting the 'everyone else has settled in' myth eases the loneliness."},{"prompt":"As you get up to leave, Ananya says: \"Thanks for sitting with me.\"","options":[{"text":"\"No problem. See you around.\"","then":"\"Yeah,\" she says, and you drift off in different directions."},{"text":"\"You'll be fine. Everyone gets through it.\"","then":"\"Hope so,\" she says, not sounding sure."},{"text":"\"See a counsellor if it's this bad.\"","then":"\"It's not that bad,\" she says quickly, and looks away."},{"text":"\"Any time. If you ever want to talk, I'm here.\"","then":"She smiles properly for the first time. \"I might take you up on that.\"","best":true}],"why":"An open offer to talk passes on the support that once helped you."}],"relearn":"When steadier, reach out to someone struggling like you once were."},
  {"id":"mb-069","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"If others look like they're doing better, they really are.\"","relearn":"Comparing your behind-the-scenes to others' highlight reels is never fair.","persona":"any","source":"comparison","myth":{"un":"If others look like they're doing better, they really are.","re":"Comparing your behind-the-scenes to others' highlight reels is never a fair fight.","why":"You see their edits, not their reality."}},
  {"id":"mb-070","cat":"tools-and-help","type":"match","hook":"Match the long-term habit to what it protects.","relearn":"Self-check-ins, connection and the basics protect mental health long-term.","persona":"any","source":"long-term habit","pairs":[{"left":"Checking in with yourself","right":"Catching trouble early"},{"left":"Staying connected","right":"Beating isolation"},{"left":"Keeping the basics","right":"A steady mind"},{"left":"Knowing your help routes","right":"A faster reach when it's hard"},{"left":"Resting before empty","right":"Not burning out"}]},
  {"id":"mb-071","type":"sort","hook":"Sort: a kind expectation of yourself settling in, or an unfair one?","items":[{"id":"a","text":"\"It's okay to take time\""},{"id":"b","text":"\"I should feel at home instantly\""},{"id":"c","text":"\"Some hard days are normal\""},{"id":"d","text":"\"I must never struggle\""},{"id":"e","text":"\"I can ask for help when I'm stuck\""},{"id":"f","text":"\"I should figure it all out alone\""}],"bins":[{"id":"kind","label":"Kind","valence":"pos"},{"id":"unfair","label":"Unfair","valence":"neg"}],"key":{"a":"kind","b":"unfair","c":"kind","d":"unfair","e":"kind","f":"unfair"},"relearn":"Taking time and expecting some hard days is kind; demanding instant ease or zero struggle is unfair.","persona":"any","source":"fair expectations","cat":"settling-in"},
  {"id":"mb-072","cat":"find-your-people","type":"strike-rewrite","hook":"\"If I haven't found my people by now, I never will.\"","myth":{"un":"If I haven't found my people by now, I never will.","re":"Belonging keeps growing over time; it's never too late to build it.","why":"Connections form at every stage."},"relearn":"It's never too late to find your people; belonging keeps growing.","persona":"any","source":"never too late"},
  {"id":"mb-073","cat":"cope-well","type":"spot","persona":"any","source":"the basics","hook":"Spot the two that don't steady your mind day to day.","scene":[{"id":"a","text":"Regular sleep","trick":false},{"id":"b","text":"Pulling all-nighters","trick":true},{"id":"c","text":"A daily walk or a chat","trick":false},{"id":"d","text":"Skipping meals all day","trick":true},{"id":"e","text":"A bit of daylight and air","trick":false}],"why":"All-nighters and skipping meals don't steady you; sleep, a walk, a chat and daylight quietly do.","relearn":"Sleep, a walk, a chat and daylight steady your mind; all-nighters and skipping meals don't."},
  {"id":"mb-074","cat":"mind-and-self-worth","type":"branch","persona":"any","source":"off the scoreboard","hook":"Your mood rises and falls with every test result and every like on your posts.","steps":[{"prompt":"Your latest reel got fewer likes than usual, and your whole evening sinks. What do you do?","options":[{"text":"Refresh the post every few minutes","then":"The number barely moves. Your mood follows it down."},{"text":"Delete the reel and post something better","then":"The new post does a little better. You check it every ten minutes."},{"text":"Remind yourself a like-count isn't your worth","then":"You put the phone face down. The evening slowly becomes yours again.","best":true},{"text":"Ask friends in a group chat to like it","then":"A few likes trickle in. The lift lasts about ten minutes."}],"why":"Separating your worth from a number is how you step off the rollercoaster."},{"prompt":"The next week, you top a class test and feel on top of the world. What do you do?","options":[{"text":"Enjoy it, knowing a low mark wouldn't make you less","then":"You celebrate with friends. The next test feels less like a trial.","best":true},{"text":"Decide this is what makes you worth something","then":"The high is huge. You already dread the next test."},{"text":"Post the marks everywhere and watch the likes","then":"The likes pour in. By night, you feel oddly empty."},{"text":"Shrug it off. It's only one test","then":"You play it down so fast that the good feeling goes with it."}],"why":"Enjoying wins without tying your worth to them keeps you steady either way."},{"prompt":"A month later, your results are mixed and you catch yourself asking if you're good enough. What do you do?","options":[{"text":"Study past midnight till the scores prove you are","then":"A week of late nights later, you feel more tired, not more worthy."},{"text":"Check how everyone else did","then":"Someone always did better. The question gets louder."},{"text":"Tell yourself to stop being dramatic","then":"The question goes quiet for a while, then comes back at night."},{"text":"Think about what you value in yourself beyond marks","then":"Kindness, humour, showing up for friends. None of it moved with the results.","best":true}],"why":"Worth rooted in who you are doesn't rise and fall with results."}],"debrief":"Detaching your worth from scoreboards, grades or likes is how you get off the emotional rollercoaster.","relearn":"Anchor your worth in who you are, not grades or like-counts."},
  {"id":"mb-075","cat":"reach-out","type":"sort","hook":"Sort: a sign it's time to reach for more support, or just a normal day?","items":[{"id":"a","text":"Heavy low mood most days for weeks"},{"id":"b","text":"A single tough afternoon"},{"id":"c","text":"Losing interest in everything you loved"},{"id":"d","text":"Nervous before one big event"},{"id":"e","text":"Sleep and appetite off for a month"},{"id":"f","text":"One rough night before a deadline"}],"bins":[{"id":"reach","label":"Reach for support","valence":"tell"},{"id":"normal","label":"Normal day","valence":"neutral"}],"key":{"a":"reach","b":"normal","c":"reach","d":"normal","e":"reach","f":"normal"},"relearn":"Weeks of heaviness, lost interest or month-long sleep changes signal reaching out; a tough afternoon or one rough night are normal.","persona":"any","source":"when to reach"},
  {"id":"mb-076","cat":"tools-and-help","type":"reflect","hook":"Lensy: you don't have to carry any of this alone, ever. Let that land?","prompt":"What do you think?","options":["Yes","Not alone","That helps"],"affirm":"You never have to carry it alone; support, in people and helplines, is always within reach.","relearn":"You don't have to carry any of this alone; support is always within reach.","persona":"any","source":"not alone"},
  {"id":"mb-077","cat":"find-your-people","type":"role-play","persona":"any","source":"making the offer","hook":"You get on well with Kavya and Dev from your course, but you only ever see them in class.","setup":"After the last lecture of the week, they're packing up beside you.","steps":[{"prompt":"Kavya says: \"Finally, Friday. Any plans for the weekend?\"","options":[{"text":"\"Nothing much. Probably sleep and laundry.\"","then":"Kavya laughs. \"Same.\" They wave and head out."},{"text":"\"Not sure yet. What are you two doing this weekend?\"","then":"\"Just home stuff,\" Dev says. \"See you Monday.\""},{"text":"\"A few of us are meeting Sunday. Want to come?\"","then":"Kavya looks at Dev. \"Sure, why not? Send us the details.\"","best":true},{"text":"\"We should all hang out sometime, na?\"","then":"\"Totally,\" Kavya says. Nobody names a day."}],"why":"A simple, specific invite gives acquaintances an easy way to say yes."},{"prompt":"The next week, Dev says: \"I'm so bored of hostel food. Know anywhere good?\"","options":[{"text":"\"Try the dosa place near the gate. It's great.\"","then":"\"Cool, thanks,\" Dev says. \"I'll take my roommate.\""},{"text":"\"Let's all try the dosa place on Saturday.\"","then":"\"Done,\" Dev says. \"Kavya, you in?\"","best":true},{"text":"\"Not really. I just eat whatever's there.\"","then":"\"Same,\" Dev sighs, and the talk drifts back to assignments."},{"text":"\"Ask someone who's been here longer.\"","then":"Dev shrugs. \"Fair. I'll ask the seniors.\""}],"why":"Turning a small chat into a plan is how acquaintances start becoming friends."},{"prompt":"A month later, Kavya says: \"Exams end on Friday. We should celebrate somehow.\"","options":[{"text":"\"Ha, I'm pretty boring at celebrating.\"","then":"Kavya laughs politely. \"I'm sure you're not.\""},{"text":"\"Yes! Someone should plan something.\"","then":"\"Totally,\" Kavya agrees. Everyone waits for someone else."},{"text":"\"Dinner on Friday? I'll ask a few others too.\"","then":"\"Yes! Dev, you're coming.\" Dev is already nodding.","best":true},{"text":"\"I'll come if you two plan it.\"","then":"\"Okay,\" Kavya says. \"Dev, you plan it?\" Dev groans."}],"why":"Making the plan yourself, and widening it, turns classmates into friends."}],"relearn":"A simple invitation can turn acquaintances into real friends."},
  {"id":"mb-078","cat":"cope-well","type":"branch","persona":"any","source":"numbing","hook":"You realise you've been drinking most evenings to unwind, more than you'd like.","steps":[{"prompt":"On Sunday morning you count the evenings this week and feel uneasy. What do you do with that feeling?","options":[{"text":"Tell yourself it's fine. Everyone at college drinks","then":"The unease fades by lunch. So does any plan to change things."},{"text":"Notice it honestly, without calling yourself names","then":"The unease stays, but it feels like information now, not a verdict.","best":true},{"text":"Feel disgusted with yourself and keep it secret","then":"The shame sits heavy, and it makes the evenings harder, not easier."},{"text":"Decide willpower alone will sort it out","then":"You feel determined. You haven't worked out what you'll do on hard evenings."}],"why":"Noticing kindly lets you see the pattern clearly. Shame and brushing it off both hide it."},{"prompt":"On Tuesday evening the stress of the day hits, and the usual urge comes. What do you do?","options":[{"text":"Shut yourself in your room with it all evening","then":"The evening drags. Alone with the urge, it feels louder."},{"text":"Call a friend and go for a walk together","then":"By the time you're back, the edge has gone out of the evening.","best":true},{"text":"Work till you're too tired to think","then":"It gets you through tonight, but you're running on empty by Thursday."},{"text":"Tell yourself tonight doesn't count after that day","then":"The day gets its excuse, and the pattern gets another evening."}],"why":"Connection and movement meet the stress without numbing it."},{"prompt":"By the weekend, some evenings have gone the way you hoped and some haven't. What do you do next?","options":[{"text":"Decide you've failed because of the slips","then":"The slips start to feel like proof. Next week begins heavy."},{"text":"Stop keeping track. It's making you anxious","then":"The anxiety fades, and so does any clear picture of the pattern."},{"text":"Keep it all to yourself so no one worries","then":"No one worries. No one helps either."},{"text":"Look at what helped and plan more of that","then":"You spot what the better evenings had in common and pencil more of it into next week.","best":true}],"why":"Learning from what worked builds new habits. One slip isn't failure."},{"prompt":"A few weeks on, the urge is still strong on hard days. What do you do?","options":[{"text":"Handle it alone. Asking feels like a big deal","then":"You keep managing, just. Hard days still feel like a fight."},{"text":"Tell a friend, but play it down as nothing","then":"Your friend laughs along. You walk away feeling unseen."},{"text":"Talk to a counsellor or call Tele-MANAS 14416","then":"It feels awkward for a minute to say it out loud. Then it feels like relief.","best":true},{"text":"Decide this is just who you are now","then":"The idea sticks, and trying again starts to feel pointless."}],"why":"Getting support early is the strong move when a habit is hard to shift alone."}],"debrief":"Leaning on drink to cope drains you. Notice it kindly, swap in healthier ways and get support.","relearn":"If you lean on substances to cope, notice it kindly and swap in healthier ways."},
  {"id":"mb-079","type":"spot","hook":"Spot the two harsh, untrue things to stop telling yourself when it's hard.","relearn":"It tends to get better; a year on you'll likely feel far more at home.","persona":"any","source":"it gets better","scene":[{"id":"a","text":"\"This is hard now, and it tends to get better\"","trick":false},{"id":"b","text":"\"It'll always feel this bad\"","trick":true},{"id":"c","text":"\"A year on, I'll likely feel more at home\"","trick":false},{"id":"d","text":"\"Everyone copes but me\"","trick":true},{"id":"e","text":"\"I'm allowed to find my feet slowly\"","trick":false}],"why":"'It gets better' and 'more at home in a year' are kind and true; 'always this bad' and 'everyone but me' are harsh and untrue.","cat":"settling-in"},
  {"id":"mb-080","cat":"reach-out","type":"branch","persona":"any","source":"valid to call","hook":"Exam stress has kept you up all week. You wonder if Tele-MANAS is only for emergencies.","steps":[{"prompt":"It's 1 a.m. and your mind won't slow down. What do you do?","options":[{"text":"Decide stress is too small for a helpline","then":"You lie awake till 4 a.m., the same thoughts looping."},{"text":"Keep the number for a real emergency","then":"The number stays saved. The night stays long."},{"text":"Call Tele-MANAS 14416 and say you're stressed","then":"The listener takes it seriously and helps you slow your breathing.","best":true},{"text":"Get up and study, since exams are the cause","then":"You reread notes till dawn and remember almost none of it."}],"why":"Tele-MANAS 14416 is for everyday stress too. You don't have to be in crisis to call."},{"prompt":"The next evening, your friend Dev says helplines are 'only for people in danger.' What do you say?","options":[{"text":"Agree. You'd hate to take a line from someone in danger","then":"Dev nods, and the idea that you're 'not bad enough' settles in deeper."},{"text":"Say they're for everyday stress too","then":"Dev looks surprised. \"Huh. Didn't know that. Maybe I'd call too.\"","best":true},{"text":"Say nothing, since you're not sure","then":"The talk moves on, and the myth goes unchallenged."},{"text":"Say you'd never call one either","then":"\"Same,\" says Dev. You both keep the stress to yourselves."}],"why":"Knowing helplines cover everyday stress makes them easier to use, for you and your friends."},{"prompt":"Two days before your exam, the stress spikes again. What do you do?","options":[{"text":"Wait till it's unbearable, then call","then":"The stress builds for two days. By the time you call, you're exhausted."},{"text":"Tell yourself everyone's stressed, so just cope","then":"You grit your teeth through it, and the knot in your stomach stays."},{"text":"Cancel every break and study non-stop","then":"By exam morning your head feels foggy and heavy."},{"text":"Call Tele-MANAS 14416 or talk to someone you trust","then":"Talking it out takes the edge off, and you sleep properly that night.","best":true}],"why":"Reaching out early, before it's unbearable, is exactly what helplines are for."}],"debrief":"Helplines like Tele-MANAS are for everyday stress too, not only crises. Reaching out is valid.","relearn":"Tele-MANAS 14416 is for everyday stress too; nothing's too small."},
  {"id":"mb-081","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"Being kind to yourself is soft or weak.\"","relearn":"Being kind to yourself isn't soft; it's how you keep going.","persona":"any","source":"self-kindness","myth":{"un":"Being kind to yourself is soft or weak.","re":"Self-kindness isn't soft; it's how you actually keep going.","why":"Self-compassion builds resilience."}},
  {"id":"mb-082","cat":"tools-and-help","type":"sort","hook":"Sort: something this game does, or something it doesn't?","items":[{"id":"a","text":"Builds coping skills and signposts help"},{"id":"b","text":"Replaces a therapist"},{"id":"c","text":"Points serious distress to professionals"},{"id":"d","text":"Diagnoses or treats you"},{"id":"e","text":"Normalises the struggle"},{"id":"f","text":"Rates how 'bad' you are"}],"bins":[{"id":"does","label":"It does","valence":"pos"},{"id":"doesnt","label":"It doesn't","valence":"neg"}],"key":{"a":"does","b":"doesnt","c":"does","d":"doesnt","e":"does","f":"doesnt"},"relearn":"This builds skills, normalises struggle and signposts help; it doesn't diagnose, treat or rate you.","persona":"any","source":"what it is"},
  {"id":"mb-083","cat":"find-your-people","type":"sort","hook":"Sort: deepens belonging over time, or stays surface?","items":[{"id":"a","text":"Being there for people in hard times"},{"id":"b","text":"Only ever small talk"},{"id":"c","text":"Sharing something real about yourself"},{"id":"d","text":"Keeping everyone at arm's length"},{"id":"e","text":"Remembering and asking about their life"},{"id":"f","text":"Cancelling whenever it's slightly inconvenient"}],"bins":[{"id":"deepens","label":"Deepens","valence":"pos"},{"id":"surface","label":"Stays surface","valence":"neg"}],"key":{"a":"deepens","b":"surface","c":"deepens","d":"surface","e":"deepens","f":"surface"},"relearn":"Showing up in hard times, realness and real interest deepen belonging; small talk, arm's length or flaking stays surface.","persona":"any","source":"deeper bonds"},
  {"id":"mb-084","cat":"reach-out","type":"reflect","hook":"Lensy: look after your mind, find your people, and ask for help, that's how you thrive, not just survive. Ready?","prompt":"What will you carry?","options":["Cope well","Build belonging","Reach out early","Be kind to myself"],"affirm":"Carry that, and you can truly thrive here, and help others do the same. You're not alone.","relearn":"Look after your mind, find your people and ask for help: that's how you thrive.","persona":"any","source":"thrive"},
  {"id":"mb-900","cat":"cope-well","type":"strike-rewrite","persona":"Rohan","source":"feelings aren't a switch","hook":"\"Stress means I'm weak: strong people just feel fine.\"","myth":{"un":"Stress means I'm weak. Strong people just feel fine.","re":"Stress is your body reacting to pressure, not weakness; everyone feels it.","why":"Stress is a normal human response, not a flaw."},"relearn":"Stress is a normal reaction to pressure, not a sign you're weak."},
  {"id":"mb-901","cat":"cope-well","type":"strike-rewrite","persona":"any","source":"slowing down","hook":"\"If I slow down even a little, everything I've built will fall apart.\"","myth":{"un":"If I slow down even a little, everything will fall apart.","re":"Short breaks steady you; you do better rested than running on fumes.","why":"A rested mind thinks and copes more clearly."},"relearn":"Short breaks steady you; you cope better rested than running on empty."},
  {"id":"mb-902","cat":"cope-well","type":"strike-rewrite","persona":"any","source":"venting","hook":"\"Talking about stress just makes it bigger: better to keep it in.\"","myth":{"un":"Talking about stress just makes it bigger.","re":"Sharing it with someone you trust usually makes it feel lighter, not bigger.","why":"Naming a worry out loud often shrinks it."},"relearn":"Talking to someone you trust usually makes stress lighter, not bigger."},
  {"id":"mb-903","cat":"cope-well","type":"strike-rewrite","persona":"any","source":"sleep","hook":"\"Sleep is the first thing to cut when I'm busy. I'll catch up later.\"","myth":{"un":"Sleep is the first thing to cut when I'm busy.","re":"Sleep is when your mind resets; cutting it makes everything harder to handle.","why":"Rest restores focus, mood and patience."},"relearn":"Sleep resets your mind; cutting it first makes coping harder, not easier."},
  {"id":"mb-904","cat":"cope-well","type":"strike-rewrite","persona":"Deepak","source":"good days myth","hook":"\"A good coping day means I felt happy the whole time.\"","myth":{"un":"Coping well means feeling happy the whole time.","re":"Coping well means tending yourself kindly even on hard, mixed days.","why":"Wellbeing is care and steadiness, not constant happiness."},"relearn":"Coping well is tending yourself kindly on hard days, not feeling happy all the time."},
  {"id":"mb-905","cat":"cope-well","type":"strike-rewrite","persona":"any","source":"small things","hook":"\"Little habits like a walk are too small to matter for real stress.\"","myth":{"un":"Little habits like a walk are too small to matter.","re":"Small daily habits add up and are some of the steadiest coping you have.","why":"Tiny, repeated care does the quiet heavy lifting."},"relearn":"Small daily habits like a walk add up to real, steady coping."},
  {"id":"mb-906","cat":"cope-well","type":"strike-rewrite","persona":"any","source":"productivity worth","hook":"\"Resting is only allowed once I've earned it by finishing everything.\"","myth":{"un":"Rest is only allowed once I've earned it.","re":"Rest is a basic need, not a reward; you're allowed it before the list is done.","why":"You can't keep going without refuelling."},"relearn":"Rest is a need, not a reward you have to earn by finishing everything."},
  {"id":"mb-907","cat":"cope-well","type":"strike-rewrite","persona":"any","source":"distraction vs rest","hook":"\"Scrolling for hours is the same as resting my mind.\"","myth":{"un":"Scrolling for hours is the same as resting.","re":"Endless scrolling often leaves you more drained; real rest is calmer and kinder.","why":"A racing feed isn't the same as a quiet pause."},"relearn":"Endless scrolling isn't rest; real rest is a calmer, kinder pause."},
  {"id":"mb-908","cat":"cope-well","type":"strike-rewrite","persona":"Meena","source":"no campus","hook":"\"Coping tools are only for students with a fancy campus and free time.\"","myth":{"un":"Coping tools are only for students with a campus and free time.","re":"Breathing, a short walk and a quick chat work anywhere, free, in minutes.","why":"The basics need no campus and no money."},"relearn":"Breathing, a short walk and a chat are free coping tools that work anywhere."},
  {"id":"mb-909","cat":"cope-well","type":"strike-rewrite","persona":"any","source":"one big fix","hook":"\"There's one big fix out there that will finally sort my stress for good.\"","myth":{"un":"There's one big fix that will sort my stress for good.","re":"Coping is lots of small, repeated habits, not one magic fix.","why":"Steadiness is built daily, not bought once."},"relearn":"Coping is many small repeated habits, not one big magic fix."},
  {"id":"mb-910","cat":"cope-well","type":"strike-rewrite","persona":"any","source":"feelings pass","hook":"\"This awful feeling is permanent: it's how things will always be now.\"","myth":{"un":"This awful feeling is permanent and always will be.","re":"Feelings shift; tending the basics helps a heavy patch pass sooner.","why":"Even hard feelings move and change over time."},"relearn":"Heavy feelings shift; tending the basics helps a low patch pass sooner."},
  {"id":"mb-911","cat":"cope-well","type":"strike-rewrite","persona":"Zoya","source":"perfect routine","hook":"\"If I can't keep a perfect routine, there's no point keeping any of it.\"","myth":{"un":"If I can't keep a perfect routine, there's no point at all.","re":"A messy, partial routine still steadies you; some basics beat none.","why":"Coping is progress, not perfection."},"relearn":"A partial routine still helps; some basics beat none. It's not all-or-nothing."},
  {"id":"mb-912","cat":"cope-well","type":"strike-rewrite","persona":"any","source":"appetite","hook":"\"Skipping meals when I'm stressed shows discipline and saves time.\"","myth":{"un":"Skipping meals when stressed shows discipline.","re":"Your brain needs food to handle stress; regular meals help you cope.","why":"An unfed mind struggles to stay steady."},"relearn":"Regular meals fuel your mind to handle stress; skipping them makes coping harder."},
  {"id":"mb-913","cat":"cope-well","type":"strike-rewrite","persona":"any","source":"comparison","hook":"\"Everyone else copes effortlessly. I'm the only one who finds it hard.\"","myth":{"un":"Everyone else copes effortlessly; only I find it hard.","re":"Most people are quietly finding it hard too; the calm faces hide a lot.","why":"You're comparing your insides to others' outsides."},"relearn":"Most people quietly find coping hard too; you're not the only one."},
  {"id":"mb-914","cat":"cope-well","type":"strike-rewrite","persona":"any","source":"sunlight & movement","hook":"\"Going outside won't help: my problems are still there when I get back.\"","myth":{"un":"Going outside won't help; the problems are still there after.","re":"A bit of fresh air and movement steadies you to face the same problems better.","why":"A calmer body handles the same load more clearly."},"relearn":"Fresh air and movement steady you to face problems more clearly, even if they remain."},
  {"id":"mb-915","cat":"cope-well","type":"sort","persona":"any","source":"steadies vs spikes","hook":"Drop each into Steadies you or Winds you up.","items":[{"id":"a","text":"A slow walk after class"},{"id":"b","text":"Refreshing bad news on a loop"},{"id":"c","text":"A few quiet breaths"},{"id":"d","text":"Replaying the worst case all night"},{"id":"e","text":"A proper meal and water"},{"id":"f","text":"Three more cups of strong tea to push on"}],"bins":[{"id":"steady","label":"Steadies you","valence":"pos"},{"id":"winds","label":"Winds you up","valence":"neg"}],"key":{"a":"steady","b":"winds","c":"steady","d":"winds","e":"steady","f":"winds"},"relearn":"Walking, breathing and a proper meal steady you; doom-scrolling and pushing on overstimulated wind you up."},
  {"id":"mb-916","cat":"cope-well","type":"sort","persona":"any","source":"refuels vs drains","hook":"Drop each into Refuels you or Drains you.","items":[{"id":"a","text":"Seven hours of sleep"},{"id":"b","text":"Two nights with almost none"},{"id":"c","text":"A call with a good friend"},{"id":"d","text":"Cancelling on everyone for weeks"},{"id":"e","text":"A short break between tasks"},{"id":"f","text":"Working through every break"}],"bins":[{"id":"refuel","label":"Refuels you","valence":"pos"},{"id":"drain","label":"Drains you","valence":"neg"}],"key":{"a":"refuel","b":"drain","c":"refuel","d":"drain","e":"refuel","f":"drain"},"relearn":"Sleep, connection and breaks refuel you; skipping sleep, cutting everyone off and skipping breaks drain you."},
  {"id":"mb-917","cat":"cope-well","type":"sort","persona":"any","source":"in the moment","hook":"For a sudden stress spike: a calming step, or one that adds fuel?","items":[{"id":"a","text":"Step outside for a minute"},{"id":"b","text":"Snap at whoever's nearest"},{"id":"c","text":"Slow your breathing out"},{"id":"d","text":"Bottle it and grip tighter"},{"id":"e","text":"Splash cold water, sip slowly"},{"id":"f","text":"Spiral into 'everything's ruined'"}],"bins":[{"id":"calm","label":"Calms the spike","valence":"pos"},{"id":"fuel","label":"Adds fuel","valence":"neg"}],"key":{"a":"calm","b":"fuel","c":"calm","d":"fuel","e":"calm","f":"fuel"},"relearn":"Stepping out, slow breathing and cold water calm a spike; snapping, bottling and spiralling add fuel."},
  {"id":"mb-918","cat":"cope-well","type":"sort","persona":"Deepak","source":"deadline week","hook":"Deadline week: keeps you going, or burns you out?","items":[{"id":"a","text":"Break the work into chunks"},{"id":"b","text":"One long all-nighter"},{"id":"c","text":"A short walk between chunks"},{"id":"d","text":"Skip every meal to save time"},{"id":"e","text":"Sleep before the early start"},{"id":"f","text":"Forty browser tabs, no plan"}],"bins":[{"id":"going","label":"Keeps you going","valence":"pos"},{"id":"burns","label":"Burns you out","valence":"neg"}],"key":{"a":"going","b":"burns","c":"going","d":"burns","e":"going","f":"burns"},"relearn":"Chunking work, walks, and sleep keep you going through deadline week; all-nighters, skipped meals and chaos burn you out."},
  {"id":"mb-919","cat":"cope-well","type":"sort","persona":"any","source":"low patch","hook":"In a low patch: gently helps, or quietly deepens it?","items":[{"id":"a","text":"Keep one small daily routine"},{"id":"b","text":"Drop everything and withdraw"},{"id":"c","text":"Text one person you trust"},{"id":"d","text":"Stay in the dark all day"},{"id":"e","text":"Get a little daylight and air"},{"id":"f","text":"Tell yourself you're a burden"}],"bins":[{"id":"helps","label":"Gently helps","valence":"pos"},{"id":"deepens","label":"Deepens it","valence":"neg"}],"key":{"a":"helps","b":"deepens","c":"helps","d":"deepens","e":"helps","f":"deepens"},"relearn":"Keeping a small routine, reaching one person and getting daylight gently help a low patch; withdrawing and self-blame deepen it."},
  {"id":"mb-920","cat":"cope-well","type":"sort","persona":"any","source":"self-talk","hook":"Self-talk under pressure: kind and steadying, or harsh and draining?","items":[{"id":"a","text":"'This is hard; I'll take it bit by bit'"},{"id":"b","text":"'I'm useless and always will be'"},{"id":"c","text":"'I'm doing my best with a lot on'"},{"id":"d","text":"'Everyone's ahead; I'm a failure'"},{"id":"e","text":"'A break now will help me think'"},{"id":"f","text":"'I don't deserve to rest'"}],"bins":[{"id":"kind","label":"Kind & steadying","valence":"pos"},{"id":"harsh","label":"Harsh & draining","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"Talking to yourself kindly steadies you; harsh, all-or-nothing self-talk drains you."},
  {"id":"mb-921","cat":"cope-well","type":"sort","persona":"Meena","source":"no-campus coping","hook":"Coping with no campus or money: works for you, or needs what you don't have?","items":[{"id":"a","text":"A walk around the block"},{"id":"b","text":"An expensive weekend retreat"},{"id":"c","text":"Breathing slowly on a break"},{"id":"d","text":"A paid app you can't afford"},{"id":"e","text":"A free call to Tele-MANAS 14416"},{"id":"f","text":"Waiting till life is perfect first"}],"bins":[{"id":"works","label":"Works for you now","valence":"pos"},{"id":"needs","label":"Needs what you lack","valence":"neg"}],"key":{"a":"works","b":"needs","c":"works","d":"needs","e":"works","f":"needs"},"relearn":"A walk, slow breathing and a free helpline work with no campus or money; retreats, paid apps and waiting for perfect don't."},
  {"id":"mb-922","cat":"cope-well","type":"sort","persona":"any","source":"now vs later","hook":"Coping that helps now AND later, or feels nice now but costs later?","items":[{"id":"a","text":"A short walk and a real meal"},{"id":"b","text":"Numbing it for hours on end"},{"id":"c","text":"An early night before a big day"},{"id":"d","text":"Avoiding the task till the panic"},{"id":"e","text":"A quick chat with a friend"},{"id":"f","text":"Bottling it to deal with 'later'"}],"bins":[{"id":"both","label":"Helps now & later","valence":"pos"},{"id":"costs","label":"Costs you later","valence":"neg"}],"key":{"a":"both","b":"costs","c":"both","d":"costs","e":"both","f":"costs"},"relearn":"Walks, meals, sleep and chatting help now and later; numbing, avoiding and bottling feel easy now but cost you later."},
  {"id":"mb-923","cat":"cope-well","type":"branch","persona":"Deepak","source":"submission night","hook":"It's midnight, the submission's due at noon tomorrow, and your mind has gone foggy.","steps":[{"prompt":"You've read the same line five times. What do you do?","options":[{"text":"Force through the fog till dawn","then":"By 4 a.m. the words swim. You delete more than you write."},{"text":"Put a video on to wake your brain up","then":"One video becomes four. It's half past one and the fog is still there."},{"text":"Sleep now and set an alarm for six","then":"You drop off fast. The work will still be there in the morning.","best":true},{"text":"Keep going and grab a quick nap on the desk","then":"You wake stiff at three, neck aching and foggier than before."}],"why":"When your mind fogs over, sleep does more for the work than forcing hours."},{"prompt":"In the morning you wake with a knot in your stomach about the time left. What do you do first?","options":[{"text":"Eat something, then list what's left to finish","then":"The list has three items. With breakfast in you, they look doable.","best":true},{"text":"Skip breakfast and start straight away","then":"You start fast, then feel shaky and scattered by nine."},{"text":"Rewrite the whole thing from the start","then":"The fresh start eats two hours. By ten you're behind again."},{"text":"Check what classmates have submitted already","then":"Three people have submitted. The knot tightens."}],"why":"Fuel and a short list turn a scary morning into a few clear steps."},{"prompt":"At eleven you're nearly done, but one part still isn't as good as you want. What do you do?","options":[{"text":"Keep polishing right up to noon","then":"At 11:58 the upload stalls. Your heart pounds until it goes through."},{"text":"Submit it and call yourself useless all day","then":"The work is in, but the harsh voice follows you to lunch."},{"text":"Rewrite that part fully, even if it goes in late","then":"You submit ten minutes late, and the part isn't much better."},{"text":"Give it fifteen minutes, then submit either way","then":"You tighten two sentences and submit at twenty past. You breathe out.","best":true}],"why":"A short, set polish and then letting go protects both your rest and your deadline."}],"debrief":"When your mind fogs over, sleep and finish fresh. An all-nighter makes the work worse.","relearn":"When you're foggy at night, rest and finish fresh rather than forcing an all-nighter."},
  {"id":"mb-924","cat":"cope-well","type":"branch","persona":"any","source":"panic before presenting","hook":"You're next to present, and your heart is racing so hard you can hear it.","steps":[{"prompt":"Your name will be called in about three minutes. What do you do?","options":[{"text":"Tell yourself to just stop being nervous","then":"The order makes it worse. Now you're nervous about being nervous."},{"text":"Reread all your slides one last time, fast","then":"The words blur. You feel less ready than before."},{"text":"Ask to swap and go last instead","then":"The teacher agrees. The dread gets twenty more minutes to grow."},{"text":"Feet flat, breathe out slowly a few times","then":"Your heart is still quick, but your hands stop trembling.","best":true}],"why":"Slow out-breaths with your feet grounded settle a racing body fastest."},{"prompt":"At the front, your voice wobbles on the first line and someone coughs. What do you do?","options":[{"text":"Speed up to get it over with","then":"You race through the slides. Afterwards you can't recall what you said."},{"text":"Pause, breathe and start the line again","then":"The second try comes out steadier. The room waits.","best":true},{"text":"Apologise for being so nervous","then":"A few people smile, but now everyone is watching your nerves."},{"text":"Joke that you've forgotten everything","then":"A few laugh. Then you really do lose your place."}],"why":"A pause and a breath reset you. The room barely notices a short silence."},{"prompt":"Afterwards your mind replays the wobble on a loop. What do you do?","options":[{"text":"Decide you're just bad at presenting","then":"The thought sticks. Next time the dread starts days earlier."},{"text":"Ask five friends if it was really that bad","then":"They all say it was fine. You're not sure you believe them."},{"text":"Note what went okay and one thing to practise","then":"The list surprises you. Most of it went fine.","best":true},{"text":"Promise yourself you'll never volunteer again","then":"Relief comes, then a small sense of loss. You liked the topic."}],"why":"Looking at the whole picture, kindly, builds confidence for next time."}],"debrief":"A few slow out-breaths with feet grounded calm the body faster than scolding yourself.","relearn":"Before something nerve-wracking, slow your breathing out rather than ordering yourself to calm down."},
  {"id":"mb-925","cat":"cope-well","type":"branch","persona":"Rohan","source":"stress alone","hook":"After a brutal week you're wound up tight, and your instinct is to handle it all alone.","steps":[{"prompt":"Your friend Aman texts a thumbs-up and asks if you've survived the week. What do you reply?","options":[{"text":"\"All good, just busy\"","then":"Aman replies \"cool cool\". The weight stays right where it was."},{"text":"\"Barely. Rough week, honestly.\"","then":"Aman replies in seconds: \"Same here. Want to grab food?\"","best":true},{"text":"Leave it on read until you've sorted things","then":"The chat goes quiet. By night you feel more cut off."},{"text":"\"Lol\" and a meme to keep it light","then":"Aman laughs. The chat moves on, and so does your chance to say it."}],"why":"Saying it's rough, even in three words, takes some of the weight off."},{"prompt":"That night you can't sleep, and an old voice says real men deal with things alone. What do you tell yourself?","options":[{"text":"Fair. Talking about it would be weak","then":"You grit your teeth. Sleep comes late and thin."},{"text":"I'll talk once it gets really bad","then":"You set a line to wait for. The stress keeps edging toward it."},{"text":"Everyone needs to offload sometimes. So do I","then":"The voice quietens. You lie there thinking about who you could talk to.","best":true},{"text":"Grind harder tomorrow and it'll go away","then":"You plan an extra-long day. Just picturing it makes you tired."}],"why":"Help-seeking is strength for everyone. Carrying it alone isn't a test you have to pass."},{"prompt":"Next day your cousin Nikhil calls and asks how college is going. What do you say?","options":[{"text":"\"All good\", then ask about his job instead","then":"He talks for twenty minutes. You hang up feeling heavier."},{"text":"Say it's hard, then laugh it off at once","then":"He laughs too and moves on. The moment passes."},{"text":"\"It's been hard. Can I tell you about it?\"","then":"Nikhil goes quiet, then says, \"Of course. Go on.\"","best":true},{"text":"Complain about everyone making it harder","then":"He agrees they sound annoying. You still haven't said how you feel."}],"why":"A plain ask to talk opens the door. Laughing it off shuts it again."},{"prompt":"A week later the stress has eased a little, but it keeps coming back. What's your next step?","options":[{"text":"Wait and see if it settles on its own","then":"It eases one week and flares up the next. Nothing underneath changes."},{"text":"Hit the gym harder and not talk about it","then":"The workouts help for an hour. Then the stress is back."},{"text":"Decide you're just a stressed person","then":"The label sticks, and the weeks that follow feel the same."},{"text":"Book a chat with the campus counsellor","then":"The booking takes two minutes. You feel oddly lighter walking to class.","best":true}],"why":"Stress that keeps returning deserves real support. Reaching out early is the smart move."}],"debrief":"Telling one trusted person it's a rough day shares the load. Strength isn't carrying it alone.","relearn":"A short 'rough day' message to one person lightens stress more than grinding it out alone."},
  {"id":"mb-926","cat":"cope-well","type":"branch","persona":"any","source":"overwhelm list","hook":"Your to-do list has grown to twenty items and feels like one giant, impossible wall.","steps":[{"prompt":"It's Monday morning and you're staring at it while your tea goes cold. What do you do?","options":[{"text":"Rewrite the whole list neatly by priority","then":"The new list looks calmer. Forty minutes later, nothing on it is done."},{"text":"Try to finish five things before lunch","then":"You jump between all five. By lunch, none of them is finished."},{"text":"Keep staring until you know where to start","then":"The tea goes cold. So does the morning."},{"text":"Pick the smallest next step and just do it","then":"You reply to one email in four minutes. The wall has a small gap now.","best":true}],"why":"One tiny step breaks the freeze, and momentum does the rest."},{"prompt":"After lunch the list still looks long, and your energy dips. What do you do next?","options":[{"text":"Count everything left to see how bad it is","then":"The number sits on your chest all afternoon."},{"text":"Take a short walk, then pick the next small thing","then":"You come back and clear two more items before four.","best":true},{"text":"Push straight on without a break to catch up","then":"You keep going, but by four you're rereading the same line."},{"text":"Give up for today and start fresh tomorrow","then":"The evening is free, but the list follows you into it."}],"why":"A short break plus one small next step keeps you moving without burning out."},{"prompt":"That night the list comes to mind as you try to sleep. What do you do?","options":[{"text":"Get up and clear a few more items","then":"You finish two items and lose an hour of sleep."},{"text":"Go through the whole list in your head","then":"Your mind spins through the list until well past one."},{"text":"Note tomorrow's first small step and put it away","then":"With one step on paper, your mind lets go of the rest.","best":true},{"text":"Promise yourself you'll do all of it tomorrow","then":"The promise feels good for a minute, then heavy."}],"why":"Naming just the next step lets your mind rest instead of carrying the whole wall."}],"debrief":"Shrinking an overwhelming list to one tiny next step is how you get unstuck.","relearn":"Beat overwhelm by doing the smallest next step, not by staring at the whole list."},
  {"id":"mb-927","cat":"cope-well","type":"branch","persona":"Zoya","source":"family pressure","hook":"A tense call home has left you flat, and you want to skip everything today.","steps":[{"prompt":"You'd planned lunch with your friend Tara and a study session after. What do you do?","options":[{"text":"Cancel it all and stay in with the curtains shut","then":"The room is dark and quiet. The call keeps replaying."},{"text":"Keep both and act like nothing happened","then":"You get through both. By evening you feel emptied out."},{"text":"Keep lunch, and walk the long way there for air","then":"The walk clears your head a little. Tara waves from the corner table.","best":true},{"text":"Cancel lunch but make yourself study alone","then":"You stare at your notes. The call is louder than the words."}],"why":"Holding one small plan and getting air keeps you gently connected instead of sinking."},{"prompt":"Your mother messages: \"We only want what's best for you.\" What do you do?","options":[{"text":"Fire back everything you didn't say on the call","then":"Three long messages later, the tension is higher than before."},{"text":"Replay the whole call in your head all afternoon","then":"Every line gets sharper each time you replay it."},{"text":"Decide your hurt doesn't count, since she means well","then":"You swallow it and put the phone down. Inside, you feel smaller."},{"text":"Reply briefly that you'll talk at the weekend","then":"She sends a heart. The talk is still coming, but it has a time now.","best":true}],"why":"Setting a time to talk keeps the bond without letting the pressure run your day."},{"prompt":"That evening the heaviness comes back as the hostel goes quiet. What do you do?","options":[{"text":"Message a friend who knows how things are at home","then":"Tara replies: \"Ugh, those calls. Want to talk or be distracted?\"","best":true},{"text":"Scroll until you're too tired to think","then":"It's 2 a.m. The heaviness is still there, just tired now."},{"text":"Tell yourself you're overreacting and ungrateful","then":"Guilt piles on top of the flatness."},{"text":"Rehearse every argument for the next call home","then":"Your mind replays fights until late. Sleep comes slowly."}],"why":"Reaching a friend who understands eases the heaviness. None of this is your fault."},{"prompt":"A few days later the holidays are close, and you're dreading going home. What helps most?","options":[{"text":"Tell yourself you'll just get through it somehow","then":"The dread stays shapeless, and it grows as the date gets closer."},{"text":"Plan to win every argument this time","then":"You go home braced for a fight, and the first dinner turns tense fast."},{"text":"Plan anchors: friend calls, walks, some quiet time","then":"The trip still feels big, but now it has a few safe spots in it.","best":true},{"text":"Bury yourself in extra work so you won't think of it","then":"The work helps for a while. The dread waits for you at night."}],"why":"Small anchors keep you steady through family pressure, without a rupture."}],"debrief":"After a hard call, hold one small plan and get some air rather than cancelling your whole day.","relearn":"After a tense call home, keep one small plan and get air instead of shutting down."},
  {"id":"mb-928","cat":"cope-well","type":"branch","persona":"any","source":"can't switch off","hook":"It's late and you're exhausted, but your thoughts won't switch off.","steps":[{"prompt":"It's 1 a.m. and the same three worries keep circling. What do you do?","options":[{"text":"Argue with each thought until it goes away","then":"Every answer sparks a new worry. You're more awake than before."},{"text":"Write the worries down and put the page aside","then":"Written down, the worries look smaller. Your head feels a little emptier.","best":true},{"text":"Pick up your phone to distract yourself","then":"The screen lights up the room. Forty minutes pass and you're wide awake."},{"text":"Get up and start fixing one worry right now","then":"You open your laptop. By two you're wired and nothing is fixed."}],"why":"Parking worries on paper tells your mind they're safe till morning."},{"prompt":"A little later you're still wired, lying in the dark. What do you do?","options":[{"text":"Check the time and count the hours left","then":"Five hours, then four and a half. Each check winds you tighter."},{"text":"Tell yourself you'll be useless tomorrow","then":"The thought adds a fresh worry to the pile."},{"text":"Lie rigid and force yourself to sleep","then":"The harder you try, the more alert you feel."},{"text":"Breathe out slowly, longer each time","then":"Your breathing slows. The night starts to soften at the edges.","best":true}],"why":"Slow breathing calms your body, and sleep follows calm, not effort."},{"prompt":"The next evening you notice the worries starting up again. What do you do?","options":[{"text":"Stay up till you're too tired to think","then":"It works, sort of. You wake up drained."},{"text":"Give them ten minutes on paper, then wind down","then":"You write for ten minutes and dim the lights. Sleep comes earlier.","best":true},{"text":"Hope tonight will be different on its own","then":"You lie down hoping. The same worries turn up on time."},{"text":"Watch shows in bed until you drop off","then":"One more episode turns into three. It's past one again."}],"why":"A set worry time before bed builds a habit that helps your mind switch off."}],"debrief":"When thoughts won't stop, write them down and slow your breathing rather than wrestling them.","relearn":"When you can't switch off, park worries on paper and breathe slow instead of arguing with them."},
  {"id":"mb-929","cat":"cope-well","type":"branch","persona":"any","source":"missed the gym","hook":"You missed your morning run all week, and it feels like the whole routine's blown.","steps":[{"prompt":"It's Saturday and you've got a free hour. What do you do?","options":[{"text":"Wait for Monday and start fresh then","then":"The weekend slips by. Monday arrives packed and busy."},{"text":"Do a long, hard run to make up for the week","then":"You finish wiped out and too stiff to run again for days."},{"text":"Go for a ten-minute walk. That counts","then":"The air feels good. Ten minutes turns into twenty.","best":true},{"text":"Decide you're just not a running person","then":"The thought is almost a relief. It also closes the door."}],"why":"Starting small today beats waiting for a perfect fresh start."},{"prompt":"On Monday your alarm goes off and it's pouring with rain. What do you do?","options":[{"text":"Go back to sleep. The week's already off","then":"You sleep in. The all-or-nothing voice gets a little louder."},{"text":"Plan to run double tomorrow to catch up","then":"The plan makes tomorrow feel heavy before it's begun."},{"text":"Watch fitness videos in bed for motivation","then":"Twenty minutes of other people's workouts. You feel behind, still in bed."},{"text":"Stretch in your room for ten minutes","then":"It's not a run, but your body feels awake. The habit stays alive.","best":true}],"why":"A small version on a hard day keeps the habit alive. It needn't be all or nothing."},{"prompt":"Two weeks later exams hit, and you miss three days again. What do you tell yourself?","options":[{"text":"Here we go again. I never stick to anything","then":"The thought stings, and your running shoes stay by the door."},{"text":"A few missed days happen. Short walk tomorrow","then":"Tomorrow you walk for ten minutes, and the routine picks up again.","best":true},{"text":"I'll restart properly once exams are over","then":"Exams end, then a trip comes up. The proper restart keeps moving away."},{"text":"I'll run twice a day to make it up","then":"The plan sounds strong. You can't picture actually doing it."}],"why":"Slips are normal. Restarting small, soon, is what keeps a habit going."}],"debrief":"A skipped week isn't a blown routine. Restart small today instead of waiting for Monday.","relearn":"If you slip on a healthy habit, restart small today rather than writing it off."},
  {"id":"mb-930","cat":"cope-well","type":"branch","persona":"Meena","source":"long shift stress","hook":"After a ten-hour shift you're frayed, and there's no quiet corner at work or at home.","steps":[{"prompt":"On the crowded bus back to your shared room, your jaw is clenched tight. What do you do?","options":[{"text":"Push the feeling down. There's no time for it","then":"You get home still clenched, ready to snap at the first thing."},{"text":"Sip water and breathe out slowly for two minutes","then":"The bus is still loud, but the sharp edge in your chest softens.","best":true},{"text":"Replay every rude thing the supervisor said","then":"By your stop you're angrier than when you left work."},{"text":"Wait until you're home to calm down","then":"Home is noisy too. The calm you were waiting for never comes."}],"why":"A tiny reset right where you are works, even with no quiet space."},{"prompt":"At home, your roommate asks you to help cook before you've even sat down. What do you do?","options":[{"text":"Snap that you've had a long day too","then":"She goes quiet. The kitchen feels tense all evening."},{"text":"Help straight away and say nothing","then":"You help, but every small thing grates. You go to bed wound up."},{"text":"Ask for two minutes first, then help","then":"She nods. After a glass of water, chopping onions feels almost calm.","best":true},{"text":"Say you're not hungry and lie down","then":"The room stays noisy. You wake at midnight hungry and more tired."}],"why":"Asking for a short pause is fair. It lets you help without snapping."},{"prompt":"Tomorrow's shift will be just as long. What do you plan for it?","options":[{"text":"Get through it on willpower like always","then":"By evening you're frayed again, with four more days to go."},{"text":"Keep your head down and talk to no one","then":"The day passes in silence. You feel more alone with the strain."},{"text":"Hold on for a full rest day on Sunday instead","then":"Sunday feels far away. Monday to Saturday stay the same."},{"text":"Two short breaks for water and breathing","then":"The shift is hard, but you end it tired rather than frayed.","best":true}],"why":"Small, planned resets through the day stop the strain building up."}],"debrief":"Even two minutes to breathe and drink water resets you better than ploughing on frayed.","relearn":"After a draining shift, take two minutes to breathe and sip water before pushing on."},
  {"id":"mb-931","cat":"cope-well","type":"branch","persona":"any","source":"comparison scroll","hook":"You're stressed about placements, and you've just spent an hour scrolling everyone's highlights.","steps":[{"prompt":"Another post pops up: a classmate's big internship offer. What do you do?","options":[{"text":"Keep scrolling to see who else got offers","then":"Three more offers. Your stress climbs with each one."},{"text":"Mute her, then carry on scrolling","then":"Her post disappears. Someone else's news fills the gap."},{"text":"Put the phone in another room and make tea","then":"The kettle hums. Away from the screen, your chest loosens a little.","best":true},{"text":"Comment congratulations while feeling awful","then":"You post a smiley. The sinking feeling stays."}],"why":"Stepping away from the screen to do one real thing stops the spiral feeding itself."},{"prompt":"Later the thought comes: everyone is ahead of me. What do you tell yourself?","options":[{"text":"It's true. I'm falling behind","then":"The idea settles in, and your motivation drains away."},{"text":"Posts show the wins, not the waiting","then":"You remember your own feed looks shiny too. The thought loosens.","best":true},{"text":"I'll apply to fifty places tonight to catch up","then":"You open ten tabs and feel more frantic by the minute."},{"text":"I shouldn't feel jealous. It's petty","then":"Now you feel jealous and guilty at once."}],"why":"Remembering that feeds are highlight reels keeps comparison in proportion."},{"prompt":"The next evening stress builds, and your thumb reaches for the app again. What do you do?","options":[{"text":"Delete every app for good, right now","then":"It feels bold for a day. Then you reinstall one to check a message."},{"text":"Open it, but only for five minutes","then":"Five minutes turns into forty. The comparing starts up again."},{"text":"Take a short walk or call a friend first","then":"You come back calmer. Opening the app no longer feels urgent.","best":true},{"text":"Scroll, then feel bad about scrolling","then":"Now the stress and the guilt feed each other."}],"why":"Having a real-world swap ready makes it easier to step out of the scroll."}],"debrief":"When stress meets a comparison scroll, put the phone down and do one small real thing.","relearn":"When stressed and comparing online, put the phone down and do one small real-world thing."},
  {"id":"mb-932","cat":"cope-well","type":"branch","persona":"any","source":"angry text","hook":"Your flatmate Varun ate the food you'd saved for tomorrow, and you're furious.","steps":[{"prompt":"Your thumb is hovering over send on a long, heated message. What do you do?","options":[{"text":"Send it. He needs to know","then":"Varun fires back a sharp reply of his own. Now you're both angry."},{"text":"Save it as a draft and walk it off","then":"Ten minutes around the block, and your heart stops pounding.","best":true},{"text":"Delete it and act like you're not bothered","then":"The anger goes nowhere. It returns each time you open the fridge."},{"text":"Post it in the flat group chat instead","then":"Everyone sees it. The chat goes awkwardly silent."}],"why":"Cooling down first lets you choose what to say, instead of the anger choosing."},{"prompt":"An hour later you're calmer, but still annoyed. What do you do about it?","options":[{"text":"Stick a sharp note on the fridge door","then":"Varun reads it and goes stiff. The heat is still in the words."},{"text":"Drop it. It's not worth a fight","then":"It stays quiet, but you start eyeing the fridge whenever he's near."},{"text":"Complain about him to other friends","then":"They sympathise. Nothing between you and Varun gets sorted."},{"text":"Plan to talk to him face to face tonight","then":"You jot down what you want to say. It's much shorter than that first message.","best":true}],"why":"A calm talk in person sorts things out better than a heated text."},{"prompt":"That evening you and Varun end up in the kitchen together. What do you say?","options":[{"text":"Nothing. Wait for him to bring it up","then":"He makes his dinner and leaves. The annoyance goes to bed with you."},{"text":"\"You ate my food. Please ask next time.\"","then":"He winces. \"Sorry, I thought it was mine. I'll replace it.\"","best":true},{"text":"\"You always do this. You're so selfish.\"","then":"He folds his arms, and it turns into a shouting match."},{"text":"\"Enjoyed my food, did you?\" with a look","then":"Varun gives an awkward laugh and leaves. Nothing gets sorted."}],"why":"Naming what happened and what you need, calmly, gives him a fair chance to fix it."},{"prompt":"A week later something else sets you off, and the urge to fire off a text returns. What do you do?","options":[{"text":"Send it fast before you lose your nerve","then":"It lands harder than you meant. You spend the evening patching it up."},{"text":"Swallow it and say nothing, like always","then":"The anger folds up quietly and waits for next time."},{"text":"Wait one minute, then send it anyway","then":"A minute isn't long enough. The message still stings to read."},{"text":"Draft it, walk, and decide later","then":"By the time you're back, you know what you actually want to say.","best":true}],"why":"Making the pause a habit turns cooling down into part of how you cope."}],"debrief":"When anger spikes, draft it and walk before deciding. Cooling down is part of coping.","relearn":"When you're furious, save the message as a draft and walk before deciding to send."},
  {"id":"mb-933","cat":"cope-well","type":"branch","persona":"any","source":"weekend crash","hook":"You ran on empty all week, and now that the weekend's here, you feel guilty for resting.","steps":[{"prompt":"It's Saturday morning and nothing urgent is due. What do you do?","options":[{"text":"Start next week's work early to stay ahead","then":"You're at your desk by nine. By noon you're already tired."},{"text":"Rest, but check your email every hour","then":"You never quite switch off, so the rest doesn't really land."},{"text":"Stay in bed scrolling all day","then":"The day disappears into the screen. You feel neither rested nor done."},{"text":"Sleep in, eat well and do something you enjoy","then":"By afternoon you feel more like yourself than you have all week.","best":true}],"why":"Rest is recovery, not laziness. You don't have to earn it."},{"prompt":"That evening a friend texts that she's been working all weekend. What do you do?","options":[{"text":"Open your laptop and match her pace","then":"You work till midnight. Sunday starts tired."},{"text":"Notice the guilt, and rest anyway","then":"The guilt fades within the hour, and you sleep well.","best":true},{"text":"Tell her you've been working all weekend too","then":"Saying it makes resting feel like something to hide. The guilt lingers all evening."},{"text":"Keep resting, but call yourself lazy","then":"Your body rests. Your mind spends the evening criticising it."}],"why":"Someone else's pace isn't your rule. Rest is still what you need."},{"prompt":"On Sunday night you plan the week ahead. What do you build in?","options":[{"text":"More work, so next weekend can be fully free","then":"The plan is packed tight. You feel tired just reading it."},{"text":"Sleep, meals and one real break each day","then":"The week looks doable. There's space in it to breathe.","best":true},{"text":"Nothing. You'll see how it goes","then":"Monday arrives, and the week starts running you."},{"text":"One long rest day next Sunday, nothing before","then":"Monday to Saturday look just like last week."}],"why":"Building rest into the week stops you running on empty in the first place."}],"debrief":"After a draining week, rest is recovery, not laziness. You don't have to earn it.","relearn":"After running on empty, let yourself rest to recover instead of cramming the weekend with work."},
  {"id":"mb-934","cat":"cope-well","type":"branch","persona":"Deepak","source":"homesick evening","hook":"It's your third week in the hostel, far from home, and a homesick evening hits hard.","steps":[{"prompt":"The room is quiet, and everyone back home will be sitting down to eat. What do you do?","options":[{"text":"Scroll old photos from home for hours","then":"Every photo tugs harder. It's past midnight and the ache has grown."},{"text":"Call home for ten minutes","then":"Your little sister grabs the phone to tell you about her exam. You laugh for the first time today.","best":true},{"text":"Tell yourself to toughen up and study","then":"You open a book, but the heaviness sits on every page."},{"text":"Text home that all's fine, and leave it there","then":"Your mother sends a smiley. Somehow you feel further away."}],"why":"Hearing familiar voices eases homesickness. Hiding in old photos tends to deepen it."},{"prompt":"At lights out, home feels very far away. What do you do?","options":[{"text":"Decide you'll never really fit in here","then":"The thought follows you to sleep, and morning feels heavy."},{"text":"Plan one small thing for tomorrow","then":"You message Irfan from your lab. He's up for a walk after class tomorrow.","best":true},{"text":"Stay up watching shows till two","then":"Sleep is short. Tomorrow starts tired and just as far from home."},{"text":"Vow to join five clubs this week","then":"The list feels exciting, then exhausting. You don't start any of them."}],"why":"One small plan gives you something to move toward instead of sinking."},{"prompt":"At breakfast in the mess, you spot a batchmate from another state eating alone. What do you do?","options":[{"text":"Sit alone. He probably wants his space","then":"You both eat in silence, two tables apart."},{"text":"Smile at him, then look at your phone","then":"He smiles back. Neither of you says anything more."},{"text":"Sit with him and ask where he's from","then":"His name is Tenzin. He misses home too, and asks if you play Sunday football.","best":true},{"text":"Hurry through breakfast to get to class early","then":"You're first to class, and still on your own there."}],"why":"Reaching out to someone who may feel the same is how belonging starts."},{"prompt":"At the weekend the family WhatsApp group fills with photos from a cousin's function you missed. What do you do?","options":[{"text":"Zoom into every photo and feel left out","then":"Each photo makes the distance feel bigger."},{"text":"Mute the group so it can't sting","then":"The photos stop. So do the warm messages from home."},{"text":"Tell them you're too busy to miss anyone","then":"The joke lands flat, and it feels lonely to have said it."},{"text":"Send your wishes, then head out for a walk","then":"Your aunt replies with a heart. Outside, the evening feels less lonely.","best":true}],"why":"Staying lightly in touch while doing something real nearby keeps both worlds close."},{"prompt":"A few weeks on, homesickness still comes in waves, though less often. What do you tell yourself?","options":[{"text":"If I still miss home this much, I don't belong","then":"The thought makes each wave feel like proof."},{"text":"Waves are normal. If it stays heavy, I'll reach out","then":"The next wave comes and goes. You know what you'd do if it stayed.","best":true},{"text":"I should be completely over this by now","then":"Each wave now arrives with disappointment in yourself."},{"text":"Everyone else seems fine, so it must just be me","then":"You keep quiet, not knowing others on your corridor feel the same."}],"why":"Homesickness in waves is normal. Weeks of heavy low mood is the signal to reach for help."}],"debrief":"On a homesick evening, connect and plan one small next thing rather than sitting alone with it.","relearn":"Ease a homesick evening by connecting and planning one small next thing, not isolating."},
  {"id":"mb-935","cat":"cope-well","type":"branch","persona":"any","source":"caffeine spiral","hook":"At 4 p.m. you're wired and jittery, and you're reaching for a fourth coffee to push through.","steps":[{"prompt":"Your hands are shaky and you've reread one page three times. What do you do?","options":[{"text":"Drink it. You need to get this done","then":"Your heart races, and your focus scatters further."},{"text":"Swap it for water, a snack and a short walk","then":"Fifteen minutes later the jitters ease, and the page makes sense.","best":true},{"text":"Switch to an energy drink instead","then":"The buzz hits hard. So does the crash an hour later."},{"text":"Skip the coffee and push on without a break","then":"The jitters fade slowly, but you're still stuck on the same page."}],"why":"When you're already jittery, water, food and movement steady you better than more caffeine."},{"prompt":"By evening you feel tired, but your mind is still buzzing. What do you do?","options":[{"text":"Have another coffee to finish the work","then":"You finish at one, then lie awake till three."},{"text":"Work late until the buzz wears off","then":"It wears off at 2 a.m., along with any chance of real rest."},{"text":"Lie down now, with your phone in hand","then":"An hour of scrolling later, you're still buzzing."},{"text":"Eat a proper dinner and plan an early night","then":"With food in you, the buzz settles. By eleven your eyes are heavy.","best":true}],"why":"Food and a wind-down let a wired body settle so sleep can come."},{"prompt":"The next morning you're tired and tempted to start the same cycle. What do you plan?","options":[{"text":"Same as yesterday. It got the work done","then":"By four you're shaky again, rereading the same page."},{"text":"Quit caffeine completely, starting right now","then":"By noon a headache arrives, and the whole plan feels shaky."},{"text":"One morning coffee, then water and breaks","then":"By afternoon you're steadier than yesterday, without the shakes.","best":true},{"text":"Sleep in late to make up, then rush","then":"You wake at eleven, flustered, and reach straight for coffee."}],"why":"Pacing caffeine and adding water and breaks keeps your energy steady all day."}],"debrief":"When you're already jittery, water, food and a walk steady you better than more caffeine.","relearn":"When wired and jittery, choose water, a snack and a short walk over more caffeine."},
  {"id":"mb-936","cat":"cope-well","type":"branch","persona":"any","source":"one bad mark","hook":"One bad mark on a mid-sem test has you spiralling that you're failing at everything.","steps":[{"prompt":"You're staring at the mark on the portal and your chest feels tight. What do you do first?","options":[{"text":"Tell yourself you fail at everything","then":"The thought spreads to your other subjects, and your chest stays tight."},{"text":"Close the portal and act like it didn't happen","then":"It's out of sight, but it nags at you all day."},{"text":"Breathe, and name it as one result on one test","then":"The tightness loosens a little. It's one number, not your whole year.","best":true},{"text":"Check your classmates' marks to compare","then":"Most scored higher. Now it feels even bigger."}],"why":"Naming a setback as one result keeps it in proportion."},{"prompt":"The next day you have a free hour. What do you do about the test?","options":[{"text":"Go to office hours and ask what went wrong","then":"Your professor shows you two errors. Both are fixable.","best":true},{"text":"Look over the paper alone and guess","then":"You find one mistake and puzzle over the rest."},{"text":"Restart the whole syllabus from page one","then":"By evening you're on chapter two, exhausted, with the test still unexamined."},{"text":"Wait for the feeling to pass before looking","then":"By evening the feeling hasn't passed, and the paper stays unopened."}],"why":"Finding out what went wrong turns a bad mark into one clear fix."},{"prompt":"That evening your friend Priya asks how the test went. What do you say?","options":[{"text":"\"Fine,\" and change the subject","then":"The talk moves on. You carry the mark home alone."},{"text":"\"Terrible. I'm useless at everything.\"","then":"Priya looks worried and tries to cheer you up. Saying it makes you feel worse."},{"text":"\"How did you do?\" and compare marks","then":"She scored higher. The mark feels heavier than before."},{"text":"\"Not great. But it's just one test.\"","then":"Priya nods. \"I bombed one last sem too. Want to study together?\"","best":true}],"why":"Being honest and in proportion lets a friend support you."},{"prompt":"Before the next test, the fear of another bad mark creeps in. What do you do?","options":[{"text":"Cram every night so it never happens again","then":"By the test you're exhausted, and the fear is louder."},{"text":"Revise steadily and ask about anything unclear","then":"The fear doesn't vanish, but you have a plan to hold on to.","best":true},{"text":"Tell yourself you'll probably fail again","then":"The prediction follows you around all week."},{"text":"Put the test out of mind until the night before","then":"The night before arrives with all of it at once."}],"why":"One setback plus one fix is how you grow. Steady preparation beats fear."}],"debrief":"A single setback is one result. Name it, breathe and plan one step instead of letting it define everything.","relearn":"When a setback spirals, name it as one result and plan one fix, not 'I fail at everything'."},
  {"id":"mb-937","cat":"cope-well","type":"branch","persona":"Rohan","source":"saying yes too much","hook":"You've said yes to every plan, favour and group task, and you're stretched thin and resentful.","steps":[{"prompt":"Your friend Sahil asks you to help him move rooms tonight, your only free evening. What do you do?","options":[{"text":"Say yes. He'd do the same for you","then":"You spend the evening lugging boxes, quietly fuming."},{"text":"Say yes, then cancel an hour before","then":"Sahil scrambles for help. You feel guilty and still tired."},{"text":"Say not this time, and offer Sunday","then":"Sahil says Sunday works. Your evening opens up.","best":true},{"text":"Make up an excuse about a deadline","then":"He believes you. The small lie nags at you all evening."}],"why":"A kind, honest no protects your rest and still keeps the friendship."},{"prompt":"The next day your project lead adds another task under your name. What do you do?","options":[{"text":"Take it on and stay up late","then":"The work gets done. You get four hours of sleep."},{"text":"Take it on, then vent in the group chat","then":"The chat turns tense, and the task is still yours."},{"text":"Say nothing and quietly do less of everything","then":"Others notice the gaps before you've explained."},{"text":"Say you're at capacity and ask to share it out","then":"The lead moves half of it to others. Your list looks human again.","best":true}],"why":"Saying you're at capacity early is fair, and it keeps you from burning out."},{"prompt":"By the weekend, even the thought of saying no to anyone makes you feel guilty. What do you tell yourself?","options":[{"text":"Real friends never say no","then":"You start planning how to fit in even more for everyone."},{"text":"Protecting my rest isn't letting people down","then":"The guilt eases. You keep Saturday evening for yourself and actually rest.","best":true},{"text":"I'll say no once things calm down","then":"Things don't calm down. The stretched feeling rolls into another week."},{"text":"If I say no, they'll think I'm lazy","then":"You say yes to two more things, just in case."}],"why":"Saying a kind no to protect rest is healthy coping, not failing people."}],"debrief":"Saying a kind no to protect your rest is healthy coping, not letting people down.","relearn":"When stretched thin, protect rest with a kind 'not this time' instead of saying yes to everything."},
  {"id":"mb-938","cat":"cope-well","type":"branch","persona":"any","source":"frozen on task","hook":"You've been frozen at your desk for an hour, unable to start an essay due Thursday.","steps":[{"prompt":"The blank document is still open, with the cursor blinking. What do you do?","options":[{"text":"Wait until you feel motivated","then":"Another hour slips by before you finally type a first line."},{"text":"Research a bit more before you begin","then":"Twelve tabs later, you know more, and only now start writing."},{"text":"Set a five-minute timer and write badly","then":"The first lines are clumsy. When the timer rings, you have a paragraph.","best":true},{"text":"Clean your whole room first to clear your head","then":"The room sparkles. It's evening before you type a word."}],"why":"A tiny timed start breaks the freeze. Motivation usually follows action, not the other way round."},{"prompt":"Later, a few paragraphs in, you hit a hard section and feel the freeze creeping back. What do you do?","options":[{"text":"Stay on it until it's perfect","then":"You rewrite one sentence for half an hour."},{"text":"Tell yourself you're just bad at writing","then":"The words dry up completely."},{"text":"Take a quick break on your phone","then":"The phone pulls you in. Forty minutes later the freeze is back at full strength."},{"text":"Skip it for now and write the next easy bit","then":"The easy bit flows, and the hard section looks smaller when you return.","best":true}],"why":"Moving around a hard patch keeps your momentum instead of letting it stall."},{"prompt":"The next morning you sit down to finish, and the same dread shows up. What do you do?","options":[{"text":"Set a five-minute timer and just begin","then":"Once you start, it gets easier. Soon you forget the timer is running.","best":true},{"text":"Wait until after lunch, when you might feel sharper","then":"After lunch you feel sleepy, and the dread has grown."},{"text":"Plan to do it all in one go the night before","then":"The dread follows you around for two more days."},{"text":"Reread yesterday's paragraph five times first","then":"You fiddle with the same lines, and the essay doesn't move."}],"why":"A small timed start builds momentum each time the dread shows up."}],"debrief":"When frozen, a tiny timed start beats waiting for motivation that may not come.","relearn":"When you can't start, set a five-minute timer and begin badly rather than waiting for motivation."},
  {"id":"mb-939","cat":"cope-well","type":"branch","persona":"any","source":"skipped meals","hook":"You've skipped meals all day to study, and now you feel shaky and snappy.","steps":[{"prompt":"It's 7 p.m. and you still have two chapters to go. What do you do?","options":[{"text":"Push on hungry so you don't waste time","then":"You read the same paragraph four times, getting snappier."},{"text":"Grab a packet of biscuits and keep going","then":"The sugar helps for half an hour. Then you're shaky again."},{"text":"Stop and eat a proper meal first","then":"Twenty minutes later your hands are steady, and the words make sense again.","best":true},{"text":"Have a strong coffee instead","then":"On an empty stomach, the coffee makes your hands shake more."}],"why":"Food isn't a distraction from work. A fed brain copes and focuses far better."},{"prompt":"Later your roommate Neha says you snapped at her earlier. What do you say?","options":[{"text":"Tell her she's being too sensitive","then":"She goes quiet, and the room feels chilly all night."},{"text":"Say sorry, and that you'd skipped meals","then":"Neha laughs. \"Hungry you is scary. Apology accepted.\"","best":true},{"text":"Apologise and promise it will never happen again","then":"She nods, unsure. You both know another bad day will come."},{"text":"Say nothing and put your headphones on","then":"The tension sits between you until morning."}],"why":"Owning it simply, and naming why, repairs things and helps you spot the pattern."},{"prompt":"The next day is packed with classes and study again. How do you plan your food?","options":[{"text":"Eat whenever you happen to remember","then":"You remember at four, shaky again."},{"text":"One big meal at night to save time","then":"The afternoon drags, and you're foggy by three."},{"text":"Coffee through the day, and eat later","then":"By noon your hands are shaking again."},{"text":"Set meal times and pack a snack for class","then":"By evening you've eaten three times and feel steadier than yesterday.","best":true}],"why":"Planning food into a busy day keeps your focus and mood steady."}],"debrief":"Food isn't a distraction from work. A fed brain copes and focuses far better.","relearn":"When shaky from skipping meals, stop and eat properly before more work."},
  {"id":"mb-940","cat":"cope-well","type":"branch","persona":"Zoya","source":"dreading a thing","hook":"You're dreading a call with your mother about the holidays, and it's hijacking your whole day.","steps":[{"prompt":"It's 10 a.m. and the dread is already looping. What do you do?","options":[{"text":"Let it loop and hope it passes","then":"By lunch you've replayed it twenty times and done nothing else."},{"text":"Call her right now, still wound up, to get it over with","then":"The call goes round in circles until she has to go. Nothing is settled."},{"text":"Set a time for the call, then park it till then","then":"You text her to ask about seven. The rest of the day loosens.","best":true},{"text":"Keep busy all day so you don't think about it","then":"You tidy, shop and reorganise. The dread follows you from job to job."}],"why":"Containing a worry to a set time frees the rest of your day."},{"prompt":"In the afternoon the worry pops up again in the middle of class. What do you do?","options":[{"text":"Tell yourself you'll deal with it this evening","then":"The worry steps back. You catch the rest of the lecture.","best":true},{"text":"Write out every possible argument in your notes","then":"The lecture goes past unheard. Your notebook fills with worst cases."},{"text":"Scold yourself for not being able to focus","then":"Now you're worried and annoyed with yourself."},{"text":"Leave class to think it through properly","then":"You sit on a bench outside, going round in circles."}],"why":"Giving the worry its own time this evening lets you come back to now."},{"prompt":"That evening, as you pick up your phone to call her, your stomach tightens. What do you do?","options":[{"text":"Scroll for a while first to calm down","then":"Half an hour later you're jittery, with nothing clear to say."},{"text":"Tell yourself your side doesn't matter","then":"The nerves quieten, and you feel yourself shrinking."},{"text":"Note one or two points, then breathe slowly","then":"The list is short. You feel ready enough.","best":true},{"text":"Script every word she might say","then":"The script grows long, and your stomach tightens further."}],"why":"A short plan and a slow breath let you go in steady. Your side matters too."}],"debrief":"Containing a worry to a set time stops it hijacking everything else.","relearn":"When dread hijacks your day, schedule a time to handle it and park it till then."},
  {"id":"mb-941","cat":"cope-well","type":"branch","persona":"any","source":"good day too","hook":"You're having a rare good day after a hard few weeks, and you feel oddly guilty about feeling okay.","steps":[{"prompt":"In the afternoon you catch yourself humming. What do you do with the feeling?","options":[{"text":"Brace yourself for it to crash","then":"Waiting for the fall, you stop noticing the good bits."},{"text":"Tell yourself you don't deserve it yet","then":"The humming stops, and the day turns grey at the edges."},{"text":"Use the energy to catch up on everything","then":"You race through tasks all afternoon, and by evening you're running on empty."},{"text":"Let yourself enjoy it","then":"The afternoon feels light. You finish two things without forcing it.","best":true}],"why":"Good days are part of coping too. You're allowed to enjoy them."},{"prompt":"That evening a friend asks how you've been lately. What do you say?","options":[{"text":"\"Great! Everything's fine now.\"","then":"Your friend relaxes. The hard weeks stay unspoken."},{"text":"\"Today was good. The last few weeks were hard.\"","then":"Your friend smiles. \"I'm glad. Tell me about the hard bit too.\"","best":true},{"text":"Play the good day down so you don't jinx it","then":"Your friend looks worried. You're not sure why you said it."},{"text":"Ask about their week instead","then":"They talk about their exams for an hour. You never get to your own news."}],"why":"Being honest about the good and the hard helps a friend stay close."},{"prompt":"Before bed you think back over the day. What do you do?","options":[{"text":"Assume it was luck and won't last","then":"You fall asleep already bracing for tomorrow."},{"text":"Note down what helped: sleep, a walk, a call","then":"You spot a pattern. The list goes up on the back of your door.","best":true},{"text":"Plan to do exactly the same every day now","then":"The plan feels rigid. By Wednesday it's already slipping."},{"text":"Push it out of mind so you don't get hopeful","then":"The good feeling fades without leaving a trace."}],"why":"Noticing what helped gives you a map for harder days."}],"debrief":"Good days are part of coping too. Savour them and notice what helped, guilt-free.","relearn":"On a good day, enjoy it and notice what helped, instead of bracing for a crash."},
  {"id":"mb-942","cat":"cope-well","type":"spot","persona":"any","source":"spot the drainers","hook":"Spot the two habits that drain you, not steady you.","scene":[{"id":"a","text":"A short walk after a hard class","trick":false},{"id":"b","text":"Pulling another all-nighter","trick":true},{"id":"c","text":"Texting a friend when it's heavy","trick":false},{"id":"d","text":"Skipping meals to save time","trick":true},{"id":"e","text":"A few slow breaths to reset","trick":false}],"why":"All-nighters and skipping meals drain you; walking, reaching out and breathing steady you.","relearn":"Walking, reaching out and breathing steady you; all-nighters and skipping meals drain you."},
  {"id":"mb-943","cat":"cope-well","type":"spot","persona":"any","source":"spot the traps","hook":"Spot the two coping traps that feel easy but cost you later.","scene":[{"id":"a","text":"A proper meal and some water","trick":false},{"id":"b","text":"Numbing it for hours on end","trick":true},{"id":"c","text":"An early night before a big day","trick":false},{"id":"d","text":"Bottling it all up alone","trick":true},{"id":"e","text":"A quick call with a friend","trick":false}],"why":"Numbing for hours and bottling up feel easy now but cost you later; meals, sleep and connection don't.","relearn":"Meals, sleep and connection are real coping; numbing and bottling up only feel easy now and cost you later."},
  {"id":"mb-944","cat":"cope-well","type":"spot","persona":"any","source":"spot the spike-feeders","hook":"In a stress spike, spot the two moves that add fuel.","scene":[{"id":"a","text":"Step outside for a minute","trick":false},{"id":"b","text":"Spiral into 'everything's ruined'","trick":true},{"id":"c","text":"Slow your breathing out","trick":false},{"id":"d","text":"Snap at whoever's nearest","trick":true},{"id":"e","text":"Sip water slowly","trick":false}],"why":"Spiralling and snapping add fuel to a spike; stepping out, slow breathing and water calm it.","relearn":"Stepping out, slow breathing and water calm a spike; spiralling and snapping add fuel."},
  {"id":"mb-945","cat":"cope-well","type":"spot","persona":"Deepak","source":"spot deadline traps","hook":"Deadline week: spot the two moves that burn you out.","scene":[{"id":"a","text":"Break the work into chunks","trick":false},{"id":"b","text":"One marathon all-nighter","trick":true},{"id":"c","text":"A short walk between chunks","trick":false},{"id":"d","text":"Skip every meal to save time","trick":true},{"id":"e","text":"Sleep before the early start","trick":false}],"why":"All-nighters and skipped meals burn you out; chunking, walks and sleep keep you going.","relearn":"Chunking, walks and sleep keep you going in deadline week; all-nighters and skipped meals burn you out."},
  {"id":"mb-946","cat":"cope-well","type":"spot","persona":"any","source":"spot harsh self-talk","hook":"Spot the two lines that are harsh self-talk, not steadying.","scene":[{"id":"a","text":"'This is hard; I'll go bit by bit'","trick":false},{"id":"b","text":"'I'm useless and always will be'","trick":true},{"id":"c","text":"'I'm doing my best with a lot on'","trick":false},{"id":"d","text":"'Everyone's ahead; I'm a failure'","trick":true},{"id":"e","text":"'A break will help me think'","trick":false}],"why":"'I'm useless' and 'I'm a failure' are harsh, draining self-talk; the others are kind and steadying.","relearn":"Kind, bit-by-bit self-talk steadies you; 'I'm useless' or 'I'm a failure' just drains you."},
  {"id":"mb-947","cat":"cope-well","type":"spot","persona":"any","source":"spot low-patch traps","hook":"In a low patch, spot the two moves that quietly deepen it.","scene":[{"id":"a","text":"Keep one small daily routine","trick":false},{"id":"b","text":"Drop everything and withdraw","trick":true},{"id":"c","text":"Text one person you trust","trick":false},{"id":"d","text":"Tell yourself you're a burden","trick":true},{"id":"e","text":"Get a little daylight and air","trick":false}],"why":"Withdrawing and 'I'm a burden' deepen a low patch; routine, reaching out and daylight gently help.","relearn":"Routine, reaching out and daylight gently help a low patch; withdrawing and self-blame deepen it."},
  {"id":"mb-948","cat":"cope-well","type":"spot","persona":"any","source":"spot fake rest","hook":"Spot the two things that look like rest but don't actually rest you.","scene":[{"id":"a","text":"A quiet walk with no phone","trick":false},{"id":"b","text":"Two hours doom-scrolling the feed","trick":true},{"id":"c","text":"A short nap or eyes closed","trick":false},{"id":"d","text":"Refreshing bad news on a loop","trick":true},{"id":"e","text":"Sitting outside with a chai","trick":false}],"why":"Doom-scrolling and refreshing bad news leave you more drained; a walk, a nap or sitting outside actually rest you.","relearn":"A walk, a nap or sitting outside rest you; doom-scrolling and news-refreshing only look like rest."},
  {"id":"mb-949","cat":"cope-well","type":"spot","persona":"Meena","source":"spot what needs money","hook":"Spot the two 'coping tips' that wrongly assume money or a campus.","scene":[{"id":"a","text":"A free walk around the block","trick":false},{"id":"b","text":"Book a pricey weekend retreat","trick":true},{"id":"c","text":"Slow breathing on a break","trick":false},{"id":"d","text":"Buy a paid wellness app","trick":true},{"id":"e","text":"A free call to Tele-MANAS 14416","trick":false}],"why":"Retreats and paid apps assume money you may not have; a walk, breathing and a free helpline don't.","relearn":"A walk, breathing and a free helpline cost nothing; retreats and paid apps wrongly assume money."},
  {"id":"mb-950","cat":"cope-well","type":"spot","persona":"any","source":"spot all-or-nothing","hook":"Spot the two all-or-nothing thoughts that sabotage your routine.","scene":[{"id":"a","text":"'A ten-minute walk still counts'","trick":false},{"id":"b","text":"'I skipped once, so why bother'","trick":true},{"id":"c","text":"'Some basics beat none today'","trick":false},{"id":"d","text":"'No perfect plan means no plan'","trick":true},{"id":"e","text":"'I can restart small right now'","trick":false}],"why":"'Why bother' and 'no perfect plan means no plan' sabotage you; partial effort still counts.","relearn":"Partial effort still counts; all-or-nothing thoughts like 'why bother' sabotage a routine."},
  {"id":"mb-951","cat":"cope-well","type":"spot","persona":"any","source":"spot what fuels nerves","hook":"Before a big moment, spot the two things that feed the nerves.","scene":[{"id":"a","text":"A few slow out-breaths","trick":false},{"id":"b","text":"Reading the worst-case over and over","trick":true},{"id":"c","text":"Feet planted, shoulders down","trick":false},{"id":"d","text":"A fourth strong coffee","trick":true},{"id":"e","text":"A sip of water and a pause","trick":false}],"why":"Rehearsing the worst case and extra caffeine feed the nerves; breathing, grounding and water settle them.","relearn":"Breathing, grounding and water settle nerves; rehearsing the worst case or more caffeine feeds them."},
  {"id":"mb-952","cat":"cope-well","type":"spot","persona":"Rohan","source":"spot lonely-cope traps","hook":"Stressed and alone: spot the two moves that leave the weight all on you.","scene":[{"id":"a","text":"Text one person 'rough day'","trick":false},{"id":"b","text":"Go fully silent and grind solo","trick":true},{"id":"c","text":"Join a friend for a quick chai","trick":false},{"id":"d","text":"Decide no one would get it","trick":true},{"id":"e","text":"Ask someone for a hand","trick":false}],"why":"Going silent and 'no one would get it' leave the weight on you; reaching out shares the load.","relearn":"Reaching out shares the load; going silent or assuming no one gets it leaves it all on you."},
  {"id":"mb-953","cat":"cope-well","type":"match","persona":"any","source":"tool to moment","hook":"Match the healthy coping tool to the moment it fits.","pairs":[{"left":"Slow breathing","right":"A sudden stress spike"},{"left":"A proper meal","right":"Shaky after skipping food"},{"left":"An early night","right":"Foggy before a big day"},{"left":"Texting a friend","right":"A heavy, lonely evening"},{"left":"A short walk","right":"Frozen and can't start"}],"relearn":"Breathing for spikes, food for shaky, sleep for fog, a friend for lonely, a walk to get unstuck."},
  {"id":"mb-954","cat":"cope-well","type":"match","persona":"any","source":"draining to healthy","hook":"Match each draining habit to the healthy swap.","pairs":[{"left":"Numbing for hours","right":"A real break, then connect"},{"left":"Bottling it up","right":"Telling one trusted person"},{"left":"All-nighters","right":"Sleep, then finish fresh"},{"left":"Skipping meals","right":"Eating something proper"},{"left":"Harsh self-talk","right":"Talking to yourself kindly"}],"relearn":"Swap numbing for a break and connection, bottling for sharing, all-nighters for sleep, skipping for eating, harshness for kindness."},
  {"id":"mb-955","cat":"cope-well","type":"match","persona":"any","source":"feeling to first step","hook":"Match the hard feeling to a gentle first step.","pairs":[{"left":"Overwhelmed","right":"Do the smallest next thing"},{"left":"Wired and jittery","right":"Water and a short walk"},{"left":"Flat and low","right":"Daylight and one small plan"},{"left":"Furious","right":"Walk it off before deciding"},{"left":"Can't switch off","right":"Park worries on paper"}],"relearn":"Smallest step for overwhelm, water and a walk for jittery, daylight for low, a walk for fury, paper for a racing mind."},
  {"id":"mb-956","cat":"cope-well","type":"match","persona":"any","source":"basic to what it protects","hook":"Match the daily basic to what it quietly protects.","pairs":[{"left":"Regular sleep","right":"Your focus and patience"},{"left":"Regular meals","right":"Steady energy and mood"},{"left":"Daily movement","right":"A calmer, clearer head"},{"left":"Staying in touch","right":"Feeling less alone"},{"left":"Short breaks","right":"Not burning out"}],"relearn":"Sleep protects focus, meals steady mood, movement clears your head, contact eases loneliness, breaks prevent burnout."},
  {"id":"mb-957","cat":"cope-well","type":"match","persona":"any","source":"myth to truth","hook":"Match each coping myth to the truth that answers it.","pairs":[{"left":"'Stress means I'm weak'","right":"It's a normal human response"},{"left":"'Rest must be earned'","right":"Rest is a need, not a reward"},{"left":"'One big fix exists'","right":"It's many small habits"},{"left":"'This feeling is forever'","right":"Feelings shift over time"},{"left":"'Talking makes it bigger'","right":"Sharing it makes it lighter"}],"relearn":"Stress is normal, rest is a need, coping is small habits, feelings shift, and sharing lightens the load."},
  {"id":"mb-958","cat":"cope-well","type":"match","persona":"Meena","source":"need to free route","hook":"Match the need to a free coping route that needs no campus.","pairs":[{"left":"Need to calm down fast","right":"Slow breathing, anywhere"},{"left":"Need to move a little","right":"A walk around the block"},{"left":"Need to talk to someone","right":"A free call to a trusted person"},{"left":"Need real support now","right":"Tele-MANAS 14416, free, 24/7"},{"left":"Need to reset the day","right":"Daylight and a few minutes out"}],"relearn":"Breathing to calm, a walk to move, a trusted person to talk, Tele-MANAS 14416 for support, daylight to reset: all free."},
  {"id":"mb-959","cat":"cope-well","type":"match","persona":"any","source":"trap to cost","hook":"Match the coping trap to what it quietly costs you.","pairs":[{"left":"All-nighters","right":"Worse recall and mood"},{"left":"Doom-scrolling","right":"More drained, not rested"},{"left":"Bottling up","right":"All the weight on you"},{"left":"Skipping meals","right":"Shaky focus and temper"},{"left":"Saying yes to all","right":"Burnout and resentment"}],"relearn":"All-nighters cost recall, scrolling drains you, bottling isolates, skipping meals frays focus, over-committing burns you out."},
  {"id":"mb-960","cat":"cope-well","type":"match","persona":"any","source":"setting to coping","hook":"Match the everyday setting to a coping move that fits it.","pairs":[{"left":"Crowded hostel room","right":"Step out for some air"},{"left":"Long bus commute","right":"Slow breathing with eyes shut"},{"left":"Library before exams","right":"Short breaks between chunks"},{"left":"Late night, can't sleep","right":"Worries on paper, dim lights"},{"left":"After a tense call home","right":"One small plan and a walk"}],"relearn":"Step out in a crowd, breathe on the bus, break up library time, write worries down at night, plan small after a hard call."},
  {"id":"mb-961","cat":"cope-well","type":"role-play","persona":"Rohan","source":"asking for the night off","hook":"Your friends want a late night out, but you're fried after a long week.","setup":"Kunal knocks on your door, shoes already on.","steps":[{"prompt":"Kunal says: \"We're leaving in ten. You're coming, right?\"","options":[{"text":"\"Yeah, fine. Give me five minutes.\"","then":"Kunal grins. \"That's the spirit. Meet you downstairs.\""},{"text":"\"I'm wiped tonight. I need an early one.\"","then":"Kunal pauses. \"Fair. You did look dead in class.\"","best":true},{"text":"\"I can't. I've got a family call.\"","then":"\"Oh, okay,\" Kunal says. \"Say hi to them.\""},{"text":"\"Maybe. I'll see how I feel.\"","then":"\"So that's a yes,\" Kunal says. \"I'll knock again in ten.\""}],"why":"Saying plainly that you need rest is honest and kind, and it protects your energy."},{"prompt":"At lunch the next day, Kunal says: \"You look wiped out a lot lately. What's going on?\"","options":[{"text":"\"Nothing. I'm fine.\"","then":"He shrugs. \"Okay, if you say so.\""},{"text":"\"Just exams. It'll pass once they're done.\"","then":"\"Cool,\" Kunal says, and moves on to cricket."},{"text":"\"Why, are you keeping count?\"","then":"He raises his hands. \"Whoa. Just asking.\""},{"text":"\"It's been heavy. I'm running on empty.\"","then":"Kunal puts his fork down. \"Man. Why didn't you say?\"","best":true}],"why":"Naming that you're running on empty lets a friend understand instead of guess."},{"prompt":"Kunal says: \"The gang's planning Saturday. Would you come if it's something chill?\"","options":[{"text":"\"Nah. I'll just stay in all weekend.\"","then":"\"Okay,\" he says slowly. \"Tell me if you change your mind.\""},{"text":"\"Whatever you guys pick is fine.\"","then":"\"Cool,\" Kunal says. By evening, the group has picked another late one."},{"text":"\"Yes. Chai and a walk in the afternoon?\"","then":"\"Done,\" Kunal says. \"Honestly, I could use a quiet one too.\"","best":true},{"text":"\"Let's do a late one. I'll push through.\"","then":"\"Legend,\" Kunal says, already texting the group."}],"why":"Offering a low-key plan protects your rest and keeps you close to your friends."}],"relearn":"It's healthy to say a kind no and protect your rest when you're running on empty."},
  {"id":"mb-962","cat":"cope-well","type":"role-play","persona":"any","source":"naming a rough day","hook":"You've had a rough day: a bad class, then a tense phone call with home.","setup":"Your friend Meher finds you sitting on the hostel steps.","steps":[{"prompt":"Meher asks: \"Hey, how are you doing?\"","options":[{"text":"\"All good!\"","then":"Meher tilts her head. \"You sure? You look done in.\""},{"text":"\"Fine. Just tired.\"","then":"\"Tired or tired-tired?\" Meher asks, sitting down."},{"text":"\"Honestly, rough day. Could use some company.\"","then":"Meher sits down beside you. \"I've got time. What happened?\"","best":true},{"text":"\"Don't ask. Everything's a mess.\"","then":"Meher hesitates. \"Oh. Do you want me to leave you alone?\""}],"why":"Naming a rough day, even briefly, lets someone share the weight."},{"prompt":"Meher says: \"I'm here. Want to talk about it, or just sit for a bit?\"","options":[{"text":"\"It's nothing. Other people have it worse.\"","then":"Meher frowns. \"It's not a competition, you know.\""},{"text":"\"Talk, I think. It's been a lot today.\"","then":"Meher nods and waits. The words come slowly, then easier.","best":true},{"text":"\"Just sit. I don't want to be a burden.\"","then":"\"You're not,\" Meher says. You sit, the day still bottled up."},{"text":"\"Nah, you go. I'll be fine alone.\"","then":"Meher stands, unsure. \"Okay. Text me if you want.\""}],"why":"Letting someone in when they offer is how support starts. You're not a burden."},{"prompt":"Later that evening, Meher texts: \"Still thinking of you. How's the evening going?\"","options":[{"text":"\"Fine!\" with a thumbs-up","then":"Meher sends a heart. The chat goes quiet."},{"text":"\"Sorry for being such a downer today.\"","then":"\"You weren't,\" Meher replies. \"Rough days happen to everyone.\""},{"text":"\"Up and down, honestly. Thanks for asking.\"","then":"\"Anytime,\" Meher replies. \"Breakfast tomorrow?\"","best":true},{"text":"\"Don't worry about me. I'll sort myself out.\"","then":"\"Okay,\" Meher replies, unsure what else to say."}],"why":"Closing the loop honestly keeps the door open for next time."},{"prompt":"The next week, Meher says: \"You seem a bit low again today. Rough one?\"","options":[{"text":"\"No, no. I'm fine.\"","then":"\"Okay,\" she says, but she keeps glancing at you."},{"text":"\"Yeah, but I don't want to keep bothering you.\"","then":"\"You're not bothering me,\" Meher says. \"But okay, if you're sure.\""},{"text":"\"Why do you keep asking me that?\"","then":"Meher flushes. \"Sorry. I just care. That's all.\""},{"text":"\"Yeah. Can we grab chai and talk?\"","then":"\"Let's go,\" she says, already picking up her bag.","best":true}],"why":"Saying so again, simply, is how a friendship carries the weight together."}],"relearn":"Naming a rough day to someone you trust shares the weight instead of carrying it alone."},
  {"id":"mb-963","cat":"cope-well","type":"role-play","persona":"any","source":"taking a break","hook":"It's late in your study group's session, and everyone is flagging.","setup":"Aditi, who organises the group, looks up from her notes.","steps":[{"prompt":"Aditi says: \"Two more hours straight and we finish the syllabus. Agreed?\"","options":[{"text":"\"Sure, let's power through.\"","then":"\"Great,\" Aditi says. Across the table, Rahul yawns loudly."},{"text":"\"Let's take ten to breathe and refuel first.\"","then":"Aditi sighs, then nods. \"Okay. Ten minutes. Chai's on me.\"","best":true},{"text":"\"I'll stay, but I'm taking a break on my own.\"","then":"Aditi shrugs. \"Suit yourself.\" The others keep going, heads drooping."},{"text":"\"We're all exhausted. This plan is pointless.\"","then":"Aditi's face tightens. \"Fine. Then you plan it.\""}],"why":"A short break helps everyone think clearer. Suggesting it isn't slacking."},{"prompt":"An hour later, Rahul rubs his eyes and says: \"I've read this line five times.\"","options":[{"text":"\"Just push. We're nearly there.\"","then":"Rahul groans and goes back to the same line."},{"text":"\"Maybe go home and sleep, then.\"","then":"Rahul hesitates. \"And miss the last chapter? No way.\""},{"text":"\"Same. Let's all stand up and stretch.\"","then":"Rahul laughs and stands. Two others join him.","best":true},{"text":"\"Have another coffee.\"","then":"\"That'll be my fourth,\" Rahul says, and pours it anyway."}],"why":"Naming the tiredness and moving together resets the group without blame."},{"prompt":"At the end, Aditi asks: \"Same time tomorrow? Same plan?\"","options":[{"text":"\"Yes, with a short break every hour.\"","then":"\"Deal,\" Aditi says, writing it into the plan.","best":true},{"text":"\"Sure, same as today.\"","then":"\"Perfect,\" Aditi says. Rahul quietly groans."},{"text":"\"I'll study alone from now on.\"","then":"Aditi looks hurt. \"Oh. Okay, if that's easier.\""},{"text":"\"Let's do four hours straight and be done.\"","then":"Aditi laughs. \"Ambitious. Okay, if you say so.\""}],"why":"Building breaks into the plan helps the whole group, every day."}],"relearn":"Suggesting a short break to refuel helps everyone think clearer: it isn't slacking."},
  {"id":"mb-964","cat":"cope-well","type":"role-play","persona":"any","source":"talking to yourself","hook":"You forgot to submit a form on time, and your inner voice is turning harsh.","setup":"Alone in your room, you decide to answer it back.","steps":[{"prompt":"Your inner voice says: \"Typical. You always mess everything up.\"","options":[{"text":"\"You're right. I'm useless at all of this.\"","then":"The voice gets louder. \"See? Even you agree.\""},{"text":"\"That stings. I'm human, and it's one form.\"","then":"The voice pauses. \"Still, you should have remembered.\"","best":true},{"text":"\"Shut up. I don't even care.\"","then":"The voice goes quiet, then comes back ten minutes later."},{"text":"\"I'll never, ever let anything slip again.\"","then":"The voice sounds pleased. \"Good. Never again. Not once.\""}],"why":"Talking to yourself like a friend steadies you. Harsh self-talk only drains you."},{"prompt":"The voice adds: \"Everyone else remembers these things. Why can't you?\"","options":[{"text":"\"Maybe I'm just not cut out for this.\"","then":"The voice agrees, and the room feels smaller."},{"text":"\"I'll just not think about it.\"","then":"The voice waits, then returns the moment you lie down."},{"text":"\"Lots of people miss things. What's the fix?\"","then":"The voice softens. \"Email the office, I suppose.\"","best":true},{"text":"\"Because I'm lazy. I deserve to feel bad.\"","then":"The voice settles in for the evening."}],"why":"Remembering that everyone slips, and looking for a fix, turns blame into a next step."},{"prompt":"The voice asks: \"What if they won't accept it late?\"","options":[{"text":"\"Then I've ruined everything.\"","then":"The voice swells. Your chest tightens, and the email stays unwritten."},{"text":"\"Then I'll just pretend it never happened.\"","then":"The voice keeps whispering \"what if\" all night."},{"text":"\"Someone should have reminded me. It's on them.\"","then":"The voice shifts its blame, but the worry stays."},{"text":"\"Then I'll ask about my options. I can handle it.\"","then":"The voice goes quiet. You open your email.","best":true}],"why":"A calm, kind voice helps you face the next step instead of freezing."}],"relearn":"Speaking to yourself kindly after a slip steadies you; harsh self-talk just drains you."},
  {"id":"mb-965","cat":"cope-well","type":"role-play","persona":"Deepak","source":"asking for an extension","hook":"You're overwhelmed this week, and two extra days on one assignment would really help.","setup":"You catch Professor Rao as the class empties out.","steps":[{"prompt":"Professor Rao asks: \"Yes? What can I do for you?\"","options":[{"text":"\"Sorry, it's nothing. It's okay.\"","then":"She tilts her head. \"You look worried. Are you sure?\""},{"text":"\"My laptop crashed, so I need more time.\"","then":"\"That's unlucky,\" she says. \"Did you back anything up?\""},{"text":"\"I'm stretched thin. Could I have two more days?\"","then":"She looks up from her papers. \"Two days? Let's see.\"","best":true},{"text":"\"Everyone's struggling. Could you extend it for all of us?\"","then":"She frowns. \"Nobody else has said so. Is this about you?\""}],"why":"Asking plainly for what you need, without an excuse, makes it easy to say yes."},{"prompt":"Professor Rao says: \"I may be able to help. Tell me a bit about what's going on.\"","options":[{"text":"\"It's nothing serious. I'm just slow at this stuff.\"","then":"She shakes her head. \"I doubt that. You look worn out, though.\""},{"text":"\"Three deadlines at once, and I'm behind.\"","then":"She nods slowly. \"That's a lot. Thanks for saying it plainly.\"","best":true},{"text":"\"I don't want to make excuses. Forget it.\"","then":"\"It's not an excuse if it's true,\" she says. \"I'd rather you asked.\""},{"text":"\"Everyone else probably manages fine.\"","then":"\"You'd be surprised,\" she says. \"Plenty of students ask.\""}],"why":"A plain, honest reason makes it easy for someone to help."},{"prompt":"Professor Rao says: \"I can give you till Friday on this one. Can you manage the rest of the week?\"","options":[{"text":"\"Friday's great. The rest I'll just grind through.\"","then":"\"Okay,\" she says. \"Don't burn yourself out.\""},{"text":"\"The whole week is heavy. Who else could help?\"","then":"\"Student support can help plan it. And the counsellor's door is open.\"","best":true},{"text":"\"Could I have till next Friday instead?\"","then":"She raises an eyebrow. \"Let's start with this Friday.\""},{"text":"\"Thanks. Sorry for being such a bother.\"","then":"\"You're not a bother,\" she says, already turning to the next student."}],"why":"Saying the load is heavy opens the door to more help. Asking isn't failing."},{"prompt":"That night your roommate asks: \"You actually asked her? I'd never dare.\"","options":[{"text":"\"Yeah, but don't tell anyone. It's embarrassing.\"","then":"\"Why embarrassing?\" he asks. \"Sounds sensible to me.\""},{"text":"\"She only said yes because she felt sorry for me.\"","then":"He shrugs. \"Or maybe you just asked.\""},{"text":"\"Nah, I didn't in the end.\"","then":"\"Same,\" he says. \"We just suffer, I guess.\""},{"text":"\"I did. She was fine about it. You could ask too.\"","then":"\"Really?\" he says. \"Maybe I'll ask about my lab report.\"","best":true}],"why":"Talking openly about asking for help makes it easier for others to ask too."}],"relearn":"Asking for a little more time when you're overwhelmed is sensible coping, not failure."},
  {"id":"mb-966","cat":"cope-well","type":"role-play","persona":"Meena","source":"asking for a quiet minute","hook":"You're frayed after a long shift, and there's more to do the moment you get home.","setup":"Your cousin Sunita meets you at the door of the room you share.","steps":[{"prompt":"Sunita says: \"Finally! I've done the sabzi. Can you make the rotis?\"","options":[{"text":"\"Fine. Where's the flour?\"","then":"\"On the shelf,\" Sunita says, already turning away."},{"text":"\"Two minutes to breathe and drink water, then I'm in.\"","then":"Sunita nods. \"Okay. I'll put the tawa on.\"","best":true},{"text":"\"Can't I get one second to myself?\"","then":"Sunita blinks. \"I only asked. No need to shout.\""},{"text":"\"Sorry I'm late. I'll do the rest of dinner and the dishes.\"","then":"Sunita grins. \"You're a star.\" Your head is already pounding."}],"why":"Claiming a tiny pause is fair, and it helps you show up without snapping."},{"prompt":"While you cook, Sunita says: \"You look tired every evening now. Is work bad?\"","options":[{"text":"\"It's fine. Don't worry about me.\"","then":"\"If you say so,\" she says, but she keeps watching you."},{"text":"\"Everyone's tired. Complaining won't help.\"","then":"\"Maybe not,\" Sunita says. \"Talking might, though.\""},{"text":"\"It's long and loud. Small breaks help me.\"","then":"Sunita nods. \"Then take them. I'll start the dal.\"","best":true},{"text":"\"Why, am I not doing enough here?\"","then":"Sunita looks hurt. \"That's not what I meant.\""}],"why":"Naming what you need helps the people you live with support you."},{"prompt":"The next evening, Sunita calls from the kitchen: \"Can you help with dinner again?\"","options":[{"text":"\"Again? I always have to help.\"","then":"Sunita goes quiet. The kitchen feels tense."},{"text":"\"Yes, coming. Just two minutes with water first.\"","then":"\"Take them,\" she says. \"I'll put the kettle on.\"","best":true},{"text":"\"Yes, right away.\"","then":"\"Thanks,\" Sunita says. By the end of dinner, she's noticed you snapping at small things."},{"text":"\"In a bit. Let me scroll for a while first.\"","then":"\"Sure,\" she says. Half an hour later, you still feel frayed."}],"why":"A small, regular reset makes each evening easier for you and for everyone."}],"relearn":"Claiming even two minutes to breathe and drink water resets you before the next thing."},
  {"id":"mb-967","cat":"cope-well","type":"role-play","persona":"any","source":"suggesting a walk","hook":"Your friend Ishaan has been stewing for hours over a fight in his project group.","setup":"He's hunched at his desk, staring at the group chat.","steps":[{"prompt":"Ishaan says: \"I can't stop thinking about it. They're all against me.\"","options":[{"text":"\"Just stop stressing. It's fine.\"","then":"Ishaan's jaw tightens. \"It's not fine. You don't get it.\""},{"text":"\"They're idiots. Want me to message them?\"","then":"\"No, that'll make it worse,\" he says, gripping his phone tighter."},{"text":"\"Let's go through every message and see who's right.\"","then":"Ishaan scrolls up eagerly. An hour later, he's angrier."},{"text":"\"Come on. Quick walk and chai, then we'll think.\"","then":"Ishaan hesitates, then grabs his jacket. \"Fine. Ten minutes.\"","best":true}],"why":"A walk and a chat is a gentle reset. 'Just stop stressing' shuts him down."},{"prompt":"Ishaan sighs: \"Sorry. I know I'm being a lot today.\"","options":[{"text":"\"Yeah, a bit, honestly.\"","then":"Ishaan goes quiet. \"Right. Sorry.\""},{"text":"\"You're not. It's a stressful thing.\"","then":"His shoulders drop a little. \"Thanks. It really got to me.\"","best":true},{"text":"\"Don't apologise. Anyway, did you see the match?\"","then":"\"Uh, no,\" he says, the worry still behind his eyes."},{"text":"\"Everyone has stuff. Just get over it.\"","then":"\"Wow. Okay,\" Ishaan says, and looks away."}],"why":"Reassuring him it's okay to feel stressed keeps him talking."},{"prompt":"Ishaan says: \"I don't even know what to do about the group now.\"","options":[{"text":"\"Quit the group. They don't deserve you.\"","then":"\"I can't quit. It's graded,\" he says, stress rising again."},{"text":"\"I'll talk to them for you.\"","then":"\"Would you?\" he says, then frowns. \"Wait, that might look weird.\""},{"text":"\"What's one small thing you could say tomorrow?\"","then":"Ishaan thinks. \"Maybe ask for a call to sort out roles.\"","best":true},{"text":"\"Forget it for now. Let's watch something.\"","then":"\"Okay,\" he says. Halfway through, he's checking the chat again."}],"why":"Helping him find one small step lets him act instead of stew."}],"relearn":"Offering a friend a walk and a chat is kinder and more useful than 'just stop stressing'."},
  {"id":"mb-968","cat":"cope-well","type":"role-play","persona":"Zoya","source":"setting a worry-time","hook":"A worry about next week's visit home keeps hijacking your evening out with a friend.","setup":"You're sharing fries at a café with your friend Rhea.","steps":[{"prompt":"Rhea asks: \"You've checked your phone ten times. Where's your head?\"","options":[{"text":"\"Nowhere. Sorry. I'm fine.\"","then":"Rhea raises an eyebrow. \"Your phone says otherwise.\""},{"text":"\"On home. I'll deal with it tomorrow at noon.\"","then":"Rhea nods. \"Okay. Tonight's ours, then.\"","best":true},{"text":"\"On home. Let me plan every conversation now.\"","then":"\"Right now?\" Rhea asks, watching you type notes."},{"text":"\"Can we leave? I'm not in the mood any more.\"","then":"Rhea looks disappointed. \"Oh. We just ordered.\""}],"why":"Naming the worry and parking it for a set time frees you to be here now."},{"prompt":"Your phone buzzes again. Rhea asks: \"Is that home? Do you want to talk about it?\"","options":[{"text":"\"Hang on. Let me just reread what they sent.\"","then":"You scroll back through the family chat. Rhea starts checking her own phone."},{"text":"\"Let me go through every way the visit could go wrong.\"","then":"You list what-ifs until the fries go cold. Rhea can't get a word in."},{"text":"\"A little, then I want to switch off.\"","then":"\"Deal,\" Rhea says. \"Five minutes, then dessert.\"","best":true},{"text":"\"No. I don't want to bring the mood down.\"","then":"Rhea shakes her head. \"You wouldn't.\" You change the subject, but your eyes keep drifting to your phone."}],"why":"Sharing as much as you choose, then switching off, gives the worry its place without letting it take over."},{"prompt":"At the end of the evening, Rhea asks: \"How are you feeling about the visit now?\"","options":[{"text":"\"Dreading it. It'll be a disaster.\"","then":"Rhea looks worried. \"You don't know that yet.\""},{"text":"\"I'll just avoid thinking about it till I'm there.\"","then":"\"Hmm,\" Rhea says. \"Has that worked before?\""},{"text":"\"Nervous. I'll think it through tomorrow at noon.\"","then":"Rhea squeezes your hand. \"Noon, then. Tell me how it goes.\"","best":true},{"text":"\"I'll be fine. I always am.\"","then":"Rhea hesitates. \"You don't always have to be.\""}],"why":"Giving the worry a set time lets you rest tonight and still face it."}],"relearn":"Parking a worry to a set time stops it hijacking the rest of your evening."},
  {"id":"mb-969","cat":"cope-well","type":"reflect","persona":"any","source":"rest is allowed","hook":"Lensy: you're allowed to rest before the whole list is done. Does that land?","prompt":"What do you think?","options":["Yes","I needed that","I'll try"],"affirm":"Rest is a basic need, not a reward you earn; tending yourself is part of getting things done.","relearn":"Rest is a need, not a reward; you're allowed it before the list is done."},
  {"id":"mb-970","cat":"cope-well","type":"reflect","persona":"any","source":"not the only one","hook":"Lensy: most people are quietly finding coping hard too, behind the calm faces. Sit with that?","prompt":"How does that feel?","options":["Reassuring","Honestly, yes","A relief"],"affirm":"You're comparing your insides to others' outsides; nearly everyone struggles to cope sometimes.","relearn":"Most people quietly find coping hard too; you're not the only one."},
  {"id":"mb-971","cat":"cope-well","type":"reflect","persona":"any","source":"small things count","hook":"Lensy: a ten-minute walk still counts, even on a messy day. Can that be enough today?","prompt":"What do you think?","options":["Yes","Some beats none","I'll take it"],"affirm":"Small, partial care adds up; coping is progress, not a perfect routine.","relearn":"Small, partial care counts; coping is progress, not a perfect routine."},
  {"id":"mb-972","cat":"cope-well","type":"reflect","persona":"Rohan","source":"strength to rest","hook":"Lensy: choosing to rest and refuel is strength, not slacking. Could that be true for you?","prompt":"Does it fit?","options":["Yes","Reframing it","Maybe so"],"affirm":"Looking after your mind and body is strength; running yourself empty isn't toughness.","relearn":"Choosing to rest and refuel is strength; running yourself empty isn't toughness."},
  {"id":"mb-973","cat":"cope-well","type":"reflect","persona":"any","source":"feelings shift","hook":"Lensy: even a heavy feeling moves and changes. It isn't the whole rest of your life. Let that in?","prompt":"How does that sit?","options":["It helps","I'll hold it","Yes"],"affirm":"Feelings shift over time; tending the basics helps a heavy patch pass sooner.","relearn":"Feelings shift over time; tending the basics helps a heavy patch pass sooner."},
  {"id":"mb-974","cat":"cope-well","type":"reflect","persona":"any","source":"kind inner voice","hook":"Lensy: you can talk to yourself the way you'd talk to a good friend. Worth a try?","prompt":"What do you think?","options":["Yes","I'll practise","Kinder, then"],"affirm":"A kind inner voice steadies you under pressure; you deserve the warmth you'd give a friend.","relearn":"A kind inner voice steadies you; talk to yourself like you would a good friend."},
  {"id":"mb-975","cat":"cope-well","type":"reflect","persona":"Deepak","source":"good days too","hook":"Lensy: a good day is yours to enjoy. You don't have to brace for a crash. Can you let it be good?","prompt":"How does that feel?","options":["I'll try","Yes","Guilt-free"],"affirm":"Good days are part of coping too; you're allowed to savour one without waiting for it to break.","relearn":"Good days are part of coping; savour one without bracing for a crash."},
  {"id":"mb-976","cat":"cope-well","type":"reflect","persona":"any","source":"one thing at a time","hook":"Lensy: when it's all too much, just the next small step is enough for now. Can that be the plan?","prompt":"Does that help?","options":["Yes","One step","I can do that"],"affirm":"When everything feels like too much, the smallest next step is plenty; you don't have to do it all at once.","relearn":"When it's all too much, the smallest next step is enough for now."},
  {"id":"mb-990","cat":"find-your-people","type":"strike-rewrite","hook":"\"Everyone here already has their group; I missed the bus.\"","myth":{"un":"Everyone already has their group; I missed my chance.","re":"Groups keep forming all year; new friendships start in week 1 and week 30 alike.","why":"People drift, switch and look for new connections constantly."},"relearn":"Groups keep forming all year; it's never too late to start a new connection.","persona":"Deepak","source":"missed the bus myth"},
  {"id":"mb-991","cat":"find-your-people","type":"strike-rewrite","hook":"\"If they wanted to be my friend, they'd reach out to me.\"","myth":{"un":"If they wanted to be friends, they'd reach out to me first.","re":"Most people are waiting for the same thing; someone has to go first, and it can be you.","why":"Everyone fears the first move, so connections stall until one person tries."},"relearn":"Most people are also waiting; someone has to reach out first, and it can be you.","persona":"any","source":"waiting to be chosen"},
  {"id":"mb-992","cat":"find-your-people","type":"strike-rewrite","hook":"\"Making friends should feel instant; if it's effort, it's fake.\"","myth":{"un":"Real friendship is instant; if it takes effort it isn't real.","re":"Most real friendships grow slowly, from repeated small moments, not one spark.","why":"Closeness is built by showing up again and again over time."},"relearn":"Real friendship usually grows slowly from repeated small moments, not one instant spark.","persona":"any","source":"instant friendship myth"},
  {"id":"mb-993","cat":"find-your-people","type":"strike-rewrite","hook":"Rohan: \"Asking to hang out makes you look desperate.\"","myth":{"un":"Asking someone to hang out makes you look desperate.","re":"Inviting someone is normal and usually welcomed; most are glad someone bothered.","why":"People remember who included them far more than who 'played it cool'."},"relearn":"Inviting someone to hang out is normal and usually welcomed, not desperate.","persona":"Rohan","source":"desperate myth"},
  {"id":"mb-994","cat":"find-your-people","type":"strike-rewrite","hook":"\"I'm too quiet to ever fit into a group.\"","myth":{"un":"I'm too quiet to ever fit into a group.","re":"Quiet people belong everywhere; good listeners are some of the most valued friends.","why":"Connection needs presence and care, not being the loudest in the room."},"relearn":"Quiet people belong too; being a good listener is a real strength in friendship.","persona":"any","source":"too quiet myth"},
  {"id":"mb-995","cat":"find-your-people","type":"strike-rewrite","hook":"\"If I have to be the one organising plans, they're not real friends.\"","myth":{"un":"If I'm always the one organising, they aren't really my friends.","re":"Someone usually starts the plans; being that person is a gift, not a sign you're unwanted.","why":"Most groups have one or two natural initiators; the rest gladly say yes."},"relearn":"Someone usually has to start the plans; being the initiator doesn't mean you're unwanted.","persona":"any","source":"the organiser"},
  {"id":"mb-996","cat":"find-your-people","type":"strike-rewrite","hook":"Meena: \"With no campus and long shifts, people like me can't really make friends.\"","myth":{"un":"With no campus and long shifts, people like me can't make friends.","re":"Belonging is built anywhere people gather, your workplace, area, or a shared-interest group.","why":"Friendship grows from regular contact, not from having a college."},"relearn":"You can build belonging anywhere people gather, no campus needed.","persona":"Meena","source":"no campus"},
  {"id":"mb-997","cat":"find-your-people","type":"branch","persona":"any","source":"say yes to chai","hook":"A group from your class is heading out for chai, and Sneha turns to you and says you should come.","steps":[{"prompt":"You barely know any of them, and you've got notes to finish. What do you do?","options":[{"text":"Make an excuse. You'd only feel awkward","then":"They head off laughing. The notes take twice as long as you hoped."},{"text":"Say you'll catch up with them later","then":"You mean it. By the time you're done, they've all gone back."},{"text":"Say yes and go. The notes can wait an hour","then":"The chai stall is loud and cheerful. Someone asks where you're from.","best":true},{"text":"Ask Sneha if she's sure they want you there","then":"\"I did just ask,\" she laughs. The group waits, a little awkward."}],"why":"Casual invites are open doors. Saying yes is how acquaintances become friends."},{"prompt":"The next day in class, the same group is laughing at a joke you don't know. What do you do?","options":[{"text":"Laugh along as if you get it","then":"It works, but you feel a step outside the circle."},{"text":"Ask, smiling, what the joke is","then":"Sneha explains it badly. Everyone laughs harder, and you with them.","best":true},{"text":"Decide they're too close for you to fit in","then":"The next day you sit a row further back."},{"text":"Put your earphones in","then":"The laughter carries on without you."}],"why":"Asking openly turns an inside joke into your way in."},{"prompt":"On Friday, the group plans a movie night and adds you to their WhatsApp group. What do you do?","options":[{"text":"Mute the group and stay quiet","then":"The plans happen in messages you never read."},{"text":"Say you'll come, and decide on the day","then":"On the day you're tired, and the bed wins."},{"text":"Leave the group quietly. It feels too soon","then":"Someone notices and asks if you left by mistake."},{"text":"Reply that you're in, and suggest a film","then":"Two people react with a heart. Sneha says your pick is next.","best":true}],"why":"Each yes adds up. That's how acquaintances become real friends."}],"debrief":"Casual invites are open doors. Saying yes is how acquaintances become friends.","relearn":"Say yes to casual invites. That's how acquaintances become real friends."},
  {"id":"mb-998","cat":"find-your-people","type":"branch","persona":"Rohan","source":"one regular thing","hook":"For two weeks now, you've spent every evening scrolling alone in your room.","steps":[{"prompt":"It's Monday, and the evenings are starting to feel very long. What do you do?","options":[{"text":"Keep waiting until you feel ready to socialise","then":"The week looks exactly like the last two."},{"text":"Sign up for five things at once","then":"Your week fills up on paper. By Thursday you've been to none."},{"text":"Game online all evening. That's social too","then":"The banter's fun. When you log off, the room feels just as empty."},{"text":"Pick one weekly thing to go to","then":"You find a Wednesday five-a-side on the notice board and save it in your phone.","best":true}],"why":"One regular activity gives belonging a place to grow, instead of waiting for it."},{"prompt":"On Wednesday there's a five-a-side on the notice board, open to all, and part of you wants to stay in. What do you do?","options":[{"text":"Go, even if only for an hour","then":"The first ten minutes are awkward. Then someone passes you the ball.","best":true},{"text":"Stay in. There's always next week","then":"Next week comes with the same nerves."},{"text":"Go, but stand at the edge on your phone","then":"You're there, but nobody can tell you want in."},{"text":"Tell yourself real men don't need this stuff","then":"The thought sounds tough. The room still feels empty."}],"why":"Showing up, even nervously, is what turns a plan into belonging."},{"prompt":"Farid, from your floor, plays on Wednesdays and asks if you'll come and grab food after. What do you do?","options":[{"text":"Say you're not really a food-after person","then":"Farid shrugs. \"Cool.\" He doesn't ask again."},{"text":"Say maybe, and see how you feel","then":"Farid says okay. On Wednesday, nobody waits for you."},{"text":"Say yes, and suggest the dhaba by the gate","then":"\"Perfect,\" Farid says. \"I'm always starving after.\"","best":true},{"text":"Say you're too busy these days","then":"Farid nods. \"Another time, then.\""}],"why":"Saying yes to the next small step turns a regular thing into a friendship."},{"prompt":"A month later you've had a rough week and want to skip Wednesday. What do you do?","options":[{"text":"Skip it and stay in your room","then":"The room is quiet. The rough week gets rougher."},{"text":"Go, but act like everything's great","then":"The game helps. The rough week stays unspoken."},{"text":"Go, and tell Farid it's been a rough week","then":"Farid nods. \"Same. Let's play, then eat.\" By nine you feel lighter.","best":true},{"text":"Quit. You're not in the mood for people","then":"The Wednesday slot goes empty. So do the evenings around it."}],"why":"Keeping your regular thing, and letting someone in, carries you through a rough patch."}],"debrief":"One regular activity gives belonging a place to grow.","relearn":"Pick one regular activity. Showing up beats waiting to feel ready."},
  {"id":"mb-999","cat":"find-your-people","type":"branch","persona":"any","source":"follow up","hook":"You hit it off with Tanvi at a workshop a week ago, but you haven't spoken since.","steps":[{"prompt":"Her number is still in your phone. What do you do?","options":[{"text":"Assume the moment has passed and leave it","then":"The number sits there. Tanvi fades into \"that nice person from the workshop\"."},{"text":"Message her that the chat was fun, and suggest coffee","then":"She replies an hour later: \"Yes! Thursday?\"","best":true},{"text":"Like her old posts and hope she messages","then":"She likes one of yours back. Nobody says anything."},{"text":"Wait for her to message first","then":"A week passes. She's probably waiting too."}],"why":"A friendly follow-up is how one good chat becomes a friendship."},{"prompt":"A few days later you spot Tanvi across the campus café. What do you do?","options":[{"text":"Pretend you haven't seen her","then":"She leaves before you've made up your mind."},{"text":"Wave from your table and stay put","then":"She waves back and heads out with her friends."},{"text":"Walk over and say hi","then":"Tanvi lights up. \"Hey! I was just thinking about that workshop.\"","best":true},{"text":"Wait to see if she notices you first","then":"She doesn't. The café fills up between you."}],"why":"A small step in person keeps a new connection warm."},{"prompt":"Later that week, you wonder if Tanvi really wants to be friends. What do you tell yourself?","options":[{"text":"She's probably just being polite","then":"You hold back, and your next chat feels stiff."},{"text":"If she wanted to, she'd make the effort","then":"You wait. The friendship stays stuck in first gear."},{"text":"I'll ask her straight out if she likes me","then":"The idea makes you cringe before you've typed a word."},{"text":"A few more small steps will show me","then":"You suggest a walk next week. She says yes.","best":true}],"why":"Friendships build through a few small steps. Doubts fade as you keep showing up."}],"debrief":"Following up after a good first chat is how a spark becomes a friendship.","relearn":"Follow up after a good chat. A small message turns a spark into a connection."},
  {"id":"mb-1000","cat":"find-your-people","type":"branch","persona":"any","source":"trek group","hook":"A senior, Arjun, offers to add you to the hostel group that goes on weekend treks.","steps":[{"prompt":"He's holding out his phone for your number. What do you do?","options":[{"text":"Give it, and say you'd love to join","then":"Within a minute you're in the group. Twenty people send a wave.","best":true},{"text":"Decline. They're close, and you'd stick out","then":"Arjun shrugs. \"Offer's open.\" Their photos from the hills pop up on Monday."},{"text":"Say you'll think about it","then":"Arjun nods and moves on. The group chat carries on without you."},{"text":"Join, but plan to stay silent in the chat","then":"You're added. The messages scroll past without you."}],"why":"Shared-activity groups are an easy way in. Everyone there was new once."},{"prompt":"Arjun mentions a Saturday trek, open to anyone, and you don't know who's going. What do you do?","options":[{"text":"Skip this one. Maybe once you know people","then":"The weekend's quiet. On Monday everyone's talking about the view."},{"text":"Sign up, then drop out the night before","then":"Arjun messages, \"No worries.\" You spend Saturday wondering."},{"text":"Go, but plan to stick close to Arjun all day","then":"Arjun's busy leading. You spend the first hour trailing him."},{"text":"Sign up and ask what to bring","then":"\"Water, snacks, good shoes,\" Arjun says. \"You'll be fine.\"","best":true}],"why":"Saying yes to the first outing lets the shared activity do the work."},{"prompt":"Later in the month Pooja, a first-year on your floor, tells you she's nervous about trekking alone. What do you do?","options":[{"text":"Tell her it's easy and she'll be fine","then":"\"Okay,\" she says, not looking convinced. She doesn't sign up."},{"text":"Offer to go together and meet at the gate","then":"Pooja sends a relieved smile. \"Thank you. Half six at the gate?\"","best":true},{"text":"Say you're not sure you're going either","then":"Neither of you goes."},{"text":"Change the subject. You're still new yourself","then":"Pooja goes quiet, and she doesn't sign up for the trek."}],"why":"Everyone there was new once. Folding someone else in is how the circle grows."}],"debrief":"Joining a shared-activity group is one of the easiest ways into a circle.","relearn":"Join shared-activity groups. Everyone there was new once."},
  {"id":"mb-1001","cat":"find-your-people","type":"branch","persona":"Deepak","source":"second chance","hook":"You went to the debating society once, felt awkward, and haven't been back.","steps":[{"prompt":"Their next meeting is tonight. What do you do?","options":[{"text":"Write the whole place off after one visit","then":"The evening is free. The society's poster catches your eye all week."},{"text":"Wait until you've read up on debating properly","then":"You bookmark ten videos. The meeting happens without you."},{"text":"Tell yourself it's for kids from fancy schools","then":"The thought stings. You stay in, and it goes unchallenged."},{"text":"Give it a second try tonight","then":"A few faces look familiar. Someone nods at you from across the room.","best":true}],"why":"Most groups feel awkward once and warmer by the third visit."},{"prompt":"A week later Kavya, from the society, sits next to you in the library and asks if you'll come on Friday. What do you do?","options":[{"text":"Say you're not really a debate person","then":"\"Oh, okay,\" Kavya says, and turns back to her book."},{"text":"Say yes, and admit the first time felt awkward","then":"Kavya laughs. \"Mine too. I nearly didn't come back.\"","best":true},{"text":"Say maybe, and keep your worries to yourself","then":"Kavya nods. By Friday you're still undecided."},{"text":"Say you're too busy this term","then":"Kavya nods. \"Another time.\" The invite drifts off."}],"why":"Being honest about an awkward first visit often shows you you're not alone."},{"prompt":"Later that month you notice you still feel out of place in new groups at college. What do you tell yourself?","options":[{"text":"People like me don't belong here","then":"The old thought settles in, and you stop looking at the noticeboard."},{"text":"I'll only go where I already know people","then":"It feels safer. Your circle stays exactly the size it is."},{"text":"Places warm up once I'm familiar. Give it time","then":"You put the society's next two dates in your phone.","best":true},{"text":"I should feel at home by now","then":"The pressure makes each new room feel harder."}],"why":"Familiarity takes a few visits. Feeling out of place at first isn't proof you don't belong."}],"debrief":"Most groups feel awkward once and warmer by the third visit.","relearn":"Give a new group a few tries. It warms up once you're familiar."},
  {"id":"mb-1002","cat":"find-your-people","type":"branch","persona":"any","source":"one friend leaving","hook":"Your only close friend here, Kabir, is going home for the holidays. You're staying back.","steps":[{"prompt":"Kabir leaves on Friday and your break is a blank page. What do you do?","options":[{"text":"Sign up for one new thing running over the break","then":"The notice board has a quiz night and a weekend trek. You put your name down for the quiz.","best":true},{"text":"Wait it out. Kabir is back in three weeks","then":"The first two days are quiet. By day three, the corridor feels very long."},{"text":"Plan to video call Kabir every evening","then":"Kabir answers the first night, then gets swept up in family. The calls get shorter."},{"text":"Fill every hour with coursework so you don't notice","then":"The days blur into notes and readings. You barely speak to anyone."}],"why":"One new thing over the break widens your circle, so it doesn't hang on one person."},{"prompt":"One evening that first week, a few students still in the hostel head to the canteen. What do you do?","options":[{"text":"Hang around nearby in case they invite you","then":"One of them glances over, but nobody asks. They leave together."},{"text":"Ask if you can join them","then":"They shift along the bench. One of them, Tanvi, turns out to be in your department.","best":true},{"text":"Stay in and text Kabir about your day","then":"Kabir sends a thumbs up from a family wedding. The room goes quiet again."},{"text":"Wave and keep walking, since you barely know them","then":"They wave back. You spend the evening wondering what they talked about."}],"why":"Asking to join is how new faces become part of your circle."},{"prompt":"Midway through the break, someone posts about a Sunday cricket match in the hostel group. What do you do?","options":[{"text":"Wait to see who else is going first","then":"By the time the list fills up, adding your name feels too late."},{"text":"Ask Kabir whether you should go","then":"Kabir replies hours later: \"Sure, why not?\" The teams are already fixed."},{"text":"Say you'll come, even if you don't play much","then":"Someone replies: \"Come! We need a fielder anyway.\" You have a plan for Sunday.","best":true},{"text":"React with a thumbs up but don't commit","then":"The match happens. You see the photos later, full of people you half know."}],"why":"Saying yes to open invites is how a wider circle actually forms."},{"prompt":"Kabir comes back and suggests your old routine: every meal, just the two of you. What do you do?","options":[{"text":"Go back to just the two of you. It's easier that way","then":"It feels cosy again, until Kabir joins a club and is busy most evenings."},{"text":"Tell Kabir you need some space from him now","then":"Kabir looks hurt. \"Oh. Okay.\" Lunch that week is awkward."},{"text":"Ask Kabir to find a bigger group for the two of you","then":"Kabir shrugs. \"We're fine as we are.\" Nothing changes."},{"text":"Pick up with Kabir, and say yes to others too","then":"Kabir is glad to be back. Your week has him in it, and room for new faces.","best":true}],"why":"Keeping your old friend and making room for others means no one person carries your whole belonging."}],"debrief":"Resting your whole social life on one person is fragile. A wider circle is steadier.","relearn":"Don't rest all your belonging on one person; widen your circle."},
  {"id":"mb-1003","cat":"find-your-people","type":"branch","persona":"Zoya","source":"shrinking to fit","hook":"With your new group, you keep toning yourself down to fit in, and every hangout leaves you drained.","steps":[{"prompt":"On the way home, you realise you didn't share one real opinion all evening. What do you do?","options":[{"text":"Try harder to be what they seem to like","then":"Next time you laugh at all the right moments. You get home even more tired."},{"text":"Tell yourself every group feels like this at first","then":"The next week feels the same. The drained feeling starts to seem normal."},{"text":"Admit this group costs you, and ease back from it","then":"You skip the next hangout. It stings a little, and you also feel lighter.","best":true},{"text":"Give up on groups altogether for now","then":"Your evenings are free and quiet. You also stop meeting anyone new."}],"why":"Noticing what a group costs you is the first step to finding people who fit."},{"prompt":"A week later, a classmate, Ira, mentions the small poetry circle she runs on Thursdays. What do you do?","options":[{"text":"Go, but stay quiet so you don't misstep","then":"You leave having said almost nothing. It's hard to tell if you'd fit."},{"text":"Say you're too busy with your group","then":"Ira says \"another time.\" Thursday passes like every other week."},{"text":"Go along and see how you feel there","then":"Nobody there is polished. By the end, you've laughed out loud twice.","best":true},{"text":"Ask your group if they'd come too","then":"They roll their eyes at poetry. You don't bring it up again."}],"why":"Trying a new space is how you find people who like the real you."},{"prompt":"Your group messages about a party on Saturday and says you have to come. What do you do?","options":[{"text":"Go and play the version of you they know","then":"The party is loud and familiar. You spend it nodding along to things you don't believe."},{"text":"Say yes to keep the peace, then cancel on the day","then":"They're annoyed at the late cancel. Where you stand with them stays unclear."},{"text":"Tell them kindly you're stepping back for a while","then":"One replies: \"Okay, cool.\" Nobody pushes, and the pressure lifts.","best":true},{"text":"Go and tell them all how fake they make you feel","then":"The room goes quiet. Someone says \"Wow, okay,\" and the evening sours."}],"why":"Stepping back honestly protects your worth without burning bridges."},{"prompt":"Weeks later, on a lonely evening, you wish you had people who really get you. What do you do?","options":[{"text":"Message someone you feel at ease with to meet up","then":"They suggest chai tomorrow. The loneliness eases a notch.","best":true},{"text":"Text the group for plans. Any company beats none","then":"They're up for it. Within an hour you're toning yourself down again."},{"text":"Decide you're just hard to fit in with","then":"The thought follows you to bed. You wake up feeling smaller."},{"text":"Wait for someone new to text you first","then":"Nobody messages tonight. The evening stays lonely."}],"why":"Loneliness eases with people you needn't shrink for, not a group that costs you."}],"debrief":"Belonging shouldn't cost you yourself. The right people fit the real you.","relearn":"If a group makes you shrink, look for people you don't have to."},
  {"id":"mb-1004","cat":"find-your-people","type":"branch","persona":"any","source":"one conversation goal","hook":"Your classmate Nikhil invites you to his birthday party. You'll know almost no one there.","steps":[{"prompt":"The party is tonight and your stomach is in knots. What do you do?","options":[{"text":"Skip it and wish Nikhil happy birthday by text","then":"Nikhil's roommate calls: \"He keeps asking where you are.\" You go, late."},{"text":"Go for an hour and aim for one real conversation","then":"You set a small goal and a time to leave. It feels almost doable.","best":true},{"text":"Go, and push yourself to meet everyone there","then":"You rehearse names in the auto. By the gate, you're already worn out."},{"text":"Go only if a classmate you know is going","then":"Nobody replies in time. At nine you go anyway, alone and later than planned."}],"why":"One real chat is a kind, doable goal that makes a room of strangers manageable."},{"prompt":"At the party, everyone seems to be in groups already. What do you do?","options":[{"text":"Stand by the snacks and scroll your phone","then":"Twenty minutes pass. Nobody bothers you, and nobody talks to you."},{"text":"Stick close to Nikhil all night","then":"Nikhil introduces you twice, then gets pulled away. You're alone again."},{"text":"Find someone standing alone and say hi","then":"Her name is Sana. She's Nikhil's cousin and knows nobody either.","best":true},{"text":"Join the loudest group with a joke","then":"The joke half lands. They smile politely and carry on with their story."}],"why":"Someone standing alone is often hoping to talk too, so it's the easiest first chat."},{"prompt":"Near the cake, Nikhil's friend Arjun asks how you know Nikhil. What do you say?","options":[{"text":"Talk about yourself nonstop so there's no silence","then":"Arjun's eyes drift to the door. You realise you haven't asked him a thing."},{"text":"Apologise for being bad at parties","then":"Arjun laughs awkwardly. \"Oh, no, it's fine.\" The chat runs dry."},{"text":"Give a one-word answer and look away","then":"Arjun nods and turns to someone else."},{"text":"Answer, then ask him something back","then":"Arjun says they grew up on the same street. Ten minutes pass without you noticing.","best":true}],"why":"Answering and asking back turns a polite question into a real conversation."},{"prompt":"It's been an hour and you're getting tired. What do you do?","options":[{"text":"Say bye to Nikhil and head home","then":"Nikhil hugs you. \"So glad you came.\" You leave tired, and a little proud.","best":true},{"text":"Stay till the end so you don't seem rude","then":"By midnight you're drained, and you dread the next party a bit more."},{"text":"Slip out without telling anyone","then":"Nikhil texts later: \"Where did you vanish?\" You feel a pang of guilt."},{"text":"Stay to try talking to three more people","then":"Two more small talks later, the one good chat is buried under the tiredness."}],"why":"Leaving while you still have energy keeps the next party doable. One real chat was the goal."}],"debrief":"Aiming for one real chat, not the whole room, makes new rooms doable.","relearn":"In a room of strangers, aim for one real conversation, not the whole room."},
  {"id":"mb-1005","cat":"find-your-people","type":"branch","persona":"any","source":"sitting alone","hook":"Priya from your class always sits alone at the back, the way you used to.","steps":[{"prompt":"Before today's lecture, the seat next to her is empty. What do you do?","options":[{"text":"Leave her be. She probably likes her space","then":"Priya spends the lecture alone again. So do you, two rows ahead."},{"text":"Smile at her on the way to your usual seat","then":"Priya smiles back quickly, then looks down at her notes."},{"text":"Sit there and ask how she found the last assignment","then":"Priya looks up, surprised. \"Honestly? I was lost.\" You both laugh.","best":true},{"text":"Ask your friends if one of them could talk to her","then":"Your friends shrug. \"She seems quiet.\" Nobody moves."}],"why":"Sitting with her and asking something easy starts belonging for both of you."},{"prompt":"After class, Priya packs up slowly while your friends head to the canteen. What do you do?","options":[{"text":"Tell her she can join you some other time","then":"Priya says \"sure\" softly. Some other time has no date on it."},{"text":"Assume she'd hate a group and don't ask","then":"Priya leaves by the side door. The moment passes."},{"text":"Ask if she wants to come along","then":"Priya hesitates, then nods. At the canteen she mostly listens, and smiles.","best":true},{"text":"Go with your friends. You've done your bit","then":"Priya heads off alone. On the stairs you wonder if you should have asked."}],"why":"An invitation lets her choose. Deciding for her keeps her on her own."},{"prompt":"Next week, the professor asks everyone to form project groups and Priya is left without one. What do you do?","options":[{"text":"Hope someone else asks her","then":"Nobody does. Priya ends up in the leftover group, at its edge."},{"text":"Tell Priya she can join you if she really wants","then":"Priya says she doesn't want to impose. She joins the leftover group."},{"text":"Wait for the professor to place her somewhere","then":"The professor adds her to a group that has already split the work."},{"text":"Ask her to join your group","then":"Priya joins. By the end of the first meeting, she's taking notes for everyone.","best":true}],"why":"Asking her in directly makes the welcome real, not a favour she must request."}],"debrief":"Reaching out to someone who sits alone often builds belonging for you both.","relearn":"Reaching out to someone who's alone often helps you both belong."},
  {"id":"mb-1006","cat":"find-your-people","type":"branch","persona":"any","source":"lab partner","hook":"Aman asks if you want to be lab partners this semester. You'd planned to work solo.","steps":[{"prompt":"He's waiting for an answer at the lab bench. What do you do?","options":[{"text":"Say you'll think about it","then":"Aman waits two days, then pairs with Divya. You end up with whoever's left."},{"text":"Say yes and swap numbers","then":"Aman grins. \"Great. I'm hopeless at titrations.\" You have a partner.","best":true},{"text":"Say yes, but split it so you each work alone","then":"Aman agrees, a little flat. You each do half at opposite ends of the bench."},{"text":"Say no. You work better alone","then":"Aman pairs with someone else. Two weeks later, the professor makes pairs compulsory."}],"why":"Regular shared work is one of the easiest ways a friendship starts."},{"prompt":"In week three, a long experiment leaves the whole lab tired and cranky. What do you do?","options":[{"text":"Pack up fast and head back to your room","then":"You're back by six. The room is quiet, and the day feels longer."},{"text":"Suggest a chai break with the people around you","then":"Four of you end up at the canteen, laughing about the burnt samples.","best":true},{"text":"Stay back to redo your readings perfectly","then":"You finish alone at seven. The others have already left together."},{"text":"Grumble about the professor to your bench mate","then":"You vent for five minutes. Then you both go your separate ways."}],"why":"Small shared breaks after shared work are how lab mates turn into friends."},{"prompt":"Mid-semester, a few classmates plan to study together for the practical exam. What do you do?","options":[{"text":"Join, but only listen so you don't slow anyone","then":"You pick up a lot. Nobody quite learns your name."},{"text":"Ask for their notes instead of joining","then":"Someone sends a blurry photo of a page. You're still studying on your own."},{"text":"Join and offer to explain a part you know well","then":"You explain titrations. Someone suggests making the group a weekly thing.","best":true},{"text":"Study alone. Groups waste time","then":"You cover the syllabus. Next day, the group's inside jokes are all new to you."}],"why":"Showing up and giving something to shared work is how friendships quietly start."}],"debrief":"Shared, repeated tasks like lab work are a natural way friendships form.","relearn":"Shared, regular work like a lab partner is a natural way friendships start."},
  {"id":"mb-1007","cat":"find-your-people","type":"branch","persona":"Rohan","source":"drop the mask","hook":"You hang out with your hostel wing but keep up a joking front, in case they don't like the real you.","steps":[{"prompt":"Late one night, Harsh and the rest of the wing start talking about missing home. What do you do?","options":[{"text":"Crack a joke about homesick guys being soft","then":"Everyone laughs. The talk moves on, and nobody says anything real again."},{"text":"Admit you miss home cooking more than you let on","then":"Harsh laughs. \"Same, bro. I dream about rajma chawal.\" The talk gets real.","best":true},{"text":"Share it, but say it's about a friend of yours","then":"They're kind about your \"friend\". You still feel unseen."},{"text":"Stay quiet and let the others do the talking","then":"You listen. It's nice, but you go to bed feeling outside it."}],"why":"Sharing one small true thing lets the right people lean in."},{"prompt":"A few days later, the wing plans a cricket screening and assumes you're a big fan. You're not. What do you do?","options":[{"text":"Fake excitement and look up the scores fast","then":"You pass for a fan. All evening, you dread someone asking you something."},{"text":"Say it's not your thing, but you'll come for the food","then":"Harsh laughs. \"Honest man. Come anyway. We'll convert you.\"","best":true},{"text":"Skip it and say you have work","then":"They watch without you. Next morning, every joke is about the match."},{"text":"Go along and quietly spend the evening on your phone","then":"Nobody minds much. You leave without really talking to anyone."}],"why":"Being honest about small things shows people who you are, and most don't mind."},{"prompt":"One evening, Harsh asks why you always joke when things get serious. What do you say?","options":[{"text":"Laugh it off with another joke","then":"Harsh smiles, but drops it. The moment passes."},{"text":"Say he's reading too much into it","then":"Harsh shrugs. \"Okay, man.\" He doesn't ask again."},{"text":"Admit you worry people won't like the serious you","then":"Harsh is quiet a second. \"Honestly? I do the same thing.\"","best":true},{"text":"Admit it, then joke that he's getting soft on you","then":"Harsh laughs, a bit thrown. The real part gets lost in the joke."}],"why":"Owning the worry honestly lets a friend meet the real you."},{"prompt":"Weeks later, at a college fest, you meet new people and feel the old front creeping back. What do you do?","options":[{"text":"Keep quiet till you know if they're your type","then":"The group chats on. By the time you speak, they're getting up to leave."},{"text":"Stick with your wing friends only","then":"You have a good time with the wing. The new faces stay strangers."},{"text":"Put the front back on. New people are different","then":"The evening goes fine. By the end, none of them really knows you."},{"text":"Let a little of the real you show from the start","then":"One of them loves the same old films you do. You swap numbers.","best":true}],"why":"Showing a little of yourself early is how the right people find you."}],"debrief":"Letting a little of the real you show is how the right people recognise you.","relearn":"Show a little of the real you; that's how the right people find you."},
  {"id":"mb-1008","cat":"find-your-people","type":"branch","persona":"Meena","source":"first footing","hook":"At your new job in the city, you meet two women from your home town. Talking in your own language feels instantly easier.","steps":[{"prompt":"Lakshmi and Revathi ask you to sit with them at lunch. What do you do?","options":[{"text":"Sit with them, but say little about yourself","then":"The talk flows around you. You leave lunch no closer to them."},{"text":"Decline. You came here to make city friends","then":"They nod and move on. At lunch you sit alone, unsure where to start."},{"text":"Sit with them and enjoy the easy talk","then":"Lunch is full of jokes from home. For the first time in weeks, you relax.","best":true},{"text":"Sit with them and trade complaints about the city","then":"They join in. Lunch becomes a daily list of what's wrong with this place."}],"why":"A group that feels like home is a real comfort and a great first footing."},{"prompt":"A week later, Sunita from another line asks you to join her group for chai at break. What do you do?","options":[{"text":"Go, and keep up with Lakshmi and Revathi too","then":"Sunita's group shows you a shortcut to the bus stand. Now you have two circles to wave to.","best":true},{"text":"Say no. New groups feel like too much right now","then":"Sunita shrugs. Her group stays strangers to you."},{"text":"Say you'll come next week instead","then":"Sunita says okay. Next week, she doesn't think to ask."},{"text":"Go, and keep away from the home-town group to fit in","then":"Sunita's group is nice, but you miss talking in your own language."}],"why":"Staying open lets you keep your first footing and build on it."},{"prompt":"Before Diwali, the workers' hostel plans an evening with people from many states. What do you do?","options":[{"text":"Skip it. It's not really your crowd","then":"The music carries across the yard. You feel left out of your own building."},{"text":"Go, but stay in one corner with your group","then":"You have fun together. By the end, you know no one else's name."},{"text":"Go with Lakshmi and Revathi and meet a few new faces","then":"A woman from Odisha swaps food with you and teaches you a song.","best":true},{"text":"Go alone so you're forced to mix with others","then":"You meet a couple of people. Lakshmi asks later why you didn't come with them."}],"why":"Your familiar group can walk into new rooms with you. That's how both circles grow."}],"debrief":"A group that shares your language is a great first footing. Stay open to others too.","relearn":"Let a familiar group be your first footing, but stay open to others."},
  {"id":"mb-1009","cat":"find-your-people","type":"branch","persona":"Deepak","source":"awkward start reset","hook":"You froze and barely spoke the first time you met your three new flatmates.","steps":[{"prompt":"Next morning, one of them, Varun, is making tea in the kitchen. What do you do?","options":[{"text":"Wait in your room until the kitchen is empty","then":"You hear them laughing over breakfast. The door feels heavier to open."},{"text":"Say hi, and hope he starts a conversation","then":"Varun says hi back and returns to his phone."},{"text":"Ask Varun where he's from","then":"Varun says Pune, and asks where you're from. The kettle boils while you talk.","best":true},{"text":"Apologise at length for being so quiet yesterday","then":"Varun looks puzzled. \"Were you? Didn't notice.\" It gets a bit awkward."}],"why":"One small, friendly question resets a quiet start without any big effort."},{"prompt":"That evening, the flatmates are watching a match in the hall. What do you do?","options":[{"text":"Sit with them and ask who's winning","then":"Varun explains the score. Someone passes you the chips.","best":true},{"text":"Stay in your room. They probably find you odd","then":"The cheering carries through the wall. You feel further away than one door."},{"text":"Sit at the edge and watch silently","then":"You enjoy the match. Nobody quite notices you're there."},{"text":"Join, and talk nonstop to make up for last night","then":"They're polite, but a bit thrown. You go to bed replaying what you said."}],"why":"Showing up and asking one easy thing lets people meet the real you."},{"prompt":"A week on, you still feel like the quiet odd one in the flat. What do you do?","options":[{"text":"Wait for them to invite you to things first","then":"A few days pass. Nobody invites you, and nobody knows you're hoping."},{"text":"Decide the first night set their opinion of you","then":"You start timing your kitchen trips to avoid them."},{"text":"Keep going with small, friendly moments","then":"By Sunday, Varun saves you a seat for the match without being asked.","best":true},{"text":"Start looking for a different flat to start over","then":"The listings are costly and far away. You feel stuck, and more alone."}],"why":"Belonging builds through small moments over weeks, not one first meeting."}],"debrief":"A quiet first meeting isn't the verdict. A small, friendly follow-up resets it.","relearn":"A quiet first meeting isn't the verdict; try again with one small question."},
  {"id":"mb-1010","cat":"find-your-people","type":"branch","persona":"any","source":"online community","hook":"There's an online group for the sketching you love, but you doubt online friends really count.","steps":[{"prompt":"The group runs a weekly sketch challenge. What do you do?","options":[{"text":"Wait until your work is good enough to post","then":"Weeks pass. No sketch ever feels ready."},{"text":"Join, but only lurk and like others' posts","then":"You enjoy the art. Nobody there knows you exist."},{"text":"Join and post your first sketch","then":"Two people comment within the hour. One asks what pen you use.","best":true},{"text":"Skip it. Only in-person friends count","then":"You close the tab. A month later, a classmate forwards you the same group."}],"why":"Posting and chatting, not just watching, is how an online group becomes your people."},{"prompt":"Members in your city plan a Sunday sketch walk in a public park. What do you do?","options":[{"text":"Skip it. Chatting online is enough","then":"The photos go up that evening. Everyone looks like they had fun."},{"text":"Say you'll come, then decide on the day","then":"Sunday comes and staying in is easier. You don't go."},{"text":"Go along and say hi to whoever's there","then":"The group is small and friendly. By noon you're swapping sketchbooks.","best":true},{"text":"Go, but leave before anyone talks to you","then":"You spot the group across the lawn, then head home."}],"why":"Meeting in a public place deepens friendships that began online."},{"prompt":"A classmate says online groups are for people who can't make real friends. What do you say?","options":[{"text":"Laugh along and agree it's a bit sad","then":"She moves on. You feel oddly ashamed of something you enjoy."},{"text":"Say plenty of real friendships start online now","then":"She shrugs. \"Maybe. I met my closest friend on a gaming server, actually.\"","best":true},{"text":"Say it's just a hobby group, nothing serious","then":"She nods. You've played down something that matters to you."},{"text":"Call her closed-minded","then":"She rolls her eyes. The chat turns into a small argument."}],"why":"Online groups are a real way to find your people, and it's fine to say so plainly."}],"debrief":"Online communities can genuinely find your people. Meeting offline deepens them.","relearn":"Online hobby communities can find your people; meeting offline deepens it."},
  {"id":"mb-1011","cat":"find-your-people","type":"role-play","persona":"any","source":"canteen opener","hook":"Neel, from your hostel, is sitting alone in the canteen. You'd like to get to know him.","setup":"You walk over with your tray.","steps":[{"prompt":"Neel looks up and says: \"Hi. Looking for a seat?\"","options":[{"text":"\"No, no. Just passing.\"","then":"\"Oh, okay.\" A minute later every table is full, and you end up beside him anyway."},{"text":"\"Yeah, everywhere else is full.\"","then":"\"Oh. Sure.\" He shifts his tray and goes back to his food."},{"text":"\"Yes. Mind if I sit here? I don't know many people yet.\"","then":"Neel smiles. \"Please. Me neither, honestly.\"","best":true},{"text":"\"Is this free? I can move if your friends are coming.\"","then":"Neel hesitates. \"Uh, no, it's fine.\" It feels a bit stiff."}],"why":"An honest, simple opener like asking to sit is enough to start."},{"prompt":"Neel says: \"I transferred here this year, so I don't really know anyone.\"","options":[{"text":"\"At least you've done a year of college already.\"","then":"\"Different place, though,\" he says, and stirs his dal."},{"text":"\"Oh, that's hard. Where did you move from?\"","then":"\"Indore.\" He brightens. \"You'd love the food there. Let me tell you.\"","best":true},{"text":"\"Ugh. People here are so cliquey.\"","then":"\"Yeah,\" Neel says, gloomier now. \"Maybe it's hopeless.\""},{"text":"\"Same. Anyway, what are you studying?\"","then":"\"Commerce,\" he says. The chat stays polite."}],"why":"Asking about his story shows real interest and gives him room to open up."},{"prompt":"As you both get up, Neel says: \"This was nice. I usually eat alone.\"","options":[{"text":"\"Yeah. See you around.\"","then":"\"See you around,\" Neel echoes. Neither of you knows when."},{"text":"\"No worries. Happy to keep you company.\"","then":"\"Right. Thanks,\" Neel says, a little stiffly."},{"text":"\"Same time tomorrow, then?\"","then":"\"Yes. I'll save a seat.\" He's grinning.","best":true},{"text":"\"You should join some clubs. That'd help.\"","then":"Neel's smile fades a little. \"Yeah, maybe.\""}],"why":"A simple plan to meet again turns one good lunch into a habit."}],"relearn":"A simple, honest opener like asking to sit is enough to start a connection."},
  {"id":"mb-1012","cat":"find-your-people","type":"role-play","persona":"any","source":"concrete invite","hook":"Riya from class is friendly and easy to talk to, and you'd like her to become a real friend.","setup":"She catches up with you after the morning lecture.","steps":[{"prompt":"Riya laughs and says: \"We keep saying we'll hang out. We never do!\"","options":[{"text":"\"We should! Let's plan something soon.\"","then":"\"Yes, soon!\" Riya says. Neither of you names a day."},{"text":"\"True. We're getting chai after class. Come?\"","then":"\"Yes! Finally.\" She walks with you to the canteen.","best":true},{"text":"\"I know. I'm just so busy these days.\"","then":"\"Same,\" Riya says. \"Some other time, then.\""},{"text":"\"You're right. You should plan something.\"","then":"\"Me?\" She laughs. \"Okay, maybe.\" Nothing gets planned."}],"why":"A small, concrete invite beats a vague 'sometime' that never comes."},{"prompt":"Later that week, Riya says: \"My roommate's gone home. The hostel's so quiet.\"","options":[{"text":"\"Enjoy the peace! I'd love a quiet room.\"","then":"Riya laughs. \"I guess.\" She heads back alone."},{"text":"\"Aw. Call me if you get bored.\"","then":"\"Sure,\" she says. She doesn't call."},{"text":"\"You should make more friends in your hostel.\"","then":"\"Thanks,\" Riya says, a bit flat."},{"text":"\"Come for dinner with us tonight.\"","then":"\"Really? Yes. Eight o'clock?\"","best":true}],"why":"A specific invite for tonight answers loneliness better than an open offer."},{"prompt":"A few days later, Riya says: \"There's a stand-up show on campus next Friday.\"","options":[{"text":"\"Nice. Tell me how it is.\"","then":"\"Oh. Sure,\" she says, a little deflated."},{"text":"\"Let's go! We'll sort out timing later.\"","then":"\"Great!\" she says. Later never quite comes."},{"text":"\"Let's go. Meet at the gate at seven?\"","then":"\"Done. I'll bring snacks.\"","best":true},{"text":"\"Maybe. Text me closer to the day.\"","then":"\"Okay,\" Riya says. Friday comes, and neither of you texts."}],"why":"Fixing a time turns an idea into a plan that actually happens."}],"relearn":"A small concrete invite beats a vague 'we should hang out' that never happens."},
  {"id":"mb-1013","cat":"find-your-people","type":"role-play","persona":"Deepak","source":"stepping into a group","hook":"At your first debate society meeting, everyone seems to know each other already.","setup":"You're standing near the door with your bag still on.","steps":[{"prompt":"A senior, Farhana, spots you by the door and says: \"Hi! Here for the meeting?\"","options":[{"text":"\"Yes. I'll just sit at the back and watch.\"","then":"\"Sure,\" she says. You take a seat at the edge of the room."},{"text":"\"Sorry, just looking. I'll come another time.\"","then":"\"Stay! It's fine,\" she says, and pulls out a chair for you."},{"text":"\"Yes, but I'm probably not good enough to speak.\"","then":"Farhana waves it off. \"Nobody is at first. Sit.\""},{"text":"\"Yes. I'm new. What got you all into this?\"","then":"Farhana laughs. \"Arguing with my brothers.\" Two others join in.","best":true}],"why":"A friendly question about them is an easy way to step into a group."},{"prompt":"Farhana says: \"We're doing a practice round. Want to try speaking for a minute?\"","options":[{"text":"\"Only after I've prepared properly.\"","then":"\"Next week, then,\" she says. The round starts without you."},{"text":"\"I'm nervous, but okay. One minute.\"","then":"\"Go on, then,\" she says, and hands you a topic card.","best":true},{"text":"\"My English isn't good enough for this.\"","then":"\"Plenty of us mix languages,\" Farhana says. \"Next time, maybe.\""},{"text":"\"No, no. I'll just watch today.\"","then":"\"Sure,\" she says, and asks someone else."}],"why":"Trying once, nerves and all, is how you go from outsider to part of it."},{"prompt":"After the meeting, a member, Kunal, says: \"A few of us get chai after. Coming?\"","options":[{"text":"\"Are you sure? I don't want to intrude.\"","then":"Kunal pauses. \"Uh, yeah. I asked.\" It gets a little awkward."},{"text":"\"I can't. I need to get back.\"","then":"\"Next time,\" Kunal says, and the group heads off."},{"text":"\"Maybe after a few more meetings.\"","then":"\"Sure,\" Kunal says. The group heads off laughing."},{"text":"\"Yes. Thanks for asking.\"","then":"\"Come on, then.\" He makes room for you on the stairs.","best":true}],"why":"Saying yes to the plan after is where members turn into friends."},{"prompt":"Next week, Farhana says: \"Can you help welcome the new people at the door?\"","options":[{"text":"\"Sure. I know exactly how they feel.\"","then":"\"That's why I asked,\" Farhana says, and hands you the sign-up sheet.","best":true},{"text":"\"Me? I barely belong here myself.\"","then":"Farhana laughs. \"You're here, aren't you?\" She asks someone else anyway."},{"text":"\"Okay, but I'll only hand out forms.\"","then":"\"Sure,\" she says. You hand out forms and talk to no one."},{"text":"\"I'd rather let them find their own way in.\"","then":"Farhana shrugs. Two newcomers hover at the door, just like you did."}],"why":"Welcoming others shows you belong now, and helps the next newcomer too."}],"relearn":"A friendly question to a group is an easy way to step in when everyone seems to know each other."},
  {"id":"mb-1014","cat":"find-your-people","type":"role-play","persona":"any","source":"reassure not too late","hook":"Your friend Aditi has been lonely this term, and it's starting to get her down.","setup":"It's week eight, and you're walking back from class together.","steps":[{"prompt":"Aditi says: \"Everyone found their group in week one. I missed the boat.\"","options":[{"text":"\"Yeah, the friend groups are pretty locked in now.\"","then":"Aditi's face drops. \"Great. So I'm right.\""},{"text":"\"Groups keep forming all year. You're not late.\"","then":"Aditi looks up. \"Really? It doesn't feel like it.\"","best":true},{"text":"\"You have me. Isn't that enough?\"","then":"\"I know,\" she says. \"But I still feel on the outside.\""},{"text":"\"Honestly, those groups aren't that great anyway.\"","then":"\"Easy for you to say,\" Aditi mutters."}],"why":"Honest reassurance that groups keep forming loosens the too-late story."},{"prompt":"Aditi says: \"Even if I tried now, it'd be so awkward.\"","options":[{"text":"\"Then don't force it. It'll happen on its own.\"","then":"\"Maybe,\" she says. Nothing in her week changes."},{"text":"\"Just be more confident and it won't be.\"","then":"\"If only it were that easy,\" Aditi sighs."},{"text":"\"A bit. Want to try the photo club with me?\"","then":"Aditi thinks. \"With you? Okay. That's less scary.\"","best":true},{"text":"\"True. It's probably easier to wait for next year.\"","then":"Aditi nods slowly. \"Next year\" sounds very far away."}],"why":"Going with her makes the first step less awkward and more likely."},{"prompt":"On Thursday, Aditi says: \"There's a photo club meeting tomorrow. What if nobody talks to me?\"","options":[{"text":"\"Someone will. I promise.\"","then":"\"You can't promise that,\" she says, half smiling."},{"text":"\"Then at least you'll know it's not for you.\"","then":"\"So one bad day and I'm done?\" Aditi looks less sure."},{"text":"\"You're overthinking it. Just go.\"","then":"\"Okay, okay,\" she says, sounding more anxious."},{"text":"\"Then go again next week. It takes a few goes.\"","then":"Aditi breathes out. \"Okay. A few goes. I can do that.\"","best":true}],"why":"Planning to keep showing up takes the pressure off any one meeting."}],"relearn":"Remind a lonely friend that groups keep forming all year; they're not too late."},
  {"id":"mb-1015","cat":"find-your-people","type":"role-play","persona":"any","source":"reconnect","hook":"At the library, you bump into Siddharth, who you clicked with at orientation weeks ago.","setup":"He stops by your table on his way out.","steps":[{"prompt":"Siddharth says: \"Hey! Orientation, right? How've you been?\"","options":[{"text":"\"Good, good. We should catch up sometime.\"","then":"\"Definitely!\" he says, already walking off."},{"text":"\"Good! Want to grab a coffee this week?\"","then":"\"Yes! I've been meaning to find you.\" He pulls out his phone.","best":true},{"text":"\"Busy. You know how it is.\"","then":"\"Tell me about it,\" he says, and waves goodbye."},{"text":"\"Oh, you remember me? I thought you'd forgotten.\"","then":"He laughs, a little unsure. \"Of course I remember.\""}],"why":"A direct, warm offer reconnects far better than a vague 'sometime'."},{"prompt":"Two days later, Siddharth texts: \"Nice bumping into you! Crazy week of labs though.\"","options":[{"text":"\"Haha. All the best with the labs!\"","then":"He sends a thumbs up. That's the end of it."},{"text":"\"Same here. Free Thursday evening for a quick chai?\"","then":"\"Thursday works. Six at the canteen?\"","best":true},{"text":"\"Let me know whenever you're free.\"","then":"\"Will do!\" he replies. The chat goes quiet."},{"text":"\"I get it. You're probably too busy for new friends.\"","then":"\"What? No,\" he replies. \"Just busy this week.\""}],"why":"A specific, small plan makes it easy for a busy person to say yes."},{"prompt":"A month on, Siddharth texts: \"Sorry, labs swamped me again. Still keen to catch up properly?\"","options":[{"text":"\"It's fine. I figured you weren't interested.\"","then":"\"No! Sorry,\" he replies. \"I really am.\""},{"text":"\"No worries. Whenever you're free.\"","then":"\"Great!\" he replies. Neither of you names a day."},{"text":"\"No problem. Chai on Saturday?\"","then":"\"Saturday. Yes. I'll set a reminder this time.\"","best":true},{"text":"\"Everyone's busy. Maybe next semester.\"","then":"\"Yeah, maybe,\" he replies. It sounds a long way off."}],"why":"Answering warmly with a real plan, not guilt, keeps a new friendship alive."}],"relearn":"A direct, warm follow-up reconnects far better than a vague 'we should catch up'."},
  {"id":"mb-1016","cat":"find-your-people","type":"role-play","persona":"Rohan","source":"room for one more","hook":"Classmates are planning a weekend trip to the hills. You'd love to go but fear sounding needy.","setup":"They're talking about it in the canteen.","steps":[{"prompt":"At the next table, Yash says: \"We book the bus tonight. Six of us so far.\"","options":[{"text":"\"Sounds fun. I'm free all weekend, by the way.\"","then":"\"Nice,\" Yash says, and turns back to the booking."},{"text":"\"Trips like that are overrated anyway.\"","then":"Yash raises an eyebrow. \"Okay, man.\""},{"text":"\"That trip sounds great. Room for one more?\"","then":"Yash grins. \"Obviously. I'll add you to the group.\"","best":true},{"text":"\"You guys never invite me to anything.\"","then":"Yash looks caught out. \"Uh. We didn't know you'd want to come.\""}],"why":"Asking directly works better than hinting and hoping."},{"prompt":"On Monday, Yash says: \"The hills were a blast. A few of us are seeing a film on Friday.\"","options":[{"text":"\"If there's space, I could maybe come, I guess.\"","then":"Yash can't tell if that's a yes. \"Uh, cool. Let me know.\""},{"text":"\"Cool. Have fun.\"","then":"\"Thanks,\" Yash says, and the plan moves on without you."},{"text":"\"Count me in. What time?\"","then":"\"Seven. I'll save you a seat.\"","best":true},{"text":"\"Only if you actually want me there.\"","then":"Yash frowns. \"Why would I mention it otherwise?\""}],"why":"A plain yes tells people you want in, without making them guess."},{"prompt":"Later, Yash says: \"You're always so quiet. I thought you didn't like us.\"","options":[{"text":"\"Whatever. I'm fine on my own.\"","then":"Yash shrugs. \"Okay. Just saying.\""},{"text":"\"I'm just like that. Doesn't matter.\"","then":"\"Okay,\" Yash says. He doesn't quite get it."},{"text":"\"I worried about seeming needy. I do like you all.\"","then":"Yash laughs. \"Needy? Bro, we thought you were too cool for us.\"","best":true},{"text":"\"You lot never make space for new people.\"","then":"\"That's not fair,\" Yash says, stung."}],"why":"Saying honestly that you want to belong clears the mix-up and brings you closer."}],"relearn":"Asking 'room for one more?' directly works better than hinting and hoping."},
  {"id":"mb-1017","cat":"find-your-people","type":"role-play","persona":"any","source":"shared hobby","hook":"Mira from your hostel just mentioned she plays chess. You rarely meet anyone who does.","setup":"You're both waiting for the laundry machines.","steps":[{"prompt":"Mira says: \"I've been playing online, but I miss a real board.\"","options":[{"text":"\"Chess? I wouldn't have guessed that.\"","then":"Mira shrugs. \"People never do.\""},{"text":"\"I play a bit too, but I'm not very good.\"","then":"\"Oh, cool,\" she says. The machine beeps and she goes."},{"text":"\"Wait, you play too? I've got a board in my room.\"","then":"Her eyes light up. \"No way. A real one? Tonight?\"","best":true},{"text":"\"Online's easier anyway. More people to play.\"","then":"\"True,\" Mira says, and goes back to her phone."}],"why":"Naming the shared interest out loud is what turns it into common ground."},{"prompt":"A few days later, Mira says: \"Some of us want to start a chess night in the common room.\"","options":[{"text":"\"Nice idea. Let me know how it goes.\"","then":"\"Oh. Okay,\" she says. \"I thought you might want in.\""},{"text":"\"Maybe. I'm not sure I'm good enough.\"","then":"\"Nobody cares about good,\" she says. \"But okay.\""},{"text":"\"I'd love that. I'll bring my board.\"","then":"\"Perfect. Wednesday at nine, then.\"","best":true},{"text":"\"Chess nights always fizzle out, honestly.\"","then":"Mira's face falls a little. \"We'll see.\""}],"why":"Saying yes, and bringing something, makes the shared hobby a real plan."},{"prompt":"Two weeks later, Mira says: \"Chess night keeps growing. We need someone to help run it.\"","options":[{"text":"\"Not me. I'd only mess it up.\"","then":"\"You wouldn't,\" Mira says, but she asks someone else."},{"text":"\"I can help run it with you.\"","then":"\"Yes! You do the boards. I'll do the snacks.\"","best":true},{"text":"\"Maybe once exams are over.\"","then":"\"Okay,\" she says. By then, someone else has stepped in."},{"text":"\"Just keep it small. Big groups ruin it.\"","then":"Mira frowns. \"I kind of like it big.\""}],"why":"Helping run it turns a shared hobby into a steady place to belong."}],"relearn":"Naming a shared interest out loud and suggesting doing it together turns it into a friendship."},
  {"id":"mb-1018","cat":"find-your-people","type":"role-play","persona":"Meena","source":"tea opener","hook":"A neighbour at your working women's hostel keeps to herself, the way you do.","setup":"You're both back from long shifts.","steps":[{"prompt":"Your neighbour Shanti nods at you in the corridor and says: \"Long day?\"","options":[{"text":"\"Always. This city is too much.\"","then":"\"Hmm,\" she says, and unlocks her door."},{"text":"\"Yes. Sorry, I'll let you rest.\"","then":"\"Oh. Okay,\" Shanti says, and goes in."},{"text":"\"Very. I'm making tea. Want a cup?\"","then":"She pauses, then smiles. \"Yes. I'd like that.\"","best":true},{"text":"\"Very. We should have tea sometime.\"","then":"\"Sometime, sure,\" she says. Her door clicks shut."}],"why":"A small, low-pressure offer like tea is an easy way to start knowing a neighbour."},{"prompt":"Next evening, Shanti knocks and says: \"Do you have a little sugar? I've run out.\"","options":[{"text":"\"Keep the whole packet. I really don't need it.\"","then":"\"Oh, thank you!\" She takes it and heads off."},{"text":"\"Here you go. Goodnight.\"","then":"\"Thanks,\" she says, and goes back to her room."},{"text":"\"It's late, Shanti. Can you ask someone else?\"","then":"\"Oh. Sorry,\" she says, and knocks on the next door."},{"text":"\"Here. Sit for a minute? I'm in room twelve.\"","then":"\"I know.\" She laughs and sits on the edge of your cot.","best":true}],"why":"Turning a small errand into a short chat opens the door to knowing someone."},{"prompt":"On Sunday, Shanti says: \"I'm from a village near Madurai. Here, I don't really know anyone.\"","options":[{"text":"\"You'll get used to it. Everyone does.\"","then":"\"Maybe,\" she says quietly."},{"text":"\"Me neither. I miss home too.\"","then":"Shanti nods slowly. \"It helps to hear someone say it.\"","best":true},{"text":"\"At least you have work here.\"","then":"\"True,\" Shanti says, and the talk ends there."},{"text":"\"You should call your family more often.\"","then":"\"I do,\" she says. \"It's not the same.\""}],"why":"Saying you feel it too helps you both feel less alone."},{"prompt":"A few days later, Shanti says: \"There's a free Sunday market by the station. Have you been?\"","options":[{"text":"\"No. Tell me what it's like there.\"","then":"\"Lots of stalls, cheap bangles,\" she says. She goes alone."},{"text":"\"Maybe some other time, when I'm less tired.\"","then":"\"Sure,\" she says. Sunday comes and goes."},{"text":"\"No. I don't really go out much.\"","then":"\"Oh. Okay,\" she says, and asks the girl next door instead."},{"text":"\"No. Shall we go together next Sunday?\"","then":"\"Yes! I'll show you the best chaat stall.\"","best":true}],"why":"Going together turns a neighbour into a friend, and the city a little more into home."}],"relearn":"A small, low-pressure offer like sharing tea is an easy way to start knowing a neighbour."},
  {"id":"mb-1019","cat":"find-your-people","type":"role-play","persona":"any","source":"say you enjoyed it","hook":"You went to your first hangout with Aarav's group and had a really good time.","setup":"Everyone is getting up to leave the café.","steps":[{"prompt":"Aarav says: \"Thanks for coming! Hope we weren't too loud.\"","options":[{"text":"\"It was okay. A bit noisy for me.\"","then":"\"Oh. Fair,\" Aarav says, unsure whether to ask you again."},{"text":"\"Not at all. I had a great time. Let's do it again.\"","then":"Aarav grins. \"Yes! You're in the group chat now.\"","best":true},{"text":"\"No, no. Thanks so much for letting me tag along.\"","then":"\"Anytime,\" he says, and turns to grab his jacket."},{"text":"\"Ha, you were. Anyway, see you around.\"","then":"\"See you,\" he says with a small laugh."}],"why":"Saying you enjoyed it and want more makes people likelier to include you."},{"prompt":"A week later, Aarav says: \"We're planning another outing. Any ideas?\"","options":[{"text":"\"Whatever you all decide is fine with me.\"","then":"\"Okay,\" Aarav says. The plan gets made without your input."},{"text":"\"I'm not great with ideas. Ask the others.\"","then":"\"Sure,\" he says, and turns to someone else."},{"text":"\"The book fair's on Saturday. I'd love to go.\"","then":"\"Oh, nice. I'll put it to the group.\"","best":true},{"text":"\"Oh, am I invited? I wasn't sure.\"","then":"\"Of course,\" Aarav says, a bit puzzled."}],"why":"Offering an idea shows you're in, not just waiting to be picked."},{"prompt":"After the next outing, Aarav messages: \"You seemed quiet today. All okay?\"","options":[{"text":"\"I didn't think anyone would even notice.\"","then":"\"I noticed,\" he replies. \"You sure you're okay?\""},{"text":"\"Fine. Just really busy with assignments.\"","then":"\"Okay,\" he replies. The chat stays quiet."},{"text":"\"Yeah, I didn't want to get in the way.\"","then":"\"In the way?\" Aarav replies. \"We want to hear from you.\""},{"text":"\"All good. I'm just shy. I love our plans.\"","then":"\"Same, honestly. Glad you're with us.\"","best":true}],"why":"Telling people you value them keeps you in the circle, even when you're shy."}],"relearn":"Saying out loud that you enjoyed it and want more makes people likelier to include you again."},
  {"id":"mb-1020","cat":"find-your-people","type":"role-play","persona":"any","source":"start the group","hook":"Exams are six weeks away. You want to start a study group but worry nobody will join.","setup":"Harpreet sees you staring at the class group chat.","steps":[{"prompt":"Harpreet says: \"You've been typing and deleting for ages. What's up?\"","options":[{"text":"\"Nothing. Just thinking about exams.\"","then":"She glances at your screen. \"A study group? Post it!\""},{"text":"\"I'm starting a study group. Want to be the first in?\"","then":"\"Me? Yes. Put my name down.\"","best":true},{"text":"\"I had an idea for a study group, but it's pointless.\"","then":"\"Why pointless?\" Harpreet asks. \"Post it and see.\""},{"text":"\"Do you think anyone would want to study with me?\"","then":"\"Of course,\" she says. \"So what's stopping you?\""}],"why":"Saying it out loud and asking one person turns a worry into a start."},{"prompt":"Harpreet says: \"Okay, so what are you going to write?\"","options":[{"text":"\"Sorry to bother everyone, but maybe a study group?\"","then":"\"Why sorry?\" she asks. You post it anyway, apology and all."},{"text":"\"I'll post once I've made a full timetable.\"","then":"\"Okay,\" she says. Three days later, you post it."},{"text":"\"Study group before exams, Tuesdays at five. Anyone in?\"","then":"Harpreet reads it over your shoulder. You hit send.","best":true},{"text":"\"Maybe I'll wait and see if someone else starts one.\"","then":"\"Or you could be the one,\" she says. You post it, half hoping no one sees."}],"why":"A clear, specific offer is easy for people to say yes to."},{"prompt":"A few days later, Harpreet says: \"Only two others have signed up. Is that enough?\"","options":[{"text":"\"No. Nobody's interested. I'll cancel it.\"","then":"\"Don't,\" Harpreet says. \"Let's at least try the first one.\""},{"text":"\"It's a start. Three of us can get a lot done.\"","then":"\"True,\" she says. \"And small means we'll actually talk.\"","best":true},{"text":"\"Let's wait till we have ten before meeting.\"","then":"\"Ten could take weeks,\" she says. \"Let's try one session first.\""},{"text":"\"See? I knew people wouldn't want to.\"","then":"\"Two people did want to,\" Harpreet points out. \"Let's meet them.\""}],"why":"A small group is still a real group, and it often grows."},{"prompt":"After the first session, Harpreet says: \"That was actually fun. Same time next week?\"","options":[{"text":"\"Maybe. It depends how busy I am.\"","then":"\"Okay,\" she says. \"Let me know.\" It sounds less certain."},{"text":"\"Only if the others really want to.\"","then":"\"They said they did,\" Harpreet says. \"Ask them.\""},{"text":"\"Yes. And let's tell the class there's still room.\"","then":"\"Good idea. I'll post it this time.\"","best":true},{"text":"\"Yes, but let's close it now. It works as it is.\"","then":"\"Okay,\" she says. Later, two classmates who ask are told no."}],"why":"Keeping it going, and open, is how a study group becomes your people."}],"relearn":"Offering to start a group is itself a way to find your people; others are often waiting for it."},
  {"id":"mb-1021","cat":"find-your-people","type":"role-play","persona":"Zoya","source":"low pressure invite","hook":"You've clicked with Anjali from theatre workshop, but worry an invite will seem too keen.","setup":"After rehearsal, she's walking out beside you.","steps":[{"prompt":"Anjali says: \"That scene today was so much fun.\"","options":[{"text":"\"So fun. Let me know if you ever want to hang out.\"","then":"\"Sure!\" she says. It's unclear who will ask first."},{"text":"\"Yeah. See you next week.\"","then":"\"See you,\" she says, and heads for her bus."},{"text":"\"It was! No pressure, but I'd love to hang out more.\"","then":"Anjali smiles. \"Me too, actually. I was going to say.\"","best":true},{"text":"\"We should be best friends. Meet every day?\"","then":"Anjali laughs, a bit startled. \"Every day? Wow. Maybe.\""}],"why":"A warm, low-pressure invite lets a friendship grow without coming on too strong."},{"prompt":"At the next rehearsal, Anjali sighs: \"I never see anyone. My weekends are all café shifts.\"","options":[{"text":"\"Sounds rough. Hope it eases up soon.\"","then":"\"Me too,\" she says, and goes to find her script."},{"text":"\"You could skip one shift, na?\"","then":"\"I really can't,\" she says. \"I need the money.\""},{"text":"\"Then chai after Wednesday's rehearsal?\"","then":"\"Yes! Wednesday works. Finally, a plan.\"","best":true},{"text":"\"Totally get it. Whenever you're free, then.\"","then":"\"Okay!\" she says. Neither of you picks a day."}],"why":"Working around her week shows you care, without pushing."},{"prompt":"The next week, Anjali says: \"My family wants me to quit theatre. Sorry, I'm venting.\"","options":[{"text":"\"Just tell them it's your life.\"","then":"\"You don't know my family,\" she says, with a tired smile."},{"text":"\"Vent away. I'm glad you told me.\"","then":"Anjali breathes out. \"Thanks. I don't say this to many people.\"","best":true},{"text":"\"Ugh, families. Mine's even worse, honestly.\"","then":"\"Oh?\" she says, and ends up listening to you instead."},{"text":"\"Oh. Anyway, did you learn your lines?\"","then":"\"Yeah,\" she says, and goes quiet."}],"why":"Letting her share at her own pace is how a new friendship deepens."}],"relearn":"A warm, low-pressure invite lets a friendship grow without coming on too strong."},
  {"id":"mb-1022","cat":"find-your-people","type":"role-play","persona":"any","source":"tag along","hook":"Aisha and Karan from your floor are heading out, and you'd like to join them.","setup":"The lift is just arriving.","steps":[{"prompt":"Aisha says: \"Hi! We're off to the night market.\"","options":[{"text":"\"Nice. Have fun, you two.\"","then":"\"Thanks!\" The lift doors close on them."},{"text":"\"Must be nice to have plans.\"","then":"Aisha pauses. \"Uh, yeah.\" Karan checks his phone."},{"text":"\"I'd come, but I don't want to intrude.\"","then":"\"Oh, okay,\" Aisha says, unsure whether to insist."},{"text":"\"Oh, fun. Mind if I tag along?\"","then":"\"Of course! Grab your bag.\"","best":true}],"why":"Asking to tag along in the moment is a normal, easy way to join in."},{"prompt":"Next morning, Karan says: \"We're making the market a Friday thing.\"","options":[{"text":"\"Cool. Maybe I'll see you there.\"","then":"\"Sure,\" Karan says. It's not clear if you're coming."},{"text":"\"I'm in. Knock on my door on Friday?\"","then":"\"Deal. Seven sharp.\"","best":true},{"text":"\"You two don't need me hanging around.\"","then":"\"What? It's not like that,\" Karan says, confused."},{"text":"\"Every week? That's a lot for me.\"","then":"\"Come when you can,\" he says, a bit less sure."}],"why":"A clear yes, with a way to meet, turns tagging along into a routine."},{"prompt":"A month later, Aisha says: \"A new girl moved in down the hall. She seems a bit lost.\"","options":[{"text":"\"She'll find her people. Everyone does.\"","then":"\"I guess,\" Aisha says, and the talk moves on."},{"text":"\"Let's not invite her. It'd change things for us.\"","then":"\"Sure,\" Aisha says. The new girl's door stays shut."},{"text":"\"You ask her. You're better at that.\"","then":"\"Okay,\" Aisha says. By Friday, she's forgotten."},{"text":"\"Let's ask her to the market this Friday.\"","then":"\"Yes,\" Aisha says. \"Let's knock on her door now.\"","best":true}],"why":"Passing the welcome on keeps belonging open, as it was for you."}],"relearn":"Asking to tag along in the moment is a normal, easy way to join in."},
  {"id":"mb-1023","cat":"find-your-people","type":"role-play","persona":"any","source":"no perfect moment","hook":"Rahul in your stats class seems friendly, but you keep waiting for the right time to talk.","setup":"He's still packing up next to you.","steps":[{"prompt":"As the lecture ends, Rahul mutters: \"I did not follow that last bit at all.\"","options":[{"text":"\"Me neither. I'll ask you about it next time.\"","then":"\"Okay,\" he says. Next time is a week away."},{"text":"\"It's in the textbook, I think.\"","then":"\"Right,\" he says, and zips up his bag."},{"text":"\"Same. Did you get what she meant by variance?\"","then":"\"Not a clue.\" He laughs and pulls his notes back out.","best":true},{"text":"\"Sorry, I have to run.\"","then":"\"Sure, bye,\" he says. You don't really have to be anywhere."}],"why":"A small, everyday question is enough to start. There's no perfect moment."},{"prompt":"At the next class, Rahul says: \"Did you ever figure out that last bit?\"","options":[{"text":"\"Kind of. I'll send you my notes sometime.\"","then":"\"Thanks!\" he says. Sometime never quite comes."},{"text":"\"Yeah, it was easy once I read it.\"","then":"\"Oh. Lucky you,\" he says, and turns to his notes."},{"text":"\"No. I'm hopeless at stats.\"","then":"\"Join the club,\" he says, as the lecture starts."},{"text":"\"Sort of. Want to go over it together at lunch?\"","then":"\"Yes, please. I'll bring the samosas.\"","best":true}],"why":"Turning a small question into a shared task keeps the connection going."},{"prompt":"A week later, Rahul says: \"Some of us are getting momos after class. Coming?\"","options":[{"text":"\"Next time. I've got stuff to do.\"","then":"\"Sure,\" he says. The group heads off laughing."},{"text":"\"Are you sure the others won't mind?\"","then":"\"Why would they?\" Rahul says, a little puzzled."},{"text":"\"Yes. Let me grab my bag.\"","then":"\"Great. We'll wait at the gate.\"","best":true},{"text":"\"Maybe. I'll see how I feel after class.\"","then":"\"Okay,\" he says. After class, they've already gone."}],"why":"Saying yes to a small invite builds on the start you made."}],"relearn":"A small everyday question is enough to start; there's no perfect moment to wait for."},
  {"id":"mb-1024","cat":"find-your-people","type":"role-play","persona":"Deepak","source":"honest about lonely","hook":"Two months into the city, you're finding it hard to make friends.","setup":"Nandini, your lab partner, walks back to the hostel with you.","steps":[{"prompt":"Nandini asks: \"You seem quiet lately. How are you finding it here?\"","options":[{"text":"\"Great! Everything's great.\"","then":"\"Oh, good,\" Nandini says, and the talk moves to exams."},{"text":"\"It's okay. Just a lot of work.\"","then":"\"Tell me about it,\" she says. The chat stays on assignments."},{"text":"\"Honestly, it's been a bit lonely. I'm still finding my feet.\"","then":"Nandini slows down. \"Oh. Thank you for telling me.\"","best":true},{"text":"\"Fine. People like me don't really fit here anyway.\"","then":"Nandini frowns. \"People like you? What do you mean?\""}],"why":"Saying honestly that you're lonely invites the very connection you need."},{"prompt":"Nandini says: \"You know, in first year I felt totally alone. Nobody knew.\"","options":[{"text":"\"But you're so confident. You must've fit in fast.\"","then":"\"Not at all,\" she says. \"I just got good at hiding it.\""},{"text":"\"Really? I thought it was just me.\"","then":"\"Nope. Most of my friends felt it too. We just never said.\"","best":true},{"text":"\"That's different. You're from the city.\"","then":"Nandini pauses. \"Maybe. It still felt awful.\""},{"text":"\"Oh. Anyway, did you finish the lab report?\"","then":"\"Nearly,\" she says, and the moment closes."}],"why":"Letting her story in shows you it's common, not a sign you don't belong."},{"prompt":"Nandini says: \"There's a Sunday cooking club in our hostel. Want to try it with me?\"","options":[{"text":"\"Maybe once things settle down.\"","then":"\"Okay,\" Nandini says. \"The offer stands.\""},{"text":"\"I can't cook anything. I'd embarrass myself.\"","then":"\"Nobody can,\" she laughs. \"That's the point.\""},{"text":"\"Yes. I'd like that.\"","then":"\"Great. Sunday at eleven. Bring an appetite.\"","best":true},{"text":"\"You don't have to do this out of pity.\"","then":"Nandini looks hurt. \"It's not pity. I'd like the company.\""}],"why":"Accepting a warm offer is how honesty turns into real connection."},{"prompt":"In the canteen, Nandini says: \"Come meet my friend Joseph. He's new this year too.\"","options":[{"text":"\"Nice to meet you, Joseph.\"","then":"\"You too,\" Joseph says. Nandini does the rest of the talking."},{"text":"\"Hi, Joseph. How are you finding it here?\"","then":"Joseph laughs. \"Honestly? Bit lonely. You?\"","best":true},{"text":"\"Hi. Sorry, I'm not much of a talker.\"","then":"Joseph nods politely. \"No problem.\" It goes quiet."},{"text":"\"Hey. Everything's going great for me, by the way.\"","then":"\"Oh, nice,\" Joseph says. \"Wish I could say that.\""}],"why":"Asking a newcomer what you were asked passes the connection on."},{"prompt":"On a lonely Sunday weeks later, Nandini texts: \"Free this evening?\"","options":[{"text":"\"Busy, sorry! Another time.\"","then":"\"No worries!\" she replies. The evening stays quiet."},{"text":"\"Free, but I'd be bad company tonight.\"","then":"\"Oh. Okay, another day,\" she replies."},{"text":"\"Free. It's been a lonely day, honestly. Chai?\"","then":"\"Chai. Ten minutes. I'm coming over.\"","best":true},{"text":"\"Free, but you've got better things to do.\"","then":"\"Do I?\" she replies. \"Okay, if you're sure.\""}],"why":"Saying so on a hard evening lets support in when you need it most."}],"relearn":"Saying honestly that you're finding it lonely often invites the very connection you need."},
  {"id":"mb-1025","cat":"find-your-people","type":"sort","hook":"Sort: builds belonging, or keeps you on the outside?","items":[{"id":"a","text":"Asking someone to grab chai"},{"id":"b","text":"Waiting to be invited to everything"},{"id":"c","text":"Joining a club you're curious about"},{"id":"d","text":"Turning down plans to avoid awkwardness"},{"id":"e","text":"Following up after a good chat"},{"id":"f","text":"Hoping people will just notice you"}],"bins":[{"id":"builds","label":"Builds belonging","valence":"pos"},{"id":"outside","label":"Keeps you outside","valence":"neg"}],"key":{"a":"builds","b":"outside","c":"builds","d":"outside","e":"builds","f":"outside"},"relearn":"Reaching out, joining and following up build belonging; waiting and avoiding keep you outside.","persona":"any","source":"belonging moves 2"},
  {"id":"mb-1026","cat":"find-your-people","type":"sort","hook":"Sort: a real way to deepen a friendship, or a way to stay surface?","items":[{"id":"a","text":"Sharing something honest about yourself"},{"id":"b","text":"Only ever talking about the weather"},{"id":"c","text":"Showing up when they're having a hard week"},{"id":"d","text":"Cancelling whenever it's slightly inconvenient"},{"id":"e","text":"Remembering and asking about their life"},{"id":"f","text":"Keeping every chat strictly polite and shallow"}],"bins":[{"id":"deepens","label":"Deepens it","valence":"pos"},{"id":"surface","label":"Stays surface","valence":"neg"}],"key":{"a":"deepens","b":"surface","c":"deepens","d":"surface","e":"deepens","f":"surface"},"relearn":"Honesty, showing up and real interest deepen a friendship; small talk doesn't.","persona":"any","source":"deepen vs surface"},
  {"id":"mb-1027","cat":"find-your-people","type":"sort","hook":"Sort: a healthy reason to step back from a group, or just fear talking?","items":[{"id":"a","text":"They mock you when you open up"},{"id":"b","text":"You feel a bit shy at the start"},{"id":"c","text":"You have to hide who you are to fit in"},{"id":"d","text":"It's new and not yet comfortable"},{"id":"e","text":"They pressure you into things you hate"},{"id":"f","text":"You don't know everyone's name yet"}],"bins":[{"id":"healthy","label":"Healthy to step back","valence":"uhoh"},{"id":"fear","label":"Just early nerves","valence":"neutral"}],"key":{"a":"healthy","b":"fear","c":"healthy","d":"fear","e":"healthy","f":"fear"},"relearn":"Mockery, hiding yourself or pressure are reasons to step back; shyness and newness are just early nerves.","persona":"any","source":"step back vs nerves"},
  {"id":"mb-1028","cat":"find-your-people","type":"sort","hook":"Sort: a green flag in a new friend, or a red flag?","items":[{"id":"a","text":"They include you in plans"},{"id":"b","text":"They put you down in front of others"},{"id":"c","text":"They're happy when good things happen for you"},{"id":"d","text":"They only call when they need something"},{"id":"e","text":"They respect when you say no"},{"id":"f","text":"They mock the things you care about"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Including you, celebrating you and respecting your no are green flags; put-downs, using you and mockery are red.","persona":"any","source":"friend flags"},
  {"id":"mb-1029","cat":"find-your-people","type":"sort","hook":"Sort: helps you find your people, or keeps you stuck and alone?","items":[{"id":"a","text":"Going to a meet-up a second time"},{"id":"b","text":"Writing a place off after one visit"},{"id":"c","text":"Saying yes to a casual invite"},{"id":"d","text":"Comparing your week-1 to others' year-3"},{"id":"e","text":"Trying a new shared-interest group"},{"id":"f","text":"Deciding you're 'just not a people person'"}],"bins":[{"id":"helps","label":"Helps you find them","valence":"pos"},{"id":"stuck","label":"Keeps you stuck","valence":"neg"}],"key":{"a":"helps","b":"stuck","c":"helps","d":"stuck","e":"helps","f":"stuck"},"relearn":"Going back, saying yes and trying new groups help; writing places off and labelling yourself keep you stuck.","persona":"any","source":"find vs stuck"},
  {"id":"mb-1030","cat":"find-your-people","type":"sort","hook":"Sort: a sign of real belonging, or only the look of popularity?","items":[{"id":"a","text":"A couple of people you can be real with"},{"id":"b","text":"A huge follower count online"},{"id":"c","text":"Someone who checks in when you go quiet"},{"id":"d","text":"Being invited so you'll boost the vibe"},{"id":"e","text":"People who like the real, unfiltered you"},{"id":"f","text":"Being seen with the 'right' crowd"}],"bins":[{"id":"real","label":"Real belonging","valence":"pos"},{"id":"look","label":"Just the look","valence":"uhoh"}],"key":{"a":"real","b":"look","c":"real","d":"look","e":"real","f":"look"},"relearn":"Real belonging is a few people you can be real with who like the true you; follower counts and the right crowd are just the look.","persona":"any","source":"real vs popular"},
  {"id":"mb-1031","cat":"find-your-people","type":"sort","hook":"Sort: a doable first step to belonging, or a leap that's too big?","items":[{"id":"a","text":"Saying hi to one person in class"},{"id":"b","text":"Becoming everyone's best friend in a week"},{"id":"c","text":"Going to one club meeting"},{"id":"d","text":"Hosting a huge party alone by Friday"},{"id":"e","text":"Asking a classmate one friendly question"},{"id":"f","text":"Never feeling nervous around anyone again"}],"bins":[{"id":"doable","label":"Doable first step","valence":"pos"},{"id":"toobig","label":"Too big a leap","valence":"uhoh"}],"key":{"a":"doable","b":"toobig","c":"doable","d":"toobig","e":"doable","f":"toobig"},"relearn":"One hello, one meeting or one question is doable; expecting instant best-friends or zero nerves is too big.","persona":"Deepak","source":"small steps"},
  {"id":"mb-1032","cat":"find-your-people","type":"sort","hook":"Sort: keeps a new friendship growing, or quietly lets it fade?","items":[{"id":"a","text":"Replying to their messages"},{"id":"b","text":"Leaving every invite on 'maybe'"},{"id":"c","text":"Suggesting the next plan yourself"},{"id":"d","text":"Always being too busy to meet"},{"id":"e","text":"Remembering what they told you"},{"id":"f","text":"Waiting weeks to ever reach out"}],"bins":[{"id":"grows","label":"Keeps it growing","valence":"pos"},{"id":"fades","label":"Lets it fade","valence":"neg"}],"key":{"a":"grows","b":"fades","c":"grows","d":"fades","e":"grows","f":"fades"},"relearn":"Replying, suggesting plans and remembering keep a friendship growing; vague maybes, being always busy and going silent let it fade.","persona":"any","source":"keep it growing"},
  {"id":"mb-1033","cat":"find-your-people","type":"reflect","hook":"Lensy: almost everyone feels like an outsider at the start, even the confident-looking ones. Does that ease it a bit?","prompt":"What do you think?","options":["Yes","It's not just me","That eases it"],"affirm":"Feeling like an outsider at first is nearly universal; the confident faces often feel it too.","relearn":"Almost everyone feels like an outsider at the start, even the ones who look settled.","persona":"any","source":"everyone an outsider"},
  {"id":"mb-1034","cat":"find-your-people","type":"reflect","hook":"Lensy: you don't owe anyone a big personality to be worth knowing; you can be quietly, exactly yourself. Okay?","prompt":"What do you think?","options":["Yes","I can be me","A relief"],"affirm":"You don't need a big personality to belong; the right people value the real, quiet you too.","relearn":"You don't owe anyone a big personality; the right people value the real you.","persona":"Rohan","source":"be yourself"},
  {"id":"mb-1035","cat":"find-your-people","type":"reflect","hook":"Lensy: making friends as an adult is genuinely slow for most people; you're not failing, it just takes time. Land okay?","prompt":"What do you think?","options":["Yes","I'm not failing","It takes time"],"affirm":"Adult friendships are slow to build for almost everyone; a slow start isn't failure.","relearn":"Making friends as an adult is slow for most people; a slow start isn't failure.","persona":"any","source":"slow is normal"},
  {"id":"mb-1036","cat":"find-your-people","type":"reflect","hook":"Lensy: it's okay to outgrow people you've drifted from and still want new connections. Both can be true?","prompt":"What do you think?","options":["Yes","Both are true","That fits"],"affirm":"You can grieve drifted friendships and still reach for new people; growth makes room for both.","relearn":"It's okay to outgrow some people and still want and build new connections.","persona":"Zoya","source":"outgrowing and growing"},
  {"id":"mb-1037","cat":"find-your-people","type":"reflect","hook":"Lensy: the courage to reach out first is a skill you can build, one small hello at a time. Worth practising?","prompt":"What do you think?","options":["Yes","I'll practise","One hello at a time"],"affirm":"Reaching out gets easier with practice; each small hello builds the courage for the next.","relearn":"Reaching out first is a skill you build one small hello at a time.","persona":"any","source":"courage is a skill"},
  {"id":"mb-1038","cat":"find-your-people","type":"reflect","hook":"Lensy: belonging can grow in unglamorous places, a study group, a queue, a workplace, not just a friend circle. True for you?","prompt":"What do you think?","options":["Yes","Anywhere counts","Good to know"],"affirm":"Belonging grows wherever people meet regularly; it doesn't need a perfect ready-made circle.","relearn":"Belonging can grow anywhere people meet regularly, not just a ready-made friend circle.","persona":"Meena","source":"belonging anywhere"},
  {"id":"mb-1039","cat":"find-your-people","type":"reflect","hook":"Lensy: you get to choose who your people are; you don't have to keep anyone who makes you smaller. Sit right?","prompt":"What do you think?","options":["Yes","I get to choose","That sits right"],"affirm":"You get to choose your people; belonging should grow you, not shrink you.","relearn":"You get to choose your people; you needn't keep anyone who makes you smaller.","persona":"any","source":"you choose"},
  {"id":"mb-1040","cat":"find-your-people","type":"match","hook":"Match each lonely worry to the kinder, truer reframe.","pairs":[{"left":"\"Everyone already has their group\"","right":"Groups keep forming all year"},{"left":"\"If I reach out I'll seem desperate\"","right":"Most are glad someone bothered"},{"left":"\"Real friendship should be instant\"","right":"It grows from small repeated moments"},{"left":"\"I'm too quiet to belong\"","right":"Good listeners are valued friends"},{"left":"\"One awkward meeting means it's hopeless\"","right":"Most groups warm up by the third visit"}],"relearn":"Every lonely worry has a kinder, truer reframe.","persona":"any","source":"worry to reframe"},
  {"id":"mb-1041","cat":"find-your-people","type":"match","hook":"Match each chance to connect with the small move that opens it.","pairs":[{"left":"Someone sitting alone in the canteen","right":"\"Mind if I join you?\""},{"left":"A classmate you click with","right":"\"Want to grab chai after class?\""},{"left":"A society full of strangers","right":"\"Hi, I'm new, what got you into this?\""},{"left":"A good chat that ended weeks ago","right":"\"That was fun, coffee this week?\""},{"left":"A group heading out the door","right":"\"Mind if I tag along?\""}],"relearn":"Every chance to connect has a small, simple move that opens it.","persona":"any","source":"chance to move"},
  {"id":"mb-1042","cat":"find-your-people","type":"match","hook":"Match each place people gather with the kind of belonging it can grow.","pairs":[{"left":"A weekly sports or dance class","right":"Friends through a shared activity"},{"left":"A hobby community online","right":"People who get your niche interest"},{"left":"Your work hostel kitchen","right":"Easy day-to-day neighbours"},{"left":"A study or project group","right":"Bonds built through shared effort"},{"left":"A volunteering drive","right":"People who share your values"}],"relearn":"Belonging grows in many places, each one a different kind of connection.","persona":"any","source":"places to belong"},
  {"id":"mb-1043","cat":"find-your-people","type":"match","hook":"Match each friend behaviour to whether it's a green flag or red flag.","pairs":[{"left":"Celebrates your wins genuinely","right":"Green flag worth keeping"},{"left":"Mocks you the moment you open up","right":"Red flag to step back from"},{"left":"Respects it when you say no","right":"Green flag of real care"},{"left":"Only appears when they need a favour","right":"Red flag of being used"},{"left":"Checks in when you go quiet","right":"Green flag of true friendship"}],"relearn":"Celebrating you, respecting your no and checking in are green flags; mockery and only-when-needed are red.","persona":"any","source":"flags matched"},
  {"id":"mb-1044","cat":"find-your-people","type":"match","hook":"Match each 'too late' fear to what's actually still possible.","pairs":[{"left":"Made no friends in week one","right":"New bonds start in week thirty too"},{"left":"Missed the orientation mixers","right":"Clubs welcome people all year"},{"left":"Your one friend is leaving","right":"A wider circle grows from one new thing"},{"left":"You froze meeting them","right":"A small question tomorrow resets it"},{"left":"You moved cities mid-term","right":"Others in the same boat are your first people"}],"relearn":"No 'too late' fear is final; one small step can still widen your world.","persona":"Deepak","source":"too late reframed"},
  {"id":"mb-1045","cat":"find-your-people","type":"match","hook":"Match each kind of connection with what makes it real, not just busy.","pairs":[{"left":"A huge online following","right":"Looks like reach, not closeness"},{"left":"Two people you can be honest with","right":"The core of real belonging"},{"left":"Being in the 'right' crowd","right":"Status, not necessarily friendship"},{"left":"Someone who likes the real you","right":"Worth more than any crowd"},{"left":"A packed but draining group chat","right":"Noise, not necessarily support"}],"relearn":"Real belonging is a couple of people you can be honest with, not reach or status.","persona":"any","source":"real not busy"},
  {"id":"mb-1046","cat":"find-your-people","type":"match","hook":"Match each first step to the brave little script that does it.","pairs":[{"left":"Joining a study group","right":"\"Anyone want in before exams?\""},{"left":"Inviting a new friend out","right":"\"No pressure, but I'd love to hang out more\""},{"left":"Reconnecting with someone","right":"\"We met at orientation, coffee this week?\""},{"left":"Naming a shared interest","right":"\"You're into this too? Let's do it together\""},{"left":"Being honest you're lonely","right":"\"I'm still finding my feet here socially\""}],"relearn":"Each first step has a brave little script that makes it doable.","persona":"any","source":"step to script"},
  {"id":"mb-1047","cat":"find-your-people","type":"match","hook":"Match each belonging myth with the truth that frees you from it.","pairs":[{"left":"Belonging just happens or it doesn't","right":"Belonging is built by showing up"},{"left":"I must be popular to be okay","right":"A couple of real bonds is enough"},{"left":"Asking to hang out is needy","right":"Including someone is a gift"},{"left":"I have to fit in to be liked","right":"The right people like the real you"},{"left":"If I'm shy I'll always be alone","right":"Quiet people build deep friendships"}],"relearn":"Belonging is built not found, and the right people like the real you.","persona":"any","source":"myth to truth"},
  {"id":"mb-1048","cat":"find-your-people","type":"spot","hook":"Spot the two lines that quietly keep you isolated.","relearn":"Reaching out, saying yes and trying again build belonging.","why":"Waiting to be invited and labelling yourself a non-people-person both stop you from ever reaching out.","persona":"any","source":"isolating lines","scene":[{"id":"a","text":"\"I'll ask one person to grab chai today.\"","trick":false},{"id":"b","text":"\"If they wanted me, they'd invite me first.\"","trick":true},{"id":"c","text":"\"I'll go back to that club one more time.\"","trick":false},{"id":"d","text":"\"I'm just not a people person, so why bother.\"","trick":true},{"id":"e","text":"\"I'll say yes to the next invite, even if it's awkward.\"","trick":false}]},
  {"id":"mb-1049","cat":"find-your-people","type":"spot","hook":"Spot the two thoughts that are lonely myths, not facts.","relearn":"Groups keep forming all year and friendship grows slowly with effort.","why":"'Everyone's cliqued up' and 'effort means fake' are myths, not facts.","persona":"Deepak","source":"myth thoughts","scene":[{"id":"a","text":"\"It's normal to feel like an outsider at first.\"","trick":false},{"id":"b","text":"\"Everyone's already cliqued up; I missed my chance.\"","trick":true},{"id":"c","text":"\"A simple hello is enough to start.\"","trick":false},{"id":"d","text":"\"If friendship takes effort, it isn't real.\"","trick":true},{"id":"e","text":"\"Most people felt this nervous at the start too.\"","trick":false}]},
  {"id":"mb-1050","cat":"find-your-people","type":"spot","hook":"Spot the two red flags in how a 'friend' is treating you.","relearn":"Real friends celebrate you, respect your no and show up.","why":"Putting you down for laughs and only appearing when they need a favour are signs you're being used, not valued.","persona":"any","source":"friend red flags","scene":[{"id":"a","text":"They cheer when something good happens for you.","trick":false},{"id":"b","text":"They put you down in front of the group for laughs.","trick":true},{"id":"c","text":"They check in when you've gone quiet.","trick":false},{"id":"d","text":"They only message when they need a favour.","trick":true},{"id":"e","text":"They respect it when you say you're not up for it.","trick":false}]},
  {"id":"mb-1051","cat":"find-your-people","type":"spot","hook":"Spot the two moves that keep a new friendship from growing.","relearn":"Replying, suggesting plans and remembering grow a friendship.","why":"Leaving invites on a vague 'maybe' and always being 'too busy' quietly signal disinterest and let a friendship fade.","persona":"any","source":"fading moves","scene":[{"id":"a","text":"Replying to their message that evening.","trick":false},{"id":"b","text":"Leaving every invite on a vague 'maybe'.","trick":true},{"id":"c","text":"Suggesting the next plan yourself.","trick":false},{"id":"d","text":"Always being 'too busy' whenever they ask.","trick":true},{"id":"e","text":"Asking how that thing they mentioned went.","trick":false}]},
  {"id":"mb-1052","cat":"find-your-people","type":"spot","hook":"Spot the two signs a group is one you should step back from.","relearn":"Early shyness and not knowing names are just nerves, not red flags.","why":"Having to hide who you are and being laughed at for opening up mean the group costs you yourself.","persona":"Zoya","source":"step back signs","scene":[{"id":"a","text":"You feel a little shy because it's all new.","trick":false},{"id":"b","text":"You have to hide who you really are to fit in.","trick":true},{"id":"c","text":"You don't know everyone's name yet.","trick":false},{"id":"d","text":"They laugh at you whenever you open up.","trick":true},{"id":"e","text":"It's not fully comfortable yet, but people are kind.","trick":false}]},
  {"id":"mb-1053","cat":"find-your-people","type":"spot","hook":"Spot the two 'shortcuts' that don't actually build real belonging.","relearn":"Showing up regularly and genuine interest build belonging.","why":"A fake persona and a big follower count only look like connection; neither lets anyone know the real you.","persona":"Rohan","source":"false shortcuts","scene":[{"id":"a","text":"Showing up regularly to a thing you enjoy.","trick":false},{"id":"b","text":"Putting on a fake persona to impress people.","trick":true},{"id":"c","text":"Being genuinely curious about people you meet.","trick":false},{"id":"d","text":"Chasing a big follower count as proof you're liked.","trick":true},{"id":"e","text":"Following up warmly after a good conversation.","trick":false}]},
  {"id":"mb-1054","cat":"find-your-people","type":"spot","hook":"Spot the two thoughts that talk you out of reaching out.","relearn":"Most people are glad you bothered, and a small hello is enough.","why":"'I'll look desperate' and 'wait for the perfect moment' are excuses that keep you from ever making the first move.","persona":"any","source":"talk yourself out","scene":[{"id":"a","text":"\"Most people are glad when someone reaches out.\"","trick":false},{"id":"b","text":"\"If I message first, I'll look desperate.\"","trick":true},{"id":"c","text":"\"A small, friendly hello is enough to start.\"","trick":false},{"id":"d","text":"\"I'll wait for the perfect, less awkward moment.\"","trick":true},{"id":"e","text":"\"Someone has to go first; it can be me.\"","trick":false}]},
  {"id":"mb-1055","cat":"find-your-people","type":"spot","hook":"Spot the two beliefs that keep you on the edge of every group.","relearn":"Trying again and aiming for one real chat help you find your way in.","why":"'I'd be intruding' and 'everyone belongs more than me' are assumptions, not facts.","persona":"Deepak","source":"edge beliefs","scene":[{"id":"a","text":"\"I'll aim for just one real conversation tonight.\"","trick":false},{"id":"b","text":"\"They're already close; I'd just be intruding.\"","trick":true},{"id":"c","text":"\"It felt warmer the second time I went back.\"","trick":false},{"id":"d","text":"\"Everyone here clearly belongs more than I do.\"","trick":true},{"id":"e","text":"\"Most of them were new and nervous once too.\"","trick":false}]},
  {"id":"mb-1080","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"My English isn't polished, so I don't really belong on this campus.\"","myth":{"un":"My English isn't polished, so I don't belong here.","re":"You earned your seat on merit; fluency is a skill you'll grow, not proof of belonging.","why":"An accent says nothing about your mind or worth."},"relearn":"Your seat was earned; an unpolished accent isn't proof you don't belong.","persona":"Deepak","source":"accent shame"},
  {"id":"mb-1081","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"Everyone here is from a richer, better-prepared background than me.\"","myth":{"un":"Everyone's from a richer, better-prepared background, so I'm behind for good.","re":"You crossed harder ground to get here; that's strength, and you can learn what you missed.","why":"A head start isn't the same as more ability."},"relearn":"A tougher start isn't being behind for good; you can learn what you missed.","persona":"Deepak","source":"first-gen class gap"},
  {"id":"mb-1082","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"If I were really smart, this course wouldn't feel hard.\"","myth":{"un":"If I were really smart, none of this would feel hard.","re":"Hard means you're stretching into new things; capable people find new material hard too.","why":"Difficulty is how learning feels, not a verdict on you."},"relearn":"Finding new material hard is how learning feels, not proof you're not smart.","persona":"any","source":"hard means dumb"},
  {"id":"mb-1083","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"One bad result and I've shown everyone I'm a fraud.\"","myth":{"un":"One bad result proves to everyone I'm a fraud.","re":"A single result is a snapshot, not a sentence; capable people have off days too.","why":"No one is summed up by their worst score."},"relearn":"One bad result is a snapshot, not proof you're a fraud.","persona":"any","source":"one result"},
  {"id":"mb-1084","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"My worth is whether I land a top placement.\"","myth":{"un":"My worth is whether I land a top placement.","re":"A placement is one outcome among many; your value as a person isn't decided by an offer letter.","why":"People aren't ranked by their job titles."},"relearn":"A placement is one outcome; your worth as a person isn't an offer letter.","persona":"any","source":"placement = worth"},
  {"id":"mb-1085","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"My follower count shows how much I'm worth.\"","myth":{"un":"My follower count shows how much I'm worth.","re":"Numbers on a screen measure reach, not your value; your worth isn't a metric.","why":"No real relationship runs on a like count."},"relearn":"Followers measure reach, not your worth; you aren't a metric.","persona":"any","source":"follower count"},
  {"id":"mb-1086","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"If I rest while others grind, I'm falling behind and worth less.\"","myth":{"un":"Resting while others grind means I'm worth less.","re":"Rest is how you keep going; your worth never depended on being productive every hour.","why":"You're a person, not an output machine."},"relearn":"Rest doesn't lower your worth; you were never meant to produce every hour.","persona":"any","source":"rest guilt"},
  {"id":"mb-1087","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"My skin's too dark / I'm too plain to be taken seriously.\"","myth":{"un":"My skin's too dark or I'm too plain to be taken seriously.","re":"Your worth and how seriously you deserve to be taken aren't set by skin tone or looks.","why":"Colourism is a bias to reject, not a truth about you."},"relearn":"Skin tone and looks don't set your worth or how seriously you're taken.","persona":"any","source":"colourism"},
  {"id":"mb-1088","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"I have to fix my body before I'm allowed to feel okay.\"","myth":{"un":"I have to fix my body before I'm allowed to feel okay.","re":"You're allowed to feel okay in the body you have now; worth isn't earned by changing it.","why":"Your value doesn't wait on a 'before and after'."},"relearn":"You can feel okay in the body you have now; worth isn't a 'before and after'.","persona":"any","source":"body neutrality"},
  {"id":"mb-1089","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"Being proud of myself is arrogant; I should stay humble by putting myself down.\"","myth":{"un":"Putting myself down is just being humble.","re":"Quietly valuing yourself isn't arrogance; constant self-put-downs aren't humility, they wear you down.","why":"Humility and self-respect can sit together."},"relearn":"Valuing yourself isn't arrogance, and self-put-downs aren't humility.","persona":"any","source":"false humility"},
  {"id":"mb-1090","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"My parents sacrificed so much, so a slip means I've let everyone down and I'm a failure.\"","myth":{"un":"A slip means I've let everyone down and I'm a failure.","re":"One slip doesn't erase your effort or their love; you're more than a single outcome.","why":"Care isn't withdrawn over one stumble."},"relearn":"One slip doesn't make you a failure or erase your effort.","persona":"Deepak","source":"family sacrifice weight"},
  {"id":"mb-1091","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"Confident people never feel like impostors.\"","myth":{"un":"Confident people never feel like impostors.","re":"Many confident-looking people feel like impostors too; they just don't show it.","why":"You're seeing their surface, not their doubts."},"relearn":"Even confident-looking people feel like impostors; you see surface, not doubts.","persona":"any","source":"confidence myth"},
  {"id":"mb-1092","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"If a teacher praises me, it was luck; if they criticise me, that's the real me.\"","myth":{"un":"Praise is luck; criticism is the real me.","re":"You can take praise as real evidence too; one harsh comment isn't more true than your wins.","why":"A fair view counts the good, not only the bad."},"relearn":"Praise is real evidence too; one harsh comment isn't truer than your wins.","persona":"any","source":"discounting praise"},
  {"id":"mb-1093","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"I have to be the best at something or I'm nothing.\"","myth":{"un":"I have to be the best at something or I'm nothing.","re":"You don't have to top anything to matter; ordinary, trying and kind is already enough.","why":"Worth was never a ranking."},"relearn":"You don't have to be the best to matter; trying and kind is enough.","persona":"any","source":"best or nothing"},
  {"id":"mb-1094","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"Comparing myself to toppers will push me to improve.\"","myth":{"un":"Comparing myself to toppers will push me to improve.","re":"Constant comparison mostly fuels shame, not growth; tracking your own progress helps more.","why":"You improve against yesterday-you, not a leaderboard."},"relearn":"Comparison fuels shame, not growth; track your own progress instead.","persona":"any","source":"comparison ≠ motivation"},
  {"id":"mb-1095","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"My inner critic is just being honest with me.\"","myth":{"un":"My harsh inner critic is just being honest.","re":"A cruel inner voice isn't honesty; it's a habit you can question and answer back to.","why":"Honest and kind can be the same sentence."},"relearn":"A harsh inner critic isn't honesty; it's a habit you can answer back to.","persona":"any","source":"inner critic"},
  {"id":"mb-1096","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"Everyone's judging how I look as much as I am.\"","myth":{"un":"Everyone's judging how I look as much as I am.","re":"People are far more wrapped up in themselves; they notice your looks much less than you fear.","why":"Most folks are busy worrying about their own image."},"relearn":"People notice your looks far less than you fear; they're busy with their own.","persona":"any","source":"spotlight effect"},
  {"id":"mb-1097","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"My worth goes up and down with each grade I get.\"","myth":{"un":"My worth rises and falls with every grade.","re":"Grades measure one piece of work; your worth stays steady underneath the scoreboard.","why":"A mark rates the task, not the person."},"relearn":"Grades rate the work, not you; your worth stays steady underneath.","persona":"any","source":"grade rollercoaster"},
  {"id":"mb-1098","cat":"mind-and-self-worth","type":"strike-rewrite","hook":"\"Needing help with anything proves I'm not good enough.\"","myth":{"un":"Needing help proves I'm not good enough.","re":"Everyone needs help with something; asking is smart, and it doesn't shrink your worth.","why":"No one does it all alone, and that's normal."},"relearn":"Needing help is normal and smart; it doesn't shrink your worth.","persona":"any","source":"help ≠ less worth"},
  {"id":"mb-1099","cat":"mind-and-self-worth","type":"reflect","hook":"Lensy: think of one thing you like about yourself that has nothing to do with grades or looks. Got one?","prompt":"What came to mind?","options":["Yes","I'm kind","I keep trying","Found one"],"affirm":"That's the real you: the parts no scoreboard can measure are worth holding onto.","relearn":"There are things to value in you that no grade or look can measure.","persona":"any","source":"beyond the scoreboard"},
  {"id":"mb-1100","cat":"mind-and-self-worth","type":"reflect","hook":"Lensy: you'd never talk to a friend the way your inner critic talks to you. Notice the gap?","prompt":"What do you think?","options":["Yes","Big gap","I'd be kinder"],"affirm":"You deserve the same kindness you'd give a friend; that gap is worth closing, gently.","relearn":"You deserve the same kindness you'd give a friend.","persona":"any","source":"friend test"},
  {"id":"mb-1101","cat":"mind-and-self-worth","type":"reflect","hook":"Lensy: your body carried you through today, long classes, the walk home, all of it. Can you thank it?","prompt":"What do you think?","options":["Yes","Thank you, body","It does a lot"],"affirm":"Your body does so much for you every day; gratitude for it is a kinder lens than judgement.","relearn":"Your body does a lot for you; gratitude is a kinder lens than judgement.","persona":"any","source":"body gratitude"},
  {"id":"mb-1102","cat":"mind-and-self-worth","type":"reflect","hook":"Lensy: the people who matter to you don't love you for your marks. Does that take some weight off?","prompt":"What do you think?","options":["Yes","Takes weight off","They just like me"],"affirm":"The people who matter stay for who you are, not your results; you can let that hold you.","relearn":"The people who matter love you for who you are, not your marks.","persona":"any","source":"loved for who you are"},
  {"id":"mb-1103","cat":"mind-and-self-worth","type":"reflect","hook":"Lensy: 'I'm a work in progress' is allowed to be true forever. Does that feel less heavy than 'finished and not enough'?","prompt":"What do you think?","options":["Yes","Always growing","Less heavy"],"affirm":"You're allowed to be a work in progress; growing isn't the same as not being enough.","relearn":"You're allowed to be a work in progress; growing isn't being not-enough.","persona":"any","source":"work in progress"},
  {"id":"mb-1104","cat":"mind-and-self-worth","type":"reflect","hook":"Lensy: name one mistake you've grown from. Proof you're not defined by getting it wrong?","prompt":"What do you think?","options":["Yes","I grew from it","Not defined by it"],"affirm":"Mistakes you've grown from are evidence of learning, not flaws in you.","relearn":"Mistakes you grow from are evidence of learning, not proof you're flawed.","persona":"any","source":"mistakes = learning"},
  {"id":"mb-1105","cat":"mind-and-self-worth","type":"reflect","hook":"Lensy: imagine deleting the app where you compare yourself most, for a week. How might that feel?","prompt":"What do you think?","options":["Lighter","Quieter mind","Worth a try"],"affirm":"Stepping back from the feed that fuels comparison can give your self-worth room to breathe.","relearn":"Stepping back from comparison feeds gives your self-worth room to breathe.","persona":"any","source":"comparison break"},
  {"id":"mb-1106","cat":"mind-and-self-worth","type":"reflect","hook":"Lensy: 'good enough' is genuinely good enough most days. Can you let that be okay today?","prompt":"What do you think?","options":["Yes","Good enough is okay","I'll try"],"affirm":"Good enough is a kind, realistic bar; you don't owe anyone flawless.","relearn":"Good enough is a kind, realistic bar; you don't owe anyone flawless.","persona":"any","source":"good enough"},
  {"id":"mb-1107","cat":"mind-and-self-worth","type":"sort","hook":"Sort: builds you up, or chips at your self-worth?","items":[{"id":"a","text":"\"I'm learning, and that's allowed\""},{"id":"b","text":"\"Everyone's ahead of me; I'm useless\""},{"id":"c","text":"Noticing one thing you did okay today"},{"id":"d","text":"Replaying every mistake on a loop"},{"id":"e","text":"\"My worth isn't this one result\""},{"id":"f","text":"Scrolling toppers' profiles to feel small"}],"bins":[{"id":"builds","label":"Builds you up","valence":"pos"},{"id":"chips","label":"Chips at worth","valence":"neg"}],"key":{"a":"builds","b":"chips","c":"builds","d":"chips","e":"builds","f":"chips"},"relearn":"Self-kindness and noticing small wins build you up; harsh labels, replaying mistakes and comparison chip at your worth.","persona":"any","source":"build vs chip"},
  {"id":"mb-1108","cat":"mind-and-self-worth","type":"sort","hook":"Sort: a fair, true belief about yourself, or a harsh distortion?","items":[{"id":"a","text":"\"A setback doesn't cancel my strengths\""},{"id":"b","text":"\"If I'm not perfect, I'm a failure\""},{"id":"c","text":"\"I'm allowed to still be learning\""},{"id":"d","text":"\"One bad opinion of me is the truth\""},{"id":"e","text":"\"I can be proud and still grow\""},{"id":"f","text":"\"I must earn the right to rest\""}],"bins":[{"id":"fair","label":"Fair & true","valence":"pos"},{"id":"harsh","label":"Harsh distortion","valence":"neg"}],"key":{"a":"fair","b":"harsh","c":"fair","d":"harsh","e":"fair","f":"harsh"},"relearn":"Setbacks don't cancel strengths and you can grow without being perfect; 'failure if not perfect' and 'earn rest' are distortions.","persona":"any","source":"fair vs distorted"},
  {"id":"mb-1109","cat":"mind-and-self-worth","type":"sort","hook":"Sort: a real source of self-worth, or a shaky one that can vanish overnight?","items":[{"id":"a","text":"Being a decent, caring person"},{"id":"b","text":"This week's like count"},{"id":"c","text":"Your effort and how you treat people"},{"id":"d","text":"Always being the top scorer"},{"id":"e","text":"Living by what you value"},{"id":"f","text":"Other people's approval"}],"bins":[{"id":"real","label":"Steady source","valence":"pos"},{"id":"shaky","label":"Shaky source","valence":"neg"}],"key":{"a":"real","b":"shaky","c":"real","d":"shaky","e":"real","f":"shaky"},"relearn":"Character, effort and your values are steady sources of worth; likes, rankings and approval are shaky ones that can vanish.","persona":"any","source":"steady vs shaky worth"},
  {"id":"mb-1110","cat":"mind-and-self-worth","type":"sort","hook":"Sort: a kind way to treat your body, or a self-critical one?","items":[{"id":"a","text":"Feeding and resting it well"},{"id":"b","text":"Picking it apart in the mirror"},{"id":"c","text":"Thanking it for what it does"},{"id":"d","text":"Talking down to it for how it looks"},{"id":"e","text":"Dressing in what feels comfortable"},{"id":"f","text":"Hiding it away until it 'looks right'"}],"bins":[{"id":"kind","label":"Kind to your body","valence":"pos"},{"id":"critical","label":"Self-critical","valence":"neg"}],"key":{"a":"kind","b":"critical","c":"kind","d":"critical","e":"kind","f":"critical"},"relearn":"Feeding, resting, thanking and dressing comfortably are kind to your body; picking it apart or hiding it away are self-critical.","persona":"any","source":"body kindness"},
  {"id":"mb-1111","cat":"mind-and-self-worth","type":"sort","hook":"Sort: impostor feelings (a feeling), or actual evidence about your ability?","items":[{"id":"a","text":"\"I just got lucky to be here\""},{"id":"b","text":"You met the bar to get in"},{"id":"c","text":"\"Everyone will find me out\""},{"id":"d","text":"You've handled hard things before"},{"id":"e","text":"\"I don't deserve my place\""},{"id":"f","text":"Your work has earned real feedback"}],"bins":[{"id":"feeling","label":"Just a feeling","valence":"uhoh"},{"id":"evidence","label":"Real evidence","valence":"pos"}],"key":{"a":"feeling","b":"evidence","c":"feeling","d":"evidence","e":"feeling","f":"evidence"},"relearn":"'I got lucky' and 'they'll find me out' are impostor feelings; meeting the bar and handling hard things are real evidence you belong.","persona":"Deepak","source":"feeling vs evidence"},
  {"id":"mb-1112","cat":"mind-and-self-worth","type":"sort","hook":"Sort: eases comparison, or feeds the spiral?","items":[{"id":"a","text":"Muting accounts that make you feel small"},{"id":"b","text":"Refreshing a rival's profile again"},{"id":"c","text":"Cheering a friend's win genuinely"},{"id":"d","text":"Keeping a tally of who's 'ahead'"},{"id":"e","text":"Remembering feeds are highlight reels"},{"id":"f","text":"Reading comments to compare more"}],"bins":[{"id":"healthy","label":"Eases comparison","valence":"pos"},{"id":"feeds","label":"Feeds the spiral","valence":"neg"}],"key":{"a":"healthy","b":"feeds","c":"healthy","d":"feeds","e":"healthy","f":"feeds"},"relearn":"Muting triggers, cheering friends and recalling it's a highlight reel ease comparison; refreshing rivals and tallying feed the spiral.","persona":"any","source":"comparison responses"},
  {"id":"mb-1113","cat":"mind-and-self-worth","type":"sort","hook":"Sort: keeps worth and performance separate, or fuses them?","items":[{"id":"a","text":"\"I failed the test\" (not \"I'm a failure\")"},{"id":"b","text":"\"I am my marks\""},{"id":"c","text":"\"That went badly, I'm still okay\""},{"id":"d","text":"\"A bad grade means I'm a bad person\""},{"id":"e","text":"\"I can do badly and still matter\""},{"id":"f","text":"\"My value lives or dies on results\""}],"bins":[{"id":"separates","label":"Separates them","valence":"pos"},{"id":"fuses","label":"Fuses them","valence":"neg"}],"key":{"a":"separates","b":"fuses","c":"separates","d":"fuses","e":"separates","f":"fuses"},"relearn":"'I failed the test' keeps worth separate from a result; 'I am my marks' fuses them, so every grade becomes a verdict on you.","persona":"any","source":"worth vs performance"},
  {"id":"mb-1114","cat":"mind-and-self-worth","type":"sort","hook":"Sort: a kind expectation of yourself, or a perfectionist trap?","items":[{"id":"a","text":"\"Done is better than flawless\""},{"id":"b","text":"\"It has to be perfect or not at all\""},{"id":"c","text":"\"Mistakes are part of learning\""},{"id":"d","text":"\"I should never need a second try\""},{"id":"e","text":"\"Progress counts, not just the peak\""},{"id":"f","text":"\"Anything less than the top is failure\""}],"bins":[{"id":"kind","label":"Kind expectation","valence":"pos"},{"id":"trap","label":"Perfectionist trap","valence":"neg"}],"key":{"a":"kind","b":"trap","c":"kind","d":"trap","e":"kind","f":"trap"},"relearn":"'Done beats flawless' and 'progress counts' are kind; 'perfect or nothing' and 'below the top is failure' are perfectionist traps.","persona":"any","source":"perfectionism"},
  {"id":"mb-1115","cat":"mind-and-self-worth","type":"branch","persona":"Deepak","source":"owning a win","hook":"You got the internship you interviewed for, and your first thought is that they picked you by mistake.","steps":[{"prompt":"The offer email arrives while you're in the canteen. What do you do?","options":[{"text":"Tell yourself it was luck, a fluke","then":"The joy drains out fast. You close the email and finish your tea."},{"text":"Wait for them to realise and take it back","then":"You read the email three times, looking for the catch."},{"text":"Let it sink in. You prepared and earned this","then":"You read it again, slowly this time. A grin creeps in.","best":true},{"text":"Tell no one in case it turns out to be an error","then":"The news sits in your phone. Nobody gets to be happy with you."}],"why":"Letting a real win count is how impostor feelings slowly loosen."},{"prompt":"That night, HR calls about your start date. Your roommate Sahil overhears and asks what you did right. What do you say?","options":[{"text":"Say the interviewer was just in a good mood","then":"Sahil laughs. \"Sure, that's why.\" You half believe it yourself."},{"text":"Name how you prepared and what you answered well","then":"Saying it out loud, you hear how much work went into it.","best":true},{"text":"Say you honestly have no idea","then":"Sahil shrugs. The effort you put in stays invisible, even to you."},{"text":"Say the others probably turned it down","then":"Sahil frowns. \"That's not how it works.\" You change the subject."}],"why":"Naming your own effort helps you see the win as yours."},{"prompt":"On day one, the other interns chat about their big-name colleges. What do you do?","options":[{"text":"Stay quiet so nobody notices you're different","then":"You nod along all day. By evening, you feel invisible."},{"text":"Decide to work twice as hard to justify being there","then":"You stay latest every day. You're worn out, and the feeling doesn't budge."},{"text":"Remind yourself you earned the same seat they did","then":"You join the chat about the first task. Nobody asks about your college.","best":true},{"text":"Make your background sound fancier to fit in","then":"It works for a moment. Then you worry all week about being caught out."}],"why":"Your place came from your work, not your college's name."},{"prompt":"A week in, you make a small mistake and the old voice calls you a fraud. What do you do?","options":[{"text":"Take it as proof and think about quitting","then":"You draft a resignation in your head. It sits there all evening."},{"text":"Hide it and hope nobody notices","then":"Your manager finds it two days later. Now it feels much bigger."},{"text":"Fix it, and remember everyone slips at first","then":"Your manager barely looks up. \"Thanks for catching that.\"","best":true},{"text":"Fix it, then stay back late to make up for it","then":"Nobody asked you to. You leave drained, still feeling you owe them."}],"why":"Feeling like a fraud is common, not a fact. Slips are how everyone learns."}],"debrief":"Owning a real win, rather than crediting it to luck, is how you loosen impostor feelings over time.","relearn":"Let your wins count; calling them luck keeps impostor feelings alive."},
  {"id":"mb-1116","cat":"mind-and-self-worth","type":"branch","persona":"any","source":"feed envy","hook":"Your friend Meher posts her top results and a big internship, and you suddenly feel worthless.","steps":[{"prompt":"It's the first thing you see this morning. What do you do?","options":[{"text":"Scroll her whole profile to see how she did it","then":"Every photo looks effortless. You feel worse with each one."},{"text":"Leave a quick like and pretend it didn't sting","then":"The like takes a second. The sting stays all morning."},{"text":"Be glad for her and step off the feed for a bit","then":"You send a heart and put the phone away. Breakfast tastes normal again.","best":true},{"text":"Spiral into how far behind everyone you are","then":"An hour later you're still in bed, adding to the list."}],"why":"Warmth for her plus a break from the feed protects your own worth."},{"prompt":"At lunch, a friend says Meher must have her whole life figured out. What do you say?","options":[{"text":"Agree, and say you've got nothing figured out","then":"Your friend nods. Lunch turns into a list of your worries."},{"text":"Say one post is a highlight, not her whole story","then":"Your friend thinks. \"True. My posts look way better than my life.\"","best":true},{"text":"Say she probably had connections","then":"Your friend shrugs. It doesn't make you feel any better."},{"text":"Change the subject fast","then":"The talk moves on. The comparison hums on quietly inside you."}],"why":"Remembering posts are highlights stops one update becoming your verdict."},{"prompt":"That evening, Meher messages that she's scared she won't cope at the internship. What do you do?","options":[{"text":"Reply \"you'll be fine\" and close the chat","then":"She sends a smiley. You never learn what was worrying her."},{"text":"Tell her she has nothing to complain about","then":"She goes quiet. \"Sorry. Forget I said anything.\""},{"text":"Say you're glad for her and ask what's worrying her","then":"She sends a long voice note. Her perfect post had a lot left out.","best":true},{"text":"Leave it on read till you feel less jealous","then":"By the time you reply, she's stopped waiting."}],"why":"Her post was only part of her story. Being there for her shows you both that."}],"debrief":"One curated post isn't the whole story. Warmth and a break protect your worth.","relearn":"A friend's highlight post isn't your verdict; be glad and step back."},
  {"id":"mb-1117","cat":"mind-and-self-worth","type":"branch","persona":"any","source":"body image grip","hook":"Lately you avoid mirrors and photos because you hate how you look.","steps":[{"prompt":"Getting ready for class, you catch your reflection and the harsh thoughts start. What do you do?","options":[{"text":"List everything you'd change about yourself","then":"The list grows as you dress. You leave late and feel low."},{"text":"Swap in one neutral thought about your body","then":"\"My body isn't the most interesting thing about me.\" It's small, and the grip eases.","best":true},{"text":"Turn the mirror to face the wall","then":"It helps for a day. Then every shop window does the same job."},{"text":"Tell yourself to toughen up and ignore it","then":"You push the thoughts down. They're back by lunch."}],"why":"A neutral or kind thought loosens body shame. Avoiding and criticising deepen it."},{"prompt":"At a friend's birthday, everyone gathers for a group photo. What do you do?","options":[{"text":"Offer to take the photo so you're not in it","then":"You're behind the camera all evening. Later, you're in none of the memories."},{"text":"Squeeze in with everyone","then":"Someone throws an arm round you. You're laughing when the shutter clicks.","best":true},{"text":"Leave before the photos start","then":"You slip out early. Next day, the photos are all anyone talks about."},{"text":"Stand at the back, half hidden","then":"You're in the photo, sort of. Later, you zoom in to pick it apart."}],"why":"Being in the picture puts your life ahead of how you look."},{"prompt":"At a family function, a cousin comments loudly on your weight. What do you do?","options":[{"text":"Tell yourself she's only saying what everyone else thinks","then":"The thought follows you home. Every glance at the next function feels like judgement."},{"text":"Snap back about her weight","then":"The room goes quiet. Your mother gives you a look."},{"text":"Remind yourself her words say nothing about your worth","then":"It still stings. But by the ride home, the comment has lost its grip.","best":true},{"text":"Tell yourself she means well, so it shouldn't hurt","then":"You brush it off for her sake. It still replays in your head that night."}],"why":"Her comment says nothing about your worth. Holding on to that protects you, whether or not you reply."},{"prompt":"Weeks on, the harsh thoughts are there most days and they're wearing you down. What do you do?","options":[{"text":"Keep it to yourself. It's only vanity","then":"The thoughts get louder, and lonelier."},{"text":"Compare yourself with influencers to see how far off you are","then":"Every face is filtered. You feel further from okay than ever."},{"text":"Wait for it to pass on its own","then":"Some days are lighter. Most aren't, and it doesn't really shift."},{"text":"Tell someone you trust how heavy it's got","then":"Your friend listens without rushing. \"I'm glad you told me.\"","best":true}],"why":"Telling someone you trust is strength. Heavy thoughts shouldn't be carried alone."},{"prompt":"Over chai, your friend Nisha says the campus counsellor helped her through a rough patch. What do you do?","options":[{"text":"Say it's not serious enough for a counsellor","then":"Nisha nods slowly. The thoughts keep their grip for another month."},{"text":"Say you'll go if it gets any worse","then":"\"Okay,\" Nisha says. It stays just bad enough, week after week."},{"text":"Book a session this week","then":"The counsellor is kind and unhurried. You leave with a plan, and a next session.","best":true},{"text":"Say you'd rather sort it out alone first","then":"You try alone for a while. The same thoughts keep winning."}],"why":"You needn't be in crisis to get support. A counsellor, or Tele-MANAS 14416, can help."}],"debrief":"Body image softens with neutral and kind thoughts, not more avoidance.","relearn":"Loosen harsh body image with one neutral or kind thought, not more criticism."},
  {"id":"mb-1118","cat":"mind-and-self-worth","type":"branch","persona":"any","source":"answering the critic","hook":"You bombed a class presentation, and your inner voice calls you an embarrassment.","steps":[{"prompt":"Walking back to your seat, the voice gets louder. What do you do?","options":[{"text":"Agree with it. That was embarrassing","then":"The voice takes that as permission and gets louder."},{"text":"Pretend it doesn't bother you","then":"You smile at the person beside you. Inside, the voice keeps going."},{"text":"Notice it: \"That's my inner critic talking\"","then":"Naming it puts a little space between you and the voice.","best":true},{"text":"Plan to skip the next class to avoid everyone","then":"The plan brings relief, and a new worry about falling behind."}],"why":"Naming a harsh thought as just a thought gives you room to answer it."},{"prompt":"That night, you keep replaying the moment you lost your place. What do you do?","options":[{"text":"Replay it to work out exactly what went wrong","then":"By 1 a.m., you've relived it twenty times and learned nothing new."},{"text":"Message a friend to ask if you were really that bad","then":"She says it was fine. You don't quite believe her, and ask again."},{"text":"Answer it fairly: one bad talk isn't a verdict","then":"\"I lost my place once. I also finished.\" The replay slows.","best":true},{"text":"Tell yourself you're just not made for this","then":"The thought settles in. You start dreading every presentation."}],"why":"A fair answer stops one bad moment from becoming a verdict on you."},{"prompt":"Next day, your professor asks to see you after class. What do you do?","options":[{"text":"Slip out early to avoid her","then":"She emails instead. Now you dread opening it."},{"text":"Go and apologise for wasting everyone's time","then":"She looks surprised. \"You didn't waste anything.\" You barely hear the rest."},{"text":"Go, but brace for the worst and say little","then":"She gives you two tips. You're too tense to take them in."},{"text":"Go, and ask what would help next time","then":"She says your content was strong and suggests cue cards. It's useful.","best":true}],"why":"Asking for feedback turns a bad moment into something useful."},{"prompt":"Weeks later, you're asked to present again. What do you do?","options":[{"text":"Say yes, then tell everyone you'll probably bomb again","then":"People laugh awkwardly. The voice takes it as agreement."},{"text":"Make an excuse to get out of it","then":"Relief, then a sinking feeling. The fear gets a little bigger."},{"text":"Say yes, and practise once with a friend listening","then":"Your friend times you and claps at the end. You feel almost ready.","best":true},{"text":"Say yes, then rehearse alone all night","then":"You know it by heart, and you're exhausted on the day."}],"why":"Trying again with support shows the critic one bad talk wasn't the end."}],"debrief":"Naming a harsh thought and answering it fairly stops one bad moment becoming a verdict.","relearn":"Name a harsh thought and answer it fairly; one bad moment isn't a verdict."},
  {"id":"mb-1119","cat":"mind-and-self-worth","type":"branch","persona":"any","source":"image and avoidance","hook":"You keep skipping events you'd enjoy because you don't like how you'll look in photos.","steps":[{"prompt":"Your class is holding a farewell dinner for a favourite professor on Friday. What do you do?","options":[{"text":"Say you'll decide on the day","then":"On Friday, the doubt wins. You stay home."},{"text":"Skip it and say you're unwell","then":"The dinner happens without you. You feel relieved, then quietly sad."},{"text":"Go anyway. You're more than a photo","then":"You end up next to the professor, laughing at her old stories.","best":true},{"text":"Go only if you can stay out of every photo","then":"You spend the dinner dodging cameras instead of talking."}],"why":"Putting your life ahead of an image means showing up for what matters."},{"prompt":"Next month, your cousin's wedding is coming up, with a photographer at every function. What do you do?","options":[{"text":"Tell the family you can't get away","then":"Your cousin is hurt. Later, you watch the videos alone, missing it."},{"text":"Go, but hide whenever the photographer comes near","then":"You miss the family photo. Your aunt asks where you vanished."},{"text":"Go, and enjoy it, photos and all","then":"You dance at the functions till your feet hurt. You forget the cameras.","best":true},{"text":"Go, and check every photo for how you look","then":"You spend the functions checking photos instead of dancing."}],"why":"Being there for the people you love matters more than any photo."},{"prompt":"Later, a friend tags you in a photo and your first thought is harsh. What do you do?","options":[{"text":"Zoom in and pick apart how you look","then":"Ten minutes later, you've forgotten what the moment was about."},{"text":"Look at the moment in it, not just at you","then":"Everyone's mid-laugh. You remember the joke and smile.","best":true},{"text":"Decide to avoid photos completely from now on","then":"It feels safe. It also means stepping back from more of your life."},{"text":"Tell yourself to stop being so silly","then":"The harsh thought goes quiet, then waits for the next photo."}],"why":"Seeing the moment, not your looks, keeps photos from running your life."}],"debrief":"Your life comes before any photo. Showing up beats controlling your look.","relearn":"Show up for your life; you're worth far more than a photograph."},
  {"id":"mb-1120","cat":"mind-and-self-worth","type":"branch","persona":"any","source":"relatives comparing","hook":"Relatives keep comparing you with your cousin Ritika, who \"has it all figured out\".","steps":[{"prompt":"At a family lunch, an aunt asks why you can't be more like Ritika. What do you do?","options":[{"text":"Laugh it off, but agree with it inside","then":"Everyone moves on. You don't."},{"text":"List your achievements to prove her wrong","then":"Your aunt nods vaguely. The comparison just gets a new round."},{"text":"Smile, and remember your path is your own","then":"The question stings less. You go back to your food.","best":true},{"text":"Snap that Ritika isn't perfect either","then":"The table goes quiet. Your mother looks mortified."}],"why":"Measuring yourself by your own path takes the sting out of others' comparisons."},{"prompt":"Later, Ritika's graduation photos flood the family group. What do you do?","options":[{"text":"Compare her timeline with yours, year by year","then":"By evening, you've decided you're three years behind at life."},{"text":"Congratulate her and get on with your day","then":"Ritika sends a heart back. Your afternoon stays your own.","best":true},{"text":"Send a congrats, then feel sick about it all night","then":"Your message is kind. Inside, the comparison runs on a loop."},{"text":"Leave the group without a word","then":"Your mother calls, worried. Now there's something new to explain."}],"why":"You can be glad for someone and still measure yourself by your own path."},{"prompt":"Ritika messages you privately. She's struggling and feels the pressure too. What do you do?","options":[{"text":"Tell her she has nothing to worry about","then":"\"Right,\" she replies, and doesn't say more."},{"text":"Feel quietly glad she's not perfect after all","then":"The glow fades fast. It doesn't change how you see yourself."},{"text":"Listen, and tell her you know that pressure","then":"She sends a long message. You've both been carrying the same thing.","best":true},{"text":"Say at least she's the family favourite","then":"\"That's the problem,\" she replies, and goes quiet."}],"why":"Comparison hurts both people. Every path has its own struggles."},{"prompt":"At the next gathering, your uncle starts comparing you with Ritika again. What do you do?","options":[{"text":"Agree loudly to get it over with","then":"Your uncle looks pleased. You feel smaller on the way home."},{"text":"Say calmly you're on your own path, and doing okay","then":"Your uncle pauses. \"Achha. Good.\" Someone passes the sweets.","best":true},{"text":"Tell him Ritika's actually struggling, so there","then":"The room goes quiet. Ritika looks at you, hurt."},{"text":"Let it sink in quietly, like always","then":"The words land where they always do. You leave early."}],"why":"A calm word for your own path steps you out of the comparison trap."}],"debrief":"Others' comparisons aren't a verdict. Your own journey is the only fair measure.","relearn":"Measure yourself against your own path, not a relative's comparison."},
  {"id":"mb-1121","cat":"mind-and-self-worth","type":"branch","persona":"any","source":"perfectionism freeze","hook":"You won't start your design project until you're sure it'll be perfect, so it hasn't started.","steps":[{"prompt":"It's due in ten days and the file is still blank. What do you do?","options":[{"text":"Wait until you have the perfect idea","then":"Three days pass. With a week left, panic makes you start something."},{"text":"Make a rough first draft today, flaws and all","then":"It's messy, but it exists. The knot in your chest loosens.","best":true},{"text":"Research more examples first","then":"You save forty references. Two days later, you finally start."},{"text":"Tidy your desk and plan the perfect schedule","then":"The desk is spotless. That night, you finally open the file."}],"why":"A rough start you can improve beats a flawless one that never comes."},{"prompt":"Your first attempt looks clumsy, and you want to delete it and start over. What do you do?","options":[{"text":"Delete it. Better nothing than something bad","then":"The blank page is back. You start over, days behind where you were."},{"text":"Show no one until it's flawless","then":"You polish alone. Nobody can tell you what's working."},{"text":"Stay up all night perfecting every detail","then":"By dawn, you've redone the header six times. You're wrecked."},{"text":"Keep it and improve one part at a time","then":"By Friday, two parts look good. The rest looks fixable.","best":true}],"why":"Improving a rough version step by step is how good work actually gets made."},{"prompt":"Two days before the deadline, a friend offers to look at it. What do you do?","options":[{"text":"Say it's not ready yet","then":"She says okay. You miss the one tip that would have helped most."},{"text":"Show her, but apologise for every part first","then":"She has to talk past your apologies to give feedback."},{"text":"Show her, rough edges and all","then":"She spots one fix in a minute and loves your colours.","best":true},{"text":"Keep tweaking it alone until the last minute","then":"You're still changing things at 11:58. You submit in a blur."}],"why":"Sharing unfinished work gets you help that perfection would block."}],"debrief":"Perfectionism stalls you. Starting rough and improving is how things get done.","relearn":"Start rough; done beats flawless and breaks the perfectionism freeze."},
  {"id":"mb-1122","cat":"mind-and-self-worth","type":"branch","persona":"any","source":"rest is allowed","hook":"It's Sunday and you're exhausted, but resting feels wrong, like you haven't earned it.","steps":[{"prompt":"Your to-do list isn't finished and your body wants a quiet day. What do you do?","options":[{"text":"Push through the list first, then rest","then":"By evening the list is done, and so are you. The day is gone."},{"text":"Rest only after one more hour of work","then":"One hour becomes three. The quiet day shrinks to an evening."},{"text":"Take the rest day. You don't have to earn it","then":"You sleep in, eat properly and walk to the market. Your head clears.","best":true},{"text":"Lie down, but go over the list in your head","then":"You're on your bed for hours. It doesn't feel like rest."}],"why":"Rest is allowed by default. Your worth isn't conditional on output."},{"prompt":"That night, your roommate is pulling an all-nighter and asks why you're not studying. What do you do?","options":[{"text":"Feel ashamed and open your books","then":"You read the same page for an hour. Nothing goes in."},{"text":"Say you're feeling ill, so it sounds allowed","then":"She's sympathetic. You feel you had to make up a reason to rest."},{"text":"Tell her all-nighters are pointless","then":"She bristles. \"Works for me.\" The room gets frosty."},{"text":"Say you're resting tonight, and that's okay","then":"She shrugs. \"Fair. Wish I could.\" You go back to your novel.","best":true}],"why":"You can rest without apologising. Rest isn't a reward you earn."},{"prompt":"Midweek, you slip behind on one small task, and a guilty voice says you've gone soft. What do you do?","options":[{"text":"Do the task, and remind yourself rest isn't the problem","then":"It takes forty minutes. Your head is clearer than the voice made out.","best":true},{"text":"Promise never to take a day off again","then":"The promise feels responsible. It quietly sets up the next burnout."},{"text":"Work through the evening to make up for it","then":"You catch up and then some. You're already tired for Tuesday."},{"text":"Decide rest days are only for people who've earned them","then":"Next Sunday, you work through. By Wednesday, you're running on empty."}],"why":"Rest is part of how you work well, not a debt to repay."}],"debrief":"You don't have to earn rest. Treating it as a right, not a reward, protects you.","relearn":"You don't have to earn rest; your worth isn't conditional on output."},
  {"id":"mb-1123","cat":"mind-and-self-worth","type":"branch","persona":"any","source":"receiving praise","hook":"In a group meeting, your classmate Nikita says your part of the project was brilliant.","steps":[{"prompt":"Everyone turns to look at you. What do you do?","options":[{"text":"Say \"Oh, it was nothing\"","then":"Nikita shrugs. The moment slides past, and so does the credit."},{"text":"List what's wrong with it","then":"The group gets awkward. Someone starts agreeing with your flaws."},{"text":"Give all the credit to the rest of the team","then":"The team looks confused. \"It was your part, though.\""},{"text":"Say \"Thank you\" and let it land","then":"Nikita smiles and moves on. You feel a small, warm glow.","best":true}],"why":"A simple thank you lets the credit land. Deflecting feeds the impostor story."},{"prompt":"Later, your professor says your work shows real skill. What do you do?","options":[{"text":"Assume she says that to everyone","then":"The comment fades by evening. By the weekend, you've forgotten it."},{"text":"Thank her and ask what stood out to her","then":"She points to your data section. You hadn't known that was your strength.","best":true},{"text":"Say you just got lucky with the topic","then":"She raises an eyebrow. \"Luck doesn't do analysis.\""},{"text":"Thank her, then mention the parts you'd redo","then":"She nods. The talk turns to your flaws."}],"why":"Taking praise in, and asking about it, helps you see your real strengths."},{"prompt":"That week, your friend Omar brushes off your praise of his poem. What do you say?","options":[{"text":"Agree it wasn't that great, then","then":"Omar laughs, but looks a little hurt."},{"text":"Keep praising it until he accepts","then":"Omar squirms. The more you push, the more he shrinks."},{"text":"Tell him to try just saying thank you","then":"Omar rolls his eyes, then grins. \"Fine. Thank you.\"","best":true},{"text":"Let it go. That's just how he is","then":"The moment passes. In his head, the poem stays \"nothing\"."}],"why":"Helping a friend accept praise helps you practise it too."}],"debrief":"Receiving praise instead of deflecting it is a small act of self-respect.","relearn":"Let praise land with a simple 'thank you'; deflecting feeds the impostor story."},
  {"id":"mb-1124","cat":"mind-and-self-worth","type":"branch","persona":"any","source":"CGPA identity","hook":"You've come to define yourself by your CGPA, and it's ruling your mood.","steps":[{"prompt":"Mid-sem marks pull your CGPA down a little, and you feel like a failure. What do you do?","options":[{"text":"Recalculate your CGPA every possible way","then":"Every version looks worse. By night, you can't stop."},{"text":"Remind yourself one number isn't who you are","then":"The dip still stings. It stops feeling like the whole of you.","best":true},{"text":"Draw up a punishing study plan from tomorrow","then":"The plan fills every hour. The failure feeling doesn't budge."},{"text":"Call home to apologise for letting everyone down","then":"Your mother sounds confused. \"It's one test, beta.\" You still feel guilty."}],"why":"Your worth is bigger than one number. Separating the two steadies you."},{"prompt":"A friend asks you to play in the evening football match. What do you do?","options":[{"text":"Go. You're more than your marks","then":"You run, shout and laugh. The marks feel smaller by the end.","best":true},{"text":"Say no. Fun can wait till the CGPA's back up","then":"You stay in to study. The evening feels long and grey."},{"text":"Go, but spend the match thinking about marks","then":"You miss two easy passes. Your head was in your marksheet."},{"text":"Say no. You don't deserve a break right now","then":"The shouts from the field carry up to your room."}],"why":"Things you enjoy remind you that you're a whole person, not a grade."},{"prompt":"At a family dinner, a relative asks your CGPA before anything else. What do you do?","options":[{"text":"Answer, then apologise that it's dropped","then":"Your relative nods. The number becomes the whole conversation."},{"text":"Give a slightly higher number","then":"Your relative is pleased. You feel worse, not better."},{"text":"Go quiet and look at your plate","then":"The dinner moves on. You feel smaller for the rest of it."},{"text":"Answer, then talk about what you're enjoying","then":"You mention a book you're loving. Your relative asks to borrow it.","best":true}],"why":"Your values and interests are part of the answer, not just the number."},{"prompt":"Before the next exam, you're anxious it'll define you again. What do you do?","options":[{"text":"Pull all-nighters so it's perfect","then":"You walk into the exam foggy and shaky."},{"text":"Tell yourself this exam decides everything","then":"Your hands shake as you turn over the paper."},{"text":"Prepare steadily, knowing you're more than the result","then":"You sleep well the night before. The paper is hard, and you're okay.","best":true},{"text":"Avoid thinking about it till the night before","then":"The night before, it all hits at once."}],"why":"Effort and values steady you. One exam can't decide who you are."}],"debrief":"Anchoring worth in values and effort, not one number, gets you off the rollercoaster.","relearn":"Anchor your worth in values and effort, not one number like CGPA."},
  {"id":"mb-1125","cat":"mind-and-self-worth","type":"branch","persona":"any","source":"allowed to be proud","hook":"You finish a short film you worked on for months, then your inner voice says \"don't get cocky\".","steps":[{"prompt":"The film plays at the college fest and people clap. What do you do?","options":[{"text":"Squash the feeling so you stay humble","then":"You clap along politely. The joy fades before you've left the hall."},{"text":"Point out its flaws before anyone else can","then":"A friend looks confused. \"But it was great?\""},{"text":"Let yourself feel proud of the work you put in","then":"You stand a little taller. The months of work feel worth it.","best":true},{"text":"Say it was mostly luck and the team","then":"Your team smiles. Your own months of work go unmentioned, even by you."}],"why":"Healthy pride in real effort isn't arrogance. It nourishes self-worth."},{"prompt":"Your father calls and says not to let it go to your head. What do you do?","options":[{"text":"Agree and play it all down","then":"The call ends. Your pride feels like something you shouldn't have."},{"text":"Tell him you're proud of it, and that's okay","then":"He pauses. \"Achha. Send me the link, then.\"","best":true},{"text":"Get upset that he's never proud of you","then":"The call turns tense. Nobody says what they mean."},{"text":"Say nothing and change the subject","then":"The call moves to cousin news. The film goes unmentioned."}],"why":"You can feel proud and stay humble. Saying so gently keeps both."},{"prompt":"A junior asks how you made the film. What do you do?","options":[{"text":"Say it's nothing special, anyone could do it","then":"She looks deflated. If anyone could, why can't she?"},{"text":"Brush her off so you don't seem full of yourself","then":"She walks away unsure. You feel oddly guilty."},{"text":"Share what you learned, proud and honest","then":"Her notebook comes out. You talk for half an hour.","best":true},{"text":"Tell her all the awards it deserves to win","then":"She nods politely and edges away."}],"why":"Owning your effort, without shrinking it, helps others learn too."}],"debrief":"Healthy pride in real effort isn't arrogance. Letting yourself feel it nourishes self-worth.","relearn":"Let yourself feel proud of real effort; pride isn't arrogance."},
  {"id":"mb-1126","cat":"mind-and-self-worth","type":"role-play","persona":"any","source":"reassuring an impostor","hook":"Sana won the research internship everyone applied for, and now she dreads day one.","setup":"She calls you the night before.","steps":[{"prompt":"Sana says: \"They'll realise I'm a fraud. It's only a matter of time.\"","options":[{"text":"\"Don't be silly. You're brilliant.\"","then":"\"You're just being nice,\" she says, unconvinced."},{"text":"\"Maybe you did get a bit lucky, but so what?\"","then":"Silence. Then, quietly: \"So you think so too.\""},{"text":"\"Then prepare extra hard so no one can tell.\"","then":"\"I already have forty papers to read tonight,\" she says, voice tight."},{"text":"\"That feeling is really common. It isn't proof of anything.\"","then":"She exhales. \"Really? Everyone there seems so sure of themselves.\"","best":true}],"why":"Calling it a common feeling, not a fact, gives her a way out of the fear instead of just a compliment."},{"prompt":"Sana says: \"The others all went to big-name colleges. I didn't.\"","options":[{"text":"\"They picked you from the same pile. You earned it.\"","then":"\"I guess they did read my proposal,\" she says slowly.","best":true},{"text":"\"College names don't matter at all these days.\"","then":"\"They do, though,\" she says. \"You've seen the placement lists.\""},{"text":"\"Just don't mention where you studied.\"","then":"\"So I should hide it?\" she asks, sounding smaller."},{"text":"\"Honestly, that's a gap you'll have to make up for.\"","then":"She sighs. \"Great. So I start behind.\""}],"why":"Pointing to how she was actually chosen answers the fear with a real fact."},{"prompt":"Sana asks: \"What if I don't understand something in the first meeting?\"","options":[{"text":"\"Nod along and look it up later.\"","then":"\"That's my plan anyway,\" she admits. \"Pretend now, panic later.\""},{"text":"\"You won't. You'll know everything.\"","then":"\"No one knows everything,\" she says, more worried now."},{"text":"\"Then ask. New people are expected to ask.\"","then":"\"I suppose everyone asked something once,\" she says.","best":true},{"text":"\"Maybe keep quiet for the first week or so.\"","then":"\"So they don't notice me at all?\" she asks."}],"why":"Asking is normal for anyone new. It's how people learn, not a sign they don't belong."},{"prompt":"A week in, Sana texts: \"Still feel like a fraud. Is that normal?\"","options":[{"text":"\"It should have gone by now. Something must be off.\"","then":"\"Great, so something is wrong with me,\" she writes back."},{"text":"\"Very. The feeling can linger. It still isn't a fact.\"","then":"\"Okay,\" she replies. \"Then I'll stop treating it like a warning.\"","best":true},{"text":"\"Only if you let it. Just switch it off.\"","then":"\"If only it worked like that,\" she replies."},{"text":"\"Yeah, me too. We're all frauds, ha.\"","then":"\"Ha,\" she sends. \"Not sure that helps.\""}],"why":"Impostor feelings can linger. Knowing they're common, not facts, takes away their power."}],"relearn":"Remind a friend impostor feelings are common and not proof they don't belong."},
  {"id":"mb-1127","cat":"mind-and-self-worth","type":"role-play","persona":"any","source":"body-image support","hook":"Getting ready for a cousin's sangeet, Tara stands at the mirror, picking her body apart.","setup":"You're waiting by the door with the car keys.","steps":[{"prompt":"Tara says: \"Look at my arms. I can't wear this.\"","options":[{"text":"\"You look great! Stop worrying.\"","then":"\"You have to say that,\" she says, still tugging at the sleeve."},{"text":"\"Maybe wear the one with full sleeves instead.\"","then":"\"So you see it too,\" she says, and reaches for another outfit."},{"text":"\"Your body isn't a problem you need to fix.\"","then":"She pauses. \"It just feels like everyone will be looking.\"","best":true},{"text":"\"Everyone hates something about their body.\"","then":"\"Doesn't make it better,\" she mutters, turning sideways."}],"why":"Taking her body off the 'to fix' list moves the focus off looks, instead of just offering praise."},{"prompt":"Tara says: \"Aunties at these functions always comment on bodies.\"","options":[{"text":"\"Then let's skip it and stay home.\"","then":"\"I can't skip my own cousin's sangeet,\" she says, sitting on the bed."},{"text":"\"Laugh along. It's easier than arguing.\"","then":"\"I always do,\" she says. \"Then I feel awful all night.\""},{"text":"\"They do. That says more about them than your body.\"","then":"She almost laughs. \"Masi does say it about everyone.\"","best":true},{"text":"\"I'll tell off anyone who says a word.\"","then":"\"Please don't make a scene,\" she says, alarmed."}],"why":"Naming the comments as the problem, not her body, protects her worth without starting a fight."},{"prompt":"Tara asks: \"How do I stop hating what I see?\"","options":[{"text":"\"Stop looking in mirrors for a while.\"","then":"\"In this house? There's one in every room,\" she says, half-smiling."},{"text":"\"Pick one thing about it and work on fixing that.\"","then":"\"I've been fixing things since I was fourteen,\" she says quietly."},{"text":"\"Follow some body-positive pages. They'll help.\"","then":"\"I follow twenty already,\" she says. \"I still compare.\""},{"text":"\"Think about what your body does, not how it looks.\"","then":"She looks at her feet. \"They did dance for three hours at practice.\"","best":true}],"why":"Valuing what her body does for her builds worth that doesn't depend on how she looks."}],"relearn":"Help a friend see their body as more than a problem to fix."},
  {"id":"mb-1128","cat":"mind-and-self-worth","type":"role-play","persona":"any","source":"self-talk practice","hook":"You sent your group's slides to the wrong WhatsApp group. Your inner critic is loud.","setup":"You're walking back to your room, phone still in hand.","steps":[{"prompt":"Your inner critic says: \"Typical. You always ruin everything.\"","options":[{"text":"\"You're right. I'm hopeless at this.\"","then":"\"Exactly,\" it says, and starts listing old mistakes too."},{"text":"\"One slip doesn't undo everything I've done.\"","then":"The voice gets quieter. \"Fine. But everyone saw it.\"","best":true},{"text":"\"It wasn't even my fault. The groups look the same.\"","then":"\"Nice excuse,\" it says. \"You still sent it.\""},{"text":"\"From now on I'll check every message five times.\"","then":"\"And you'll still mess up,\" it says. Your shoulders stay tense."}],"why":"Answering the critic with a fair fact takes its power away, without pretending the slip didn't happen."},{"prompt":"Your inner critic says: \"Everyone in that group thinks you're an idiot now.\"","options":[{"text":"\"I'll leave the group before anyone replies.\"","then":"\"Leaving now? That'll look even worse,\" it says. You stay, stomach tight."},{"text":"\"If a friend did this, I'd laugh with them. Same for me.\"","then":"\"Hmm,\" the voice says, sounding less sure of itself.","best":true},{"text":"\"They probably do. I'll avoid them for a while.\"","then":"\"Good. Hide,\" it says, and tomorrow's class starts to feel heavy."},{"text":"\"I'll send each of them a long apology.\"","then":"\"Now they'll really notice,\" it says. You stop typing, three paragraphs in."}],"why":"Treating yourself the way you'd treat a friend is the heart of self-compassion."},{"prompt":"Your inner critic says: \"Meanwhile, your group still doesn't have the slides.\"","options":[{"text":"\"There's nothing to fix. It doesn't matter at all.\"","then":"\"Then why are you still thinking about it?\" it asks."},{"text":"\"I'll fix it, then check all my other chats for mistakes.\"","then":"\"See? Mistakes everywhere,\" it says, as an hour disappears."},{"text":"\"I'll wait and see if anyone even noticed.\"","then":"\"Someone noticed,\" it whispers, every time your phone buzzes."},{"text":"\"I'll say sorry, wrong group, and send it to the right one.\"","then":"\"Fine,\" it mutters. Two people reply with a laughing emoji.","best":true}],"why":"A small, fair fix closes the loop. Ignoring it or over-checking keeps the critic talking."},{"prompt":"That night, your inner critic says: \"Still thinking about it, aren't you?\"","options":[{"text":"\"A bit. I'm allowed to be human.\"","then":"The voice fades, and sleep comes sooner than you expected.","best":true},{"text":"\"No. I've completely stopped caring.\"","then":"\"Liar,\" it says, and the chat replays in your head."},{"text":"\"Yes. And I deserve to feel bad about it.\"","then":"\"You do,\" it agrees, and sleep takes a long time to come."},{"text":"\"I'll replay it till I know exactly what went wrong.\"","then":"\"Let's start again,\" it says. The clock reaches 2 a.m."}],"why":"Accepting you're human lets the feeling pass. Punishing yourself only keeps it going."}],"relearn":"Talk to yourself after a mistake the way a kind friend would."},
  {"id":"mb-1129","cat":"mind-and-self-worth","type":"role-play","persona":"any","source":"worth beyond placement","hook":"Kabir was turned down in the final round of the placement he'd prepared for all year.","setup":"He's sitting on the hostel steps, phone in hand.","steps":[{"prompt":"Kabir says: \"That was my one shot. I'm nothing without that job.\"","options":[{"text":"\"Their loss! That company is rubbish anyway.\"","then":"\"It's the one everyone wanted,\" he says flatly."},{"text":"\"One offer isn't the measure of you.\"","then":"He looks at you. \"Try telling that to my dad.\"","best":true},{"text":"\"Yeah, that one really did decide a lot.\"","then":"He nods slowly and says nothing for a long time."},{"text":"\"Apply to twenty more tonight. Get straight back on it.\"","then":"\"Tonight? I can barely look at my laptop,\" he says."}],"why":"Separating his worth from one company's decision speaks to the real hurt underneath."},{"prompt":"Kabir says: \"My family told everyone back home I'd get this.\"","options":[{"text":"\"Don't tell them yet. Say it's still in process.\"","then":"\"And then what? Lie for months?\" he asks."},{"text":"\"They'll get over it. Parents always do.\"","then":"\"You don't know my family,\" he says, pulling his knees in."},{"text":"\"That's heavy to carry. You're still you without it.\"","then":"He lets out a breath. \"I never thought of it as carrying something.\"","best":true},{"text":"\"Tell them you'll definitely get the next one.\"","then":"\"And if I don't?\" he asks, very quietly."}],"why":"Naming the weight of their hopes, while keeping his worth apart from it, helps him breathe."},{"prompt":"Kabir asks: \"So what do I even do with myself now?\"","options":[{"text":"\"Take a total break from everything for a month.\"","then":"\"A month? Everyone else will be interviewing,\" he says."},{"text":"\"Focus on your grades. They matter more now.\"","then":"\"So now I have to top everything instead,\" he says, tired."},{"text":"\"Find out who got it and what they did differently.\"","then":"He scrolls the selected list, and his face falls further."},{"text":"\"Eat, sleep, then pick one next step with the placement cell.\"","then":"\"Food first,\" he says, standing up. \"The rest can wait till morning.\"","best":true}],"why":"Basics first, then one small step, keeps him moving without making the next result his whole worth."}],"relearn":"Remind a friend one offer doesn't measure their worth."},
  {"id":"mb-1130","cat":"mind-and-self-worth","type":"role-play","persona":"Deepak","source":"taking up space","hook":"First in your family at college, you open every point in class with an apology.","setup":"Today's seminar is on a reading you loved.","steps":[{"prompt":"Professor Iyer asks: \"Anyone want to add to that?\"","options":[{"text":"\"Sorry, this is probably a silly question, but...\"","then":"\"Not silly at all,\" she says, as two others start talking over you."},{"text":"\"I'd like to add a point about the second chapter.\"","then":"She nods. \"Go on. Take your time.\"","best":true},{"text":"\"Um, it's fine. Someone else can go.\"","then":"\"Alright,\" she says, and turns to the front row."},{"text":"\"I'll email you my thoughts after class, ma'am.\"","then":"\"Sure,\" she says. \"Though the room would gain from hearing it.\""}],"why":"Stating your point plainly claims your place. You belong in the discussion as much as anyone."},{"prompt":"After class, your classmate Vikram asks: \"Why don't you speak up more often?\"","options":[{"text":"\"Sorry. I know I should.\"","then":"\"Why sorry? It's not a crime,\" he says, puzzled."},{"text":"\"People like me don't really get heard here.\"","then":"He frowns. \"Who says? Half of us are from small towns.\""},{"text":"\"Old habit. I'm starting to. I've got things to say.\"","then":"\"Good,\" Vikram says. \"Sit with us next time. We argue a lot.\"","best":true},{"text":"\"Everyone else here is smarter. I just listen.\"","then":"\"Smarter? Most of us skimmed the reading,\" he laughs."}],"why":"Owning the habit while saying you have things to add treats you as someone who belongs."},{"prompt":"At the next seminar, Professor Iyer asks: \"Who'll start us off today?\"","options":[{"text":"\"I will. I think the author misses one thing.\"","then":"\"Go on,\" she says, and the room turns to you.","best":true},{"text":"\"Sorry, can I go? It's probably nothing.\"","then":"\"Of course,\" she says, as a few people glance at their phones."},{"text":"\"I'll go once a few others have spoken.\"","then":"The hour fills up fast, and she wraps up before you get a turn."},{"text":"\"Maybe someone who's read more should start.\"","then":"\"Everyone had the same reading,\" she says, and waits."}],"why":"Speaking first, without an apology, is a small, real way to take the space you've earned."}],"relearn":"You're allowed to take up space; you belong here as much as anyone."},
  {"id":"mb-1131","cat":"mind-and-self-worth","type":"role-play","persona":"any","source":"helping receive praise","hook":"You told Meher her fest poster was brilliant. She waved it off as 'nothing special.'","setup":"Later, you catch up with her at the canteen.","steps":[{"prompt":"Over chai, Meher says: \"Honestly, anyone could have made it. I got lucky.\"","options":[{"text":"\"Okay, never mind. Forget I even said anything.\"","then":"\"Sorry, I didn't mean to be weird,\" she says, and goes quiet."},{"text":"\"Stop fishing for more compliments!\"","then":"She flushes. \"I wasn't. That's the opposite of what I was doing.\""},{"text":"\"I meant it. You're allowed to take the credit.\"","then":"She stops stirring her chai. \"It did take me three nights.\"","best":true},{"text":"\"You're right. It's only a poster.\"","then":"\"Yeah,\" she says, a little too fast."}],"why":"Repeating the compliment and giving her permission helps her let it land."},{"prompt":"Meher says: \"If I own it, people will think I'm showing off.\"","options":[{"text":"\"So what? Show off. You earned it.\"","then":"She laughs. \"I could never. I'd die of embarrassment.\""},{"text":"\"Saying thank you isn't showing off.\"","then":"She tries it quietly. \"Thank you. That feels strange to say.\"","best":true},{"text":"\"Maybe. Better to stay humble, I guess.\"","then":"\"That's what my mother always says,\" she nods."},{"text":"\"Only if you go on and on about it.\"","then":"\"So I keep it short,\" she says. \"Or say nothing.\""}],"why":"A simple thank you lets praise in without bragging, and that's how self-worth grows."},{"prompt":"Meher asks: \"Why is it so hard to hear something nice about myself?\"","options":[{"text":"\"Because you're too modest. Just get over it.\"","then":"\"If it were that easy,\" she says, and looks away."},{"text":"\"Maybe deep down you don't believe you're good.\"","then":"She goes still. \"Great. Now I'm analysing that too.\""},{"text":"\"No idea. Want another chai?\"","then":"\"Sure,\" she says, relieved, and the moment passes."},{"text":"\"Lots of us learnt to shrink praise. It can change.\"","then":"\"Maybe I'll practise on you,\" she says, grinning.","best":true}],"why":"Saying it's common, and that it can change, makes taking credit feel possible."}],"relearn":"Encourage a friend to receive a genuine compliment instead of deflecting it."},
  {"id":"mb-1132","cat":"mind-and-self-worth","type":"role-play","persona":"any","source":"comparison reframe","hook":"Three weeks into his engineering course, Nikhil is sure everyone else is smarter.","setup":"He says it on the walk back from the lab.","steps":[{"prompt":"Nikhil says: \"They all get it in one go. I don't belong on this course.\"","options":[{"text":"\"Honestly, yeah. Some people are just sharper.\"","then":"He nods, and goes quiet for most of the walk."},{"text":"\"You're comparing your inside to their outside.\"","then":"He frowns. \"What do you mean?\"","best":true},{"text":"\"You should've picked something easier.\"","then":"\"Thanks,\" he says flatly. \"That's exactly my fear.\""},{"text":"\"Don't be dramatic. You'll be totally fine.\"","then":"\"I'm not being dramatic,\" he says, walking faster."}],"why":"Naming the unfair comparison, what he feels against what others show, loosens its grip."},{"prompt":"Nikhil says: \"Rahul answered every question in class today.\"","options":[{"text":"\"Rahul's a show-off. Ignore him.\"","then":"\"He's actually nice,\" Nikhil says, uncomfortable."},{"text":"\"So study the way Rahul studies. Copy it.\"","then":"\"I tried. I can't keep up with his hours,\" he says."},{"text":"\"You saw his answers. Not his confusion at 2 a.m.\"","then":"He half-laughs. \"I did hear him asking seniors for help.\"","best":true},{"text":"\"Then you need to answer more questions too.\"","then":"\"And get it wrong in front of everyone?\" he asks."}],"why":"Seeing others' struggles as well as their wins makes the comparison fair."},{"prompt":"Nikhil says: \"Maybe they made a mistake letting me in.\"","options":[{"text":"\"Even if they did, you're here now. Make it count.\"","then":"\"So you think they did,\" he says, deflating."},{"text":"\"Admissions don't make mistakes. Stop it.\"","then":"\"Okay,\" he says, but the thought clearly hasn't gone."},{"text":"\"Ask the professor if you're good enough.\"","then":"\"And if she hesitates?\" he asks, going pale."},{"text":"\"You got in on merit, same as everyone else.\"","then":"He's quiet, then says, \"I did clear the entrance with a decent rank.\"","best":true}],"why":"Reminding him he earned his place answers the fear with a fact, not a pep talk."},{"prompt":"A week later, Nikhil says: \"I'm still behind on the maths.\"","options":[{"text":"\"Watch videos all weekend till it clicks.\"","then":"\"All weekend?\" he groans. \"Then I'm behind on everything else.\""},{"text":"\"Want to go to the tutorial hour together?\"","then":"\"Yeah, okay,\" he says. \"Less scary with someone else there.\"","best":true},{"text":"\"Maybe maths just isn't your thing.\"","then":"His face closes. \"Right. Of course.\""},{"text":"\"Ask Rahul to explain all of it to you.\"","then":"\"I'd feel stupid asking him,\" he says."}],"why":"Being behind is normal. Getting help together turns it into a plan, not proof he doesn't belong."}],"relearn":"Remind a friend comparison is unfair and they made it here on merit."},
  {"id":"mb-1133","cat":"mind-and-self-worth","type":"match","hook":"Match the harsh thought to the kinder, truer reframe.","pairs":[{"left":"\"I'm a total failure\"","right":"\"This one thing went badly\""},{"left":"\"I got lucky to be here\"","right":"\"I earned my place\""},{"left":"\"I'm worthless without top marks\"","right":"\"My worth isn't a grade\""},{"left":"\"I should look different to matter\"","right":"\"I'm more than my appearance\""},{"left":"\"Resting means I'm lazy\"","right":"\"Rest is how I keep going\""}],"relearn":"Each harsh thought has a kinder reframe: a setback isn't failure, you earned your place, worth isn't a grade or look, rest isn't laziness.","persona":"any","source":"reframe pairs"},
  {"id":"mb-1134","cat":"mind-and-self-worth","type":"match","hook":"Match each source of worth to whether it's steady or can vanish overnight.","pairs":[{"left":"Your kindness to others","right":"Stays with you"},{"left":"This week's like count","right":"Gone by tomorrow"},{"left":"Your effort and values","right":"Always yours"},{"left":"A leaderboard ranking","right":"Changes constantly"},{"left":"How you treat yourself","right":"In your hands"}],"relearn":"Kindness, effort, values and self-treatment are steady sources of worth; likes and rankings vanish overnight.","persona":"any","source":"steady vs fleeting"},
  {"id":"mb-1135","cat":"mind-and-self-worth","type":"match","hook":"Match the self-compassion move to what it protects you from.","pairs":[{"left":"Talking to yourself like a friend","right":"A brutal inner critic"},{"left":"Tracking your own progress","right":"Endless comparison"},{"left":"Thanking your body","right":"Mirror self-attack"},{"left":"Letting praise land","right":"The impostor story"},{"left":"Resting without guilt","right":"Burning yourself out"}],"relearn":"Self-kindness guards against the inner critic, comparison, body-attack, impostor feelings and burnout.","persona":"any","source":"self-compassion toolkit"},
  {"id":"mb-1136","cat":"mind-and-self-worth","type":"match","hook":"Match the myth about self-worth to the truth that answers it.","pairs":[{"left":"\"Worth = productivity\"","right":"You matter beyond output"},{"left":"\"Worth = looks\"","right":"You're more than appearance"},{"left":"\"Worth = always winning\"","right":"You can lose and still matter"},{"left":"\"Worth = others' approval\"","right":"It's not theirs to grant"},{"left":"\"Worth = perfection\"","right":"You're enough while learning"}],"relearn":"Your worth isn't productivity, looks, winning, approval or perfection; you matter beyond all of them.","persona":"any","source":"myth vs truth"},
  {"id":"mb-1137","cat":"mind-and-self-worth","type":"match","hook":"Match the impostor thought to the real evidence that answers it.","pairs":[{"left":"\"I only got lucky\"","right":"You met the entry bar"},{"left":"\"They'll find me out\"","right":"Your work has stood up"},{"left":"\"I don't deserve this\"","right":"You did the hours"},{"left":"\"Everyone's ahead of me\"","right":"You handled hard things before"},{"left":"\"I'm a fraud\"","right":"Capable people feel this too"}],"relearn":"Impostor thoughts are feelings; meeting the bar, doing the hours and handling hard things are the real evidence you belong.","persona":"Deepak","source":"impostor evidence"},
  {"id":"mb-1138","cat":"mind-and-self-worth","type":"match","hook":"Match what your body did today to a reason to thank it, not judge it.","pairs":[{"left":"Walked you across campus","right":"It carried you"},{"left":"Healed a small cut","right":"It repairs itself"},{"left":"Let you hug a friend","right":"It connects you"},{"left":"Got you through a long day","right":"It kept going"},{"left":"Let you taste your food","right":"It lets you enjoy life"}],"relearn":"Your body carries, heals, connects and keeps going for you; that's a reason for gratitude, not judgement.","persona":"any","source":"body gratitude pairs"},
  {"id":"mb-1139","cat":"mind-and-self-worth","type":"match","hook":"Match the self-worth situation to the steady move for it.","pairs":[{"left":"Feeling like a fraud","right":"List what you've actually earned"},{"left":"Hating a photo","right":"Recall what your body does for you"},{"left":"A bad grade stings","right":"Separate the result from your worth"},{"left":"Comparison spiral","right":"Mute the trigger, track your own path"},{"left":"Harsh inner voice","right":"Answer it like a kind friend"}],"relearn":"List what you earned, recall your body's work, separate result from worth, mute triggers, and answer the critic kindly.","persona":"any","source":"situation to move"},
  {"id":"mb-1140","cat":"mind-and-self-worth","type":"spot","hook":"Spot the two thoughts that secretly attack your self-worth.","scene":[{"id":"a","text":"\"A bad day isn't my whole story\"","trick":false},{"id":"b","text":"\"If I'm not the best, I'm worthless\"","trick":true},{"id":"c","text":"\"I'm allowed to be still learning\"","trick":false},{"id":"d","text":"\"Everyone can see I don't belong\"","trick":true},{"id":"e","text":"\"My effort counts, not just the result\"","trick":false}],"why":"'Worthless if not the best' and 'everyone sees I don't belong' are the worth-attacking lies; the rest are kind, true.","relearn":"'Worthless if not the best' and 'everyone sees I don't belong' attack self-worth; a bad day isn't your story.","persona":"any","source":"spot the attack"},
  {"id":"mb-1141","cat":"mind-and-self-worth","type":"spot","hook":"Spot the two body-image messages that are doing you harm.","scene":[{"id":"a","text":"\"Your body is more than how it looks\"","trick":false},{"id":"b","text":"\"You'd be worth more if you looked 'better'\"","trick":true},{"id":"c","text":"\"Feed and rest your body kindly\"","trick":false},{"id":"d","text":"\"Hide until you've fixed how you look\"","trick":true},{"id":"e","text":"\"Your body carries you through the day\"","trick":false}],"why":"'Worth more if you looked better' and 'hide till you fix yourself' are the harmful ones; the rest treat your body kindly.","relearn":"'Worth more if you looked better' and 'hide till fixed' harm you; you're more than looks.","persona":"any","source":"spot harmful body messages"},
  {"id":"mb-1142","cat":"mind-and-self-worth","type":"spot","hook":"Spot the two lines that fuel impostor feelings.","scene":[{"id":"a","text":"\"I earned my place like everyone else\"","trick":false},{"id":"b","text":"\"I only got in by a fluke\"","trick":true},{"id":"c","text":"\"Feeling unsure is human, not proof\"","trick":false},{"id":"d","text":"\"Any moment they'll realise I'm a fraud\"","trick":true},{"id":"e","text":"\"My work has held up so far\"","trick":false}],"why":"'Got in by a fluke' and 'they'll realise I'm a fraud' feed the impostor story; the others answer it with truth.","relearn":"'Got in by a fluke' and 'they'll realise I'm a fraud' feed impostor feelings; you earned your place.","persona":"Deepak","source":"spot impostor lines"},
  {"id":"mb-1143","cat":"mind-and-self-worth","type":"spot","hook":"Spot the two things tying your worth to the scoreboard.","scene":[{"id":"a","text":"\"My worth holds whatever the result\"","trick":false},{"id":"b","text":"\"A low score makes me a lesser person\"","trick":true},{"id":"c","text":"\"Grades rate the task, not me\"","trick":false},{"id":"d","text":"\"I'm only valuable when I'm winning\"","trick":true},{"id":"e","text":"\"My effort matters even if I lose\"","trick":false}],"why":"'A low score makes me lesser' and 'only valuable when winning' chain worth to results; the rest keep them apart.","relearn":"'A low score makes me lesser' and 'only valuable when winning' chain worth to results; grades rate the task, not you.","persona":"any","source":"spot worth-on-scoreboard"},
  {"id":"mb-1144","cat":"mind-and-self-worth","type":"spot","hook":"Spot the two comparison habits quietly draining your self-worth.","scene":[{"id":"a","text":"Cheering a friend's good news genuinely","trick":false},{"id":"b","text":"Refreshing a rival's profile to feel small","trick":true},{"id":"c","text":"Tracking your own progress, not theirs","trick":false},{"id":"d","text":"Tallying who's 'ahead' of you all day","trick":true},{"id":"e","text":"Remembering feeds are highlight reels","trick":false}],"why":"Refreshing a rival's profile and tallying who's ahead are the draining habits; the rest ease comparison.","relearn":"Refreshing rivals' profiles and tallying who's ahead drain you; cheer friends, track your path.","persona":"any","source":"spot comparison habits"},
  {"id":"mb-1145","cat":"mind-and-self-worth","type":"spot","hook":"Spot the two 'humility' habits that are really self-put-downs.","scene":[{"id":"a","text":"Saying a plain 'thank you' to praise","trick":false},{"id":"b","text":"Calling every win of yours 'nothing'","trick":true},{"id":"c","text":"Owning what you worked hard for","trick":false},{"id":"d","text":"Listing your flaws so no one else does","trick":true},{"id":"e","text":"Letting a compliment land","trick":false}],"why":"Dismissing every win as 'nothing' and pre-listing your flaws are self-put-downs dressed as humility; the rest are healthy self-respect.","relearn":"Calling wins 'nothing' and pre-listing flaws are self-put-downs, not humility; let praise land.","persona":"any","source":"spot false humility"},
  {"id":"mb-1146","cat":"mind-and-self-worth","type":"spot","hook":"Spot the two perfectionism traps hiding as 'high standards.'","scene":[{"id":"a","text":"\"Done is better than flawless\"","trick":false},{"id":"b","text":"\"If it's not perfect, don't submit it\"","trick":true},{"id":"c","text":"\"A draft I can improve beats nothing\"","trick":false},{"id":"d","text":"\"Anything below the top is failure\"","trick":true},{"id":"e","text":"\"Progress counts, not just the peak\"","trick":false}],"why":"'Perfect or don't submit' and 'below the top is failure' are perfectionism traps; the others are kind, workable standards.","relearn":"'Perfect or don't submit' and 'below the top is failure' are perfectionism traps; done beats flawless.","persona":"any","source":"spot perfectionism"},
  {"id":"mb-1147","cat":"mind-and-self-worth","type":"spot","hook":"Spot the two things that wrongly try to set your worth.","scene":[{"id":"a","text":"Your character and how you treat people","trick":false},{"id":"b","text":"The number of likes on a post","trick":true},{"id":"c","text":"Living by what you value","trick":false},{"id":"d","text":"A stranger's approval online","trick":true},{"id":"e","text":"The effort you put in","trick":false}],"why":"Likes and a stranger's approval can't measure your worth; character, values and effort are the real, steady ground.","relearn":"Likes and strangers' approval don't set your worth; character, values and effort do.","persona":"any","source":"spot fake worth-meters"},
  {"id":"mb-1170","cat":"reach-out","type":"strike-rewrite","hook":"\"Counselling is only for people who are seriously ill.\"","myth":{"un":"Counselling is only for people who are seriously ill.","re":"A counsellor helps with everyday stress, low patches and big decisions too, not just crises.","why":"Most people who go are simply struggling, not 'ill'."},"relearn":"Counselling is for everyday stress and low patches too, not only serious illness.","persona":"any","source":"counselling normal"},
  {"id":"mb-1171","cat":"reach-out","type":"strike-rewrite","hook":"\"If I tell my family I'm struggling, I'll just be a burden.\"","myth":{"un":"If I tell my family I'm struggling, I'll just be a burden.","re":"People who care want to know; sharing usually brings you closer, not a burden.","why":"Hiding it alone is the heavier load."},"relearn":"Sharing that you're struggling isn't a burden; people who care want to know.","persona":"Deepak","source":"not a burden"},
  {"id":"mb-1172","cat":"reach-out","type":"strike-rewrite","hook":"\"I should be able to fix my own head; reaching out is cheating.\"","myth":{"un":"I should be able to fix my own head; reaching out is cheating.","re":"Minds aren't meant to be carried solo; using support is how it's done well.","why":"Nobody talks themselves through everything alone."},"relearn":"Using support isn't cheating; minds aren't meant to be carried entirely alone.","persona":"any","source":"not solo"},
  {"id":"mb-1173","cat":"reach-out","type":"strike-rewrite","hook":"\"A helpline can't help a stranger like me in a few minutes.\"","myth":{"un":"A helpline can't help a stranger like me in a few minutes.","re":"Trained listeners on Tele-MANAS 14416 can steady you and point the next step, even briefly.","why":"One calm conversation often shifts a heavy moment."},"relearn":"Tele-MANAS 14416 listeners can steady you and find a next step, even in one call.","persona":"any","source":"helpline works"},
  {"id":"mb-1174","cat":"reach-out","type":"strike-rewrite","hook":"\"Reaching out once and feeling no better means help doesn't work for me.\"","myth":{"un":"Reaching out once and feeling no better means help doesn't work for me.","re":"Support often takes a few tries to click; one off day doesn't mean it won't work.","why":"Fit and timing matter; keep going."},"relearn":"One disappointing try doesn't mean help won't work; it often takes a few goes.","persona":"any","source":"keep trying"},
  {"id":"mb-1175","cat":"reach-out","type":"strike-rewrite","hook":"\"I'm far from any campus or city; there's no real help for me.\"","myth":{"un":"I'm far from any campus or city; there's no real help for me.","re":"Tele-MANAS 14416 is free, 24/7 and works from any phone, no campus needed.","why":"Distance and no safety net don't lock you out."},"relearn":"Tele-MANAS 14416 is free and reaches any phone; you don't need a campus to get help.","persona":"Meena","source":"help anywhere"},
  {"id":"mb-1176","cat":"reach-out","type":"strike-rewrite","hook":"\"If I open up, word will spread and everyone will know my business.\"","myth":{"un":"If I open up, word will spread and everyone will know my business.","re":"Counsellors and helplines like Tele-MANAS 14416 are confidential; what you share stays private.","why":"Confidentiality is a core part of how they work."},"relearn":"Counsellors and Tele-MANAS 14416 are confidential; opening up there stays private.","persona":"any","source":"confidential"},
  {"id":"mb-1177","cat":"reach-out","type":"branch","persona":"any","source":"not a competition","hook":"You've been low for weeks, but friends seem to have it worse, so you stay quiet.","steps":[{"prompt":"Your cousin Nikita asks on a call how college is really going. What do you say?","options":[{"text":"Say it's fine. Others have real problems","then":"\"Okay,\" she says, and the call moves on to family gossip."},{"text":"Ask how she is, to keep it off you","then":"She talks for twenty minutes. You hang up feeling more alone."},{"text":"Say you're a bit stressed, but it's nothing","then":"\"Everyone is,\" she says kindly, and doesn't ask more."},{"text":"Tell her you've been low for a few weeks","then":"Nikita goes quiet, then says, \"Thanks for telling me. What's been going on?\"","best":true}],"why":"Naming what's really going on lets someone care for you. Your pain doesn't need to be the worst."},{"prompt":"A week later you think of seeing the college counsellor, but a friend's problems seem bigger. What do you do?","options":[{"text":"Leave the slots for people with bigger problems","then":"The weeks go on, and so does the low feeling."},{"text":"Book a slot. Your struggle counts too","then":"The counsellor smiles. \"This is exactly what we're here for.\"","best":true},{"text":"Encourage your friend to go instead of you","then":"Your friend goes and feels better. You're still carrying yours."},{"text":"Wait till you're sure you're struggling 'enough'","then":"You keep measuring yourself against others, and never quite qualify."}],"why":"Support isn't rationed for the worst-off. Your struggle deserves care on its own."},{"prompt":"Your inner voice says you're selfish for needing help. What do you tell yourself?","options":[{"text":"Maybe it is selfish. I'll keep it to myself","then":"The quiet feels heavy, and the low weeks keep adding up."},{"text":"I'll only ask once everyone else is okay","then":"That day never comes. There's always someone else to worry about."},{"text":"Pain isn't a competition. Mine matters too","then":"The thought loosens its grip, and reaching out feels less wrong.","best":true},{"text":"People would laugh if they knew I was struggling","then":"You picture their faces and pull further into yourself."}],"why":"Everyone's struggle deserves care. Needing help isn't selfish."}],"debrief":"Pain isn't a competition. You needn't be the worst-off to deserve support.","relearn":"Your struggle is valid even if others have it worse; reach out anyway."},
  {"id":"mb-1178","cat":"reach-out","type":"branch","persona":"any","source":"finding a fit","hook":"Two sessions with your first counsellor felt flat, and you're close to giving up on it.","steps":[{"prompt":"Your next session with Mr. Rao is tomorrow. What do you do?","options":[{"text":"Cancel quietly and stop going","then":"The slot empties. The problem you went in with stays."},{"text":"Go, and pretend it's helping so it isn't awkward","then":"The session drifts along politely, and you leave feeling unheard."},{"text":"Go, and say honestly that it isn't clicking yet","then":"Mr. Rao nods. \"Thank you for telling me. Let's talk about what you need.\"","best":true},{"text":"Decide counselling isn't for people like you","then":"You delete the reminder. Where to get help is still an open question."}],"why":"Saying it isn't working lets the counsellor adjust, or help you find a better fit."},{"prompt":"A week later, the centre texts to ask if you'd like another session. Mr. Rao still doesn't feel right. What do you do?","options":[{"text":"Give up. If this one didn't work, none will","then":"You ignore the text. What you went in for is still there."},{"text":"Ask the centre for a different counsellor","then":"The receptionist says people switch all the time, and books you with Ms. Sethi.","best":true},{"text":"Stick with him for months, out of politeness","then":"The weeks pass in careful sessions that never reach the real problem."},{"text":"Swap sessions for self-help videos at night","then":"The videos are calming, but no one knows how you're really doing."}],"why":"Fit varies from person to person. Switching is normal, and often what makes support work."},{"prompt":"Your friend Priya says, 'If counselling didn't work once, it's not for you.' What do you say?","options":[{"text":"Agree. Maybe it's a waste of time","then":"The doubt settles in, and trying again feels less likely."},{"text":"Say nothing. You're not sure either","then":"Her words replay in your head that night."},{"text":"Say counselling works for anyone who tries hard enough","then":"Priya raises an eyebrow. \"Anyone? That's a big claim.\""},{"text":"Say one poor fit doesn't mean all support fails","then":"Priya thinks. \"Fair. My first dentist was awful too.\"","best":true}],"why":"One poor fit is about that match, not about you or about counselling as a whole."}],"debrief":"One bad fit isn't a verdict on all support.","relearn":"If one counsellor isn't a fit, try another. Fit varies, and support still works."},
  {"id":"mb-1179","cat":"reach-out","type":"branch","persona":"any","source":"checking in","hook":"Aditya has cancelled three plans, gone quiet, and brushes off every text asking if he's okay.","steps":[{"prompt":"He's just cancelled Sunday's cricket too. What do you do?","options":[{"text":"Back off. He clearly wants to be left alone","then":"The chat goes silent. Now and then, you wonder how he is."},{"text":"Reply that he seems off lately, and you're around","then":"An hour later he sends, \"Thanks. Just a rough patch.\"","best":true},{"text":"Send 'fine, whatever' and stop inviting him","then":"He sends a thumbs up. The gap between you widens."},{"text":"Ask the group chat what's going on with him","then":"Three people guess at reasons, and Aditya goes even quieter."}],"why":"Naming what you've noticed, without pushing, tells him someone sees him and the door is open."},{"prompt":"A few days later, you spot Aditya alone in the canteen. What do you do?","options":[{"text":"Wave and keep walking, to give him space","then":"He waves back weakly and looks down at his plate."},{"text":"Tell him he's been a bad friend lately","then":"His face closes. \"Sorry I'm such a letdown.\""},{"text":"Sit with him and ask how he's really doing","then":"He shrugs, then says, \"Honestly? Not great. Home stuff.\"","best":true},{"text":"Sit down and chat about cricket, nothing heavy","then":"He joins in for a bit, then goes quiet. You never get to the real thing."}],"why":"A gentle, direct question in person gives him an easy way to tell the truth."},{"prompt":"That night, Aditya texts: 'Sorry I've gone quiet. I don't want to be a burden. Everyone's got stuff.' What do you say?","options":[{"text":"Tell him to see a counsellor, and leave it there","then":"\"Maybe,\" he replies, and changes the topic."},{"text":"Agree everyone's busy, but say he'll be fine","then":"\"Yeah,\" he replies, and goes offline."},{"text":"Say he's not a burden, and you'd rather know","then":"A pause, then: \"Really? It's been bad since my dad lost his job.\"","best":true},{"text":"Share your own problems so he feels less alone","then":"He replies politely to yours, and his own story stays untold."}],"why":"Telling him he's not a burden answers the fear that keeps him quiet."},{"prompt":"A week later, Aditya still seems low. What do you do?","options":[{"text":"Assume he's fine now, since he talked once","then":"The texts thin out again, and he drifts further away."},{"text":"Stop checking in, so you don't seem pushy","then":"Silence settles back in between you."},{"text":"Call his parents without asking him","then":"His mother calls him in a panic, and he stops replying to you."},{"text":"Keep checking in, and offer to go with him to a counsellor","then":"He takes a day to think, then says yes to Thursday.","best":true}],"why":"Steady check-ins, plus an offer to go with him, help without pushing."}],"debrief":"A withdrawing friend often can't ask for help. Keep the door open without pushing.","relearn":"If a friend withdraws, gently keep the door open rather than backing off."},
  {"id":"mb-1180","cat":"reach-out","type":"branch","persona":"any","source":"first session","hook":"You finally booked your first counselling session for tomorrow, and now you're panicking.","steps":[{"prompt":"Your thumb hovers over 'cancel appointment'. What do you do?","options":[{"text":"Cancel. The nerves must be a sign","then":"Relief lasts an hour. Then you rebook for next week, the knot still there."},{"text":"Keep it. You can decide about more sessions afterwards","then":"You put the phone down. Your heart's racing, but the slot is still yours.","best":true},{"text":"Move it to next month, when you'll be calmer","then":"The date feels far off. The reason you booked stays with you all month."},{"text":"Ask the centre to email you some tips instead","then":"A PDF arrives. It's sensible, but in the end you book a session again."}],"why":"Nerves before a first session are normal, not a stop sign. Going once is how you find out."},{"prompt":"Your roommate Sneha notices you're jittery and asks what's up. What do you say?","options":[{"text":"Say it's nothing, just too much coffee","then":"She laughs and heads out. The jitters stay with you."},{"text":"Say you've got a doctor's visit for a cold","then":"\"Feel better,\" she says. You feel oddly alone with the truth."},{"text":"Tell her about the session, and that you're nervous","then":"\"I went last year,\" Sneha says. \"It's less scary than it sounds.\"","best":true},{"text":"Ask if she thinks counselling is for weak people","then":"She frowns. \"No? Why would you think that?\""}],"why":"Sharing your nerves with someone you trust shrinks them, and often brings reassurance."},{"prompt":"When the day of your session comes, you sit in the waiting room, hands shaking. What do you do?","options":[{"text":"Leave before your name is called","then":"Outside, relief turns to 'why did I do that?' You rebook, and go the next week."},{"text":"Stay, but plan to say you're basically fine","then":"The session is short and polite. You leave with nothing changed."},{"text":"Ask a friend to call with a fake emergency","then":"Your phone rings ten minutes in, and you almost take the exit."},{"text":"Stay, and slow your breathing while you wait","then":"Your hands steady a little. The counsellor calls your name and smiles.","best":true}],"why":"Slow breaths steady the nerves, and staying lets you find out what the session can offer."},{"prompt":"A few days later, you're deciding whether to book another session. What do you do?","options":[{"text":"Stop. It should have helped by now","then":"A week later, the same worries are back, and so is the question."},{"text":"Book one more, and decide as you go","then":"The next session feels easier. You start to see what you want to work on.","best":true},{"text":"Book every week for a year, to be safe","then":"The commitment feels huge, and you start dreading every slot."},{"text":"Wait till you feel much worse before going back","then":"You wait, and the weeks get harder before you return."}],"why":"Going once, then deciding step by step, keeps support in your hands."}],"debrief":"Nerves before a first session are normal. Show up once to start.","relearn":"Pre-session nerves are normal; go once, then decide about continuing."},
  {"id":"mb-1181","cat":"reach-out","type":"branch","persona":"Rohan","source":"no record","hook":"You've been struggling, but you're sure seeing a counsellor will end up on some record.","steps":[{"prompt":"Internship applications open this week, and the worry comes back. What do you do?","options":[{"text":"Avoid all help to keep your record clean","then":"You push the feeling down. It follows you into every interview prep."},{"text":"Wait until placements are over to get help","then":"Placements stretch over months, and so does the struggle."},{"text":"Book a session and ask how privacy works there","then":"The counsellor explains sessions are confidential and never go to employers.","best":true},{"text":"Ask a senior if anyone's career was hurt by it","then":"He says he's 'heard stories', and your worry doubles."}],"why":"Asking how privacy works gets you the facts, and the help, instead of guessing."},{"prompt":"Your friend Aman jokes that anyone who sees a counsellor 'must be mental.' What do you do?","options":[{"text":"Laugh along so no one suspects you","then":"The laugh feels hollow, and help feels further away."},{"text":"Say looking after your mind is normal, like seeing a doctor","then":"Aman pauses. \"Fair. My cousin goes, actually.\"","best":true},{"text":"Go quiet and drop the idea of help","then":"The joke echoes in your head all evening."},{"text":"Snap at him and walk off","then":"Aman looks stunned. \"Chill, bro. It was a joke.\""}],"why":"Treating mental health like any other health chips away at stigma, for you and your friends."},{"prompt":"Late one night, the struggle feels heavier than usual. What do you do?","options":[{"text":"Tough it out alone. Needing help is weak","then":"You lie awake, alone with it, till the sky goes grey."},{"text":"Tell yourself it'll pass by morning","then":"The night drags on. The heaviness is still there in the morning."},{"text":"Call Tele-MANAS 14416. It's confidential","then":"A calm voice listens, and you feel steadier by the end of the call.","best":true},{"text":"Search online for ways to fix it quietly","then":"You find a hundred tips, and nobody to actually talk to."}],"why":"Private support like Tele-MANAS 14416 helps you now, without costing your future anything."}],"debrief":"Looking after your mind is private, not a mark against you.","relearn":"Getting support is confidential and responsible; it won't follow you around."},
  {"id":"mb-1182","cat":"reach-out","type":"branch","persona":"any","source":"safe to ask","hook":"Your friend Zara has seemed low for weeks. You worry asking directly might make it worse.","steps":[{"prompt":"You're walking back from class together. What do you do?","options":[{"text":"Keep things light and steer clear of it","then":"You talk about the canteen menu. She smiles, but it doesn't reach her eyes."},{"text":"Mention your own bad week, hoping she opens up","then":"She says, \"That sucks,\" and asks nothing more. Her own week stays hidden."},{"text":"Ask her gently how she's really been doing","then":"Zara slows down. \"Honestly? Not great. I didn't think anyone noticed.\"","best":true},{"text":"Tell her she seems depressed and needs therapy","then":"She stiffens. \"I'm not depressed. I'm just tired.\""}],"why":"Asking gently and directly doesn't plant distress. It gives her room to be honest."},{"prompt":"Later, Zara says, 'Sometimes I just feel empty.' What do you do?","options":[{"text":"Tell her to think positive, and it'll pass","then":"\"Right,\" she says, and goes quiet again."},{"text":"Change the subject so you don't make it worse","then":"She follows your lead, and the moment slips away for now."},{"text":"Listen, and ask what it's been like for her","then":"She talks for a long time while you mostly nod. She seems lighter by the end.","best":true},{"text":"Tell her exactly what she should do about it","then":"She nods at every point, then says, \"I'm too tired for all that.\""}],"why":"Listening and asking a caring follow-up helps her feel heard, and shows you how she's really doing."},{"prompt":"A few days later, Zara tells you the emptiness has been there most days for a month. What do you do?","options":[{"text":"Promise you'll be all the support she needs","then":"She leans on you every night, and you both start to run on empty."},{"text":"Say everyone feels empty sometimes","then":"\"Maybe,\" she says, and doesn't bring it up again."},{"text":"Give her space to sort it out herself","then":"She nods. Days pass without either of you mentioning it."},{"text":"Say you're glad she told you, and offer to help find support","then":"She hesitates, then asks you to sit with her while she calls Tele-MANAS 14416.","best":true}],"why":"A month of this deserves real support. Offering to help her reach it is caring, not pushy."}],"debrief":"Caring, direct questions don't make things worse. They let a friend tell the truth.","relearn":"Asking a friend directly how they are doesn't make it worse; it helps them open up."},
  {"id":"mb-1183","cat":"reach-out","type":"branch","persona":"any","source":"not later","hook":"For two months you've said you'll get support 'once things calm down'. They haven't.","steps":[{"prompt":"It's Monday, and this week looks even busier than the last. What do you do?","options":[{"text":"Wait for the semester break, when there's time","then":"The break is six weeks away. The weeks in between feel long."},{"text":"Download a meditation app to handle it yourself","then":"You try it twice, then its reminders pile up with everything else."},{"text":"Book a counselling slot this week, busy or not","then":"The only slot is Thursday at 8 a.m. You take it.","best":true},{"text":"Work late every night to clear the backlog first","then":"The backlog shrinks a little, and you feel more worn out."}],"why":"Support is built for the messy middle. Waiting for calm often means waiting forever."},{"prompt":"Midweek, a new deadline lands and the day is packed. What do you do?","options":[{"text":"Put everything personal on hold till it's submitted","then":"The deadline passes. Another one arrives right behind it."},{"text":"Tell yourself you'll sort your head out on Sunday","then":"Sunday comes and goes in laundry and catching up."},{"text":"Promise yourself a full day off once it's done","then":"You submit, then spend the day off too drained to enjoy it."},{"text":"Take ten minutes between classes to call Tele-MANAS 14416","then":"Ten minutes of being heard, and you walk into class steadier.","best":true}],"why":"Even ten minutes of support in a busy week helps. It doesn't have to wait for a clear day."},{"prompt":"Your friend Mihir says, 'I'll get help when things settle.' What do you say?","options":[{"text":"Agree. That's your plan too","then":"You both nod, and neither of you books anything."},{"text":"Say nothing. It's his call","then":"He moves on, and so does the conversation."},{"text":"Say help counts most in the messy middle","then":"Mihir laughs a little. \"Okay, fair. Maybe I'll book something.\"","best":true},{"text":"Tell him he's just being lazy about it","then":"He bristles. \"I'm not lazy. I'm swamped.\""}],"why":"Saying help fits the messy middle can nudge a friend, and reminds you too."}],"debrief":"You don't have to wait for calm to reach out. The messy middle is when it helps.","relearn":"Don't wait for things to calm down; reach out in the messy middle."},
  {"id":"mb-1184","cat":"reach-out","type":"branch","persona":"Deepak","source":"homesick adult","hook":"Eight hundred kilometres from home, you're homesick, and embarrassed about it at twenty.","steps":[{"prompt":"Your mother calls and asks if you're settling in. What do you say?","options":[{"text":"Say everything's great, so she doesn't worry","then":"She sounds relieved. You hang up and feel the distance more."},{"text":"Tell her you miss home, and it's been hard","then":"She goes quiet, then says, \"We miss you too. It's allowed, beta.\"","best":true},{"text":"Say you're too busy to talk right now","then":"She says okay, a little hurt. You stare at the phone afterwards."},{"text":"Complain about the hostel food instead","then":"She laughs and promises to send pickle. The real thing stays unsaid."}],"why":"Naming homesickness to someone who cares lets the feeling be shared instead of hidden."},{"prompt":"That evening, a hostel-mate, Suresh, asks why you're sitting alone. What do you say?","options":[{"text":"Say you're just tired and want some quiet","then":"He nods and leaves. The corridor goes quiet again."},{"text":"Laugh it off. Homesick at twenty is embarrassing","then":"He laughs too, and the chance to talk passes."},{"text":"Say you don't really fit in here","then":"\"Why not?\" he asks, surprised, but you shrug it off."},{"text":"Say you're a bit homesick, and ask if he ever is","then":"Suresh sits down. \"Every Sunday. I call my nani and nearly cry.\"","best":true}],"why":"Saying it out loud often shows others feel the same. Homesickness has no age limit."},{"prompt":"The weekend stretches out empty, and home feels very far. What do you do?","options":[{"text":"Borrow money for a ticket home this weekend","then":"The trip is lovely and short. Monday comes with a debt and the same ache."},{"text":"Spend the weekend on video calls with home","then":"The calls are sweet, but each one ends and the room feels emptier."},{"text":"Join the hostel group going to the Sunday market","then":"The market is loud and cheap, and someone teaches you to bargain.","best":true},{"text":"Study all weekend to keep your mind off it","then":"The hours pass, and the ache sits quietly under every page."}],"why":"Small plans with people nearby ease homesickness, and slowly build a home here too."},{"prompt":"A month on, you still miss home some nights. What do you tell yourself?","options":[{"text":"I should be over this by now","then":"The pressure to be over it makes the ache sharper."},{"text":"I'm clearly not cut out for living away","then":"Doubt creeps into your plans for next year."},{"text":"I'll keep it to myself from now on","then":"The feeling goes quiet, but it doesn't go away."},{"text":"Missing home is normal. I can keep reaching out","then":"The ache still comes some nights, but it feels lighter to carry.","best":true}],"why":"Homesickness can come and go for a while. It's a normal reaction to change, not weakness."}],"debrief":"Homesickness isn't childish. Saying it out loud is a real, grown-up move.","relearn":"Homesickness has no age limit; tell someone you trust rather than hiding it."},
  {"id":"mb-1185","cat":"reach-out","type":"branch","persona":"any","source":"try again","hook":"You told Varun you were struggling. He said, 'Everyone's stressed,' and moved on.","steps":[{"prompt":"Back in your room, you feel stupid for trying. What do you do?","options":[{"text":"Decide reaching out was a mistake","then":"You close up. The struggle goes back in its box."},{"text":"Send Varun a long message explaining it again","then":"Hours later he replies 'ok, take care'. It stings all over again."},{"text":"Tell yourself he's right, and you're overreacting","then":"You swallow it, and the heaviness settles back in."},{"text":"Try someone else, or call Tele-MANAS 14416","then":"You call Tele-MANAS 14416. The listener doesn't rush you, and you feel heard.","best":true}],"why":"One cold reply isn't everyone. Another person, or Tele-MANAS 14416, can listen properly."},{"prompt":"A few days later, Varun says, 'Sorry I was weird the other day.' What do you do?","options":[{"text":"Say it's fine. It wasn't a big deal anyway","then":"He looks relieved, and the real conversation never happens."},{"text":"Tell him he really let you down, and walk off","then":"He looks stung, and avoids you for a few days."},{"text":"Accept it, and say you'd still like to talk","then":"Varun nods. \"Yeah. I didn't know what to say. Chai later?\"","best":true},{"text":"Accept it, but keep the hard stuff to yourself now","then":"Things stay friendly, but a quiet wall goes up between you."}],"why":"Giving him an honest second chance lets a friendship learn to hold hard things."},{"prompt":"Your inner voice says people don't want to hear it. What do you tell yourself?","options":[{"text":"It's true. I'll stop bothering people","then":"The quiet sets in, and so does the loneliness."},{"text":"One person handled it badly. That isn't everyone","then":"The voice loses some of its grip, and you reach out again that week.","best":true},{"text":"Maybe I said it wrong. I'll find better words first","then":"You keep drafting what to say, and the words never feel ready."},{"text":"I'll wait until someone asks me first","then":"Days pass. Nobody asks, and you say nothing."}],"why":"Seeing one bad response for what it is keeps you open to the people who will listen."}],"debrief":"One unhelpful response isn't a verdict. The right listener is out there.","relearn":"If one person brushes you off, try another or Tele-MANAS 14416."},
  {"id":"mb-1186","cat":"reach-out","type":"branch","persona":"Mehta","source":"reading the signals","hook":"For over a month your sleep, appetite and focus have slipped, and you keep calling it a phase.","steps":[{"prompt":"You miss a second assignment deadline this month. What do you do?","options":[{"text":"Call it a phase and wait for it to pass","then":"The weeks roll on, and so does the fog."},{"text":"Search your symptoms online late at night","then":"Forty tabs later you're more scared, and no closer to help."},{"text":"Blame yourself for being lazy lately","then":"The guilt piles on top of the tiredness."},{"text":"Book a chat with Dr. Mehta this week","then":"Dr. Mehta has a Friday slot. Booking it feels like setting something down.","best":true}],"why":"Weeks of changed sleep, appetite and focus are a signal. A counsellor can help you read it."},{"prompt":"Your roommate Ruchi says you've seemed far away for weeks. What do you say?","options":[{"text":"Say it's just exams and deadlines, nothing more","then":"\"Exams ended two weeks ago,\" she says gently. You shrug."},{"text":"Admit you've felt off for weeks, and aren't sure why","then":"Ruchi nods. \"I noticed. Want me to come along if you see someone?\"","best":true},{"text":"Say you're fine and change the topic","then":"She lets it go, but keeps glancing over."},{"text":"Snap that you're allowed to have off days","then":"She raises her hands. \"Okay, okay.\" The room goes quiet."}],"why":"Being honest with someone close gives them a chance to support you."},{"prompt":"On a call, your mother says it's just stress and you should sleep more. What do you say?","options":[{"text":"Agree it's probably just stress","then":"She sounds relieved. You hang up, still foggy."},{"text":"Say you'll sort it out by yourself","then":"\"Good,\" she says. The call ends, and you feel more alone."},{"text":"Say it's lasted over a month, so you want proper help","then":"She pauses. \"A month? Okay. Tell me what they say.\"","best":true},{"text":"Tell her she never understands anything","then":"She goes quiet, hurt, and the call ends badly."}],"why":"Naming how long it's lasted shows it's a signal, not a mood, and helps others take it seriously."},{"prompt":"Your friend Anil says he's had the same slump for weeks, but it's 'just a phase.' What do you say?","options":[{"text":"Agree. Everyone gets slumps","then":"He nods. You both carry on as before."},{"text":"Tell him to sleep more and it'll fix itself","then":"\"I try,\" he says. \"That's kind of the problem.\""},{"text":"Say weeks of changes are worth taking to someone","then":"Anil frowns, thinking. \"Maybe I should see someone too.\"","best":true},{"text":"Tell him he's clearly depressed","then":"He stiffens. \"Whoa. You're not a doctor.\""}],"why":"Weeks of change in sleep, appetite and focus deserve real support, for anyone."}],"debrief":"A cluster of changes lasting weeks is worth taking to real support.","relearn":"Weeks of changed sleep, appetite and focus is a signal to reach for support."},
  {"id":"mb-1187","cat":"reach-out","type":"branch","persona":"any","source":"any door","hook":"You've decided to reach out, but can't choose between a friend, a counsellor or a helpline.","steps":[{"prompt":"You've spent three evenings reading about each option. What do you do tonight?","options":[{"text":"Keep researching till you're sure which is correct","then":"A fourth evening goes by in tabs and doubts."},{"text":"Pick whichever feels easiest today, and start","then":"You message your friend Neha. She replies in minutes: \"Call me?\"","best":true},{"text":"Make a detailed pros and cons list for each","then":"The list is neat. You still haven't told anyone."},{"text":"Wait till you're sure it's serious enough","then":"The evening passes. The heaviness stays, and still no one knows."}],"why":"There's no wrong door to support. The best first step is the one you'll actually take."},{"prompt":"The next day, a doubt creeps back that some doors to support are 'wrong' ones. What do you do?","options":[{"text":"Go back to researching which one is right for you","then":"More tabs, more doubts, and the day slips away."},{"text":"Give up. Getting this right is too hard","then":"Your plan to reach out goes quiet again."},{"text":"Ask five friends which door they would pick","then":"Five friends give five answers. You're more confused than before."},{"text":"Remind yourself any door is fine, and take a step","then":"The worry eases, and you take a small step forward.","best":true}],"why":"Doors connect. A friend, a counsellor and a helpline can each point you to the others."},{"prompt":"Later, your friend Tanya says she wants support but doesn't know where to begin. What do you say?","options":[{"text":"Say she should research all of them first","then":"She sighs. \"That sounds like a lot of work.\""},{"text":"Say any door works: a friend, counsellor or Tele-MANAS 14416","then":"Tanya smiles. \"Okay. I'll try Tele-MANAS tonight.\"","best":true},{"text":"Say counsellors are the only real help","then":"\"The waiting list is three weeks,\" she says, deflating."},{"text":"Say she should wait till she's sure she needs it","then":"\"Right,\" she says, and the idea fades."}],"why":"Sharing that any door works makes starting easier for a friend too."}],"debrief":"There's no wrong door to support. The best one is the one you'll use.","relearn":"Any door, friend, counsellor or helpline, is a good first step."},
  {"id":"mb-1188","cat":"reach-out","type":"branch","persona":"any","source":"crisis door","hook":"On a late call, Kunal says he's had thoughts of ending things, and begs you to tell no one.","steps":[{"prompt":"He goes quiet on the line. What do you do first?","options":[{"text":"Promise total secrecy so he keeps talking","then":"He relaxes a little. You're now holding something very heavy, alone."},{"text":"Tell him not to talk like that","then":"\"Forget it,\" he says. \"I shouldn't have said anything.\""},{"text":"Stay on the line and say you're glad he told you","then":"He breathes out. \"I didn't think anyone would get it.\"","best":true},{"text":"Hang up to find someone who knows what to do","then":"Your heart races. You call back, and it rings and rings before he answers."}],"why":"Staying with him and thanking him for telling you keeps him connected when it matters most."},{"prompt":"Kunal asks you, again, to swear you won't tell anyone. What do you say?","options":[{"text":"Agree, and plan to handle it alone","then":"He thanks you. You stay on the line, scared for him and alone with it."},{"text":"Say you care too much to keep it, and you'll get help together","then":"He's silent, then says, \"Okay. But stay on the phone.\"","best":true},{"text":"Agree, then quietly post in a group asking what to do","then":"Replies pile up, and you realise how exposed he'd feel."},{"text":"Tell him you're calling his parents right now","then":"\"Don't!\" he says, panicking, and you have to calm him down."}],"why":"Some things are too heavy to keep secret. Honesty, while staying with him, keeps him safe."},{"prompt":"It's 1 a.m. and he's still on the line. What do you do now?","options":[{"text":"Keep him talking till he sounds better, then sleep","then":"He sounds calmer by 3 a.m., but nothing has changed for tomorrow."},{"text":"Tell him to get some sleep and talk tomorrow","then":"He says okay. You lie awake, unsure if he's safe."},{"text":"Keep texting him while he calls Tele-MANAS 14416","then":"He calls. Afterwards he texts, \"They listened. I'm seeing someone tomorrow.\"","best":true},{"text":"Send him a list of helpline numbers and hang up","then":"He sends a thumbs up. You stare at the ceiling, wondering if he'll call."}],"why":"Tele-MANAS 14416 is free, any hour and trained for this. Staying connected while he calls helps."},{"prompt":"Next day, Kunal says he's okay now and wants to move on. What do you do?","options":[{"text":"Drop it. He said he's okay","then":"The days go by. You never quite know how he is."},{"text":"Tell your friend group so they can watch him","then":"He finds out, feels betrayed, and stops answering you."},{"text":"Keep asking every hour if he's safe","then":"He mutes your chat by evening."},{"text":"Check in, and help him tell a trusted adult or counsellor","then":"He hesitates, then agrees to tell his elder sister, with you there.","best":true}],"why":"One better day isn't the end. Linking him to ongoing support keeps help around him."}],"debrief":"Having those thoughts isn't Kunal's fault or a failing. A friend in crisis needs you present and connected to help.","relearn":"If a friend mentions ending things, stay and reach Tele-MANAS 14416 or an adult."},
  {"id":"mb-1189","cat":"reach-out","type":"branch","persona":"any","source":"helper's limit","hook":"For months you've been the one Pooja calls every night, and you're running on empty.","steps":[{"prompt":"She calls again at midnight, and you have an exam at nine. What do you do?","options":[{"text":"Stay up all night on the call, like always","then":"You sit the exam on no sleep, and blank on the second question."},{"text":"Let it ring and hope she falls asleep","then":"A text arrives: \"You okay?\" You feel worse than if you'd answered."},{"text":"Talk for a bit, then say you need sleep and will call tomorrow","then":"\"Oh. Right, your exam,\" she says. \"Talk tomorrow?\"","best":true},{"text":"Tell her you can't keep being her therapist anymore","then":"The line goes silent. Then she says, \"Sorry for being a burden,\" and hangs up."}],"why":"A kind limit lets you keep showing up for her without burning out."},{"prompt":"You notice you're dreading your phone and snapping at others. What do you do?","options":[{"text":"Push through. She needs you more","then":"The dread grows, and so does the snapping."},{"text":"Vent about Pooja to your other friends to let it out","then":"It feels good for an hour, then you feel you've betrayed her."},{"text":"Talk to a counsellor about how it's affecting you","then":"The counsellor helps you see you can care without carrying it all.","best":true},{"text":"Quietly start avoiding her calls","then":"Pooja notices, and her messages turn anxious."}],"why":"Helpers need support too. Talking it through keeps you steady, for her and for yourself."},{"prompt":"Pooja says you're the only one she can talk to. What do you say?","options":[{"text":"Promise to always be there, any time","then":"She relaxes. The weight on you settles even heavier."},{"text":"Say you can't handle this anymore","then":"She goes very quiet, and you both feel awful."},{"text":"Tell her to find someone else to talk to","then":"\"Right. Got it,\" she says, and hangs up."},{"text":"Say you'll stay, and she deserves more people too","then":"She's quiet, then asks, \"Like who?\" You think about it together.","best":true}],"why":"Staying while widening her circle helps her more than you ever could alone."},{"prompt":"A week later, Pooja is still low. What do you suggest?","options":[{"text":"That she tries harder to stay positive","then":"\"I've tried,\" she says, and her voice cracks."},{"text":"That she waits it out a bit longer","then":"The weeks go on, heavy for both of you."},{"text":"That you take on more, since nothing's working","then":"You cancel your own plans again, and your tank drains further."},{"text":"That she calls Tele-MANAS 14416, with you there","then":"She agrees, if you sit with her. You do, and she talks for an hour.","best":true}],"why":"Sharing the load with real support means neither of you carries it alone."}],"debrief":"Supporting someone doesn't mean carrying them alone. Mind yourself too.","relearn":"When supporting a friend, get your own support and share the load; don't run dry."},
  {"id":"mb-1190","cat":"reach-out","type":"branch","persona":"any","source":"hit send","hook":"You've typed 'I'm really not okay' to your friend Ria, and your thumb hovers over delete.","steps":[{"prompt":"It's 11 p.m. and the message is still sitting there. What do you do?","options":[{"text":"Delete it and send 'haha all good' instead","then":"Ria sends a laughing emoji. You put the phone face down."},{"text":"Soften it to 'bit of a weird week lol'","then":"\"Same lol,\" Ria replies, and the chat moves on to memes."},{"text":"Send it as it is","then":"The ticks turn blue. A minute later: \"Calling you now.\"","best":true},{"text":"Save it to send some other time","then":"You save the draft. It sits there all night, heavier each time you look."}],"why":"The hover is the hardest part. An honest message is what lets a friend actually show up."},{"prompt":"The next day, Ria calls. Partway through, she asks how you really are. What do you say?","options":[{"text":"Say you're fine, just tired","then":"\"Okay,\" she says, not quite convinced, and the call moves on."},{"text":"Tell her a little, then say it's nothing","then":"She starts to ask more, but you've already changed the topic."},{"text":"Tell her it's been a hard few weeks, and why","then":"Ria listens, then says, \"I'm glad you told me. I've had weeks like that.\"","best":true},{"text":"Apologise for being dramatic","then":"\"You're not being dramatic,\" she says. \"What's going on?\""}],"why":"Saying it plainly lets her care for the real you, not a brave face."},{"prompt":"Later that week, the fear of 'bothering people' creeps back. What do you tell yourself?","options":[{"text":"I've used up my one chance to share","then":"You go quiet again, and the week gets heavier."},{"text":"I'll only reach out if it gets really bad","then":"You wait, and it gets worse before you speak up."},{"text":"People who care would rather know","then":"The fear shrinks, and the next message is easier to send.","best":true},{"text":"I'll post a sad song and see if anyone asks","then":"Two people like it. Nobody asks."}],"why":"The dread before reaching out is bigger than what follows. It gets easier each time."}],"debrief":"The fear before sending is bigger than what comes after.","relearn":"Send the honest 'I'm not okay'; the dread is worse than what actually follows."},
  {"id":"mb-1191","cat":"reach-out","type":"branch","persona":"Zoya","source":"support beyond home","hook":"College feels like yours, but at home, talking about feelings gets shut down fast.","steps":[{"prompt":"The semester break at home is two weeks away, and you're already dreading it. What do you do?","options":[{"text":"Decide that if home won't help, no help is possible","then":"You stop thinking about other help, and the dread grows."},{"text":"Plan to finally make your family talk about feelings","then":"You rehearse a big speech, and the dread doubles."},{"text":"Line up support: a friend to text, and Tele-MANAS 14416","then":"Your friend Mariam says, \"Text me any time. Even at 2 a.m.\"","best":true},{"text":"Plan to get through it alone, and tell no one","then":"You go quiet with friends, and the break looms larger each day."}],"why":"Home isn't the only place support can come from. Building it elsewhere keeps you steady."},{"prompt":"At dinner at home, your father says, 'All this stress talk is nonsense. Just focus on studies.' What do you do?","options":[{"text":"Argue until he understands","then":"Voices rise, and dinner ends in silence."},{"text":"Agree, and decide your feelings don't matter","then":"You swallow it, and the heaviness grows."},{"text":"Tell him he's the reason you're stressed","then":"His face hardens, and the house stays tense for days."},{"text":"Let it go for now, and step out to call a friend","then":"The evening air helps. A college friend makes you laugh, and you feel less alone.","best":true}],"why":"Stepping away to reach your own support protects you, without a fight you can't win tonight."},{"prompt":"Back at college, you're still carrying the weight of the break. What do you do?","options":[{"text":"Tell yourself that's just how family is, and move on","then":"It settles in quietly and colours the first weeks of term."},{"text":"Keep it to yourself till the next break","then":"The weight stays, and the next break already looms."},{"text":"Book a session with the campus counsellor","then":"The counsellor helps you plan how to get through the next trip home.","best":true},{"text":"Call home to have it out with them","then":"The call ends in tears on both sides."}],"why":"A counsellor can help you handle home without cutting yourself off from it."}],"debrief":"If home can't hold these talks, build support elsewhere.","relearn":"If home shuts feelings down, build support outside it."},
  {"id":"mb-1192","cat":"reach-out","type":"branch","persona":"any","source":"small is welcome","hook":"A breakup has left you low all week, but it feels too small to take a helpline's time.","steps":[{"prompt":"You've got Tele-MANAS 14416 up on your phone. What do you do?","options":[{"text":"Close it. It's too minor to call about","then":"You put the phone away. The week drags on."},{"text":"Press call. It's there for exactly this","then":"The listener says, \"Breakups hurt. Tell me about it,\" and you do.","best":true},{"text":"Wait till it feels like a real crisis","then":"Days pass, and the low feeling keeps hurting without a crisis."},{"text":"Post a sad status and hope someone notices","then":"A few people react with hearts. Nobody asks how you are."}],"why":"No problem is too small for Tele-MANAS 14416. A heavy week is reason enough."},{"prompt":"Your friend Irfan says, 'Helplines are for serious stuff, not breakups.' What do you say?","options":[{"text":"Agree, and feel silly for even thinking of it","then":"The embarrassment sticks, and the phone stays in your pocket."},{"text":"Say nothing and change the subject","then":"His words stay with you the rest of the day."},{"text":"Tell him he's heartless","then":"\"Whoa, relax,\" he says, and the talk goes cold."},{"text":"Say they're for everyday hurts too","then":"Irfan shrugs. \"Didn't know that. Might be useful someday.\"","best":true}],"why":"Knowing helplines cover everyday hurts makes them easier to use, and to share with friends."},{"prompt":"Another heavy night comes, and the 'too small to call' voice starts up again. What do you do?","options":[{"text":"Wait till you've had a whole week of these","then":"The nights stack up, each one a little harder."},{"text":"Tell yourself others need the line more","then":"You lie awake, sure your pain is taking up space."},{"text":"Call Tele-MANAS 14416. Heavy nights count","then":"The call is short, and you sleep better than you have in days.","best":true},{"text":"Text your ex to feel better","then":"The reply is one word, and the night gets longer."}],"why":"You can reach out whenever it's heavy. Helplines don't ration who deserves them."}],"debrief":"Helplines are for ordinary heavy days, not only emergencies.","relearn":"No problem is too small for Tele-MANAS 14416; you needn't be in crisis to call."},
  {"id":"mb-1193","cat":"reach-out","type":"branch","persona":"any","source":"just listen","hook":"Nisha told you last night she's been struggling. Now you're scared of saying the wrong thing.","steps":[{"prompt":"She messages, asking to get chai later. What do you do?","options":[{"text":"Say you're busy, so you can't say it wrong","then":"\"Oh, okay,\" she replies. You feel relief, then a pang."},{"text":"Say yes, then read up for hours on what to say","then":"By five, your head is full of lines and your nerves are worse."},{"text":"Suggest she talks to a counsellor instead","then":"\"Right. Sure,\" she replies, and doesn't suggest another time."},{"text":"Say yes, even without knowing what to say","then":"She sends a smiley. \"See you at five.\"","best":true}],"why":"Showing up matters more than perfect words. Avoiding her would leave her alone with it."},{"prompt":"When you do meet for chai, Nisha goes quiet mid-sentence. What do you do?","options":[{"text":"Fill the silence with advice","then":"She nods politely, and doesn't finish what she was saying."},{"text":"Wait, and let the quiet be okay","then":"After a moment, she carries on. \"Sorry. It's just hard to say.\"","best":true},{"text":"Change the topic to lighten things","then":"She follows your lead, relieved and a little lonelier."},{"text":"Tell her about your own worst week","then":"She listens to you instead, and her story stays half-told."}],"why":"Letting silence sit gives her room to keep going at her own pace."},{"prompt":"Nisha says, 'I don't even know why I feel like this.' What do you say?","options":[{"text":"Ask her to list every possible cause","then":"She tries, gets muddled, and gives up."},{"text":"Say she'll feel better soon, for sure","then":"\"You can't know that,\" she says quietly."},{"text":"Say she doesn't need a reason, and you're here","then":"Her eyes fill. \"Thank you. That helps more than you know.\"","best":true},{"text":"Say maybe you're not the right person for this","then":"\"Oh,\" she says. \"Sorry. I'll stop.\""}],"why":"You don't need answers. Staying and accepting her feelings is the support."},{"prompt":"A few days later, Nisha still seems low. What do you do?","options":[{"text":"Leave it. You probably said the wrong things","then":"The gap between you grows, though she'd wanted you around."},{"text":"Tell her she should feel better by now","then":"She pulls back, and stops sharing with you."},{"text":"Keep checking in, and offer help finding support","then":"She asks you to come with her to the counselling centre.","best":true},{"text":"Promise you'll be her only support from now on","then":"She leans on you hard, and you both start to wear thin."}],"why":"Staying present over time, and offering a path to more support, is how you help."}],"debrief":"You don't need the right words to support someone. Listening and staying is enough.","relearn":"You don't need perfect words to help a friend; just listen and stay."},
  {"id":"mb-1194","cat":"reach-out","type":"role-play","persona":"any","source":"asking a senior","hook":"You want to ask Rehana, a senior you trust, how to reach a counsellor.","setup":"She's at the gate, waiting for an auto.","steps":[{"prompt":"Rehana asks: \"Hey, all good? You look like you want to say something.\"","options":[{"text":"\"Just that things are a bit much lately, you know?\"","then":"\"Totally,\" she says. \"Final year's a lot too.\" Her auto pulls up."},{"text":"\"Nothing. Just wanted to say hi, didi.\"","then":"\"Okay, see you!\" she says, and gets into the auto."},{"text":"\"I've had a rough time. How do I reach a counsellor here?\"","then":"She nods. \"The centre's in the library block. I'll show you.\"","best":true},{"text":"\"Asking for a friend: how would someone see a counsellor?\"","then":"\"Tell your friend it's in the library block,\" she says, a little curious."}],"why":"A simple, direct ask gets you to help faster than hoping someone guesses."},{"prompt":"The next day, Rehana texts: \"You seemed off yesterday. All okay?\"","options":[{"text":"\"All fine! Don't worry about me.\"","then":"\"Okay! Shout if you need anything,\" she replies."},{"text":"\"Just stressed. I'll figure it out myself.\"","then":"\"You don't have to,\" she replies. \"Offer stands.\""},{"text":"\"Not really. Could you walk me to the centre?\"","then":"\"Of course. I'm free at four,\" she replies. \"Meet me at the gate.\"","best":true},{"text":"\"Sort of. Did you ever need help like that?\"","then":"\"Yeah, in second year,\" she replies. \"It helped. Why?\""}],"why":"Asking for one specific bit of help makes it easy for someone to say yes."},{"prompt":"Later that week at the centre, the receptionist asks: \"How can we help?\"","options":[{"text":"\"Um, just picking up a leaflet.\"","then":"She hands you one with a smile. It goes into your bag."},{"text":"\"I've been having a rough time. I'd like to see someone.\"","then":"\"Of course. We have a slot on Wednesday,\" she says, writing your name down.","best":true},{"text":"\"My senior sent me. I'm not sure why, really.\"","then":"\"That's okay,\" she says. \"Would you like to see someone anyway?\""},{"text":"\"Is there a waiting list? I can come back later.\"","then":"\"There's a slot tomorrow, actually,\" she says. \"Shall I book it?\""}],"why":"Saying plainly what you need gets you booked in, without waiting to be guessed."}],"relearn":"A simple, direct ask, 'how do I reach a counsellor here?', gets you to help faster."},
  {"id":"mb-1195","cat":"reach-out","type":"role-play","persona":"any","source":"taking it seriously","hook":"On a bench outside the library, Arjun says quietly that everyone would be better off without him.","setup":"It's late, and the two of you are alone.","steps":[{"prompt":"Arjun says: \"I mean it. I'd just be one less problem.\"","options":[{"text":"\"Don't talk like that. You'll be fine.\"","then":"\"Yeah. Sure,\" he says, and his face shuts."},{"text":"\"Come on, think how your parents would feel.\"","then":"He winces. \"That just makes me feel worse.\""},{"text":"\"I'm really glad you told me. I'm staying right here.\"","then":"He looks at you, then away. \"I didn't think anyone would get it.\"","best":true},{"text":"\"You're just tired. Sleep on it.\"","then":"\"Maybe,\" he says flatly, not looking up."}],"why":"Taking him seriously, and staying close, tells him he isn't alone with this."},{"prompt":"Arjun says: \"Please don't make a big deal of this.\"","options":[{"text":"\"Okay. It stays between us, I promise. No one else.\"","then":"He nods, relieved. You're left holding it alone."},{"text":"\"You matter, so it is a big deal. I'm not going anywhere.\"","then":"His eyes fill. \"Okay. Just don't leave.\"","best":true},{"text":"\"I'm going to call your family right now, okay?\"","then":"\"No! Please don't,\" he says, and turns away from you."},{"text":"\"Fine, but promise me you won't do anything.\"","then":"\"I can't promise that,\" he says, looking at the ground."}],"why":"Staying with him and treating it seriously protects him better than any promise or secret."},{"prompt":"Arjun says: \"I don't know what anyone could even do.\"","options":[{"text":"\"I'll just stay up talking with you all night.\"","then":"You talk till dawn. He's calmer, but it's still just the two of you."},{"text":"\"Let's sleep on it and find someone tomorrow.\"","then":"He says okay. Back in your own room, you lie awake, worried."},{"text":"\"Let's call Tele-MANAS 14416 together. Right now.\"","then":"He hesitates, then nods. You dial on speaker and sit close.","best":true},{"text":"\"Let me search online for what to do first.\"","then":"You scroll while he stares at the ground, the silence stretching."}],"why":"Tele-MANAS 14416 is free, open any hour and trained for this. Calling together keeps him close."},{"prompt":"Later, Arjun says: \"I feel stupid for saying all that.\"","options":[{"text":"\"Let's just forget it ever happened.\"","then":"\"Yeah,\" he says, relieved, and the door starts to close."},{"text":"\"You did scare me, honestly.\"","then":"\"Sorry,\" he says, and shrinks further into himself."},{"text":"\"It's fine. Everyone says stuff like that sometimes.\"","then":"\"Do they?\" he asks, unsure if you took it seriously."},{"text":"\"You're not stupid. I'm glad you said it.\"","then":"He manages a small nod. \"Thanks for not freaking out.\"","best":true}],"why":"Saying you're glad he spoke keeps the door open for him to speak up again."},{"prompt":"The next day, Arjun says: \"I'm okay now. Honestly.\"","options":[{"text":"\"Great. Then we don't need to talk about it.\"","then":"He smiles, relieved. You're left wondering if he really is."},{"text":"\"Are you sure? Promise me you're really okay?\"","then":"\"I said I'm okay,\" he snaps, and looks away."},{"text":"\"Can we go to the campus counsellor together today?\"","then":"He sighs, then nods. \"Okay. But you're walking me there.\"","best":true},{"text":"\"Okay. I'll ask our friends to keep an eye on you.\"","then":"\"Please don't,\" he says, alarmed, and stops replying to you."}],"why":"One okay morning isn't the end. Linking him to ongoing support keeps him safe."}],"relearn":"If a friend says that, stay close and reach Tele-MANAS 14416 together. Don't brush it off."},
  {"id":"mb-1196","cat":"reach-out","type":"role-play","persona":"any","source":"reconnecting","hook":"You drifted from school friend Tanvi, and lately you've been struggling alone.","setup":"You open your old chat at midnight.","steps":[{"prompt":"Her last message, months old, says: \"We must catch up soon!\"","options":[{"text":"\"Hey stranger, long time! What's new with you these days?\"","then":"\"Heyyy! All good! You?\" she replies, and you type back \"same.\""},{"text":"\"Sorry I've been such a terrible friend this year.\"","then":"\"Haha no, we were both busy!\" she replies. The real thing stays unsaid."},{"text":"\"I know it's been ages. I've been struggling, and I miss you.\"","then":"Ten minutes later: \"Oh no. I'm so glad you texted. Call tomorrow?\"","best":true},{"text":"\"Saw a meme that reminded me of you, haha.\"","then":"She sends back three laughing faces. The chat goes quiet again."}],"why":"Being honest, even after a long gap, lets an old friend show up for the real you."},{"prompt":"The next day, Tanvi asks: \"So what's been going on with you?\"","options":[{"text":"\"Oh, nothing much. Just college stuff.\"","then":"\"Cool,\" she says, and starts on her news."},{"text":"\"Honestly, it's my fault for not making friends.\"","then":"\"That's not fair on yourself,\" she says. \"What's actually happened?\""},{"text":"\"College has been lonely, and I've felt low for weeks.\"","then":"\"I'm so sorry,\" she says. \"My first year was rough too. Tell me more.\"","best":true},{"text":"\"You first. I want to hear all about your year, honestly.\"","then":"She talks for an hour. You hang up with your own news untold."}],"why":"Naming what's hard gives her the chance to understand, and to help."},{"prompt":"As the call ends, Tanvi says: \"Let's not lose touch again.\"","options":[{"text":"\"Sure, we'll see how busy things get.\"","then":"\"Right,\" she says, and you both know how that usually goes."},{"text":"\"I'll try not to bother you too much.\"","then":"\"You're not a bother,\" she says, a little sad."},{"text":"\"Definitely. I'll text when things get bad.\"","then":"\"Or when things are good too,\" she says gently."},{"text":"\"Yes. Can we call every Sunday?\"","then":"\"Sunday it is,\" she says. \"I'll set a reminder.\"","best":true}],"why":"A small, regular plan keeps the door you reopened from closing again."}],"relearn":"It's never too awkward to reconnect; honesty reopens the door to support."},
  {"id":"mb-1197","cat":"reach-out","type":"role-play","persona":"any","source":"bring company","hook":"Your first counselling session is tomorrow, and you'd love your roommate Meenal to walk you there.","setup":"She's folding laundry on her bed.","steps":[{"prompt":"Meenal asks: \"You've been pacing for ten minutes. What's up?\"","options":[{"text":"\"Nothing much. Just a bit restless tonight, I think.\"","then":"\"Okay,\" she says, and goes back to her laundry."},{"text":"\"I'm nervous about my counselling session. Walk with me?\"","then":"She stops folding. \"Of course I'll come. What time?\"","best":true},{"text":"\"I've got an appointment tomorrow. It's nothing.\"","then":"\"Cool,\" she says. You keep pacing."},{"text":"\"Do you think it's weird to go to counselling?\"","then":"\"No? Why?\" she asks, and you change the subject."}],"why":"Saying what you need, plainly, gives her the chance to show up for you."},{"prompt":"The next morning, Meenal asks: \"You look pale. Everything okay?\"","options":[{"text":"\"I'm fine. Go ahead to class.\"","then":"\"Okay,\" she says, and heads off. You set out alone and shaky."},{"text":"\"I might skip it. I feel too shaky.\"","then":"\"Skip it?\" she asks. You shrug it off, and set off alone an hour later."},{"text":"\"Honestly? Nervous. My session's today.\"","then":"She grabs her bag. \"Come on. I'm walking with you.\"","best":true},{"text":"\"I'll be fine once it's over, I guess.\"","then":"\"If you say so,\" she says, and checks the time."}],"why":"Saying how you really feel in a nervous moment lets a friend step in and support you."},{"prompt":"That evening, Meenal asks: \"So, how did today go?\"","options":[{"text":"\"The session was weird. I probably won't go back.\"","then":"\"One session is early to decide,\" she says gently."},{"text":"\"Embarrassing. I really hope nobody saw me go into counselling.\"","then":"\"So what if they did?\" she says. \"It's nothing to be embarrassed about.\""},{"text":"\"Counselling went better than I feared. Walk me next week?\"","then":"She grins. \"Deal. Chai on the way back?\"","best":true},{"text":"\"Great, actually. One session and I'm totally fixed.\"","then":"She laughs. \"That fast?\" You feel a little silly."}],"why":"Asking for company, without shame, means you won't face the next one alone."}],"relearn":"It's okay to ask someone to come along; you don't have to face a first session alone."},
  {"id":"mb-1198","cat":"reach-out","type":"role-play","persona":"Rohan","source":"men reaching out","hook":"Sahil is hurting after a breakup but laughs off talk of help. You saw a counsellor last year.","setup":"At the chai stall, a therapy reel plays on his phone.","steps":[{"prompt":"Sahil says: \"Therapy? Please. Lads just deal with it.\"","options":[{"text":"\"True. Therapy's a bit much for guys like us.\"","then":"He laughs, a bit too loudly, and stares into his cup."},{"text":"\"That's honestly such a toxic thing to say, man.\"","then":"He rolls his eyes. \"Here we go. Lecture time.\""},{"text":"\"Getting help took guts for me. It helped, honestly.\"","then":"He glances at you, surprised. \"Wait, you went? Seriously?\"","best":true},{"text":"\"Ha, fair enough. Want another chai, then?\"","then":"\"Yeah,\" he says, and the moment passes."}],"why":"Sharing that help took guts, and helped, meets his pain without shaming him."},{"prompt":"Sahil says: \"I'm fine, yaar. It's just a breakup.\"","options":[{"text":"\"Then stop moping about it. Plenty more out there.\"","then":"\"Wow. Thanks,\" he says flatly."},{"text":"\"Breakups hurt. You don't have to be fine.\"","then":"He's quiet a moment. \"Yeah. It's been rough, honestly.\"","best":true},{"text":"\"You're clearly not fine, man. Everyone can see it.\"","then":"His jaw sets. \"I said I'm fine.\""},{"text":"\"Cool. Let's talk about something else, then.\"","then":"\"Sure,\" he says, relieved. A few sips later, he circles back anyway."}],"why":"Saying he doesn't have to be fine gives him permission to be honest."},{"prompt":"After a pause, Sahil says: \"I can't sleep. But I'm not crying to some stranger.\"","options":[{"text":"\"Fair enough. Just tough it out, then. It'll pass.\"","then":"He nods. \"Yeah.\" He looks more tired than before."},{"text":"\"Talking isn't weakness. The counsellor's good, honestly.\"","then":"He turns his cup around. \"The one near the library? Maybe.\"","best":true},{"text":"\"Just talk to me. I'll sort you out.\"","then":"He talks for a bit, but the sleepless nights carry on."},{"text":"\"Real talk: you need to man up a bit.\"","then":"He goes quiet, and turns the talk to football."}],"why":"Help-seeking is strength for everyone. Pointing to real support gives him a door."},{"prompt":"A week later, Sahil texts: \"Still can't sleep. Don't tell the guys I said that.\"","options":[{"text":"\"Bro, just tell them. No one cares.\"","then":"\"Not happening,\" he replies, and goes quiet."},{"text":"\"Haha, your secret's safe. Hang in there.\"","then":"He sends a thumbs up. Nothing changes."},{"text":"\"Still? Man, you need to get over her.\"","then":"\"Thanks for the advice,\" he replies. You can feel the sarcasm."},{"text":"\"I won't. Want me to walk you to the counsellor?\"","then":"A pause, then: \"Yeah. Thursday? Don't make it a thing.\"","best":true}],"why":"Respecting his privacy while offering a real step makes help feel doable."}],"relearn":"Help-seeking is strength for all genders; meet a hurting friend's bravado with warmth."},
  {"id":"mb-1199","cat":"reach-out","type":"role-play","persona":"any","source":"reaching across distance","hook":"Your younger brother Aryan sounds flat and far-off on every call from home lately.","setup":"He picks up your Sunday call.","steps":[{"prompt":"Aryan says: \"Hmm. Yeah. I'm okay. Nothing new.\"","options":[{"text":"\"Cool, cool. Did Ma make biryani this week or not?\"","then":"\"Yeah,\" he says. You talk food for five minutes, and he says bye."},{"text":"\"What's wrong with you? You're so boring now.\"","then":"\"Thanks,\" he says flatly. \"Got to go.\""},{"text":"\"You've sounded low lately, and I care. What's up?\"","then":"A long pause. \"I don't know. Everything just feels heavy.\"","best":true},{"text":"\"Are you depressed or something? You sound like it.\"","then":"\"What? No,\" he says quickly. \"I'm fine.\""}],"why":"Gently naming what you've noticed tells him you see him, and opens the door."},{"prompt":"A few days later, Aryan texts: \"Sorry I was weird on the call.\"","options":[{"text":"\"It's fine, no worries at all. Forget about it.\"","then":"\"Ok,\" he replies. The chat goes still."},{"text":"\"You were a bit. What's going on with you, seriously?\"","then":"\"Nothing. Chill,\" he replies."},{"text":"\"You weren't weird. I'm here if you want to really talk.\"","then":"Typing dots appear, stop, then appear again. \"Can we call tonight?\"","best":true},{"text":"\"Just be more cheerful with Ma. She worries.\"","then":"\"Yeah, okay,\" he replies. You feel him pull further away."}],"why":"Leaving the door open, without pressure, lets him come to you when he's ready."},{"prompt":"On the next call, Aryan says: \"School's just a lot. I feel alone.\"","options":[{"text":"\"School's the easy part, trust me. Wait till college.\"","then":"\"Great,\" he mutters. \"Something to look forward to.\""},{"text":"\"I'll tell Ma and Papa tonight so they can sort it.\"","then":"\"Don't!\" he says. \"They'll just panic.\""},{"text":"\"That sounds hard. Can we find you someone there to talk to?\"","then":"\"Maybe the school counsellor,\" he says slowly. \"Would you help me ask?\"","best":true},{"text":"\"Just talk to me. You don't need anyone else.\"","then":"\"Okay,\" he says, but you're two states away, and his nights are long."}],"why":"Listening, then helping him find support near him, cares for him across the distance."}],"relearn":"Naming gently that you've noticed a loved one's low mood opens the door to support."},
  {"id":"mb-1200","cat":"reach-out","type":"role-play","persona":"any","source":"i belong here","hook":"In your first counselling session, you worry your problems aren't 'big enough' to be there.","setup":"Ms. Kapoor waits, notepad on her knee.","steps":[{"prompt":"Ms. Kapoor asks: \"What brings you in today?\"","options":[{"text":"\"Nothing much, really. I'm basically fine.\"","then":"\"Okay,\" she says gently. \"What made you book, then?\""},{"text":"\"I'm not sure I qualify, but I'm not coping well.\"","then":"She nods. \"You don't need to qualify. Not coping is reason enough.\"","best":true},{"text":"\"Sorry for wasting a slot someone else needs.\"","then":"\"You're not wasting anything,\" she says. \"This slot is yours.\""},{"text":"\"My friend thought I should come. I'm not sure why.\"","then":"\"What do you think they noticed?\" she asks."}],"why":"Saying the doubt out loud, and that you're not coping, starts the real conversation."},{"prompt":"Ms. Kapoor asks: \"How have things been, day to day?\"","options":[{"text":"\"Just normal stuff. Everyone's stressed these days.\"","then":"\"Everyone's stress still counts,\" she says. \"Tell me about yours.\""},{"text":"\"I'd rather hear what other students come in with.\"","then":"\"Everyone's different,\" she says. \"I'd like to hear about you.\""},{"text":"\"I'm not sleeping, and I cry after calls home.\"","then":"She listens, nodding. \"That sounds exhausting. Let's look at it together.\"","best":true},{"text":"\"It's probably silly compared to real problems.\"","then":"\"It isn't silly,\" she says. \"It's affecting your days.\""}],"why":"Being specific about your days helps her understand, and help."},{"prompt":"Ms. Kapoor asks: \"Would you like to come back next week?\"","options":[{"text":"\"Maybe once I have a bigger problem to bring you.\"","then":"\"You don't need a bigger problem,\" she says. \"The offer stands.\""},{"text":"\"Yes. I think it would help.\"","then":"\"Same time Tuesday, then,\" she says, writing it down.","best":true},{"text":"\"Only if there's no one who needs it more.\"","then":"\"There's room for you,\" she says. \"Think about it.\""},{"text":"\"I'll see how I feel, and email you if I need to.\"","then":"\"Of course,\" she says, and makes a note."}],"why":"Coming back is how support builds. You don't need a bigger problem to deserve it."},{"prompt":"Walking out, your inner voice says: \"You took up a slot for nothing.\"","options":[{"text":"\"True. Next time I'll wait till it's worse.\"","then":"\"Exactly,\" it says, and the next appointment feels harder to keep."},{"text":"\"I should have just handled all of this on my own.\"","then":"\"Should have,\" it agrees, and the relief of the session fades."},{"text":"\"Maybe. I just won't tell anyone I went.\"","then":"\"Good. Hide it,\" it says, and a little shame creeps in."},{"text":"\"Not coping well is reason enough to be here.\"","then":"The voice quiets, and you walk out lighter than you walked in.","best":true}],"why":"You belong in that room. Not coping well is always reason enough."}],"relearn":"You can tell a counsellor you feel you don't 'qualify'; not coping well is reason enough."},
  {"id":"mb-1201","cat":"reach-out","type":"role-play","persona":"any","source":"how i started","hook":"Your friend Tanvi knows you've been seeing the campus counsellor for a month.","setup":"Over chai, she lowers her voice.","steps":[{"prompt":"Tanvi asks: \"How did you find the nerve to actually go?\"","options":[{"text":"\"I was scared too. I just made one call and went.\"","then":"Tanvi lets out a breath. \"Scared too? I thought it was just me.\"","best":true},{"text":"\"Honestly, it's easy. You just have to want it enough.\"","then":"Tanvi's face drops. \"Then maybe I don't want it enough.\""},{"text":"\"I waited till I felt totally ready. Then it was simple.\"","then":"\"I'm nowhere near ready,\" Tanvi says. \"So I'll wait too.\""},{"text":"\"Why? Is something going on with you?\"","then":"Tanvi pulls back. \"Nothing. Just curious.\" She changes the topic."}],"why":"Saying you were scared too shows her she doesn't need to feel ready first."},{"prompt":"Later, Tanvi admits: \"Some days are really heavy. But others have it worse.\"","options":[{"text":"\"True. Maybe just try to stay positive and keep busy for now.\"","then":"\"Yeah,\" she says flatly, and stirs her chai."},{"text":"\"Heavy days are reason enough. You don't need it worse.\"","then":"Tanvi nods slowly. \"I didn't think it counted.\"","best":true},{"text":"\"You should book a session today. Like, right now.\"","then":"Tanvi tenses. \"Right now? I don't know.\""},{"text":"\"Same here. Let me tell you about my worst week.\"","then":"Tanvi listens to your story and never finishes hers."}],"why":"No problem is too small for support. Heavy days count on their own."},{"prompt":"The next evening, Tanvi texts: \"I looked up the counsellor. I don't know what I'd even say.\"","options":[{"text":"\"Write a full script first so you don't mess it up.\"","then":"Tanvi sends a thumbs-up. Two days later, the script is still unfinished."},{"text":"\"Want me to call and book it for you?\"","then":"\"Maybe,\" she replies. \"But then it feels like your thing, not mine.\""},{"text":"\"Maybe wait till you know exactly what's wrong.\"","then":"\"Yeah, maybe,\" Tanvi replies. The booking page stays open, untouched."},{"text":"\"Say what you told me. That's enough to start.\"","then":"\"Okay,\" Tanvi replies. \"I'll call tomorrow morning.\"","best":true}],"why":"She doesn't need the right words. Showing up with what she feels is enough."}],"relearn":"You can reach out before you feel ready. One call and showing up is enough."},
  {"id":"mb-1202","cat":"reach-out","type":"role-play","persona":"any","source":"honouring trust","hook":"Aarav, a junior from your course, tells you he's been really low lately.","setup":"He glances at the door as he says it.","steps":[{"prompt":"Aarav says: \"Please don't make it a big deal. Or tell anyone.\"","options":[{"text":"\"Okay, but I'm telling our mentor so you get help.\"","then":"Aarav goes pale. \"Forget I said anything.\" He leaves quickly."},{"text":"\"Thanks for trusting me. I'm here whenever you want to talk.\"","then":"Aarav's shoulders drop. \"Thanks. I just needed someone to know.\"","best":true},{"text":"\"Low? You seem totally fine to me.\"","then":"\"Yeah, I'm good at hiding it,\" he mutters."},{"text":"\"Don't worry. I'll keep it a total secret, no matter what.\"","then":"Aarav relaxes. \"Good. Then I can stop talking about it.\""}],"why":"Thanking him and keeping the door open honours his trust without a scene."},{"prompt":"Two days later, Aarav skips the study group. When you text, he replies: \"Just tired. Don't worry.\"","options":[{"text":"\"Everyone noticed you missing. What's going on?\"","then":"\"Everyone?\" he replies. Then nothing."},{"text":"\"No worries. See you around.\"","then":"He sends a thumbs-up. You don't hear from him for days."},{"text":"\"Okay. I saved you my notes if you want them.\"","then":"A while later he finds you in the library, takes the notes and stays ten minutes.","best":true},{"text":"\"I'm coming over right now to check on you.\"","then":"\"Please don't,\" he replies fast. \"I'm fine.\""}],"why":"A quiet, practical check-in keeps you close without making a fuss."},{"prompt":"A week later, Aarav says: \"I think I'm worse than I let on. I don't know what to do.\"","options":[{"text":"\"Just give it time. Honestly, it'll pass on its own soon enough.\"","then":"\"Maybe,\" he says, but he looks more lost than before."},{"text":"\"Thanks for saying it. Want help finding someone to talk to?\"","then":"Aarav nods. \"Maybe the counsellor. Would you walk there with me?\"","best":true},{"text":"\"I'll book you in with the counsellor tomorrow.\"","then":"\"You'd do that without asking me?\" Aarav looks uneasy."},{"text":"\"Let me tell your parents. They'll know what to do.\"","then":"Aarav stiffens. \"No. They'll panic. Please don't.\""}],"why":"Offering to help him find support, at his pace, turns trust into real help."},{"prompt":"A month later, Aarav says: \"I'm doing a bit better. Sorry I dumped all that on you.\"","options":[{"text":"\"No worries. Let's not talk about it again.\"","then":"\"Sure,\" he says. The door you kept open swings half shut."},{"text":"\"Good. So you're all fixed now?\"","then":"\"Not fixed,\" he says. \"Just better.\""},{"text":"\"You didn't dump anything. I'm glad you told me.\"","then":"Aarav smiles. \"Okay. I'll remember that.\"","best":true},{"text":"\"Anytime. Just don't bottle it up again, okay?\"","then":"\"I'll try,\" he says, a little sheepish."}],"why":"Telling him he wasn't a burden keeps the door open for next time."}],"relearn":"Honour a friend's trust without making a scene, and keep the door open to support."},
  {"id":"mb-1203","cat":"reach-out","type":"role-play","persona":"any","source":"just to vent","hook":"A rotten week has piled up, and you want to talk it out with your friend Kabir.","setup":"He's free, and you're both up on the hostel roof.","steps":[{"prompt":"Kabir asks: \"You've been off all week. What's up?\"","options":[{"text":"\"Nothing much. Just tired.\"","then":"Kabir waits. After a while, the week starts spilling out anyway."},{"text":"\"Can I just vent for a bit? No fixing needed.\"","then":"Kabir leans back. \"Sure. Go. I'm all ears.\"","best":true},{"text":"\"Everything. But you've got your own stuff going on.\"","then":"\"I've always got time for you,\" Kabir says. \"What is it?\""},{"text":"\"Can you tell me what I'm doing wrong with my life?\"","then":"Kabir starts listing fixes before you've finished a sentence."}],"why":"Naming exactly what you need makes it easy for a friend to give it."},{"prompt":"As you talk, Kabir cuts in: \"Okay, here's what you should do.\"","options":[{"text":"\"You're right. Just tell me what I should do, then.\"","then":"Kabir lists five plans. You nod, feeling more tired than before."},{"text":"\"Forget it. You're not even listening.\"","then":"Kabir looks stung. \"I was trying to help.\""},{"text":"\"Can I finish first? I mostly need to get it out.\"","then":"\"Oh. Sorry,\" Kabir says. \"Go on. No fixing.\"","best":true},{"text":"\"Sorry. I'll stop dumping all of this on you now.\"","then":"\"You're not dumping,\" Kabir says, but you've already clammed up."}],"why":"Gently restating what you need keeps the talk yours without shutting him out."},{"prompt":"That night, Kabir texts: \"Next time you need to talk, what helps most?\"","options":[{"text":"\"Nothing really. I'll handle it myself next time.\"","then":"\"Okay,\" Kabir replies. He doesn't know you'd rather he asked again."},{"text":"\"Whatever you think. I don't want to be needy.\"","then":"\"You're not needy,\" he replies. \"But what do you want?\""},{"text":"\"Solving it for me, so I don't have to think.\"","then":"\"I'll try,\" he replies. You wonder if that's really what helped."},{"text":"\"Just listening. Ideas can come later, if I ask.\"","then":"\"Listening I can do,\" he replies. \"Anytime.\"","best":true}],"why":"Telling him what helps makes it easier to reach out again next time."}],"relearn":"It's fine to ask a friend to just listen. Naming what you need makes reaching out easier."},
  {"id":"mb-1204","cat":"reach-out","type":"role-play","persona":"any","source":"exam crisis","hook":"Before the exam, your classmate Riya is shaking outside the hall.","setup":"She grabs your sleeve as you pass.","steps":[{"prompt":"Riya whispers: \"I can't go on like this. I really can't.\"","options":[{"text":"\"Just focus on the exam. Sort it out after.\"","then":"Riya's eyes fill. She turns toward the hall, then stops and sits down."},{"text":"\"Let's step out and breathe. I'm right here with you.\"","then":"Riya nods and follows you to the steps, still breathing fast.","best":true},{"text":"\"Everyone's stressed today. You'll be fine.\"","then":"\"It's not stress,\" Riya says quietly. \"It's more than that.\""},{"text":"\"Wait right here. I'll run and find someone who can help.\"","then":"When you get back, Riya is sitting alone on the steps, head down."}],"why":"When someone says they can't go on, staying close matters more than the exam."},{"prompt":"Riya says: \"I just feel like there's no point anymore.\"","options":[{"text":"\"Hey, don't talk like that. You've got so much going for you.\"","then":"Riya goes quiet. \"Forget it,\" she says, looking away."},{"text":"\"Tell me exactly how bad it is first.\"","then":"Riya shrinks back. \"I don't know. I shouldn't have said anything.\""},{"text":"\"I'm staying with you. Let's ring Tele-MANAS 14416 together.\"","then":"Riya hesitates, then nods. You dial, and a calm voice answers.","best":true},{"text":"\"Here's the Tele-MANAS number. Call them after the exam.\"","then":"Riya pockets it. You can tell she won't call alone."}],"why":"Staying and reaching Tele-MANAS 14416 together gets her real support now, not later."},{"prompt":"That evening, Riya messages: \"I'm sorry about today. I feel so embarrassed.\"","options":[{"text":"\"It's okay. Let's just act like today never happened.\"","then":"\"Okay,\" she replies. The heaviness is still there, just unspoken now."},{"text":"\"I've told our group so they can all keep an eye on you.\"","then":"Riya's phone fills with worried messages. She stops replying to all of them."},{"text":"\"I'm glad you told me. Can we see the counsellor together?\"","then":"\"Tomorrow?\" Riya replies. \"Okay. If you come with me.\"","best":true},{"text":"\"Don't be. Just promise me you won't feel that way again.\"","then":"\"I'll try,\" Riya replies. She can't promise a feeling away."}],"why":"Meeting her shame with warmth and linking her to a counsellor keeps real support going."}],"relearn":"If someone says they can't go on, stay close and reach Tele-MANAS 14416 together. Don't rush past it."},
  {"id":"mb-1205","cat":"reach-out","type":"role-play","persona":"any","source":"asking for time","hook":"Your mental health has dipped, and two assignments are now overdue.","setup":"You catch Professor Iyer after class.","steps":[{"prompt":"Professor Iyer asks: \"Yes? Is this about the assignments?\"","options":[{"text":"\"Nothing, sorry. I'll catch up somehow.\"","then":"She pauses, packing up. \"You look worried,\" she says."},{"text":"\"My health's been rough. Could we talk about more time?\"","then":"Professor Iyer nods. \"Thanks for telling me. Let's look at dates.\"","best":true},{"text":"\"My laptop crashed last week and I lost all my files.\"","then":"\"Oh no,\" she says. \"Can you send what you'd saved?\" Your stomach drops."},{"text":"\"I know I'm useless lately. Please don't fail me.\"","then":"\"You're not useless,\" she says, surprised. \"What's going on?\""}],"why":"A short, honest ask is enough. Struggling is a fair reason to speak up."},{"prompt":"The next day, Professor Iyer calls you into her office and asks: \"So, what's been going on?\"","options":[{"text":"\"Honestly, I've just been lazy and disorganised. It's on me.\"","then":"\"That's not what I'm seeing,\" she says. \"You look worn out.\""},{"text":"\"Just exam stress. Everyone has it.\"","then":"\"Hm,\" she says, looking at you a little longer."},{"text":"\"My mental health has been rough. I'm starting to get help.\"","then":"She nods. \"Thank you. That's all I need to know.\"","best":true},{"text":"\"Oh, just some stuff at home. It's fine now.\"","then":"\"Glad it's fine,\" she says, and waits to see if there's more."}],"why":"Naming it briefly, without every detail, gets you fair support and keeps your privacy."},{"prompt":"Professor Iyer offers: \"I can give you until Monday for both. Is that enough?\"","options":[{"text":"\"Yes, Monday's fine. Thank you so much, Professor.\"","then":"She smiles. By Sunday night, you're behind again and dreading Monday."},{"text":"\"Could you just cancel them for me?\"","then":"\"I can't do that,\" she says gently. \"But let's find dates.\""},{"text":"\"Monday's tight for both. Could the second be Thursday?\"","then":"\"Thursday for that one works,\" she says, writing it down.","best":true},{"text":"\"Yes. I'll just pull all-nighters all weekend to finish.\"","then":"\"Please don't,\" she says. \"Sleep matters too.\""}],"why":"Asking for a realistic date sets you up to actually recover and finish."},{"prompt":"The next week, Professor Iyer asks: \"How's the catching up going?\"","options":[{"text":"\"Slowly. I'll manage the rest of it on my own, thanks.\"","then":"She nods. Two weeks later, you're behind again and don't want to ask."},{"text":"\"Slowly, but better. I'm getting some support too.\"","then":"\"Good,\" she says. \"Let me know if anything changes.\"","best":true},{"text":"\"Badly. I'm just hopeless at this.\"","then":"\"You're not hopeless,\" she says. \"Come and see me Thursday.\""},{"text":"\"Fine. Sorry, I've got to run.\"","then":"\"Oh. Okay,\" she says. You slip out early every week after that, and the gap grows."}],"why":"Keeping her honestly in the loop means support stays open if you need it."}],"relearn":"You can ask for reasonable support like more time. Struggling is a fair reason to speak up."},
  {"id":"mb-1206","cat":"reach-out","type":"role-play","persona":"Deepak","source":"holding ground","hook":"On the weekly call home, you mention you've been feeling low for a while.","setup":"Your father goes quiet, then laughs a little.","steps":[{"prompt":"Your father says: \"Low? You're just overthinking, beta. Study and sleep.\"","options":[{"text":"\"Okay, maybe I'm overthinking. It's probably nothing.\"","then":"\"Good,\" he says, relieved, and asks about your marks."},{"text":"\"You never take anything I feel seriously, Papa.\"","then":"\"What did I say wrong?\" he snaps. The call goes tense."},{"text":"\"I hear you. But this feels real, and I want some help.\"","then":"A pause. \"What kind of help?\" he asks, unsure.","best":true},{"text":"\"I'll sort it myself. Don't worry about it.\"","then":"\"Good,\" he says. \"You're strong.\" You hang up feeling more alone."}],"why":"You can respect him and still hold on to what you feel and need."},{"prompt":"On the next call, you mention the campus counsellor. Your father says: \"That's for serious cases. Not for us.\"","options":[{"text":"\"Fine. I won't go, then.\"","then":"\"Good,\" he says, and the heaviness settles back on your chest."},{"text":"\"It's for anyone who's struggling. It's free on campus.\"","then":"\"Free?\" he says. \"Hm. And they keep it private?\"","best":true},{"text":"\"You don't understand anything about my life here, Papa.\"","then":"\"Then explain it!\" he says, and hands the phone to your mother."},{"text":"\"Maybe after exams, when things calm down.\"","then":"\"Exactly,\" he says. \"Focus first.\" Exams are six weeks away."}],"why":"Explaining calmly what support is can ease a parent's worry and stigma."},{"prompt":"Your mother comes on the line: \"Beta, are you eating properly? Sleeping?\"","options":[{"text":"\"Yes, yes, all fine. Don't worry.\"","then":"\"Good,\" she says, relieved. You end the call feeling unseen."},{"text":"\"Not really, Ma. That's why I want some help.\"","then":"She is quiet, then says, \"Then get help, beta. Tell me how it goes.\"","best":true},{"text":"\"Why does everyone keep asking me that, Ma? I'm fine.\"","then":"\"Because we care,\" she says, hurt."},{"text":"\"Not much, but I'll eat more and it'll fix itself.\"","then":"\"Yes, eat well,\" she says. Your chest still feels heavy."}],"why":"Being honest about how you are lets family support you, even if they're unsure how."},{"prompt":"A few days later, your father texts: \"Still thinking about what you said. Feeling better?\"","options":[{"text":"\"Yes, totally better. Forget I said anything.\"","then":"\"Good. See, overthinking,\" he replies."},{"text":"\"No. And talking to you didn't help.\"","then":"No reply for an hour. Then: \"Call your mother.\""},{"text":"\"Not yet. I'll wait till I'm home for Diwali.\"","then":"\"Good idea,\" he replies. Diwali is two months away."},{"text":"\"A bit. I'm booking the counsellor this week.\"","then":"\"Okay,\" he replies after a while. \"Tell us how it goes.\"","best":true}],"why":"Holding your ground kindly means getting support even before family fully agrees."}],"relearn":"You can kindly hold your ground when dismissed and still seek the support you need."},
  {"id":"mb-1207","cat":"reach-out","type":"role-play","persona":"Zoya","source":"saying thanks","hook":"Months after Farah pushed you to see a counsellor, you're feeling steadier.","setup":"You meet her for chai after class.","steps":[{"prompt":"Farah asks: \"You seem lighter these days. What's changed?\"","options":[{"text":"\"Nothing much. Just a better month, I guess.\"","then":"\"Well, it suits you,\" Farah says, and moves on."},{"text":"\"The counsellor's been amazing. Such a relief.\"","then":"\"I'm so glad,\" Farah says. \"I wondered if you ever went.\""},{"text":"\"Honestly? You nudging me to get help changed things.\"","then":"Farah's eyes widen. \"Really? I worried I'd pushed too hard.\"","best":true},{"text":"\"Oh, I don't know. Don't want to get all sentimental.\"","then":"Farah laughs. \"Fine, keep your secrets.\""}],"why":"Telling her the nudge mattered lets her know her care made a difference."},{"prompt":"Farah says: \"I almost didn't say anything back then. I thought you'd be annoyed.\"","options":[{"text":"\"Annoyed? No. I'd have been fine either way.\"","then":"Farah's smile flickers. \"Oh. Okay.\""},{"text":"\"I was a bit. But I'm glad you said it anyway.\"","then":"Farah grins. \"Good. I'd do it again.\"","best":true},{"text":"\"You should've pushed harder, and sooner.\"","then":"Farah looks stung. \"I did what I could.\""},{"text":"\"Let's not talk about that time. It's awkward.\"","then":"\"Sure,\" Farah says, and the moment passes."}],"why":"Being honest about how it felt, and still thankful, makes the thanks real."},{"prompt":"Farah says: \"My cousin's struggling now. I don't know if I should say something.\"","options":[{"text":"\"Better not. People hate being told they need help.\"","then":"\"Maybe you're right,\" Farah says, but she looks uneasy."},{"text":"\"Tell her family so they can handle it.\"","then":"\"Her parents?\" Farah frowns. \"She'd never forgive me.\""},{"text":"\"Send her my counsellor's number and leave it at that.\"","then":"\"Just a number, no talk?\" Farah says. \"Feels a bit cold.\""},{"text":"\"Say it. Your nudge worked on me. It could help her too.\"","then":"Farah nods slowly. \"Okay. I'll call her tonight.\"","best":true}],"why":"Sharing how her care helped you can help her help someone else."}],"relearn":"Telling someone their nudge to seek help mattered strengthens the bond and pays it forward."},
  {"id":"mb-1208","cat":"reach-out","type":"sort","hook":"Sort: a brave, real way to reach out, or a way of staying stuck?","items":[{"id":"a","text":"Calling Tele-MANAS 14416"},{"id":"b","text":"Telling a trusted friend you're not okay"},{"id":"c","text":"Booking a counsellor"},{"id":"d","text":"Waiting for someone to magically notice"},{"id":"e","text":"Insisting you're fine when you're not"},{"id":"f","text":"Scrolling all night to avoid it"}],"bins":[{"id":"reach","label":"Reaching out","valence":"pos"},{"id":"stuck","label":"Staying stuck","valence":"neg"}],"key":{"a":"reach","b":"reach","c":"reach","d":"stuck","e":"stuck","f":"stuck"},"relearn":"Calling Tele-MANAS 14416, telling a friend or booking a counsellor is reaching out; waiting, denying or avoiding keeps you stuck.","persona":"any","source":"reach vs stuck"},
  {"id":"mb-1209","cat":"reach-out","type":"sort","hook":"Sort: a supportive thing to say to a struggling friend, or one that shuts them down?","items":[{"id":"a","text":"\"I'm glad you told me\""},{"id":"b","text":"\"That sounds really hard\""},{"id":"c","text":"\"I'm here, no rush\""},{"id":"d","text":"\"Others have it worse\""},{"id":"e","text":"\"Just think positive\""},{"id":"f","text":"\"Why are you even sad?\""}],"bins":[{"id":"supportive","label":"Supportive","valence":"pos"},{"id":"shuts","label":"Shuts down","valence":"neg"}],"key":{"a":"supportive","b":"supportive","c":"supportive","d":"shuts","e":"shuts","f":"shuts"},"relearn":"'I'm glad you told me', 'that sounds hard' and 'I'm here' support; 'others have it worse', 'just think positive' or 'why are you sad?' shut people down.","persona":"any","source":"what to say"},
  {"id":"mb-1210","cat":"reach-out","type":"sort","hook":"Sort: a real reason to reach out today, or a myth keeping you quiet?","items":[{"id":"a","text":"You've felt heavy most days for weeks"},{"id":"b","text":"You'd just like someone to talk to"},{"id":"c","text":"Coping alone is getting harder"},{"id":"d","text":"\"I'm not ill enough to deserve it\""},{"id":"e","text":"\"Asking means I'm weak\""},{"id":"f","text":"\"It would burden everyone\""}],"bins":[{"id":"reason","label":"Real reason","valence":"pos"},{"id":"myth","label":"Myth to drop","valence":"neg"}],"key":{"a":"reason","b":"reason","c":"reason","d":"myth","e":"myth","f":"myth"},"relearn":"Feeling heavy, wanting to talk or struggling to cope are real reasons to reach out; 'not ill enough', 'weak' or 'a burden' are myths to drop.","persona":"any","source":"reasons vs myths"},
  {"id":"mb-1211","cat":"reach-out","type":"sort","hook":"Sort: who can be part of your support, or who can't carry this?","items":[{"id":"a","text":"A campus counsellor"},{"id":"b","text":"Tele-MANAS 14416"},{"id":"c","text":"A trusted friend or relative"},{"id":"d","text":"A stranger's harsh comment online"},{"id":"e","text":"A bottle to numb it"},{"id":"f","text":"Pretending on social media"}],"bins":[{"id":"support","label":"Real support","valence":"pos"},{"id":"cant","label":"Can't carry it","valence":"neg"}],"key":{"a":"support","b":"support","c":"support","d":"cant","e":"cant","f":"cant"},"relearn":"A counsellor, Tele-MANAS 14416 or a trusted person are real support; online strangers, numbing or pretending can't carry this.","persona":"any","source":"who supports"},
  {"id":"mb-1212","cat":"reach-out","type":"sort","hook":"Sort: a thought that helps you reach out, or one that blocks it?","items":[{"id":"a","text":"\"Asking early is the smart move\""},{"id":"b","text":"\"I don't have to be in crisis\""},{"id":"c","text":"\"People who care want to know\""},{"id":"d","text":"\"I should handle it alone\""},{"id":"e","text":"\"They'll think less of me\""},{"id":"f","text":"\"It's too late for me anyway\""}],"bins":[{"id":"helps","label":"Helps you reach out","valence":"pos"},{"id":"blocks","label":"Blocks you","valence":"neg"}],"key":{"a":"helps","b":"helps","c":"helps","d":"blocks","e":"blocks","f":"blocks"},"relearn":"'Asking early is smart', 'I needn't be in crisis' and 'people want to know' help you reach out; 'handle it alone', 'they'll judge me' or 'too late' block you.","persona":"any","source":"helping thoughts"},
  {"id":"mb-1213","cat":"reach-out","type":"sort","hook":"Sort: a healthy first step toward help, or a dead end?","items":[{"id":"a","text":"Saving Tele-MANAS 14416 in your phone"},{"id":"b","text":"Texting a friend 'can we talk?'"},{"id":"c","text":"Asking where the counsellor sits"},{"id":"d","text":"Endlessly waiting to feel 'ready'"},{"id":"e","text":"Numbing it and hoping"},{"id":"f","text":"Deciding nobody would understand"}],"bins":[{"id":"step","label":"A real first step","valence":"pos"},{"id":"deadend","label":"A dead end","valence":"neg"}],"key":{"a":"step","b":"step","c":"step","d":"deadend","e":"deadend","f":"deadend"},"relearn":"Saving Tele-MANAS 14416, texting a friend or finding the counsellor are real first steps; waiting, numbing or 'nobody understands' are dead ends.","persona":"any","source":"first steps"},
  {"id":"mb-1214","cat":"reach-out","type":"spot","hook":"Spot the two lines that wrongly talk someone OUT of reaching for help.","scene":[{"id":"a","text":"\"Asking for help is a strong move\"","trick":false},{"id":"b","text":"\"You'd just be wasting their time\"","trick":true},{"id":"c","text":"\"You don't have to be in crisis to call\"","trick":false},{"id":"d","text":"\"Real men sort it out alone\"","trick":true},{"id":"e","text":"\"Tele-MANAS 14416 is there for this\"","trick":false}],"why":"'You'd waste their time' and 'real men sort it alone' are the myths that shut people out; the rest open the door.","relearn":"'Wasting their time' and 'men sort it alone' block help; it's strength, no crisis needed.","persona":"any","source":"spot the blockers"},
  {"id":"mb-1215","cat":"reach-out","type":"spot","hook":"Spot the two unhelpful replies to a friend who just said 'I'm not okay'.","scene":[{"id":"a","text":"\"Thank you for telling me\"","trick":false},{"id":"b","text":"\"Come on, cheer up, it's not that bad\"","trick":true},{"id":"c","text":"\"I'm here, take your time\"","trick":false},{"id":"d","text":"\"You're being dramatic\"","trick":true},{"id":"e","text":"\"Want to figure out next steps together?\"","trick":false}],"why":"'Cheer up, it's not that bad' and 'you're being dramatic' dismiss a friend; the others welcome and steady them.","relearn":"'Cheer up' and 'you're dramatic' dismiss a struggling friend; thank them, stay, and offer to find next steps.","persona":"any","source":"spot the dismissals"},
  {"id":"mb-1216","cat":"reach-out","type":"spot","hook":"Spot the two excuses that keep someone from calling a helpline.","scene":[{"id":"a","text":"\"It's free and open 24/7\"","trick":false},{"id":"b","text":"\"My problem's too small to bother them\"","trick":true},{"id":"c","text":"\"Trained listeners actually help\"","trick":false},{"id":"d","text":"\"They'll judge me for calling\"","trick":true},{"id":"e","text":"\"I can call from any phone, privately\"","trick":false}],"why":"'Too small to bother' and 'they'll judge me' are the excuses; Tele-MANAS 14416 is free, private and for everyday stress too.","relearn":"'Too small' and 'they'll judge me' are excuses; Tele-MANAS 14416 is free and private.","persona":"any","source":"spot the excuses"},
  {"id":"mb-1217","cat":"reach-out","type":"spot","hook":"Spot the two signs it's time to reach for more support, hiding among ordinary days.","scene":[{"id":"a","text":"One nervous morning before a viva","trick":false},{"id":"b","text":"Heavy hopeless feeling most days for weeks","trick":true},{"id":"c","text":"A single tearful evening","trick":false},{"id":"d","text":"Losing interest in everything you loved","trick":true},{"id":"e","text":"Tired after a long, busy week","trick":false}],"why":"Weeks of heavy hopelessness and losing all interest are signals to reach out; the others are ordinary hard days.","relearn":"Weeks of heaviness or losing all interest signal reaching out; one rough day is normal.","persona":"Mehta","source":"spot the signal"},
  {"id":"mb-1218","cat":"reach-out","type":"spot","hook":"Spot the two myths a hurting man might tell himself about getting help.","scene":[{"id":"a","text":"\"Everyone has a mind to look after\"","trick":false},{"id":"b","text":"\"Talking about it makes me less of a man\"","trick":true},{"id":"c","text":"\"Reaching out took real guts\"","trick":false},{"id":"d","text":"\"I just have to tough it out alone\"","trick":true},{"id":"e","text":"\"Help-seeking is strength for anyone\"","trick":false}],"why":"'Less of a man' and 'tough it out alone' are the stigma myths; help-seeking is strength for all genders.","relearn":"'Less of a man' and 'tough it out alone' are myths; help-seeking is strength for all genders.","persona":"Rohan","source":"spot men's stigma"},
  {"id":"mb-1219","cat":"reach-out","type":"spot","hook":"Spot the two unsafe moves if a friend mentions thoughts of ending things.","scene":[{"id":"a","text":"Stay calmly with them","trick":false},{"id":"b","text":"Promise total secrecy and leave it","trick":true},{"id":"c","text":"Help them ring Tele-MANAS 14416","trick":false},{"id":"d","text":"Tell them to snap out of it","trick":true},{"id":"e","text":"Bring in a trusted adult","trick":false}],"why":"Promising silence and 'snap out of it' leave a friend alone in danger; stay, reach Tele-MANAS 14416, bring a trusted adult.","relearn":"In a crisis, never promise silence or say 'snap out of it'; stay, reach Tele-MANAS 14416 and a trusted adult.","persona":"any","source":"spot the unsafe"},
  {"id":"mb-1220","cat":"reach-out","type":"spot","hook":"Spot the two beliefs that wrongly say you must wait to deserve support.","scene":[{"id":"a","text":"\"Early help is easier and works better\"","trick":false},{"id":"b","text":"\"I have to hit rock bottom first\"","trick":true},{"id":"c","text":"\"Wanting to talk is reason enough\"","trick":false},{"id":"d","text":"\"It has to be a real crisis to count\"","trick":true},{"id":"e","text":"\"No problem is too small to raise\"","trick":false}],"why":"'Hit rock bottom first' and 'must be a crisis to count' are false gates; you can reach out early, for anything.","relearn":"You don't have to hit rock bottom or be in crisis to deserve support; reach out early.","persona":"any","source":"spot the false gates"},
  {"id":"mb-1221","cat":"reach-out","type":"spot","hook":"Spot the two replies that quietly push a withdrawing friend further away.","scene":[{"id":"a","text":"\"I've noticed you've been quiet, I care\"","trick":false},{"id":"b","text":"\"Fine, I'll stop bothering you then\"","trick":true},{"id":"c","text":"\"No pressure, I'm around whenever\"","trick":false},{"id":"d","text":"\"Guess you don't want my help\"","trick":true},{"id":"e","text":"\"Want to grab chai sometime soon?\"","trick":false}],"why":"'I'll stop bothering you' and 'guess you don't want help' guilt-trip and close the door; the others keep it warm and open.","relearn":"Guilt-trips like 'I'll stop bothering you' push a friend away; keep the door warm.","persona":"any","source":"spot the push-away"},
  {"id":"mb-1222","cat":"reach-out","type":"reflect","hook":"Lensy: think of one person you'd actually trust with a hard day. Picture telling them. Worth keeping in mind?","prompt":"What comes up?","options":["I have someone","I'll reach out","Good to know who"],"affirm":"Knowing even one person you'd trust with a hard day is a quiet kind of safety net; lean on it when you need to.","relearn":"Knowing one person you'd trust with a hard day gives you a real safety net.","persona":"any","source":"my person"},
  {"id":"mb-1223","cat":"reach-out","type":"reflect","hook":"Lensy: imagine a friend told you they were struggling, would you think less of them? So why would they of you?","prompt":"What do you think?","options":["I wouldn't judge them","So they wouldn't judge me","Fair point"],"affirm":"You'd meet a struggling friend with care, not judgement, and good people will meet you exactly the same way.","relearn":"You wouldn't judge a struggling friend; people who care will meet you with the same care.","persona":"any","source":"the friend test"},
  {"id":"mb-1224","cat":"reach-out","type":"reflect","hook":"Lensy: saving a helpline before you need it is like keeping an umbrella handy. Want to pop Tele-MANAS 14416 in your phone?","prompt":"What do you think?","options":["Saving it now","Good to have ready","Already have it"],"affirm":"Having Tele-MANAS 14416 saved before a hard moment means help is one tap away when you most need it.","relearn":"Saving Tele-MANAS 14416 before you need it puts help one tap away in a hard moment.","persona":"any","source":"umbrella ready"},
  {"id":"mb-1225","cat":"reach-out","type":"reflect","hook":"Lensy: what's the smallest first step toward help you could actually take this week, a text, a call, a question?","prompt":"What feels doable?","options":["Text a friend","Save the helpline","Ask about a counsellor"],"affirm":"Any small step counts, a text, a saved number, one question; reaching out doesn't have to be one big leap.","relearn":"Reaching out can be one small step, a text, a saved number, a question, not a giant leap.","persona":"any","source":"small step"},
  {"id":"mb-1226","cat":"reach-out","type":"reflect","hook":"Lensy: think back to a time someone reached out to you, how did it feel to be the one they trusted?","prompt":"What did it feel like?","options":["I felt trusted","Glad they told me","It brought us closer"],"affirm":"Being trusted with someone's hard moment is a gift, not a burden, and others feel the same when you trust them.","relearn":"Being trusted with someone's struggle is a gift; others feel that way when you reach out too.","persona":"any","source":"on the other side"},
  {"id":"mb-1227","cat":"reach-out","type":"reflect","hook":"Lensy: you've made it through every hard day so far, often by leaning on someone. Can you let yourself lean again?","prompt":"What do you think?","options":["I can lean again","I've done it before","Yes, I'll reach out"],"affirm":"You've survived hard stretches before, usually not alone; letting yourself lean again is wisdom, not weakness.","relearn":"You've got through hard times by leaning on people before; you can let yourself lean again.","persona":"any","source":"lean again"},
  {"id":"mb-1228","cat":"reach-out","type":"reflect","hook":"Lensy: if reaching out feels scary, picture how you'd feel an hour after, not in the scary moment. Worth it?","prompt":"What do you imagine?","options":["Relieved","Lighter","Glad I did"],"affirm":"The fear lives in the before; most people feel lighter and relieved soon after they finally reach out.","relearn":"The fear is in the before; people usually feel lighter and relieved soon after reaching out.","persona":"any","source":"after the ask"},
  {"id":"mb-1229","cat":"reach-out","type":"match","hook":"Match each worry about reaching out to the truth that answers it.","pairs":[{"left":"\"I'm not bad enough to deserve help\"","right":"You don't have to be in crisis to reach out"},{"left":"\"Asking means I'm weak\"","right":"Reaching out early is the strong, smart move"},{"left":"\"I'll be a burden\"","right":"People who care want to know"},{"left":"\"Everyone will find out\"","right":"Tele-MANAS 14416 and counsellors are confidential"},{"left":"\"Men shouldn't need help\"","right":"Help-seeking is strength for all genders"}],"relearn":"Every reaching-out worry has a truth; none should keep you quiet.","persona":"any","source":"worry meets truth"},
  {"id":"mb-1230","cat":"reach-out","type":"match","hook":"Match each India support route to what it's best for.","pairs":[{"left":"Tele-MANAS 14416","right":"A free 24/7 listener, any phone"},{"left":"Emergency 112","right":"Immediate danger to anyone"},{"left":"A campus counsellor","right":"Regular face-to-face sessions"},{"left":"A trusted friend or relative","right":"Everyday warmth and a listening ear"},{"left":"A teacher or warden","right":"Help arranging time or adjustments"}],"relearn":"Tele-MANAS 14416 is the helpline, 112 is for danger, a counsellor for sessions, trusted people for warmth, staff for adjustments.","persona":"any","source":"routes map"},
  {"id":"mb-1231","cat":"reach-out","type":"match","hook":"Match each opening line to the moment it fits.","pairs":[{"left":"\"I've been struggling, can we talk?\"","right":"Telling a friend you're not okay"},{"left":"\"How would I reach a counsellor here?\"","right":"Asking staff for a route to help"},{"left":"\"I'm staying with you, let's call together\"","right":"Helping a friend in crisis"},{"left":"\"I just need you to listen, not fix\"","right":"Asking for a space to vent"},{"left":"\"I'm behind and could use more time\"","right":"Asking a teacher for support"}],"relearn":"There's a simple opening line for every moment you might need to reach out.","persona":"any","source":"lines for moments"},
  {"id":"mb-1232","cat":"reach-out","type":"match","hook":"Match each kind of support to the need it meets best.","pairs":[{"left":"A listening ear, no advice","right":"You just need to feel heard"},{"left":"Practical next steps","right":"You're stuck on what to do"},{"left":"A trained counsellor","right":"It's heavy and lasting"},{"left":"Crisis support now","right":"You feel unsafe today"},{"left":"Steady daily company","right":"You feel lonely and isolated"}],"relearn":"Different needs call for different support, a listener to be heard, steps when stuck, a counsellor when heavy, crisis help when unsafe, company when lonely.","persona":"any","source":"need meets support"},
  {"id":"mb-1233","cat":"reach-out","type":"match","hook":"Match each way to support a struggling friend to what it gives them.","pairs":[{"left":"Listening without fixing","right":"Feeling genuinely heard"},{"left":"Sharing Tele-MANAS 14416","right":"A real route to help"},{"left":"Checking in next week","right":"Knowing they're not forgotten"},{"left":"Sitting with them in crisis","right":"Safety and company now"},{"left":"Reminding them it's not weakness","right":"Permission to seek help"}],"relearn":"You can give a friend a lot, being heard, a help route, follow-up, safe company, and permission to seek help.","persona":"any","source":"ways to help"},
  {"id":"mb-1260","type":"strike-rewrite","hook":"\"If I were tougher, this move wouldn't be hard.\"","myth":{"un":"If I were tougher, leaving home wouldn't be this hard.","re":"A hard start is a normal reaction to a big change, not a lack of toughness.","why":"Almost everyone finds the first months bumpy, however tough they are."},"relearn":"A bumpy start is a normal reaction to a big change, not weakness.","persona":"Rohan","source":"toughness myth","cat":"settling-in"},
  {"id":"mb-1261","type":"strike-rewrite","hook":"\"By now I should have a whole friend group.\"","myth":{"un":"A few weeks in, I should already have a whole friend group.","re":"Real connections take time to build; a slow start is normal, not failure.","why":"Friendships grow over months, not in the first weeks."},"relearn":"Friendships take time; a slow start to your social circle is normal.","persona":"Deepak","source":"friend-group timeline","cat":"settling-in"},
  {"id":"mb-1262","type":"strike-rewrite","hook":"\"People like me don't really belong in a place like this.\"","myth":{"un":"People like me don't really belong somewhere like this.","re":"You earned your place; feeling like an outsider at first is common, not proof you don't fit.","why":"Almost everyone feels like an outsider at the start."},"relearn":"Feeling like an outsider at first is common; you earned your place here.","persona":"Deepak","source":"belonging doubt","cat":"settling-in"},
  {"id":"mb-1263","type":"strike-rewrite","hook":"\"If I'm still homesick after a month, something's wrong with me.\"","myth":{"un":"Still being homesick after a month means something's wrong with me.","re":"Homesickness can last a while and still be normal; it usually eases as you settle.","why":"Missing home is a sign you love it, not a sign you're broken."},"relearn":"Homesickness can last a while and still be a normal part of settling in.","persona":"any","source":"homesick timeline","cat":"settling-in"},
  {"id":"mb-1264","type":"strike-rewrite","hook":"\"Everyone in the hostel looks settled, so I'm the odd one out.\"","myth":{"un":"Everyone in the hostel looks settled, so I must be the odd one out.","re":"Most are quietly finding it hard too; the settled look is a front many people put on.","why":"You're comparing your insides to their outsides."},"relearn":"Most people are quietly struggling with the move too; you're not the odd one out.","persona":"any","source":"hostel comparison","cat":"settling-in"},
  {"id":"mb-1265","type":"strike-rewrite","hook":"\"Wanting to call home every day means I haven't grown up.\"","myth":{"un":"Calling home every day means I haven't really grown up.","re":"Staying connected to home while you settle is healthy, not childish.","why":"Connection eases a big change; it doesn't undo your independence."},"relearn":"Staying connected to home while you settle is healthy, not immature.","persona":"Zoya","source":"calling home","cat":"settling-in"},
  {"id":"mb-1266","type":"strike-rewrite","hook":"\"A bad first week means I picked the wrong place and should leave.\"","myth":{"un":"A rough first week means I chose wrong and should leave.","re":"A rough first week says little about the whole year; give settling some time first.","why":"First impressions form before you've found your feet."},"relearn":"A rough first week isn't a verdict; give settling time before big decisions.","persona":"any","source":"first-week verdict","cat":"settling-in"},
  {"id":"mb-1267","type":"strike-rewrite","hook":"\"I should feel grateful and excited, so feeling low means I'm ungrateful.\"","myth":{"un":"I should only feel grateful and excited; feeling low means I'm ungrateful.","re":"You can be grateful for the chance and still find the change hard; both are true.","why":"Mixed feelings are normal in any big transition."},"relearn":"You can be grateful for the chance and still find the move hard at the same time.","persona":"Deepak","source":"gratitude guilt","cat":"settling-in"},
  {"id":"mb-1268","type":"reflect","hook":"Lensy: the noise and crowd of a new city can feel a lot at first. Is it feeling like a lot for you?","prompt":"What's it like for you?","options":["A bit much","Yes, a lot","Getting used to it"],"affirm":"A new city is a lot to take in; needing time to adjust to it is completely normal.","relearn":"A new city feels like a lot at first; needing time to adjust to it is normal.","persona":"Meena","source":"new city","cat":"settling-in"},
  {"id":"mb-1269","type":"reflect","hook":"Lensy: some days you'll feel almost settled, then homesick again the next. Does that up-and-down sound familiar?","prompt":"Does that sound familiar?","options":["Yes","Very familiar","Some days yes"],"affirm":"Settling in isn't a straight line; good days and homesick days mixing together is completely normal.","relearn":"Settling isn't a straight line; good days and homesick days will mix, and that's normal.","persona":"any","source":"up and down","cat":"settling-in"},
  {"id":"mb-1270","type":"reflect","hook":"Lensy: it's okay if your room here doesn't feel like home yet. Would one small familiar thing help?","prompt":"What do you think?","options":["Maybe","I'll try one","Worth a go"],"affirm":"A new place takes time to feel like yours; one small familiar thing can gently help it along.","relearn":"A new place takes time to feel like home; small familiar touches can help.","persona":"any","source":"making it home","cat":"settling-in"},
  {"id":"mb-1271","type":"reflect","hook":"Lensy: there's no fixed deadline by which you must feel at home. Does it help to drop that deadline?","prompt":"What do you think?","options":["Yes","It helps","A relief"],"affirm":"There's no deadline on belonging; letting yourself settle at your own pace takes real pressure off.","relearn":"There's no deadline on feeling at home; settling at your own pace is fine.","persona":"any","source":"no deadline","cat":"settling-in"},
  {"id":"mb-1272","type":"reflect","hook":"Lensy: eating alone in the mess hall those first days can feel exposed. Has that been part of it?","prompt":"Has that been part of it?","options":["Yes","A bit","It was at first"],"affirm":"Eating alone somewhere new can feel exposing; it eases as faces become familiar, and it's a normal early phase.","relearn":"Feeling exposed eating alone somewhere new is a normal early phase that eases.","persona":"any","source":"eating alone","cat":"settling-in"},
  {"id":"mb-1273","type":"reflect","hook":"Lensy: missing the food, sounds and people of home is its own kind of ache. Is that ache around for you?","prompt":"Is that around for you?","options":["Yes","Often","Now and then"],"affirm":"Missing the textures of home is a real, tender feeling; letting yourself feel it is healthy, not weak.","relearn":"Missing the food, sounds and people of home is a normal, tender part of leaving.","persona":"Meena","source":"missing home textures","cat":"settling-in"},
  {"id":"mb-1274","type":"reflect","hook":"Lensy: you don't have to love every minute to be doing this right. Can it be hard and still be going okay?","prompt":"What do you think?","options":["Yes","Both can be true","I think so"],"affirm":"Finding it hard doesn't mean you're doing it wrong; a tough patch and a fine path can be true at once.","relearn":"Finding it hard doesn't mean you're doing it wrong; settling can be hard and still going fine.","persona":"any","source":"hard but okay","cat":"settling-in"},
  {"id":"mb-1275","type":"reflect","hook":"Lensy: comparing your week three to someone else's confident front rarely feels fair to you. Notice that pull?","prompt":"Do you notice that pull?","options":["Yes","All the time","Sometimes"],"affirm":"That comparison pull is common and rarely fair to you; most confident fronts hide a wobble too.","relearn":"Comparing your start to others' confident fronts is a common, unfair trap.","persona":"Deepak","source":"comparison pull","cat":"settling-in"},
  {"id":"mb-1276","type":"reflect","hook":"Lensy: dreading the first call home, unsure how to describe how it's going? That dread is allowed.","prompt":"Does that land for you?","options":["Yes","A bit","It did"],"affirm":"Not having tidy words for how it's going is normal; you can be honest that it's a mix and still settle.","relearn":"Not having tidy words for how settling's going is normal; honesty about the mix is fine.","persona":"Zoya","source":"call home dread","cat":"settling-in"},
  {"id":"mb-1277","type":"reflect","hook":"Lensy: your first friends here might not be your forever friends, and that's okay too. Sit alright with you?","prompt":"Does that sit alright?","options":["Yes","It does","Good to hear"],"affirm":"Early connections can be a bridge while you find your people; they count even if they shift later.","relearn":"Early connections count even if they later shift; they help you settle now.","persona":"any","source":"first friends","cat":"settling-in"},
  {"id":"mb-1278","type":"reflect","hook":"Lensy: with no campus or hostel around you, settling can feel lonelier still. Has it felt that way?","prompt":"Has it felt that way?","options":["Yes","Often","A little"],"affirm":"Settling without a built-in community is harder, and your effort to build one anyway really counts.","relearn":"Settling without a built-in community is harder; reaching out anyway is worth real credit.","persona":"Meena","source":"no campus","cat":"settling-in"},
  {"id":"mb-1279","type":"reflect","hook":"Lensy: you're allowed to feel proud you got here even on the days it feels hard. Can you hold that?","prompt":"Can you hold that?","options":["Yes","I'll try","Both at once"],"affirm":"Getting here took real courage; that pride and a hard patch can sit side by side, and both are yours.","relearn":"You can feel proud you made the move even on the hard days; both can be true.","persona":"any","source":"proud and hard","cat":"settling-in"},
  {"id":"mb-1280","cat":"settling-in","type":"branch","persona":"any","source":"group dinner","hook":"It's your third homesick evening this week, and your floor has a group dinner at 8.","steps":[{"prompt":"At quarter to eight, you're in bed scrolling old photos from home. What do you do?","options":[{"text":"Skip it and scroll alone all night","then":"By midnight, you've seen every photo twice and feel further from home."},{"text":"Go, but only if your roommate comes too","then":"Your roommate's at the library. You stay in as the smell of dinner drifts up."},{"text":"Go down for a bit, even if you leave early","then":"The dinner's loud. Someone passes you the pickle, and you stay longer than planned.","best":true},{"text":"Tell yourself you're too tired for people","then":"You lie awake anyway, hearing laughter from downstairs."}],"why":"A little connection when you're low eases homesickness more than a night alone."},{"prompt":"The next evening, Priya from your class waves you over in the mess. What do you do?","options":[{"text":"Sit with her and ask where home is for her","then":"\"Nagpur,\" she says. \"I cried every night the first week.\" You both laugh.","best":true},{"text":"Wave back but sit alone with your phone","then":"Priya's table fills up. You finish quickly and head back."},{"text":"Sit with her, but keep checking the family group","then":"Priya tries a few topics, then turns to someone else."},{"text":"Say you already ate, to skip the small talk","then":"You eat alone later, cold rice in your room."}],"why":"Asking about her home builds a real connection and shows you're not alone in missing yours."},{"prompt":"At the weekend, the homesickness hits hard again. What helps most?","options":[{"text":"Stay in bed all day until it passes","then":"The day passes in a blur. By night, the ache is heavier."},{"text":"Call home every hour to feel close to them","then":"Each call ends, and the missing starts again, sharper."},{"text":"Keep busy with assignments so you don't feel it","then":"You finish two assignments. The ache waits for you at bedtime."},{"text":"Call home, then join the floor's Sunday cricket","then":"Your mother's voice steadies you. By evening, you're sunburnt and starving.","best":true}],"why":"Staying close to home and building connection here, together, eases the ache."}],"debrief":"Showing up briefly when you're low eases homesickness more than another night alone.","relearn":"On a homesick evening, a little connection beats isolating."},
  {"id":"mb-1281","cat":"settling-in","type":"branch","persona":"any","source":"no routine","hook":"Two weeks in, your days have no shape, and you're up till 4 a.m. most nights.","steps":[{"prompt":"It's noon. You've missed breakfast again, and class is at 2. What do you do?","options":[{"text":"Set one anchor: a fixed wake-up time","then":"You set an alarm for 8. It feels small, almost silly.","best":true},{"text":"Wait till you feel like building a routine","then":"The feeling doesn't come. Another afternoon slips away."},{"text":"Draw up a perfect hour-by-hour timetable","then":"It looks great on paper. By Wednesday, you've missed half of it."},{"text":"Pull an all-nighter to reset your sleep","then":"You crash at 6 p.m. and wake at 3 a.m., wide awake."}],"why":"One small anchor is easier to keep than a whole new timetable."},{"prompt":"A few days later, you're still wide awake at 2 a.m. What do you try?","options":[{"text":"Scroll until you finally feel sleepy","then":"At 4 you're still scrolling, eyes stinging."},{"text":"Watch one more calm episode in bed to wind down","then":"One episode becomes three. It's 4 a.m. again."},{"text":"Put the phone across the room and dim the lights","then":"It feels dull without the screen, and you're asleep within the hour.","best":true},{"text":"Skip sleep and nap all afternoon instead","then":"The nap runs into evening, and the night starts wide awake again."}],"why":"A calmer, screen-free wind-down helps your body clock settle."},{"prompt":"At the weekend, the days still feel empty. What do you try?","options":[{"text":"Nothing. It'll pass once classes pick up","then":"Classes pick up, but the afternoons stay long and empty."},{"text":"A full gym, study and club plan from Monday","then":"Monday goes fine. By Thursday, you're back in bed at noon."},{"text":"More time alone to recharge before classes","then":"The quiet hours stretch, and you're up late again."},{"text":"One meal a day in the mess with other people","then":"Lunch at 1 becomes a habit, and the faces at your table start to feel familiar.","best":true}],"why":"Adding a small routine that includes people steadies you and builds belonging."}],"debrief":"A little structure is what helps settling begin. Build it before you feel ready.","relearn":"Set one small routine anchor. Don't wait to feel ready."},
  {"id":"mb-1282","cat":"settling-in","type":"branch","persona":"Deepak","source":"thinking of leaving","hook":"A month in and lonely, you're seriously thinking of dropping out and going home.","steps":[{"prompt":"Tonight, you draft a message telling your family you're leaving college. What do you do?","options":[{"text":"Send it now, before you lose your nerve","then":"Your phone rings at once. Your mother sounds panicked and full of questions."},{"text":"Delete it and tell yourself to toughen up","then":"The draft's gone, but the loneliness is exactly where it was."},{"text":"Save it, and talk it through with someone first","then":"You save the draft. Not deciding tonight lets you breathe a little.","best":true},{"text":"Sleep on it, then decide alone in the morning","then":"Morning comes, and you feel just as stuck, only more tired."}],"why":"A lonely month is a normal patch. Big calls are best made after talking them through."},{"prompt":"The next day, you pass the counselling centre on your way to class. What do you do?","options":[{"text":"Walk past. Counsellors are for serious cases","then":"The centre fades behind you, and so does the chance to talk."},{"text":"Book a slot to talk through staying or going","then":"The receptionist offers Thursday at 4. You write it on your hand.","best":true},{"text":"Plan to go once you've made up your mind","then":"You never feel sure enough, so you never go."},{"text":"Read stories online of people who dropped out","then":"Every story says something different. You feel more confused."}],"why":"Talking it through with someone trained helps you decide clearly, not in the thick of it."},{"prompt":"At the weekend, your roommate asks why you've been so quiet all week. What do you say?","options":[{"text":"Nothing much. Just tired. Don't worry about it","then":"He nods and puts his earphones back in."},{"text":"Honestly? I've been lonely and thinking of leaving","then":"He sits down. \"I nearly left in my first month too. What's it been like?\"","best":true},{"text":"I'm leaving soon anyway, so it doesn't really matter","then":"He looks startled. \"Wait, what? Since when?\""},{"text":"Ask about his cricket match instead","then":"He talks about the match for ten minutes. You feel far away."}],"why":"Telling someone how you really feel often shows you're not the only one who's found it hard."},{"prompt":"At the month's end, you're still torn about staying or going. What do you base the choice on?","options":[{"text":"How you felt on your very worst night","then":"The worst night makes every option look bleak."},{"text":"What your relatives will say either way","then":"You picture the family WhatsApp and feel pulled in two directions."},{"text":"Whatever your roommate thinks is the right thing to do","then":"He shrugs. \"It's your call.\" You're back where you started."},{"text":"How it feels after a few more weeks with support","then":"You give it a few more weeks and talk it through. The choice feels clearer.","best":true}],"why":"A decision made after the wobble, with support, is more truly your own."}],"debrief":"Big decisions are best made after the wobble settles, not during it.","relearn":"Give settling time and talk it through before a leave-or-stay decision."},
  {"id":"mb-1283","cat":"settling-in","type":"branch","persona":"any","source":"roommate comparison","hook":"Your classmate Shreya seems to have it all together, and around her you feel behind.","steps":[{"prompt":"She breezes into class from her third club meeting this week, smiling. What do you do?","options":[{"text":"Decide you're the only one who's struggling","then":"You smile back and stare at your notes. The gap feels wider."},{"text":"Ask her how her first weeks have really been","then":"Shreya drops her bag. \"Honestly? I cry after calls home most nights.\"","best":true},{"text":"Sign up for three clubs to catch up with her","then":"You sign up, exhausted before the first meeting even starts."},{"text":"Say 'You're so lucky it's easy for you'","then":"Shreya's smile fades. \"Easy? Is that what it looks like?\""}],"why":"Asking how it's really going beats comparing your insides to her outside."},{"prompt":"That night, your feed is all perfect first-term photos. What do you tell yourself?","options":[{"text":"Everyone's thriving except me","then":"You keep scrolling, and each photo stings a little more."},{"text":"I should post something that looks just as good as theirs","then":"You spend an hour on one post. It gets likes, and you still feel behind."},{"text":"Maybe I'm just not cut out for college","then":"The thought follows you to bed and into the morning."},{"text":"These are highlights. Most people find it hard too","then":"You close the app. The photos feel less like a scoreboard.","best":true}],"why":"Posts show the best moments. Remembering that breaks the comparison trap."},{"prompt":"A week later, another classmate, Ritu, says she's feeling lost in lectures too. What do you do?","options":[{"text":"Tell her it gets easy fast, and you're totally fine","then":"She nods and looks more alone than before."},{"text":"Give her tips so she thinks you've got it sorted","then":"She thanks you. You walk away feeling like a fraud."},{"text":"Say you feel the same and suggest studying together","then":"Her face lights up. You meet at the library the next day.","best":true},{"text":"Nod, relieved, and keep your own worries to yourself","then":"You both feel slightly better, then drift apart."}],"why":"Being honest about struggling turns comparison into connection."},{"prompt":"At the month's end, Shreya aces a test you barely passed. What do you tell yourself?","options":[{"text":"One test isn't my worth. I'll ask for help","then":"You email your tutor, and Shreya offers to share her notes.","best":true},{"text":"I'm clearly not as smart as everyone here","then":"The thought follows you into the next class."},{"text":"I'll study every night till I catch up to her","then":"By the weekend, you're exhausted and still comparing."},{"text":"Pretend you don't care about marks at all","then":"You shrug it off in public and replay it in bed."}],"why":"Comparing marks wears down your worth. Asking for help moves you forward."}],"debrief":"A real chat usually dissolves the 'only me' story. Almost everyone finds it hard.","relearn":"Ask how others' first weeks really went. The confident front hides a wobble too."},
  {"id":"mb-1284","cat":"settling-in","type":"branch","persona":"any","source":"rough weekend","hook":"You skipped meals and stayed in all weekend, and now you feel worse for it.","steps":[{"prompt":"It's Sunday evening and your head feels foggy. What do you do first?","options":[{"text":"Tell yourself you've ruined the whole week","then":"The thought loops, and you stay curled up on the bed."},{"text":"Make up for it by studying all night","then":"An hour in, the words swim on the page."},{"text":"Stay in. You'll reset properly on Monday","then":"You lie there, and the fog settles in for the night."},{"text":"Eat something simple and drink some water","then":"Toast, a banana and a big glass of water. The fog lifts a little.","best":true}],"why":"Food and water are the first, kindest step when you feel low and foggy."},{"prompt":"You realise you haven't been outside since Friday. What do you do?","options":[{"text":"Walk round the block, even for ten minutes","then":"The cool air wakes you up a bit, and the street feels busy and alive.","best":true},{"text":"Open the window and get back into bed","then":"Some air comes in. You drift back into scrolling."},{"text":"Plan a long run tomorrow to make up for it","then":"Tomorrow's alarm goes off, and you switch it off."},{"text":"Scroll to see what everyone else did","then":"Everyone seems to have had a great weekend. You feel worse."}],"why":"A short walk outside lifts your mood more than you'd expect."},{"prompt":"That evening, you still feel alone. What do you do?","options":[{"text":"Wait until someone messages you first","then":"The phone stays quiet all evening."},{"text":"Message one friend: 'Rough weekend. Chai tomorrow?'","then":"\"Yes! 8.30 before class?\" comes back within minutes.","best":true},{"text":"Decide not to tell anyone about the weekend","then":"You feel better, but the weekend stays yours alone to carry."},{"text":"Send a long message apologising for going quiet all weekend","then":"Your friend replies, \"No need to say sorry! You okay?\" You're not sure what to say."}],"why":"Reaching out to one person turns a rough weekend into a fresh start."}],"debrief":"After a rough patch, the way back is small kind basics, not harsh self-talk.","relearn":"Reset a low weekend with gentle basics: food, fresh air, one message to someone."},
  {"id":"mb-1285","cat":"settling-in","type":"branch","persona":"any","source":"chai invite","hook":"After class, Vikram asks if you want to come on a chai run with his friends.","steps":[{"prompt":"Your stomach flips at the thought of a group you don't know. What do you do?","options":[{"text":"Make an excuse about an assignment","then":"Vikram says, \"Next time, then.\" You spend the evening alone."},{"text":"Say yes, then drop out at the last minute","then":"You send a quick \"sorry, can't\" and feel both relieved and flat."},{"text":"Say yes and go, nerves and all","then":"The chai stall is loud. You mostly listen, but someone asks your name twice.","best":true},{"text":"Ask to come another day when it's quieter","then":"\"Sure,\" Vikram says, but he doesn't set a day."}],"why":"Small yeses, even nervous ones, are how belonging starts."},{"prompt":"The next week, the same group is heading out again, and no one has asked you. What do you do?","options":[{"text":"Assume they don't want you there","then":"You watch them leave from the library window."},{"text":"Ask Vikram if you can tag along","then":"\"Obviously,\" he says. \"We just assumed you'd come.\"","best":true},{"text":"Wait near the gate hoping someone invites you","then":"They walk past chatting. Someone waves, but no one stops."},{"text":"Tell yourself groups aren't your thing","then":"The label sticks, and you skip the next one too."}],"why":"Asking to join is normal. People often forget to invite, not decide to leave you out."},{"prompt":"Later that month, in a group at the canteen, the talk turns to a movie you haven't seen. What do you do?","options":[{"text":"Pretend you've seen it and nod along","then":"Someone asks your favourite scene. Your face goes hot."},{"text":"Go quiet and check your phone until the topic changes","then":"The group chats on around you. You feel on the outside again."},{"text":"Change the subject to something you know","then":"The talk shifts, but it goes a little flat."},{"text":"Ask what it's about and whether it's worth seeing","then":"Three people start explaining at once, and you end up laughing.","best":true}],"why":"Curious questions pull you into a group more than pretending or hiding."}],"debrief":"Saying yes to small low-stakes invites, even nervous, is how belonging starts to grow.","relearn":"Say yes to small invites even when nervous. That's how settling and belonging grow."},
  {"id":"mb-1286","cat":"settling-in","type":"branch","persona":"any","source":"gone quiet","hook":"Most of your floor went home for the long weekend, and you've barely spoken in four days.","steps":[{"prompt":"You wake up flat on day five. What do you tell yourself?","options":[{"text":"I'm just antisocial. That's who I am","then":"You pull the blanket up. The quiet feels like proof."},{"text":"Nothing's wrong. I'll be fine when they're back","then":"You wait it out. By lunch, the flatness is still there."},{"text":"I've drifted. One small step will help","then":"You sit up and scroll your contacts for someone to message.","best":true},{"text":"I must be boring if no one's messaged","then":"The thought stings, and you put the phone face down."}],"why":"Noticing the drift kindly, without a label, makes the next step feel doable."},{"prompt":"At lunch, the mess is nearly empty except for the cook, Raju bhaiya. What do you do?","options":[{"text":"Eat fast and head back to your room","then":"The room is exactly as quiet as you left it."},{"text":"Stay on your phone the whole time","then":"The meal passes. You don't remember what you ate."},{"text":"Ask him how his long weekend is going","then":"He grins and tells you about his daughter's school play. You stay for a second cup.","best":true},{"text":"Nod hello and leave it there","then":"He nods back. The quiet returns as you leave."}],"why":"Even a small chat with anyone nearby breaks a quiet stretch."},{"prompt":"That evening, the hostel is still quiet and the night feels long. What do you do?","options":[{"text":"Plan to be more social once everyone's back","then":"The plan feels fine. Tonight still feels long."},{"text":"Watch shows until you fall asleep","then":"Four episodes in, you're awake and still flat."},{"text":"Send a voice note to a friend from home","then":"Your friend sends one back within the hour, laughing and full of news.","best":true},{"text":"Tell yourself you should be over this by now","then":"The pressure makes the evening feel heavier."}],"why":"One small, real connection each day keeps a quiet patch from deepening."}],"debrief":"Catching a quiet drift early and taking one small step protects how you settle.","relearn":"Gone quiet for days? Notice it kindly and take one small step to reconnect."},
  {"id":"mb-1287","cat":"settling-in","type":"branch","persona":"Zoya","source":"family demands","hook":"Your family wants daily updates and top marks, and you're still finding your feet.","steps":[{"prompt":"It's 11 p.m. and the family group shows five missed calls. What do you do?","options":[{"text":"Call back now and go through every single detail of your day","then":"The call runs past midnight. You fall asleep with your notes unread."},{"text":"Text: 'All okay, just tired. Call you tomorrow evening.'","then":"Your mother sends a heart. \"Okay. Sleep.\"","best":true},{"text":"Ignore the calls and mute the group for a week","then":"By morning, there are fourteen missed calls and a worried aunt on WhatsApp."},{"text":"Call back and promise you'll top every exam","then":"They sound thrilled. The promise sits heavy in your chest."}],"why":"A short, warm reply with a set time keeps them close and gives you space."},{"prompt":"The next morning, your father asks why your marks slipped in one test. What do you say?","options":[{"text":"I'm so sorry. I'll never let it happen again. I promise","then":"He seems satisfied. You start to dread the next test."},{"text":"Why do you only ever ask about marks?","then":"He goes quiet. \"Because we worry,\" he says, hurt."},{"text":"It was one test. I'm settling in and working on it","then":"He pauses. \"Okay. Just keep trying.\"","best":true},{"text":"Say nothing, then study all night to fix it","then":"Your eyes burn through the next morning's lecture."}],"why":"Calm honesty about settling in sets realistic hopes without a fight."},{"prompt":"By Friday, you feel stretched thin between home and college. Who do you turn to?","options":[{"text":"No one. It's family stuff, so you keep it private","then":"You hold it alone, and the weekend feels long."},{"text":"Your friend Tara, to say it's been a lot with home","then":"Tara listens and says, \"Mine are the same. Chai and a rant?\"","best":true},{"text":"Everyone, through a vague sad quote on your story","then":"Two likes, no messages. You feel more alone."},{"text":"Your cousin, who's likely to repeat it to the family","then":"By Sunday, your aunt has called to ask what's wrong."}],"why":"Leaning on a friend widens your support beyond the people adding the pressure."},{"prompt":"On Sunday, your mother asks if you can call every night from now on. What do you say?","options":[{"text":"Yes, of course. Every night","then":"Nightly calls start. Your evenings shrink to fit around them."},{"text":"No. You're being way too much","then":"She goes quiet, then says, \"We just miss you.\""},{"text":"Every few days works better. I love you all","then":"A pause. \"Okay. But Sundays for sure?\"","best":true},{"text":"'Let's see, maybe,' and hope she forgets","then":"The next night, she calls at 9 sharp."}],"why":"A kind, clear boundary protects your space and keeps the bond warm."}],"debrief":"A kind boundary plus wider support beats being perfect for everyone.","relearn":"Set gentle boundaries with family pressure and widen your support."},
  {"id":"mb-1288","type":"sort","hook":"Sort: a kind way to talk to yourself in week one, or a harsh one?","items":[{"id":"a","text":"\"I'm finding my feet\""},{"id":"b","text":"\"I'm failing at this\""},{"id":"c","text":"\"This takes time\""},{"id":"d","text":"\"Everyone's ahead of me\""},{"id":"e","text":"\"One day at a time\""},{"id":"f","text":"\"I should be over it by now\""}],"bins":[{"id":"kind","label":"Kind","valence":"pos"},{"id":"harsh","label":"Harsh","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"Kind, patient self-talk helps you settle; harsh 'failing' and 'everyone's ahead' lines don't.","persona":"any","source":"week-one self-talk","cat":"settling-in"},
  {"id":"mb-1289","type":"sort","hook":"Sort: a real way to build belonging, or a way to stay stuck?","items":[{"id":"a","text":"Joining one club this week"},{"id":"b","text":"Waiting for people to come to you"},{"id":"c","text":"Saying yes to a study group"},{"id":"d","text":"Turning down every invite"},{"id":"e","text":"Saying hi to a classmate first"},{"id":"f","text":"Eating in your room every day"}],"bins":[{"id":"build","label":"Builds belonging","valence":"pos"},{"id":"stuck","label":"Stays stuck","valence":"neg"}],"key":{"a":"build","b":"stuck","c":"build","d":"stuck","e":"build","f":"stuck"},"relearn":"Joining things and reaching out first build belonging; waiting and declining keep you stuck.","persona":"any","source":"building belonging","cat":"settling-in"},
  {"id":"mb-1290","type":"sort","hook":"Sort: a healthy way to handle a homesick night, or a draining one?","items":[{"id":"a","text":"A short call with someone you trust"},{"id":"b","text":"Replaying every regret about leaving"},{"id":"c","text":"A walk and an early night"},{"id":"d","text":"Scrolling till you feel worse"},{"id":"e","text":"Planning one small thing for tomorrow"},{"id":"f","text":"Skipping food and bottling it up"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"draining","label":"Draining","valence":"neg"}],"key":{"a":"healthy","b":"draining","c":"healthy","d":"draining","e":"healthy","f":"draining"},"relearn":"Connecting, a walk and a small plan ease a homesick night; replaying regrets and bottling up drain you.","persona":"any","source":"homesick night","cat":"settling-in"},
  {"id":"mb-1291","type":"sort","hook":"Sort: a fair thing to expect of week one, or an unfair one?","items":[{"id":"a","text":"A few awkward, lonely moments"},{"id":"b","text":"Instant best friends"},{"id":"c","text":"Not knowing where things are yet"},{"id":"d","text":"Feeling fully at home on day one"},{"id":"e","text":"Needing time to find a routine"},{"id":"f","text":"Zero homesickness at all"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"unfair","label":"Unfair","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Awkward moments and needing time are fair to expect; instant friends and zero homesickness are not.","persona":"any","source":"week-one expectations","cat":"settling-in"},
  {"id":"mb-1292","type":"sort","hook":"Sort: settles you into a new place, or keeps it feeling alien?","items":[{"id":"a","text":"Learning your way around the area"},{"id":"b","text":"Never leaving your room"},{"id":"c","text":"Finding a regular chai spot"},{"id":"d","text":"Avoiding talking to anyone local"},{"id":"e","text":"A few familiar things on your desk"},{"id":"f","text":"Refusing to unpack properly"}],"bins":[{"id":"settles","label":"Settles you in","valence":"pos"},{"id":"alien","label":"Keeps it alien","valence":"neg"}],"key":{"a":"settles","b":"alien","c":"settles","d":"alien","e":"settles","f":"alien"},"relearn":"Exploring, small routines and familiar touches settle you in; hiding away keeps a place feeling alien.","persona":"Meena","source":"making place yours","cat":"settling-in"},
  {"id":"mb-1293","type":"sort","hook":"Sort: a normal settling-in feeling, or a signal it's time to reach out?","items":[{"id":"a","text":"Some lonely evenings"},{"id":"b","text":"Dreading every single day for weeks"},{"id":"c","text":"Nerves before a new class"},{"id":"d","text":"Crying most days, can't stop"},{"id":"e","text":"Taking a while to feel comfortable"},{"id":"f","text":"No appetite or sleep for weeks"}],"bins":[{"id":"normal","label":"Normal","valence":"pos"},{"id":"reach","label":"Reach out","valence":"tell"}],"key":{"a":"normal","b":"reach","c":"normal","d":"reach","e":"normal","f":"reach"},"relearn":"Lonely evenings and nerves are normal; weeks of dread, daily crying or no sleep are signals to reach out.","persona":"any","source":"normal or signal","cat":"settling-in"},
  {"id":"mb-1294","type":"sort","hook":"Sort: helps you feel you belong, or feeds the impostor feeling?","items":[{"id":"a","text":"Remembering you earned your place"},{"id":"b","text":"\"People like me don't belong\""},{"id":"c","text":"Asking a doubt in class anyway"},{"id":"d","text":"Hiding so no one finds you out"},{"id":"e","text":"Knowing most feel like outsiders first"},{"id":"f","text":"Comparing yourself to everyone"}],"bins":[{"id":"belong","label":"Helps you belong","valence":"pos"},{"id":"impostor","label":"Feeds the doubt","valence":"neg"}],"key":{"a":"belong","b":"impostor","c":"belong","d":"impostor","e":"belong","f":"impostor"},"relearn":"Recalling you earned your place and that most feel like outsiders first helps; hiding and comparing feed the doubt.","persona":"Deepak","source":"first-gen belonging","cat":"settling-in"},
  {"id":"mb-1295","type":"sort","hook":"Sort: a steady first-week step, or one that makes it harder?","items":[{"id":"a","text":"Keeping a rough sleep schedule"},{"id":"b","text":"Pulling all-nighters from day one"},{"id":"c","text":"Eating proper meals"},{"id":"d","text":"Living on chips and energy drinks"},{"id":"e","text":"Texting home now and then"},{"id":"f","text":"Cutting off everyone from home"}],"bins":[{"id":"steady","label":"Steadies you","valence":"pos"},{"id":"harder","label":"Makes it harder","valence":"neg"}],"key":{"a":"steady","b":"harder","c":"steady","d":"harder","e":"steady","f":"harder"},"relearn":"Sleep, real meals and staying in touch with home steady your first week; all-nighters, junk and cutting off don't.","persona":"any","source":"first-week basics","cat":"settling-in"},
  {"id":"mb-1296","type":"sort","hook":"Sort: an honest thing to say about settling, or a comparison trap?","items":[{"id":"a","text":"\"Some days are good, some are hard\""},{"id":"b","text":"\"Everyone's thriving except me\""},{"id":"c","text":"\"I'm slowly finding my way\""},{"id":"d","text":"\"I'm the only one homesick\""},{"id":"e","text":"\"I'll get there in my own time\""},{"id":"f","text":"\"Their photos prove they're fine\""}],"bins":[{"id":"honest","label":"Honest","valence":"pos"},{"id":"trap","label":"Comparison trap","valence":"neg"}],"key":{"a":"honest","b":"trap","c":"honest","d":"trap","e":"honest","f":"trap"},"relearn":"Honest 'good and hard days' talk helps; 'everyone but me' and 'their photos prove it' are comparison traps.","persona":"any","source":"honest vs trap","cat":"settling-in"},
  {"id":"mb-1297","type":"sort","hook":"Sort: eases the move for an off-campus worker, or piles it on?","items":[{"id":"a","text":"Finding one friendly face at work"},{"id":"b","text":"Working every hour, no rest"},{"id":"c","text":"A small routine on your day off"},{"id":"d","text":"Never calling anyone back home"},{"id":"e","text":"Knowing a helpline you can call"},{"id":"f","text":"Telling yourself struggling is shameful"}],"bins":[{"id":"eases","label":"Eases the move","valence":"pos"},{"id":"piles","label":"Piles it on","valence":"neg"}],"key":{"a":"eases","b":"piles","c":"eases","d":"piles","e":"eases","f":"piles"},"relearn":"A friendly face, a rest day, staying in touch and knowing a helpline ease the move; overwork and shame pile it on.","persona":"Meena","source":"off-campus settling","cat":"settling-in"},
  {"id":"mb-1298","type":"sort","hook":"Sort: a sign you're slowly settling, or a sign it's still early days?","items":[{"id":"a","text":"Knowing a couple of names now"},{"id":"b","text":"Still getting lost on campus"},{"id":"c","text":"Having one go-to chai spot"},{"id":"d","text":"Not sure where anything is yet"},{"id":"e","text":"A small routine taking shape"},{"id":"f","text":"Everything still feeling new"}],"bins":[{"id":"settling","label":"Slowly settling","valence":"pos"},{"id":"early","label":"Still early days","valence":"neutral"}],"key":{"a":"settling","b":"early","c":"settling","d":"early","e":"settling","f":"early"},"relearn":"Knowing names, a go-to spot and a forming routine are signs you're settling; still getting lost just means it's early days.","persona":"any","source":"signs of settling","cat":"settling-in"},
  {"id":"mb-1299","type":"sort","hook":"Sort: a gentle response to a wobbly day, or a self-critical one?","items":[{"id":"a","text":"\"A wobbly day is allowed\""},{"id":"b","text":"\"I'm so weak for struggling\""},{"id":"c","text":"\"I'll be kinder to myself today\""},{"id":"d","text":"\"I should have this sorted\""},{"id":"e","text":"\"Tomorrow can be different\""},{"id":"f","text":"\"Everyone would cope better than me\""}],"bins":[{"id":"gentle","label":"Gentle","valence":"pos"},{"id":"critical","label":"Self-critical","valence":"neg"}],"key":{"a":"gentle","b":"critical","c":"gentle","d":"critical","e":"gentle","f":"critical"},"relearn":"Allowing a wobbly day and being kinder helps; calling yourself weak or saying everyone copes better doesn't.","persona":"any","source":"wobbly day","cat":"settling-in"},
  {"id":"mb-1300","type":"spot","hook":"Spot the two harsh, untrue things in this week-one pep talk to catch and drop.","relearn":"Settling takes time; a slow, wobbly start is normal, not a verdict on you.","persona":"any","source":"pep talk","scene":[{"id":"a","text":"\"It's only been a week; give it time\"","trick":false},{"id":"b","text":"\"If I were better I'd have friends by now\"","trick":true},{"id":"c","text":"\"Most people find this start hard\"","trick":false},{"id":"d","text":"\"I've already failed at this\"","trick":true},{"id":"e","text":"\"One small step at a time is fine\"","trick":false}],"why":"'I'd have friends if I were better' and 'I've already failed' are harsh and untrue; a slow start is normal.","cat":"settling-in"},
  {"id":"mb-1301","type":"spot","hook":"Spot the two draining moves on a low homesick night to catch.","relearn":"Connection, food and a small plan ease a low night; isolating and bottling up drain it.","persona":"any","source":"low night moves","scene":[{"id":"a","text":"Calling a friend for ten minutes","trick":false},{"id":"b","text":"Skipping dinner to lie in the dark","trick":true},{"id":"c","text":"Making a small plan for tomorrow","trick":false},{"id":"d","text":"Bottling it all up alone","trick":true},{"id":"e","text":"A short walk to clear your head","trick":false}],"why":"Skipping food to lie in the dark and bottling it up alone drain you; calling, planning and a walk ease the night.","cat":"settling-in"},
  {"id":"mb-1302","type":"spot","hook":"Spot the two comparison traps when you scroll others' college photos.","relearn":"Confident posts hide a wobble; you're comparing your insides to their outsides.","persona":"any","source":"scrolling photos","scene":[{"id":"a","text":"\"Their highlights aren't the whole story\"","trick":false},{"id":"b","text":"\"Everyone but me has it figured out\"","trick":true},{"id":"c","text":"\"Photos show the good bits, not the hard\"","trick":false},{"id":"d","text":"\"I'm the only one struggling\"","trick":true},{"id":"e","text":"\"Most are quietly finding it hard too\"","trick":false}],"why":"'Everyone but me' and 'only one struggling' are the traps; posts show highlights, not the hard parts.","cat":"settling-in"},
  {"id":"mb-1303","type":"spot","hook":"Spot the two unfair things you tell yourself about asking for help.","relearn":"Needing help finding your feet somewhere new is normal; asking is sensible, not weak.","persona":"Deepak","source":"asking for help","scene":[{"id":"a","text":"\"Everyone needs help somewhere new\"","trick":false},{"id":"b","text":"\"Asking means I don't belong here\"","trick":true},{"id":"c","text":"\"It's fine to not know my way yet\"","trick":false},{"id":"d","text":"\"A real student would manage alone\"","trick":true},{"id":"e","text":"\"People are usually glad to point the way\"","trick":false}],"why":"'Asking means I don't belong' and 'a real student manages alone' are unfair; needing help somewhere new is normal.","cat":"settling-in"},
  {"id":"mb-1304","type":"spot","hook":"Spot the two things in this list that isolate you rather than help you settle.","relearn":"Small social steps and routine help you settle; hiding away and refusing invites isolate you.","persona":"any","source":"settle or isolate","scene":[{"id":"a","text":"Joining the floor's chai run","trick":false},{"id":"b","text":"Eating every meal alone in your room","trick":true},{"id":"c","text":"Saying hi to your lab partner","trick":false},{"id":"d","text":"Turning down every single invite","trick":true},{"id":"e","text":"Going to one club this week","trick":false}],"why":"Eating every meal alone and declining every invite isolate you; the chai run, a hello and a club help you settle.","cat":"settling-in"},
  {"id":"mb-1305","type":"spot","hook":"Spot the two myths about homesickness to catch and rewrite.","relearn":"Homesickness is a normal, common reaction to a big change that eases as you settle.","persona":"any","source":"homesickness myths","scene":[{"id":"a","text":"\"Homesickness is a normal reaction to a big change\"","trick":false},{"id":"b","text":"\"Missing home means I'm weak\"","trick":true},{"id":"c","text":"\"Almost everyone feels it leaving home\"","trick":false},{"id":"d","text":"\"I'm the only one this homesick\"","trick":true},{"id":"e","text":"\"It usually eases as I settle in\"","trick":false}],"why":"'Missing home means I'm weak' and 'only one this homesick' are the myths; homesickness is common and eases.","cat":"settling-in"},
  {"id":"mb-1306","type":"spot","hook":"Spot the two unfair expectations to drop from your first-month checklist.","relearn":"A first month is for finding your feet slowly; instant ease and zero struggle aren't fair to expect.","persona":"any","source":"first-month checklist","scene":[{"id":"a","text":"\"Some days will feel hard, and that's okay\"","trick":false},{"id":"b","text":"\"I should feel fully at home by now\"","trick":true},{"id":"c","text":"\"I'm allowed to still be settling\"","trick":false},{"id":"d","text":"\"I must have a big friend group already\"","trick":true},{"id":"e","text":"\"Finding my feet slowly is fine\"","trick":false}],"why":"'Fully at home by now' and 'big friend group already' are unfair this early; settling slowly is fine.","cat":"settling-in"},
  {"id":"mb-1307","type":"spot","hook":"Spot the two unkind responses to a wobbly settling-in day to catch.","relearn":"A wobbly day calls for kindness and a small step, not self-blame or going home in your head.","persona":"any","source":"wobbly-day responses","scene":[{"id":"a","text":"\"A hard day is allowed; tomorrow can differ\"","trick":false},{"id":"b","text":"\"I'm clearly not cut out for this\"","trick":true},{"id":"c","text":"\"Let me do one small kind thing\"","trick":false},{"id":"d","text":"\"I should just give up and go home\"","trick":true},{"id":"e","text":"\"Wobbly days are part of settling\"","trick":false}],"why":"'Not cut out for this' and 'give up and go home' are unkind and untrue on a normal wobbly day.","cat":"settling-in"},
  {"id":"mb-1308","cat":"settling-in","type":"role-play","persona":"any","source":"honest answer","hook":"It's been a rough week of missed classes and lonely evenings.","setup":"After class, Dev from your course stops you in the corridor.","steps":[{"prompt":"Dev asks: \"Hey! How are you settling in?\"","options":[{"text":"\"Yeah, all good here. No problems at all, really.\"","then":"\"Lucky,\" Dev says, a little wistful, and heads off."},{"text":"\"Why, do I look that bad?\"","then":"Dev steps back. \"No, no! Just asking.\""},{"text":"\"Honestly, it's a mixed bag. Still settling. You?\"","then":"Dev laughs. \"Mixed bag is right. I've cried twice this week.\"","best":true},{"text":"\"Okay, I guess. Anyway, did you finish the assignment?\"","then":"Dev talks about the assignment, and the moment passes."}],"why":"Being honest about the mix invites a real answer back, and a real connection."},{"prompt":"Later that week, Dev says: \"A few of us are getting late-night chai at the canteen. Coming?\"","options":[{"text":"\"Nah, I'm fine on my own.\"","then":"\"Suit yourself,\" he says with a shrug."},{"text":"\"Maybe. If I'm not too tired.\"","then":"You're too tired, of course. Later, their canteen selfies fill the class group."},{"text":"\"Only if it's not a big crowd.\"","then":"\"It's four people,\" Dev says. \"Small enough?\""},{"text":"\"Yes. I could use the company.\"","then":"\"Ten o'clock at the canteen,\" Dev says. \"First chai's on me.\"","best":true}],"why":"Saying yes, and why, lets people show up for you."},{"prompt":"The next day, Dev asks: \"Do you think it ever gets easier?\"","options":[{"text":"\"I think so. Talking like this already helps.\"","then":"Dev nods. \"Yeah. Same time next week?\"","best":true},{"text":"\"No idea. I just try not to think about it.\"","then":"\"Right,\" Dev says, and neither of you says more."},{"text":"\"For you, maybe. You seem fine.\"","then":"\"I'm really not,\" Dev says quietly."},{"text":"\"It has to. Just push through, right?\"","then":"\"I guess,\" he says, not sounding sure."}],"why":"Naming what helps, like talking, keeps a real connection going."}],"relearn":"Being honest that it's a mix invites real connection more than 'all good' does."},
  {"id":"mb-1309","cat":"settling-in","type":"role-play","persona":"any","source":"warm opener","hook":"You'd like to get to know Sneha from your class, but you feel shy.","setup":"You spot her alone at a library table.","steps":[{"prompt":"Sneha glances up as you pass and says: \"Oh, hi.\"","options":[{"text":"\"Hi. Mind if I sit here? I'm still finding my way.\"","then":"Sneha moves her bag. \"Sure. It took me three weeks to find this spot.\"","best":true},{"text":"\"Oh, sorry. Didn't mean to disturb you.\"","then":"\"No problem,\" Sneha says, and goes back to her book."},{"text":"\"Just looking for a free table.\"","then":"\"There's one there,\" Sneha says, pointing, and looks back down."},{"text":"\"Hi! So what are you doing this weekend?\"","then":"Sneha blinks. \"Um, not sure yet.\" She turns back to her notes."}],"why":"A simple, warm opener is enough. You don't need the perfect line."},{"prompt":"Next day in class, Sneha says: \"Did you get any of today's lecture?\"","options":[{"text":"\"Totally. It was easy.\"","then":"\"Oh,\" she says. \"Maybe it's just me, then.\""},{"text":"\"Barely. Want to go through it together after?\"","then":"\"Please,\" she says. \"Canteen at 4?\"","best":true},{"text":"\"Not really. Anyway, see you.\"","then":"\"Oh. Okay, see you,\" she says, and packs up."},{"text":"\"No. I'm completely hopeless at this subject anyway.\"","then":"\"You're not,\" she says, unsure what else to say."}],"why":"Sharing the struggle and suggesting a small plan turns a chat into a connection."},{"prompt":"A week later, Sneha says: \"Some of us are going for a movie on Saturday. Coming?\"","options":[{"text":"\"I'll only be boring company.\"","then":"\"You won't,\" she says. \"Think about it.\""},{"text":"\"Maybe. I'll see how my week looks.\"","then":"\"Okay,\" she says. By Friday, the plan is full."},{"text":"\"Yes, I'd like that. Which one?\"","then":"\"The new Malayalam one,\" she says. \"Six o'clock show.\"","best":true},{"text":"\"Movies aren't really my thing.\"","then":"\"Oh, okay,\" Sneha says. \"Maybe something else next time.\""}],"why":"Saying yes to small invites is how belonging grows."}],"relearn":"A simple, warm opener is enough to start a connection. You don't need the perfect line."},
  {"id":"mb-1310","cat":"settling-in","type":"role-play","persona":"Deepak","source":"reassure parents","hook":"Your parents call, anxious, needing to hear that everything here is perfect.","setup":"Your mother is on the line, your father close by.","steps":[{"prompt":"Your mother asks: \"Is everything perfect there? Tell me the truth.\"","options":[{"text":"\"Everything's perfect, Ma. Honestly, don't worry at all.\"","then":"\"Really?\" she says. She sounds relieved, and you feel oddly alone."},{"text":"\"It's an adjustment. Some days are hard, but I'm okay.\"","then":"Your mother exhales. \"Hard how? Are you eating?\"","best":true},{"text":"\"Why do you always assume something's wrong?\"","then":"\"Because you sound tired,\" she says quietly."},{"text":"\"It's fine. How are things at home?\"","then":"She talks about the neighbours for ten minutes."}],"why":"Honest and reassuring lets them worry less without you pretending."},{"prompt":"Your father asks: \"Should one of us come there? Or should you come home for a bit?\"","options":[{"text":"\"No! You'll embarrass me in front of everyone here.\"","then":"A hurt silence. \"We only wanted to help.\""},{"text":"\"Don't even think of it. Everything's perfect here.\"","then":"\"Then why do you sound so tired?\" he asks."},{"text":"\"No need. I'm finding my feet. I'll call if I need you.\"","then":"\"Okay,\" he says. \"But call us Sunday, no excuses.\"","best":true},{"text":"\"Let me think about it properly and call you back tomorrow.\"","then":"You don't call back. They call twice more that evening."}],"why":"Being honest and clear about what you need lets them trust you're okay."},{"prompt":"On Sunday, your mother asks: \"And friends? Have you made any friends?\"","options":[{"text":"\"Loads! I'm out with them almost every night.\"","then":"\"Every night? And studies?\" she asks, now worried in a new way."},{"text":"\"None. I don't really need friends here anyway.\"","then":"She goes quiet, then asks if she should come after all."},{"text":"\"One or two. It's slow, but they're good people.\"","then":"\"One or two good ones is plenty,\" she says, and you hear her smile.","best":true},{"text":"\"Ma, I don't want to talk about that.\"","then":"\"Okay,\" she says, sounding hurt."}],"why":"The honest middle, slow but okay, is reassuring and true."}],"relearn":"You can reassure them and be honest it's an adjustment without pretending it's flawless."},
  {"id":"mb-1311","cat":"settling-in","type":"role-play","persona":"any","source":"accept invite","hook":"You've been studying alone all term, and groups make you nervous.","setup":"After the lab, your classmate Mihir catches up.","steps":[{"prompt":"Mihir asks: \"A few of us study together on Thursdays. Want to join?\"","options":[{"text":"\"Maybe some other time.\"","then":"\"Sure,\" Mihir says. \"Offer stands. Thursdays, 6.\""},{"text":"\"Yeah, I'd like that. Thanks for asking.\"","then":"\"Great,\" Mihir says. \"Room 204, 6 p.m.\"","best":true},{"text":"\"I'd only slow you all down, honestly.\"","then":"\"You won't,\" he says. \"We're all lost anyway.\""},{"text":"\"Could you just send me your notes instead?\"","then":"\"Ha, sure,\" Mihir says. \"But the group's more fun. Thursdays, 6.\""}],"why":"Saying yes, even nervous, is how belonging starts to grow."},{"prompt":"On Thursday, Mihir texts: \"We're starting in ten. You coming?\"","options":[{"text":"\"Something came up, sorry.\"","then":"\"No worries,\" he replies. You spend the evening alone with the notes."},{"text":"\"I'll try to make the next one.\"","then":"\"Cool,\" he replies. The next one comes and goes too."},{"text":"\"On my way. Save me a seat.\"","then":"\"Done,\" he replies. You walk in to four tired, friendly faces.","best":true},{"text":"\"Who else is there? I'll decide after.\"","then":"He sends four names you barely know. The nerves spike."}],"why":"Showing up the first time is the hardest step, and the one that counts."},{"prompt":"The next week, Mihir says: \"Some of us are getting dinner after Thursday's session. Come?\"","options":[{"text":"\"No thanks. Studying is enough for me.\"","then":"\"Okay,\" he says. The group heads out without you."},{"text":"\"Only if you're sure the others want me.\"","then":"\"Of course they do,\" he says, a little puzzled."},{"text":"\"Maybe. I'll see how I feel on Thursday.\"","then":"\"Okay,\" Mihir says. By Thursday, you've talked yourself out of it."},{"text":"\"Yes, count me in. Thanks for including me.\"","then":"\"Good,\" Mihir says. \"It's biryani night.\"","best":true}],"why":"Each small yes grows a real connection."}],"relearn":"Saying yes to a low-stakes invite, even nervous, is how belonging starts to grow."},
  {"id":"mb-1312","cat":"settling-in","type":"role-play","persona":"any","source":"shared struggle","hook":"You've just met Pooja at the campus laundry, both of you waiting for machines.","setup":"She sighs and leans against the wall.","steps":[{"prompt":"Pooja says: \"Honestly, this first month has been tough for me.\"","options":[{"text":"\"Yeah, well, it's college. Everyone just has to toughen up.\"","then":"She nods slowly. \"Maybe. It still gets to me at night, though.\""},{"text":"\"Oh, I've been totally fine. Busy day?\"","then":"\"Oh. Good for you,\" she says, a little flat."},{"text":"\"Same here, honestly. It's good to know it's not just me.\"","then":"Pooja laughs, relieved. \"Oh thank God. I thought everyone else was fine.\"","best":true},{"text":"\"Really? You seem so confident.\"","then":"\"It's an act,\" she says with a small smile."}],"why":"Naming your own struggle back makes the moment real and two-way."},{"prompt":"Pooja asks: \"Do you ever miss home so much it's hard to sleep?\"","options":[{"text":"\"Never. I'm not really the homesick type.\"","then":"\"Oh,\" she says, and looks away."},{"text":"\"All the time. I think I'm just weak or something.\"","then":"\"You're not weak,\" she says. \"It's hard for everyone.\""},{"text":"\"Yes, some nights. What helps you on those nights?\"","then":"\"Calling my sister,\" Pooja says. \"And bad chai at the canteen.\"","best":true},{"text":"\"Sometimes, yeah. Anyway, which course are you in?\"","then":"\"Economics,\" she says. The talk drifts to timetables."}],"why":"Sharing honestly and asking back builds real connection."},{"prompt":"As the machine beeps, Pooja says: \"We should get chai sometime.\"","options":[{"text":"\"Yes. Tomorrow after class?\"","then":"\"Perfect,\" she says, saving your number.","best":true},{"text":"\"Sure, sometime. I'll let you know.\"","then":"\"Okay,\" she says. Weeks pass, and you only ever wave in passing."},{"text":"\"Only if others come. I'm awkward one on one.\"","then":"\"Oh. Sure,\" she says, a little thrown. \"I'll see who's free.\""},{"text":"\"You don't have to be nice. It's okay.\"","then":"\"I'm not being nice,\" she laughs. \"I mean it.\""}],"why":"Turning 'sometime' into a real plan is how a moment becomes a friendship."}],"relearn":"Naming your own struggle back turns a small moment into real, both-ways connection."},
  {"id":"mb-1313","cat":"settling-in","type":"role-play","persona":"Rohan","source":"let someone in","hook":"You've been low and quiet for days, skipping the gym and dinner.","setup":"Your roommate Aditya pauses his game.","steps":[{"prompt":"Aditya asks: \"You've been off for days. You okay?\"","options":[{"text":"\"I'm fine. Leave it.\"","then":"\"Okay,\" he says, and turns back to the screen."},{"text":"\"Just tired. Nothing a gym session won't fix.\"","then":"\"You haven't been to the gym in a week,\" he says."},{"text":"\"Whining won't fix it. I'll handle it myself.\"","then":"Aditya raises an eyebrow. \"Who says it's whining?\""},{"text":"\"Not my best week, honestly. Still settling in.\"","then":"Aditya puts the controller down. \"Yeah? Same, kind of. Talk?\"","best":true}],"why":"Letting one person in when you're low is strength, not weakness."},{"prompt":"Later, Aditya says: \"You don't have to talk. But want to grab food?\"","options":[{"text":"\"Nah. I'll eat later. Or not.\"","then":"He shrugs and heads out alone. The room goes quiet."},{"text":"\"Yeah. And maybe I will talk a bit.\"","then":"Over dosa, the week comes out in pieces. Aditya just listens.","best":true},{"text":"\"Only if we don't talk about anything real.\"","then":"\"Deal,\" he says. You eat, talk cricket, and the weight stays."},{"text":"\"Why are you being so nice? Weird.\"","then":"\"It's called being a friend,\" he says, grabbing his keys."}],"why":"Saying yes to company, and a little honesty, helps more than going it alone."},{"prompt":"A few days later, Aditya says: \"If it keeps feeling heavy, maybe talk to the counsellor?\"","options":[{"text":"\"Counsellors are for people who can't cope.\"","then":"\"I went last year,\" Aditya says quietly. \"It helped.\""},{"text":"\"Maybe. I'll look up how to book one.\"","then":"\"I'll come with you if you want,\" he says.","best":true},{"text":"\"I'll be fine. You're enough.\"","then":"\"Glad I can help,\" he says. \"But I'm not a professional.\""},{"text":"\"Are you saying something's wrong with me?\"","then":"\"No,\" he says. \"Just that you don't have to do it alone.\""}],"why":"Being open to a counsellor is strength. Support works best with more than one person."},{"prompt":"A week later, Aditya asks: \"How are you doing, really? Still heavy?\"","options":[{"text":"\"Stop asking. I told you I'm fine.\"","then":"Aditya holds his hands up. \"Okay. Just checking.\""},{"text":"\"Heavy. But I don't want to keep dumping it on you.\"","then":"\"You're not dumping,\" he says. \"But okay, if you're sure.\""},{"text":"\"Up and down. Want to get food tonight?\"","then":"\"Dosa place?\" Aditya says, pulling on his shoes.","best":true},{"text":"\"All good now. Back to the grind.\"","then":"\"Cool,\" he says, not quite convinced."}],"why":"Asking for company again, honestly, keeps the support going."}],"relearn":"Letting one person in when you're low beats brushing it off and staying alone with it."},
  {"id":"mb-1314","cat":"settling-in","type":"role-play","persona":"Zoya","source":"gentle boundary","hook":"Your relatives want a report from you every day, and you need some room to settle.","setup":"Everyone at the family lunch crowds the screen.","steps":[{"prompt":"Your aunt says: \"No message yesterday! We were so worried. What happened?\"","options":[{"text":"\"Sorry, sorry! I'll message you every morning from now on.\"","then":"\"That's better,\" she beams. The whole table cheers."},{"text":"\"Nothing happened, Khala. I'm fine, just busy settling.\"","then":"\"Busy is good,\" she says. \"But one line is enough for us.\"","best":true},{"text":"\"I don't have to report to you every day.\"","then":"The table goes silent. Someone mutters, \"College attitude.\""},{"text":"\"Sorry, the network here is terrible.\"","then":"\"Then use the Wi-Fi!\" she laughs. \"And message tonight.\""}],"why":"Reassuring them simply, without over-apologising, sets up the boundary kindly."},{"prompt":"Your aunt says: \"Your cousin sends a photo every day. Why can't you?\"","options":[{"text":"\"Fine. I'll send a photo every single day, then.\"","then":"The group fills with thumbs-ups. Your mornings now start with a photo."},{"text":"\"Can you please stop comparing me to her? It's exhausting.\"","then":"Her smile drops. \"We only ask because we care.\""},{"text":"\"I'll check in every few days while I settle. Love you.\"","then":"She hesitates. \"Every few days? Hm. Alright, but no skipping.\"","best":true},{"text":"\"Maybe. If I remember and have time, I'll try.\"","then":"\"Not maybe. Daily!\" she says, laughing but firm."}],"why":"A warm, clear plan gives you room and still keeps the family close."},{"prompt":"A week later, your mother calls: \"Your aunt keeps asking about you. Are you really okay?\"","options":[{"text":"\"She's overreacting. Just ignore her.\"","then":"\"Don't talk about your aunt like that,\" Ammi says."},{"text":"\"Tell her I'll message daily. Whatever keeps the peace.\"","then":"\"Good,\" Ammi says, relieved. Your own space feels a little smaller."},{"text":"\"I'm okay, Ammi. I just need room to settle in.\"","then":"\"Okay,\" Ammi says. \"I'll tell her. Call me Sunday?\"","best":true},{"text":"\"I'm fine. Nothing to talk about.\"","then":"\"Hmm,\" Ammi says. She doesn't sound convinced."}],"why":"Explaining the boundary warmly to someone close helps it hold."}],"relearn":"A warm, firm boundary protects your space without rupturing the relationship."},
  {"id":"mb-1315","type":"match","hook":"Match each settling-in worry to the kinder, truer reframe.","relearn":"Most settling-in worries have a kind, true reframe; you're not failing, you're adjusting.","persona":"any","source":"worry to reframe","pairs":[{"left":"\"I have no friends yet\"","right":"\"Real friendships take time to grow\""},{"left":"\"I'm so homesick\"","right":"\"Missing home is normal, not weakness\""},{"left":"\"Everyone's settled but me\"","right":"\"Most are quietly finding it hard too\""},{"left":"\"I should feel at home by now\"","right":"\"There's no deadline on belonging\""},{"left":"\"A bad week means I chose wrong\"","right":"\"One rough week isn't the whole year\""}],"cat":"settling-in"},
  {"id":"mb-1316","type":"match","hook":"Match each homesick moment to a small healthy step that helps.","relearn":"Small healthy steps, connection and routine ease homesickness more than waiting it out alone.","persona":"any","source":"moment to step","pairs":[{"left":"Missing your family at night","right":"A short call with someone you trust"},{"left":"Days with no shape","right":"Set one small routine anchor"},{"left":"Stuck inside, low energy","right":"Step out for a short walk"},{"left":"Feeling cut off from everyone","right":"Say yes to one small invite"},{"left":"Dreading tomorrow","right":"Plan one small thing to look forward to"}],"cat":"settling-in"},
  {"id":"mb-1317","type":"match","hook":"Match each settling feeling to who can help with it.","relearn":"Different feelings have different go-to people; you don't have to face any of it alone.","persona":"any","source":"feeling to helper","pairs":[{"left":"Heavy low mood for weeks","right":"A campus counsellor"},{"left":"Just need to vent about home","right":"A trusted friend or family member"},{"left":"Lost on where things are","right":"A friendly classmate or senior"},{"left":"Want to meet new people","right":"A club or student group"},{"left":"A hard moment late at night","right":"Tele-MANAS 14416, open all night"}],"cat":"settling-in"},
  {"id":"mb-1318","type":"match","hook":"Match each unhelpful self-talk line to its kinder rewrite.","relearn":"Swapping harsh self-talk for a kinder, truer line is a small move that protects how you settle.","persona":"any","source":"self-talk rewrite","pairs":[{"left":"\"I'm failing at this\"","right":"\"I'm still finding my feet\""},{"left":"\"I'm so weak for struggling\"","right":"\"Struggling at first is human\""},{"left":"\"I'll always feel this lost\"","right":"\"This tends to get better\""},{"left":"\"I should cope alone\"","right":"\"Reaching out is a smart move\""},{"left":"\"I don't belong here\"","right":"\"I earned my place here\""}],"cat":"settling-in"},
  {"id":"mb-1319","type":"match","hook":"Match each first-week task to why it helps you settle.","relearn":"Small concrete first-week tasks build the routine and connection that settling needs.","persona":"any","source":"task to why","pairs":[{"left":"Learning your way around","right":"The place stops feeling alien"},{"left":"Finding a regular meal time","right":"Your days get a steadying rhythm"},{"left":"Saying hi to one person","right":"A first thread of connection starts"},{"left":"Joining one group","right":"Belonging gets a place to grow"},{"left":"Keeping in touch with home","right":"You stay supported while you adjust"}],"cat":"settling-in"},
  {"id":"mb-1320","type":"match","hook":"Match each normal settling-in sign to the signal that means reach out instead.","relearn":"Knowing normal from a signal helps you settle without missing when it's time to reach for help.","persona":"any","source":"normal vs signal pairs","pairs":[{"left":"A few homesick evenings","right":"Heavy low mood for weeks"},{"left":"Taking time to make friends","right":"Losing all interest in everything"},{"left":"Nerves before something new","right":"Dreading every day for weeks"},{"left":"An occasional bad night's sleep","right":"Barely sleeping for weeks"},{"left":"Missing home now and then","right":"Crying most days and can't stop"}],"cat":"settling-in"},
  {"id":"mb-1321","type":"match","hook":"Match each person's first-week wobble to a step that helps them belong.","relearn":"Whatever the wobble, a small step toward people and routine helps belonging grow.","persona":"any","source":"wobble to step","pairs":[{"left":"Too shy to speak first","right":"A simple, warm opener is enough"},{"left":"Feels like an outsider","right":"Remember most feel that at first"},{"left":"No campus community around","right":"Build one connection at work or nearby"},{"left":"Family pressure piling on","right":"Set a gentle boundary and widen support"},{"left":"Drifting into isolation","right":"Take one small step to reconnect"}],"cat":"settling-in"},
  {"id":"mb-1322","type":"match","hook":"Match each settling-in myth to the truth that replaces it.","relearn":"Each settling myth has a truth that lifts the weight; you're adjusting, not failing.","persona":"any","source":"myth to truth","pairs":[{"left":"\"Tougher people don't find it hard\"","right":"\"A hard start is normal\""},{"left":"\"I should have friends by now\"","right":"\"Connections take time\""},{"left":"\"Calling home means I'm not grown up\"","right":"\"Staying connected is healthy\""},{"left":"\"A bad first week means leave\"","right":"\"Give settling time first\""},{"left":"\"Feeling low means I'm ungrateful\"","right":"\"Grateful and finding it hard both fit\""}],"cat":"settling-in"},
  {"id":"mb-1350","cat":"tools-and-help","type":"match","hook":"Match the everyday wobble to a tool that fits it.","relearn":"A tool fits the moment: breathe to calm, walk to unstick, talk to lighten, sleep to reset.","persona":"any","source":"tool-to-moment","pairs":[{"left":"Heart racing before a viva","right":"Three slow breaths"},{"left":"Stuck and foggy at your desk","right":"A short walk outside"},{"left":"Carrying it all alone","right":"Telling a trusted person"},{"left":"Wired and can't switch off","right":"Winding down for sleep"},{"left":"Don't know where to turn","right":"Tele-MANAS 14416"}]},
  {"id":"mb-1351","cat":"tools-and-help","type":"match","hook":"Match the support route to who it's for.","relearn":"On-campus, off-campus, free-line and crisis routes each suit a different moment.","persona":"any","source":"route picker","pairs":[{"left":"A student wanting on-campus help","right":"The campus counsellor"},{"left":"A worker with no campus","right":"Tele-MANAS 14416"},{"left":"A life in danger, right now","right":"Emergency 112"},{"left":"A quiet daily check-in","right":"A trusted friend"},{"left":"A 3am low that won't lift","right":"A free 24/7 line"}]},
  {"id":"mb-1352","cat":"tools-and-help","type":"match","hook":"Match what you'd say to who you'd say it to.","relearn":"You can open simply: a friend, a counsellor, a helpline each take an honest first line.","persona":"any","source":"opening lines","pairs":[{"left":"To a close friend","right":"\"Can we talk? I'm not okay.\""},{"left":"To a campus counsellor","right":"\"I've been low for weeks.\""},{"left":"To a helpline","right":"\"I just need someone to talk to.\""},{"left":"To a worried roommate","right":"\"Thanks for noticing, you're right.\""},{"left":"To yourself, first","right":"\"It's okay to need help.\""}]},
  {"id":"mb-1353","cat":"tools-and-help","type":"match","hook":"Match the helpline fact to why it matters.","relearn":"Tele-MANAS is free, 24/7, in many languages, and for everyday stress too: no problem is too small.","persona":"any","source":"line facts","pairs":[{"left":"It costs nothing","right":"Money is never the barrier"},{"left":"It runs day and night","right":"3am is covered too"},{"left":"Many Indian languages","right":"Talk in the one that's yours"},{"left":"Everyday stress counts","right":"No problem is too small"},{"left":"The number to save","right":"Tele-MANAS 14416"}]},
  {"id":"mb-1354","cat":"tools-and-help","type":"match","hook":"Match the grounding step to what it does in the moment.","relearn":"5-4-3-2-1, slow breaths, cold water and feet-on-floor each pull you back to now.","persona":"any","source":"grounding kit","pairs":[{"left":"Name 5 things you can see","right":"Pulls you out of the spiral"},{"left":"Breathe out slower than in","right":"Settles a racing heart"},{"left":"Cold water on your wrists","right":"A quick body reset"},{"left":"Press your feet to the floor","right":"Anchors you to now"},{"left":"Unclench your jaw and shoulders","right":"Lets tension drain"}]},
  {"id":"mb-1355","cat":"tools-and-help","type":"match","hook":"Match the late-night low to a healthy next step.","relearn":"Even at the worst hour there's a step: breathe, message someone, or call a 24/7 line.","persona":"any","source":"hard-hour map","pairs":[{"left":"Mind racing at midnight","right":"A few slow breaths"},{"left":"Feeling utterly alone","right":"Message one trusted person"},{"left":"It feels too big tonight","right":"Call Tele-MANAS 14416"},{"left":"Can't stop the scrolling","right":"Put the phone down, lie still"},{"left":"Tears out of nowhere","right":"Let them come, you're safe"}]},
  {"id":"mb-1356","cat":"tools-and-help","type":"match","hook":"Match each part of a simple safety plan.","relearn":"A plan has three parts: a coping step, a trusted person, and a helpline you've saved.","persona":"any","source":"safety plan","pairs":[{"left":"A coping step you trust","right":"Breathe, walk, or call someone"},{"left":"A person who'd pick up","right":"A friend, sibling or mentor"},{"left":"A line saved in your phone","right":"Tele-MANAS 14416"},{"left":"A calmer place to go","right":"The library, a park, a balcony"},{"left":"One kind line to yourself","right":"\"This feeling will pass.\""}]},
  {"id":"mb-1357","cat":"tools-and-help","type":"match","hook":"Deepak: match the cost worry to why it's no barrier.","relearn":"Real help in India can cost nothing: free lines, campus counsellors and trusted people.","persona":"Deepak","source":"no-cost help","pairs":[{"left":"\"Therapy is too expensive\"","right":"Tele-MANAS is free"},{"left":"\"I can't pay for sessions\"","right":"Campus counsellors are usually free"},{"left":"\"Calling will cost money\"","right":"Helpline calls are free"},{"left":"\"Help isn't for people like me\"","right":"These lines are for everyone"},{"left":"\"I'd need to travel far\"","right":"A call reaches help from your room"}]},
  {"id":"mb-1358","cat":"tools-and-help","type":"match","hook":"Match the myth about helplines to the real picture.","relearn":"Helplines aren't only for crises, aren't judgey, and you needn't have it all figured out first.","persona":"any","source":"line myths","pairs":[{"left":"\"Only for emergencies\"","right":"Everyday stress counts too"},{"left":"\"They'll judge me\"","right":"They're trained to listen, not judge"},{"left":"\"I must explain it perfectly\"","right":"\"I'm not okay\" is enough"},{"left":"\"It'll go on a record\"","right":"It's confidential support"},{"left":"\"One call won't help\"","right":"It's a real first step"}]},
  {"id":"mb-1359","cat":"tools-and-help","type":"match","hook":"Match the moment to whether it needs a pro or a quick tool.","relearn":"Quick tools steady a passing wobble; heavy, lasting distress is a pro's job.","persona":"any","source":"tool vs pro","pairs":[{"left":"Pre-exam jitters","right":"Breathe and reset"},{"left":"One rough, tiring day","right":"Rest and a good sleep"},{"left":"Weeks of heavy low mood","right":"Reach a professional"},{"left":"Losing all interest for a while","right":"Tele-MANAS 14416"},{"left":"A lonely Sunday","right":"Message someone, make a plan"}]},
  {"id":"mb-1360","cat":"tools-and-help","type":"match","hook":"Meena: match the off-campus reality to a help route that fits.","relearn":"With no campus safety net, Tele-MANAS 14416, a doctor and trusted people are your routes.","persona":"Meena","source":"off-campus routes","pairs":[{"left":"No campus counsellor near","right":"Tele-MANAS 14416"},{"left":"Long hours, little time","right":"A two-minute breathing reset"},{"left":"Far from family","right":"A regular call to someone you trust"},{"left":"A heavy stretch building up","right":"Seeing a doctor early"},{"left":"No private space to talk","right":"A quiet corner and a phone call"}]},
  {"id":"mb-1361","cat":"tools-and-help","type":"match","hook":"Match the breathing-space step to its order in a reset.","relearn":"A reset: pause, breathe slow, name what you feel, then choose one small next step.","persona":"any","source":"reset steps","pairs":[{"left":"Step one","right":"Pause and put down the phone"},{"left":"Step two","right":"Breathe out slowly, a few times"},{"left":"Step three","right":"Name what you're feeling"},{"left":"Step four","right":"Pick one small next thing"},{"left":"Any step, anytime","right":"It's okay to reach out"}]},
  {"id":"mb-1362","cat":"tools-and-help","type":"match","hook":"Match the warning sign to the steadier move it calls for.","relearn":"Signs like no sleep, no appetite or pulling away each have a healthy, doable response.","persona":"any","source":"sign-to-step","pairs":[{"left":"Not sleeping for days","right":"Wind-down routine, then talk to someone"},{"left":"Skipping meals, no appetite","right":"Small regular food, tell a friend"},{"left":"Pulling away from everyone","right":"One small reconnect"},{"left":"Heavy, constant low mood","right":"Reach Tele-MANAS 14416 today"},{"left":"Snapping at everyone","right":"A break, a walk, some rest"}]},
  {"id":"mb-1363","cat":"tools-and-help","type":"match","hook":"Match the worry about reaching out to a gentler truth.","relearn":"You needn't be in crisis, have perfect words, or carry it alone to deserve support.","persona":"any","source":"reach-out worries","pairs":[{"left":"\"I'm not bad enough yet\"","right":"You don't have to be in crisis"},{"left":"\"I'll waste their time\"","right":"No problem is too small"},{"left":"\"I won't know what to say\"","right":"\"I'm struggling\" is enough"},{"left":"\"I should handle it myself\"","right":"Everyone needs support sometimes"},{"left":"\"It's too late to ask\"","right":"It's never too late to reach out"}]},
  {"id":"mb-1364","cat":"tools-and-help","type":"match","hook":"Match the support person to what they're best for.","relearn":"Friends, mentors, counsellors and helplines each hold a different kind of support.","persona":"any","source":"who-for-what","pairs":[{"left":"A friend who gets you","right":"Day-to-day venting and company"},{"left":"A senior or mentor","right":"Practical college guidance"},{"left":"A campus counsellor","right":"Trained, confidential help"},{"left":"A 24/7 helpline","right":"Support at any hour"},{"left":"A warden or RA you trust","right":"A first nudge toward help"}]},
  {"id":"mb-1365","cat":"tools-and-help","type":"match","hook":"Match the small daily anchor to the wobble it cushions.","relearn":"Sleep, food, movement and a check-in are quiet anchors that make hard days less steep.","persona":"any","source":"daily anchors","pairs":[{"left":"A steady sleep time","right":"A foggy, short-fused morning"},{"left":"Regular meals","right":"The mid-afternoon crash"},{"left":"A daily walk","right":"A restless, stuck feeling"},{"left":"A quick self check-in","right":"Catching a low before it deepens"},{"left":"One message to a friend","right":"A creeping sense of alone"}]},
  {"id":"mb-1366","cat":"tools-and-help","type":"sort","hook":"Sort: a real first step toward help, or a dead end?","items":[{"id":"a","text":"Saving Tele-MANAS 14416 in your phone"},{"id":"b","text":"Telling yourself to just snap out of it"},{"id":"c","text":"Booking the campus counsellor"},{"id":"d","text":"Waiting till you 'hit rock bottom'"},{"id":"e","text":"Telling one trusted person"},{"id":"f","text":"Scrolling to avoid the feeling"}],"bins":[{"id":"step","label":"A real step","valence":"pos"},{"id":"dead","label":"A dead end","valence":"neg"}],"key":{"a":"step","b":"dead","c":"step","d":"dead","e":"step","f":"dead"},"relearn":"Saving a line, booking a counsellor or telling someone are real steps; waiting or avoiding aren't.","persona":"any","source":"first-step sort"},
  {"id":"mb-1367","cat":"tools-and-help","type":"sort","hook":"Sort: a healthy in-the-moment reset, or not a reset at all?","items":[{"id":"a","text":"Slow breaths, longer out-breath"},{"id":"b","text":"Replaying the worst thought on loop"},{"id":"c","text":"Stepping outside for two minutes"},{"id":"d","text":"Naming five things you can see"},{"id":"e","text":"Doomscrolling till it's worse"},{"id":"f","text":"Splashing cold water on your face"}],"bins":[{"id":"reset","label":"A reset","valence":"pos"},{"id":"noreset","label":"Not a reset","valence":"neg"}],"key":{"a":"reset","b":"noreset","c":"reset","d":"reset","e":"noreset","f":"reset"},"relearn":"Breath, fresh air, grounding and cold water reset you; looping thoughts and doomscrolling don't.","persona":"any","source":"reset sort"},
  {"id":"mb-1368","cat":"tools-and-help","type":"sort","hook":"Sort: a true thing about helplines, or a myth?","items":[{"id":"a","text":"They're free to call"},{"id":"b","text":"They're only for emergencies"},{"id":"c","text":"You can call about everyday stress"},{"id":"d","text":"They'll judge you for calling"},{"id":"e","text":"They run day and night"},{"id":"f","text":"You must have it all figured out first"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Helplines are free, 24/7, for everyday stress and don't judge: you needn't have it figured out.","persona":"any","source":"helpline truths"},
  {"id":"mb-1369","cat":"tools-and-help","type":"sort","hook":"Sort: belongs in your hard-day kit, or doesn't?","items":[{"id":"a","text":"A saved helpline number"},{"id":"b","text":"A promise to suffer in silence"},{"id":"c","text":"One trusted person to text"},{"id":"d","text":"A go-to breathing step"},{"id":"e","text":"A rule to never bother anyone"},{"id":"f","text":"A short walk you can take"}],"bins":[{"id":"in","label":"In the kit","valence":"pos"},{"id":"out","label":"Leave out","valence":"neg"}],"key":{"a":"in","b":"out","c":"in","d":"in","e":"out","f":"in"},"relearn":"A kit holds a line, a person, a breath and a walk, not rules to suffer in silence.","persona":"any","source":"kit sort"},
  {"id":"mb-1370","cat":"tools-and-help","type":"sort","hook":"Sort: needs a quick self-help tool, or a real professional?","items":[{"id":"a","text":"Nerves before a presentation"},{"id":"b","text":"Heavy low mood for weeks"},{"id":"c","text":"One tiring, off day"},{"id":"d","text":"Losing interest in everything"},{"id":"e","text":"A short lonely evening"},{"id":"f","text":"Constant dread that won't lift"}],"bins":[{"id":"tool","label":"A quick tool","valence":"pos"},{"id":"pro","label":"A professional","valence":"tell"}],"key":{"a":"tool","b":"pro","c":"tool","d":"pro","e":"tool","f":"pro"},"relearn":"Passing wobbles suit a quick tool; weeks-long heaviness or lost interest are a professional's job.","persona":"any","source":"tool-or-pro sort"},
  {"id":"mb-1371","cat":"tools-and-help","type":"sort","hook":"Rohan: sort what makes reaching out easier, or harder.","items":[{"id":"a","text":"\"Help-seeking is strength\""},{"id":"b","text":"\"Real men handle it alone\""},{"id":"c","text":"Saving a friend's number"},{"id":"d","text":"\"Talking is for the weak\""},{"id":"e","text":"Knowing one free helpline"},{"id":"f","text":"\"I'll deal with it never\""}],"bins":[{"id":"easier","label":"Makes it easier","valence":"pos"},{"id":"harder","label":"Makes it harder","valence":"neg"}],"key":{"a":"easier","b":"harder","c":"easier","d":"harder","e":"easier","f":"harder"},"relearn":"Help-seeking is strength for all genders; 'men handle it alone' only makes reaching out harder.","persona":"Rohan","source":"stigma sort"},
  {"id":"mb-1372","cat":"tools-and-help","type":"sort","hook":"Sort: a healthy way to use your phone in a low moment, or not?","items":[{"id":"a","text":"Texting a friend to meet"},{"id":"b","text":"Doomscrolling comparison feeds"},{"id":"c","text":"Calling Tele-MANAS 14416"},{"id":"d","text":"Refreshing who left you on read"},{"id":"e","text":"Opening a breathing app"},{"id":"f","text":"Stalking an ex at 2am"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"hurts","label":"Hurts","valence":"neg"}],"key":{"a":"helps","b":"hurts","c":"helps","d":"hurts","e":"helps","f":"hurts"},"relearn":"A phone can connect you or call a line, or deepen a low by scrolling and stalking. Choose connect.","persona":"any","source":"phone sort"},
  {"id":"mb-1373","cat":"tools-and-help","type":"sort","hook":"Sort: part of a calm wind-down, or wires you up more?","items":[{"id":"a","text":"Dimming the lights"},{"id":"b","text":"One more anxious news scroll"},{"id":"c","text":"Slow breaths in bed"},{"id":"d","text":"Replaying every mistake"},{"id":"e","text":"A warm drink, no screen"},{"id":"f","text":"Lying still, letting the day go"}],"bins":[{"id":"calms","label":"Calms you","valence":"pos"},{"id":"wires","label":"Wires you up","valence":"neg"}],"key":{"a":"calms","b":"wires","c":"calms","d":"wires","e":"calms","f":"calms"},"relearn":"Dim light, slow breath, a warm drink and stillness wind you down; scrolling and replaying wire you up.","persona":"any","source":"wind-down sort"},
  {"id":"mb-1374","cat":"tools-and-help","type":"spot","hook":"Spot the two lines that quietly push someone AWAY from help.","relearn":"\"Just be positive\" and \"don't make a fuss\" shut help down; naming, asking and routing open it.","persona":"any","source":"unhelpful lines","scene":[{"id":"a","text":"\"It's okay to not be okay\"","trick":false},{"id":"b","text":"\"Just think positive, you're fine\"","trick":true},{"id":"c","text":"\"Want me to sit with you while you call?\"","trick":false},{"id":"d","text":"\"Don't make a fuss, others have it worse\"","trick":true},{"id":"e","text":"\"There's a free line you can ring anytime\"","trick":false}],"why":"\"Just think positive\" and \"don't make a fuss\" dismiss the struggle; the others actually help."},
  {"id":"mb-1375","cat":"tools-and-help","type":"spot","hook":"Spot the two 'coping' moves that are really NOT coping.","relearn":"Real coping rests, talks and breathes; powering through on empty and numbing only drain you.","persona":"any","source":"fake coping","scene":[{"id":"a","text":"Going to bed on time","trick":false},{"id":"b","text":"Skipping sleep to power through","trick":true},{"id":"c","text":"Talking it out with a friend","trick":false},{"id":"d","text":"Numbing out to feel nothing","trick":true},{"id":"e","text":"A short walk to clear your head","trick":false}],"why":"Skipping sleep and numbing drain you, not steady you; rest, talk and a walk are real coping."},
  {"id":"mb-1376","cat":"tools-and-help","type":"spot","hook":"Spot the two helpline 'facts' that are actually false.","relearn":"Tele-MANAS is free, 24/7 and for everyday stress: it isn't paid, daytime-only or crisis-only.","persona":"any","source":"line fact-check","scene":[{"id":"a","text":"Tele-MANAS calls are free","trick":false},{"id":"b","text":"You have to pay per minute","trick":true},{"id":"c","text":"It runs 24 hours a day","trick":false},{"id":"d","text":"It only opens office hours","trick":true},{"id":"e","text":"Everyday stress is welcome","trick":false}],"why":"Tele-MANAS is free and 24/7; 'pay per minute' and 'office hours only' are the false claims."},
  {"id":"mb-1377","cat":"tools-and-help","type":"spot","hook":"Spot the two steps that DON'T belong in a safety plan.","relearn":"A plan holds a coping step, a person and a saved line, never 'tell no one' or 'wait it out alone'.","persona":"any","source":"plan check","scene":[{"id":"a","text":"A coping step you trust","trick":false},{"id":"b","text":"\"Tell absolutely no one\"","trick":true},{"id":"c","text":"One trusted person to call","trick":false},{"id":"d","text":"\"Just wait it out alone\"","trick":true},{"id":"e","text":"A helpline saved in your phone","trick":false}],"why":"\"Tell no one\" and \"wait it out alone\" are the opposite of a plan; the others are its real parts."},
  {"id":"mb-1378","cat":"tools-and-help","type":"spot","hook":"Rohan: spot the two manosphere lines that block help.","relearn":"Looking after your mind is strength for all genders; 'men don't talk' and 'just grind' block help.","persona":"Rohan","source":"stigma spot","scene":[{"id":"a","text":"\"Everyone has a mind to look after\"","trick":false},{"id":"b","text":"\"Real men don't talk about feelings\"","trick":true},{"id":"c","text":"\"Asking for help is a strong move\"","trick":false},{"id":"d","text":"\"Just grind, weakness is a choice\"","trick":true},{"id":"e","text":"\"You're allowed to not be okay\"","trick":false}],"why":"\"Real men don't talk\" and \"just grind\" shame help-seeking; the others make it strength."},
  {"id":"mb-1379","cat":"tools-and-help","type":"spot","hook":"Spot the two replies that AREN'T helping a low friend.","relearn":"Helping a friend means presence, listening and sharing a route, not minimising or vanishing.","persona":"any","source":"friend-reply spot","scene":[{"id":"a","text":"\"I'm here, take your time\"","trick":false},{"id":"b","text":"\"You're being dramatic\"","trick":true},{"id":"c","text":"\"Want me to share a helpline?\"","trick":false},{"id":"d","text":"Leaving them on read for days","trick":true},{"id":"e","text":"\"Let's grab chai and talk\"","trick":false}],"why":"\"Being dramatic\" and going silent abandon a friend; presence, a route and chai actually help."},
  {"id":"mb-1380","cat":"tools-and-help","type":"spot","hook":"Spot the two signs that say 'time to reach for real help'.","relearn":"A bad day passes; weeks of heavy low mood or losing all interest are signals to reach for help.","persona":"any","source":"signal spot","scene":[{"id":"a","text":"One tiring, off day","trick":false},{"id":"b","text":"Heavy low mood for weeks","trick":true},{"id":"c","text":"Nervous before a big exam","trick":false},{"id":"d","text":"Losing interest in everything","trick":true},{"id":"e","text":"A slow start to making friends","trick":false}],"why":"Weeks of heavy low mood and losing all interest are real signals; the others are normal wobbles."},
  {"id":"mb-1381","cat":"tools-and-help","type":"spot","hook":"Spot the two phone habits that deepen a low instead of easing it.","relearn":"A phone can call a line or a friend; doomscrolling and comparison feeds just deepen a low.","persona":"any","source":"phone spot","scene":[{"id":"a","text":"Calling a trusted person","trick":false},{"id":"b","text":"Doomscrolling for an hour","trick":true},{"id":"c","text":"Saving a helpline number","trick":false},{"id":"d","text":"Comparing yourself on feeds","trick":true},{"id":"e","text":"Texting a friend to meet up","trick":false}],"why":"Doomscrolling and comparison feeds deepen the low; calling, saving a line and meeting up ease it."},
  {"id":"mb-1382","cat":"tools-and-help","type":"reflect","hook":"Lensy: which in-the-moment reset feels most like 'you'?","prompt":"Pick the one you'd actually reach for.","options":["A few slow breaths","A short walk outside","Texting someone I trust"],"affirm":"Any of these is a real reset: knowing your go-to means it's ready when a hard moment hits.","relearn":"Pick a go-to reset that fits you; having one ready makes hard moments easier.","persona":"any","source":"your go-to"},
  {"id":"mb-1383","cat":"tools-and-help","type":"reflect","hook":"Lensy: who's one person you could text 'I'm not okay' today?","prompt":"Bring one face to mind.","options":["A close friend","A sibling or cousin","A senior or mentor"],"affirm":"Naming even one person means you're not carrying it alone: that's a tool you already have.","relearn":"Knowing one trusted person to reach is part of looking after your mind.","persona":"any","source":"your person"},
  {"id":"mb-1384","cat":"tools-and-help","type":"reflect","hook":"Lensy: it's worth saving a free line in your phone now, before a hard night. Worth a tap?","prompt":"What feels right?","options":["I'll save Tele-MANAS 14416","I already have it","Good idea"],"affirm":"Saving Tele-MANAS 14416 before you need it means help is one tap away on the hardest nights.","relearn":"Saving a 24/7 line in advance puts help one tap away when it's hard.","persona":"any","source":"save-it-now"},
  {"id":"mb-1385","cat":"tools-and-help","type":"reflect","hook":"Lensy: which everyday anchor would steady you most this week?","prompt":"Choose one to lean on.","options":["A steadier sleep time","One real meal a day with people","A daily short walk"],"affirm":"Any anchor you pick makes hard days less steep: small basics are quietly powerful tools.","relearn":"Sleep, food with people and a daily walk are quiet anchors that steady your mind.","persona":"any","source":"your anchor"},
  {"id":"mb-1386","cat":"tools-and-help","type":"reflect","hook":"Lensy: this game points to help and builds skills; it's never therapy. Sit okay with you?","prompt":"What do you think?","options":["Yes","Makes sense","Good to know"],"affirm":"That's exactly it: for anything heavy or lasting, a professional is the right next step; this points the way.","relearn":"This builds skills and points to help; for heavy or lasting distress, see a professional.","persona":"any","source":"not therapy"},
  {"id":"mb-1387","cat":"tools-and-help","type":"reflect","hook":"Lensy: what would make it easier to actually pick up the phone and reach out?","prompt":"Pick what helps you.","options":["Knowing it's free","Knowing it's confidential","Knowing no problem's too small"],"affirm":"Each of these is true: free, confidential, and no problem too small. Reaching out is allowed.","relearn":"Help is free, confidential and for everyday stress too: reaching out is always allowed.","persona":"any","source":"what makes it easier"},
  {"id":"mb-1388","cat":"tools-and-help","type":"reflect","hook":"Deepak: which truth do you most need to hear when you doubt you belong here?","prompt":"Pick the one for today.","options":["I earned my place","Asking for help is strength","I'm not the only one struggling"],"affirm":"Whichever you chose is true, and reaching out doesn't undo your place. It protects it.","relearn":"You earned your place; asking for help is strength, not proof you don't belong.","persona":"Deepak","source":"belong-and-help"},
  {"id":"mb-1389","cat":"tools-and-help","type":"reflect","hook":"Lensy: when you're calmer, what's one small kind thing you could do for yourself?","prompt":"Pick one.","options":["Rest without guilt","Step outside a while","Message a friend"],"affirm":"Any of these counts: small kind steps are real tools, not indulgence.","relearn":"Small kind steps like rest, fresh air or a message are real tools for looking after your mind.","persona":"any","source":"small kindness"},
  {"id":"mb-1390","cat":"tools-and-help","type":"reflect","hook":"Lensy: which helpline fact is most useful for you to remember?","prompt":"Pick the one that sticks.","options":["It's free","It runs 24/7","It's in many languages"],"affirm":"All true of Tele-MANAS 14416: free, around the clock, in many Indian languages. It's there for you.","relearn":"Tele-MANAS 14416 is free, 24/7 and in many Indian languages: there for you whenever.","persona":"any","source":"line to remember"},
  {"id":"mb-1391","cat":"tools-and-help","type":"reflect","hook":"Zoya: heading home and dreading it. What's one tool you'll keep close?","prompt":"Pick what you'll carry.","options":["A coping step","A person to message","A line saved in my phone"],"affirm":"Carrying one tool home means you're not unarmed: support travels with you wherever you go.","relearn":"Your tools, like a coping step, a person or a saved line, travel with you, even home.","persona":"Zoya","source":"tools travel"},
  {"id":"mb-1392","cat":"tools-and-help","type":"reflect","hook":"Lensy: which feels like the easiest first step for you right now?","prompt":"No wrong pick, just the lightest one.","options":["Save a helpline","Tell one friend","Try one breathing reset"],"affirm":"The lightest step is still a step, and any of these moves you toward support, not away.","relearn":"Any first step, like saving a line, telling a friend or one breath, moves you toward support.","persona":"any","source":"lightest step"},
  {"id":"mb-1393","cat":"tools-and-help","type":"reflect","hook":"Lensy: what's one thing you'd want a struggling friend to know they can do?","prompt":"Pick one to pass on.","options":["Talk to someone","Call a free line","They're not alone"],"affirm":"Whatever you'd tell a friend, you're allowed to tell yourself too: the kindness goes both ways.","relearn":"What you'd offer a friend is yours to use as well: talk, call a line, you're not alone.","persona":"any","source":"pass it on"},
  {"id":"mb-1394","cat":"tools-and-help","type":"role-play","persona":"any","source":"name the route","hook":"Late one night, you and your friend Rehana get talking about hard times.","setup":"She pulls her knees up on the steps outside the night canteen.","steps":[{"prompt":"Rehana asks: \"If it ever got really bad, would you even know what to do?\"","options":[{"text":"\"I'd probably just keep it to myself, honestly.\"","then":"\"Same,\" she says quietly. \"Isn't that bad?\""},{"text":"\"I'd call Tele-MANAS 14416 and tell someone I trust.\"","then":"\"Wait, there's a number?\" Rehana says, sitting up.","best":true},{"text":"\"Wait for it to pass. It always does, eventually.\"","then":"\"What if it doesn't, though?\" she asks."},{"text":"\"Google it, I guess. Figure it out then.\"","then":"\"At 3 a.m.? In that state?\" she says."}],"why":"Knowing your route out loud, a free line and a trusted person, makes it usable."},{"prompt":"Rehana asks: \"Isn't a helpline only for, like, really serious stuff?\"","options":[{"text":"\"Yeah, probably only if you're in real danger or something.\"","then":"\"Then it's not for me,\" Rehana says."},{"text":"\"No idea. I've never looked into it.\"","then":"\"Me neither,\" she says, and the thought drifts off."},{"text":"\"Honestly, it's for people who can't cope.\"","then":"Rehana goes quiet. \"Maybe I can't, some days.\""},{"text":"\"No. Everyday stress counts. No problem's too small.\"","then":"\"Huh,\" she says. \"I didn't know that.\"","best":true}],"why":"Helplines like Tele-MANAS 14416 are for everyday stress too, not only crisis."},{"prompt":"Rehana says: \"Some weeks I feel really low and tell no one.\"","options":[{"text":"\"Thanks for telling me. Want to save Tele-MANAS 14416?\"","then":"She nods and hands you her phone. \"Okay. And you're my person?\"","best":true},{"text":"\"Everyone feels that. Don't worry about it.\"","then":"\"Right,\" she says, and changes the subject."},{"text":"\"You need to call them tonight, okay? Promise me you will.\"","then":"\"Tonight? I'm fine tonight,\" she says, pulling back."},{"text":"\"Me too. I just ignore it till it goes.\"","then":"\"Does it go?\" she asks. Neither of you knows."}],"why":"Thanking her and making the plan together respects her pace and opens a route."}],"relearn":"Knowing your route, like a free line and a trusted person, is a tool you can name out loud."},
  {"id":"mb-1395","cat":"tools-and-help","type":"role-play","persona":"any","source":"sit-with-them","hook":"Your friend Neel has been low for weeks, skipping classes and meals.","setup":"Tonight you find him alone in the common room.","steps":[{"prompt":"Neel says: \"Sorry I've gone missing. I just can't get going.\"","options":[{"text":"\"You'll be fine. Just try to cheer up a bit, okay?\"","then":"\"Yeah,\" he says flatly, and looks away."},{"text":"\"Bro, you need to sort yourself out.\"","then":"Neel pulls his hood up. \"I know. I'm trying.\""},{"text":"\"No worries. Want me to send you all my notes?\"","then":"\"Thanks,\" he says. The notes arrive. He doesn't open them."},{"text":"\"No stress about that. How are you really doing?\"","then":"Neel is quiet, then says, \"Not good. For a while now.\"","best":true}],"why":"Asking how he's really doing opens the door without judging."},{"prompt":"Neel says: \"I don't even know who I'd talk to about it.\"","options":[{"text":"\"Just talk to your parents. They'll know.\"","then":"\"They'd just panic,\" Neel says."},{"text":"\"Want me to sit with you while you call a helpline?\"","then":"Neel hesitates. \"Now? Okay. If you stay.\"","best":true},{"text":"\"Here's the number. Call it whenever you're ready.\"","then":"He saves it. You both know he probably won't call alone."},{"text":"\"You've got me. You don't need anyone else.\"","then":"He nods, relieved. You wonder what you'd do if it got worse."}],"why":"Offering to sit with him while he calls Tele-MANAS 14416 makes the first step less lonely."},{"prompt":"A few days later, Neel says: \"It's still heavy. I think I need proper help. Now what?\"","options":[{"text":"\"Just give it some time. It'll pass on its own.\"","then":"\"Maybe,\" he says. A week later, he's skipping everything again."},{"text":"\"Maybe you're overthinking it now.\"","then":"His face closes. \"Maybe,\" he says."},{"text":"\"Let's find the campus counsellor. I'll walk you.\"","then":"Neel nods. \"Thursday, then. Thanks for sticking around.\"","best":true},{"text":"\"I'll book it for you and tell you when to go.\"","then":"\"Oh. Okay,\" he says, a little lost."}],"why":"Helping him reach ongoing support, at his pace, is real care."},{"prompt":"A few weeks later, Neel says: \"Sorry for being such a burden through all this.\"","options":[{"text":"\"It's fine. Just don't let it get that bad again.\"","then":"\"I'll try,\" he says, looking down."},{"text":"\"You weren't a burden. I'm glad you let me in.\"","then":"Neel smiles properly for the first time in weeks.","best":true},{"text":"\"Yeah, it was a tough few weeks for me too.\"","then":"\"Sorry,\" he says again, more quietly."},{"text":"\"No worries. Let's never bring it up again.\"","then":"\"Sure,\" he says, and goes quiet."}],"why":"Telling him he wasn't a burden makes it easier for him to reach out again."}],"relearn":"Offering to sit with someone while they reach help is real support. 'Cheer up' isn't."},
  {"id":"mb-1396","cat":"tools-and-help","type":"role-play","persona":"any","source":"the opener","hook":"After a rough fortnight, you decide to ring Tele-MANAS 14416.","setup":"The line picks up after two rings.","steps":[{"prompt":"The counsellor says: \"Hello, Tele-MANAS. How can I help you today?\"","options":[{"text":"\"Sorry, never mind. It's probably nothing.\"","then":"\"No problem is too small,\" she says quickly. \"Please stay.\""},{"text":"\"Hi. I'm struggling and just need someone to talk to.\"","then":"\"I'm glad you called,\" she says. \"I'm here. Tell me.\"","best":true},{"text":"\"I'm not sure this is serious enough to call about.\"","then":"\"You don't need to be in crisis to call,\" she says. \"What's up?\""},{"text":"\"Can you just tell me what's wrong with me?\"","then":"\"Let's start with how you've been feeling,\" she says gently."}],"why":"Saying 'I'm struggling' is a complete, valid opener. No problem is too small."},{"prompt":"The counsellor asks: \"What's been hardest lately?\"","options":[{"text":"\"Nothing specific. I'm probably just being dramatic.\"","then":"\"You're not,\" she says. \"Tell me about an ordinary day.\""},{"text":"\"I don't know. Can you guess?\"","then":"\"I'd rather hear it from you,\" she says. \"Start anywhere.\""},{"text":"\"Sleeping badly and feeling alone most evenings.\"","then":"\"That sounds exhausting,\" she says. \"How long has it been like this?\"","best":true},{"text":"\"Just exams. Everyone has them.\"","then":"\"Exams can weigh a lot,\" she says. \"Is it only that?\""}],"why":"Naming even one or two real things helps them understand and help."},{"prompt":"Near the end, the counsellor asks: \"Is there someone near you that you trust?\"","options":[{"text":"\"No one I want to bother.\"","then":"\"Reaching out isn't a bother,\" she says. \"Who comes to mind?\""},{"text":"\"I'd rather just call you every night instead.\"","then":"\"You can call anytime,\" she says. \"And someone near you matters too.\""},{"text":"\"My friend Nikhil. I could tell him tomorrow.\"","then":"\"Let's make that your next step,\" she says.","best":true},{"text":"\"Not really, but I'll be fine.\"","then":"\"Let's think about who that could be,\" she says."}],"why":"A trusted person nearby adds everyday support to the helpline."}],"relearn":"\"I'm struggling and need to talk\" is a complete, valid opener: no problem is too small."},
  {"id":"mb-1397","cat":"tools-and-help","type":"role-play","persona":"Rohan","source":"hold-the-line","hook":"You've started seeing the campus counsellor, and at lunch a hostel mate mocks the idea.","setup":"Karan points his fork at the centre's poster.","steps":[{"prompt":"Karan says: \"Counselling? That's for people who can't handle life.\"","options":[{"text":"\"Yeah, you're right. I'd never go to one.\"","then":"The table laughs. You think of your own bad weeks and say nothing."},{"text":"\"Nah. Looking after your head is just smart.\"","then":"Karan smirks. \"Smart? Bit dramatic, no?\"","best":true},{"text":"\"That's such an ignorant thing to say.\"","then":"Karan bristles. \"Relax, it was a joke.\""},{"text":"\"Ha. Anyway, who's up for cricket later?\"","then":"The table moves on. The poster stays unread."}],"why":"A calm, confident line challenges the myth without a fight."},{"prompt":"Karan says: \"Real men sort their own problems. My dad never needed help.\"","options":[{"text":"\"Fair. Maybe it's different for guys.\"","then":"Karan nods, satisfied. Someone at the table goes quiet."},{"text":"\"Your dad probably just never admitted it to anyone.\"","then":"Karan's jaw tightens. \"Leave my dad out of it.\""},{"text":"\"Everyone's got a mind to look after. Men too.\"","then":"Karan shrugs. \"I guess. Doesn't mean I'd go.\"","best":true},{"text":"\"Whatever. Believe what you want.\"","then":"He rolls his eyes, and the myth hangs in the air."}],"why":"Help-seeking is strength for all genders. Saying so plainly takes the stigma down a notch."},{"prompt":"Later, alone, Karan asks: \"So do you actually go? What's it even like?\"","options":[{"text":"\"Me? No way. I was just arguing.\"","then":"\"Thought so,\" Karan says, and the subject closes again."},{"text":"\"You should go. You clearly need it.\"","then":"Karan stiffens. \"I'm fine, thanks.\""},{"text":"\"Why? Is something up with you?\"","then":"\"No, no,\" he says quickly. \"Just asking.\""},{"text":"\"I do. It's just talking, and it helps.\"","then":"Karan nods slowly. \"Just talking? Huh. Maybe I'll check it out.\"","best":true}],"why":"Sharing your own experience plainly makes it easier for him to consider help."}],"relearn":"Help-seeking is strength for all genders. Looking after your mind is smart, not weak."},
  {"id":"mb-1398","cat":"tools-and-help","type":"role-play","persona":"any","source":"accept-help","hook":"You're mid-spiral after a bad week, pacing the campus lawns at midnight.","setup":"Your friend Tanya, heading back from the library, stops.","steps":[{"prompt":"Tanya says: \"You don't look okay. Can I help you find someone to talk to?\"","options":[{"text":"\"No, no, I'm fine. Don't worry about me.\"","then":"\"You're pacing at midnight,\" Tanya says gently. \"That's not fine.\""},{"text":"\"I don't want to be a burden on you.\"","then":"\"You're not,\" she says. \"Let me help anyway.\""},{"text":"\"Yeah, actually. That'd help. Thank you.\"","then":"Tanya takes your arm. \"Come sit. Let's figure it out together.\"","best":true},{"text":"\"Maybe later. I'll sort it out first.\"","then":"\"Sort it out with someone,\" she says. \"That's what I'm offering.\""}],"why":"Accepting help when it's offered means you don't carry it alone."},{"prompt":"Tanya asks: \"Want to call Tele-MANAS 14416 now, with me here?\"","options":[{"text":"\"What if they think I'm wasting their time?\"","then":"\"They won't,\" Tanya says. \"No problem's too small for them.\""},{"text":"\"Yes. Stay while I call?\"","then":"Tanya sits beside you. The line picks up, and a calm voice says hello.","best":true},{"text":"\"Let's wait and see if I feel better tomorrow.\"","then":"\"Okay,\" Tanya says, \"but I'm checking on you in the morning.\""},{"text":"\"No. I'll just search my symptoms online.\"","then":"Twenty tabs later, you feel more scared than before."}],"why":"Taking the step now, with someone beside you, makes it easier."},{"prompt":"The next day, Tanya texts: \"How are you feeling today?\"","options":[{"text":"\"All good now! Sorry about last night.\"","then":"\"No need to be sorry,\" she replies. \"You sure you're okay?\""},{"text":"\"Better. Come with me to the counsellor?\"","then":"\"Name the time,\" Tanya replies. \"I'll be there.\"","best":true},{"text":"\"Fine. Let's forget last night happened.\"","then":"\"If that's what you want,\" she replies, a little worried."},{"text":"\"Better. I think I can handle it alone now.\"","then":"\"Okay,\" she replies. \"I'm here if that changes.\""}],"why":"Letting a friend stay alongside you while you reach ongoing help keeps you supported."},{"prompt":"A week later, Tanya asks: \"How's this week been for you?\"","options":[{"text":"\"Totally fine. Last week was a one-off.\"","then":"\"Okay,\" she says, but keeps an eye on you anyway."},{"text":"\"Up and down. Can I keep checking in with you?\"","then":"\"Always,\" she says. \"Same time next week, then?\"","best":true},{"text":"\"Rough, but I don't want to bother you with it again.\"","then":"\"You're not a bother,\" she says. \"Tell me.\""},{"text":"\"Better. I've stopped needing anyone.\"","then":"\"Everyone needs someone,\" she says gently."}],"why":"Keeping a friend in the loop is part of the support you've built."}],"relearn":"Accepting an offer of help is a tool too: you don't have to carry it alone."},
  {"id":"mb-1399","cat":"tools-and-help","type":"role-play","persona":"Meena","source":"share-the-line","hook":"Your co-worker Lakshmi, far from home like you, seems to be sinking.","setup":"You share a bench on the evening break.","steps":[{"prompt":"Lakshmi says: \"There's no counsellor here. So what's even the point?\"","options":[{"text":"\"Yeah. People like us just have to deal with it.\"","then":"She nods slowly, and her shoulders sink lower."},{"text":"\"Just go back home for a while. Your family will surely help.\"","then":"\"I can't lose the wages,\" she says quietly."},{"text":"\"There's a free line, from anywhere: Tele-MANAS 14416.\"","then":"Lakshmi looks up. \"Free? Even for people like us, not just students?\"","best":true},{"text":"\"Talk to the supervisor. Maybe he'll help.\"","then":"\"He'll just cut my shifts,\" she says."}],"why":"A free national line reaches help from anywhere, no campus needed."},{"prompt":"Lakshmi says: \"Even if I talked to someone, I wouldn't know what to say.\"","options":[{"text":"\"Wait until you've figured out what's wrong.\"","then":"\"That could take months,\" she sighs."},{"text":"\"Just say you're struggling. That's enough.\"","then":"\"That's it?\" she says. \"I could maybe manage that.\"","best":true},{"text":"\"Then maybe it's not for you.\"","then":"She shrugs. \"Maybe.\" But she keeps turning her phone over in her hands."},{"text":"\"Tell them everything, right from the start.\"","then":"\"That's too much,\" she says. \"I'd freeze.\""}],"why":"'I'm struggling' is a complete opener. No problem is too small."},{"prompt":"Lakshmi asks: \"If I called someone tomorrow, would you sit with me on the break?\"","options":[{"text":"\"Better to call alone. It's private.\"","then":"\"Oh,\" she says. \"Okay.\" She puts the phone away."},{"text":"\"I'm busy. Maybe some other day.\"","then":"Lakshmi nods. The next day's break passes without the call."},{"text":"\"Why, are you scared to call?\"","then":"She flushes. \"Forget it.\""},{"text":"\"Yes. Let's save Tele-MANAS 14416 now.\"","then":"She takes out her phone, and you save it together.","best":true}],"why":"Saying yes when she asks for company makes the first call less lonely."}],"relearn":"With no campus, a free national line like Tele-MANAS 14416 reaches help from anywhere."},
  {"id":"mb-1400","cat":"tools-and-help","type":"role-play","persona":"any","source":"ask-a-senior","hook":"You've been thinking about the campus counsellor but don't know how it works.","setup":"Akash, a senior, sees you reading the counselling poster.","steps":[{"prompt":"Akash asks: \"You look like you want to ask something. What's up?\"","options":[{"text":"\"Forget it. It's embarrassing.\"","then":"\"Nothing's embarrassing here,\" Akash says. \"Try me.\""},{"text":"\"How do you book the campus counsellor? I want to try.\"","then":"Akash grins. \"Email the centre, or just walk in on Tuesdays.\"","best":true},{"text":"\"Nothing. Just, um, which canteen's best?\"","then":"He points to the one by the gate. The real question stays unasked."},{"text":"\"Asking for a friend: is the campus counsellor any good?\"","then":"\"Tell your 'friend' it's great,\" Akash says with a smile."}],"why":"Asking how to reach help is a tool in itself. Peers can point you to the route."},{"prompt":"Akash says: \"I went to the counsellor last year, you know. The first session is just talking.\"","options":[{"text":"\"Sounds pointless if they can't fix it.\"","then":"\"It's not fixing,\" Akash says. \"It's figuring it out with someone.\""},{"text":"\"Maybe I'll wait till things get really bad.\"","then":"\"I waited,\" Akash says. \"Wish I hadn't.\""},{"text":"\"Then I'll go once I know exactly what to say.\"","then":"\"You might never feel that sure,\" he says."},{"text":"\"Okay. Is what I tell them private?\"","then":"\"It's confidential,\" Akash says. \"They explain it all at the start.\"","best":true}],"why":"Asking about what worries you, like privacy, makes the first step easier."},{"prompt":"Akash says: \"Want me to walk you to the centre this week?\"","options":[{"text":"\"No, I'd hate for anyone to see me there.\"","then":"\"Loads of people go,\" he says. \"Nobody's watching.\""},{"text":"\"I'll go someday. No rush.\"","then":"\"Someday's a long time,\" he says, but lets it go."},{"text":"\"Yes, please. Thursday after class?\"","then":"\"Thursday it is,\" he says, and taps it into his phone.","best":true},{"text":"\"Could you just book it for me instead?\"","then":"\"I can't,\" he says. \"They need to hear from you.\""}],"why":"Accepting a peer's offer to walk with you makes the first visit easier."}],"relearn":"Asking how to reach help is itself a tool: peers can point you to the campus route."},
  {"id":"mb-1401","cat":"tools-and-help","type":"role-play","persona":"any","source":"say-the-plan","hook":"You've been building a plan for hard days, and your friend Joel is curious.","setup":"You're walking back from the night canteen.","steps":[{"prompt":"Joel asks: \"So what do you actually do when it gets too much?\"","options":[{"text":"\"Honestly? I just shut down and go quiet on everyone.\"","then":"Joel slows down. \"Even on your friends? That sounds lonely.\""},{"text":"\"I push through. Stopping makes it worse.\"","then":"\"Does it work, though?\" Joel asks."},{"text":"\"I've got a plan: a breath, a person, a number.\"","then":"\"A plan?\" Joel says, impressed. \"Go on, then.\"","best":true},{"text":"\"I wait it out and hope it passes on its own.\"","then":"\"And if it doesn't?\" Joel asks."}],"why":"A plan you can say out loud is a plan you can actually use."},{"prompt":"Joel asks: \"And in the moment, when your heart's racing? What helps then?\"","options":[{"text":"\"Not breathing stuff. That's for yoga people.\"","then":"\"My sister swears by it,\" Joel says, \"and she's no yoga person.\""},{"text":"\"A slow out-breath. It takes the edge off.\"","then":"Joel tries it right there, then laughs. \"Okay, that's weirdly calming.\"","best":true},{"text":"\"Tried breathing once. Didn't fix everything, so I quit.\"","then":"\"It's not meant to fix everything,\" Joel says."},{"text":"\"I just hold it all in till it passes.\"","then":"\"Does it pass, though?\" he asks."}],"why":"A slow breath is a simple reset that works in the moment."},{"prompt":"Joel asks: \"And who would you actually tell? Like, a real person.\"","options":[{"text":"\"No one. People have their own problems.\"","then":"\"I'd want to know,\" Joel says quietly."},{"text":"\"My parents, but only once it's really bad.\"","then":"\"Why wait till it's really bad?\" he asks."},{"text":"\"Anyone who asks, I guess. I'd wait for that.\"","then":"\"What if nobody asks?\" Joel says."},{"text":"\"You, or my cousin Mansi. I'd tell one of you.\"","then":"\"Deal,\" Joel says. \"And I'd call you, for the record.\"","best":true}],"why":"Naming a real person ahead of time makes reaching out much easier."},{"prompt":"Joel asks: \"And a helpline? I wouldn't even know which one to call.\"","options":[{"text":"\"Tele-MANAS 14416. Free, any time, lots of languages.\"","then":"Joel pulls out his phone. \"Say it again? I'm saving it.\"","best":true},{"text":"\"There's one, but I don't remember the number.\"","then":"\"Then how would you call it?\" Joel asks."},{"text":"\"I'd search for one if I ever needed it.\"","then":"\"In the middle of a bad night?\" he says doubtfully."},{"text":"\"Helplines are really for people way worse off than us.\"","then":"\"Says who?\" Joel asks. \"My sister called one about exam stress.\""}],"why":"Knowing Tele-MANAS 14416 by heart means you don't search when it's hardest."},{"prompt":"At the hostel gate, Joel says: \"I don't have a plan. Maybe I should make one.\"","options":[{"text":"\"You're fine. You don't need one.\"","then":"\"Yeah, probably,\" he says, and heads upstairs."},{"text":"\"Want to make one together this weekend?\"","then":"\"Sunday, then,\" Joel says. \"Chai's on me.\"","best":true},{"text":"\"Just copy mine exactly. Same people, same steps.\"","then":"\"Mine might need different people, though,\" he laughs."},{"text":"\"Plans are overrated, honestly.\"","then":"\"Then why do you have one?\" he asks, grinning."}],"why":"Helping a friend build their own plan passes the tool on."}],"relearn":"A plan you can say out loud, like a breath, a person or a saved line, is a tool you actually own."},
  {"id":"mb-1402","cat":"tools-and-help","type":"branch","persona":"any","source":"1am-branch","hook":"It's 1 a.m. You feel low and heavy, and sleep won't come.","steps":[{"prompt":"Your roommate's asleep and the room is dark. What do you do?","options":[{"text":"Doomscroll until you're too tired to feel it","then":"1 a.m. becomes 3 a.m., and the low feels heavier."},{"text":"Call Tele-MANAS 14416. It's free and 24/7","then":"A calm voice picks up, and the hour feels less alone.","best":true},{"text":"Tell yourself to toughen up and go to sleep","then":"The feeling doesn't budge. You lie there more stuck than before."},{"text":"Wait till morning to text a friend","then":"You watch the ceiling for hours, carrying it alone."}],"why":"A free 24/7 line means even the hardest hour has a real next step."},{"prompt":"Later, you're still awake, and the heaviness hasn't fully gone. What helps now?","options":[{"text":"Replay every bad thing from this week","then":"The list grows longer and your heart speeds up."},{"text":"Watch videos till you drop off","then":"It's 4 a.m. and the videos have blurred together."},{"text":"Slow breaths, and a glass of water","then":"Your breathing slows, and your shoulders drop a little.","best":true},{"text":"Get up and start an assignment","then":"You stare at the same line for an hour."}],"why":"Calming your body helps the heaviness ease enough to rest."},{"prompt":"The next morning, you feel wrung out. What do you do?","options":[{"text":"Act like nothing happened","then":"The night stays a secret, and the next one feels just as lonely."},{"text":"Skip classes and sleep all day","then":"You wake at 5 p.m., groggy and lower than before."},{"text":"Promise yourself it won't happen again","then":"The pressure adds to the heaviness."},{"text":"Tell a friend you trust about last night","then":"Your friend listens and says, \"Next time, text me too. Anytime.\"","best":true}],"why":"Letting someone you trust know means you're not carrying it alone."}],"debrief":"A free 24/7 line means even the hardest hour has a real next step.","relearn":"At any hour, a free 24/7 line is a real step. Scrolling or 'toughen up' deepen the low."},
  {"id":"mb-1403","cat":"tools-and-help","type":"branch","persona":"any","source":"three-weeks-branch","hook":"You've felt heavy and flat for three weeks, and nothing seems to lift it.","steps":[{"prompt":"This morning, even your favourite breakfast tastes like nothing. What do you do?","options":[{"text":"Wait and hope it lifts on its own","then":"Another week slides by, heavy as the last."},{"text":"Bury it in extra work and longer hours","then":"You're busy till midnight, running on empty."},{"text":"Book a counsellor and tell someone you trust","then":"The counselling centre offers Wednesday, and your friend Rahul offers to walk you there.","best":true},{"text":"Tell a friend, but skip the counsellor for now","then":"Your friend is kind, but has no idea what to suggest next."}],"why":"Weeks of feeling flat is a signal to reach real support, not a phase to outlast."},{"prompt":"A few days later, you wonder if you're 'bad enough' to need help. What do you tell yourself?","options":[{"text":"Others have it much worse. I should just manage","then":"The guilt keeps you quiet for another week."},{"text":"I don't need to be in crisis to deserve support","then":"The thought eases the guilt, and asking for help feels allowed.","best":true},{"text":"If I can still get to class, I'm fine","then":"You make it to class, blank, and tell yourself it proves you're fine."},{"text":"I'll only go if it gets a lot worse than this","then":"You start measuring every day against 'worse'."}],"why":"Support is for anyone struggling. You never have to prove you're bad enough."},{"prompt":"Meanwhile, your days are shrinking to bed and laptop. What do you keep up?","options":[{"text":"Nothing until you feel like it again","then":"The days blur, and the heaviness settles deeper."},{"text":"Only work, since it keeps your mind busy","then":"You're productive all week and empty by Friday."},{"text":"Meals, sleep and a short walk each day","then":"The walks are short, but the days get a little shape back.","best":true},{"text":"Just sleep, as much as you can","then":"You sleep twelve hours and wake up still tired."}],"why":"Food, sleep and movement support you while help does its work."},{"prompt":"A week on, the heaviness hasn't gone. What now?","options":[{"text":"Leave it. Some days already feel a bit easier","then":"Two weeks later, the heaviness is back in full."},{"text":"Wait another month, then decide what to do about it","then":"The month passes slowly, and the low digs in."},{"text":"Decide this heaviness is just who you are now","then":"The label makes the heaviness feel permanent."},{"text":"See the counsellor this week and keep a friend close","then":"The session gives you a plan, and your friend checks in on Friday.","best":true}],"why":"Steady support, not waiting, is what helps a long low patch lift."}],"debrief":"Weeks of heaviness is a signal, not a phase to outlast. Help lifts it.","relearn":"Weeks of low mood is a signal to reach a counsellor and a trusted person, not wait."},
  {"id":"mb-1404","cat":"tools-and-help","type":"branch","persona":"any","source":"viva-branch","hook":"Ten minutes before your big viva, a panicky wave hits.","steps":[{"prompt":"Your heart races and your hands feel cold. What helps right now?","options":[{"text":"Run through every way the viva could go wrong","then":"The panic feeds itself, and your mind goes blanker."},{"text":"Cram your notes one last time, as fast as you can","then":"The words blur, and your heart races faster."},{"text":"Breathe out slowly and name five things you see","then":"The wave eases, and your mind comes back to the room.","best":true},{"text":"Tell yourself to stop being so stupid","then":"The harsh words make your chest tighter."}],"why":"A slow out-breath and grounding calm your body and pull you back to now."},{"prompt":"In the viva, you blank on the first question. What do you do?","options":[{"text":"Pause, breathe, and ask them to repeat it","then":"They repeat it slowly. The answer starts coming back to you.","best":true},{"text":"Guess wildly to fill the silence","then":"The examiner frowns, and your mind races again."},{"text":"Apologise over and over","then":"\"It's fine,\" the examiner says, but your cheeks are burning."},{"text":"Say you don't know and wait for the next one","then":"The silence stretches. The examiner moves on without you."}],"why":"A brief pause and a breath give your mind a second chance."},{"prompt":"Afterwards, the adrenaline drains and you feel shaky. What do you do?","options":[{"text":"Replay every mistake on the walk home","then":"By your door, you've convinced yourself you failed."},{"text":"Go straight to studying for the next exam","then":"Nothing sticks. You read the same page three times."},{"text":"Tell yourself it doesn't matter anyway","then":"The shakiness stays, pushed down but not gone."},{"text":"Get some water, eat something, call a friend","then":"By the time your friend picks up, the shakiness has faded.","best":true}],"why":"After stress, basics and a friendly voice help your body settle."}],"debrief":"A slow breath and grounding pull you back to now.","relearn":"Slow breathing and grounding reset a panic wave. Spiralling makes it worse."},
  {"id":"mb-1405","cat":"tools-and-help","type":"branch","persona":"any","source":"crisis-friend-branch","hook":"At midnight, your friend Ishaan texts that he feels hopeless.","steps":[{"prompt":"His message says: 'What's even the point anymore.' What do you do?","options":[{"text":"Send a thumbs-up and go back to sleep","then":"Ten minutes later, your phone buzzes again. He's still awake and still low."},{"text":"Ask how serious it 'really' is first","then":"\"Forget it,\" he replies. A minute later: \"Sorry. I just feel awful.\""},{"text":"Call him right away and stay on the line","then":"He picks up on the second ring, voice thick. \"I didn't think you'd call.\"","best":true},{"text":"Reply 'Get some sleep, talk tomorrow?'","then":"\"Okay,\" he replies. Then another text: \"I can't sleep, though.\""}],"why":"Staying with him right now matters more than anything else you could say."},{"prompt":"He says it's been like this for weeks and he's so tired of it. What do you do?","options":[{"text":"Tell him everyone feels like that sometimes, and it passes","then":"\"Right,\" he says. \"So it's just me who can't handle it.\""},{"text":"Stay with him and ring Tele-MANAS 14416 together","then":"He's quiet, then says, \"Okay. Stay on?\" A calm voice answers soon after.","best":true},{"text":"Give him the number and say goodnight","then":"He says thanks. You're not sure he'll call alone."},{"text":"Keep pressing him for exactly how bad it is","then":"He goes silent, then says he's fine and wants to sleep."}],"why":"Reaching Tele-MANAS 14416 together gets him real support now, and he isn't alone."},{"prompt":"The next day, Ishaan seems a little steadier but embarrassed. What do you do?","options":[{"text":"Act like last night never happened","then":"He relaxes, but the heaviness goes unspoken again."},{"text":"Post in your group asking everyone to check on him","then":"His phone floods with messages, and he stops replying to anyone."},{"text":"Check in, and offer to go with him to a counsellor","then":"\"Would you?\" he says. \"Okay. I don't want to do it alone.\"","best":true},{"text":"Ask him to promise he'll never feel that way again","then":"\"I'll try,\" he says, looking at the floor."}],"why":"Checking in warmly and linking him to ongoing help keeps him supported."},{"prompt":"A week on, Ishaan says he's still low some days. What do you do?","options":[{"text":"Tell him he should be better by now","then":"He goes quiet. \"Sorry. I'm trying.\""},{"text":"Keep checking in, and remind him help is always there","then":"He nods. \"Knowing you'll ask makes it easier to say.\"","best":true},{"text":"Avoid bringing it up at all, so he doesn't feel watched","then":"He stops mentioning it too, and you lose track of how he's doing."},{"text":"Try to cheer him up with jokes every time","then":"He laughs along, then goes back to his room early."}],"why":"Steady check-ins and a reminder that help is always there keep him supported."}],"debrief":"When a friend feels hopeless, stay warmly and help them reach Tele-MANAS 14416. Don't quiz them.","relearn":"A friend in crisis needs you to stay and help, not quiz them."},
  {"id":"mb-1406","cat":"tools-and-help","type":"branch","persona":"any","source":"when-to-set-up","hook":"You keep meaning to set up a support plan 'someday', and right now you're doing okay.","steps":[{"prompt":"On a calm Sunday, you have ten free minutes. What do you do with them?","options":[{"text":"Look up a helpline number and trust you'll remember it","then":"By evening, the digits have blurred together. The plan stays 'someday'."},{"text":"Research every helpline and app out there","then":"An hour later, you have twelve tabs open and nothing saved."},{"text":"Save Tele-MANAS 14416 in your phone","then":"It takes a minute. The number sits in your contacts, ready.","best":true},{"text":"Nothing. Plans like that are for people in crisis","then":"You drop the idea. Your phone has no route for a hard night."}],"why":"Setting up a route while you're steady means it's ready when you need it."},{"prompt":"Midweek, a friend's rough night makes you wonder who you'd reach for on a hard day. What do you do?","options":[{"text":"Decide you'll figure it out when it happens","then":"The question slips away with the rest of the day."},{"text":"Pick someone in your head, but don't tell them yet","then":"You have a name in mind, but they don't know to expect a call."},{"text":"Decide it's better not to burden anyone","then":"The list stays empty."},{"text":"Pick one person and tell them they're your person","then":"Your friend Aisha laughs. \"Deal. And I'm picking you back.\"","best":true}],"why":"A trusted person who knows they're your person makes reaching out easier."},{"prompt":"On Friday, a classmate mentions her go-to step for rough moments. What do you pick as yours?","options":[{"text":"A slow breath and a short walk outside","then":"You try it before Monday's test, and your shoulders drop.","best":true},{"text":"Whatever distracts you fastest, like scrolling","then":"It works for ten minutes, then the rough feeling is back."},{"text":"Staying in bed till it passes","then":"The rough moment stretches into a lost afternoon."},{"text":"Waiting for someone to call and check on you","then":"The call doesn't come, because no one knows you need it."}],"why":"A healthy coping step you know by heart is ready the moment you need it."}],"debrief":"Tools set up while you're steady are ready the moment a hard patch hits.","relearn":"Set up help routes while you're okay. A ready plan beats scrambling later."},
  {"id":"mb-1407","cat":"tools-and-help","type":"branch","persona":"Rohan","source":"grind-content-branch","hook":"Lonely after another quiet week, you land on a video saying 'just grind, never complain'.","steps":[{"prompt":"The next video says real men handle everything alone. What do you do?","options":[{"text":"Binge more till you feel less soft","then":"You feel fired up for an hour, then lonelier than before."},{"text":"Close it and message one person who cares","then":"Your old school friend replies: \"Hey! Was just thinking of you.\"","best":true},{"text":"Decide reaching out is weak","then":"You put the phone down. The room feels emptier."},{"text":"Close it and go for a run, alone, instead","then":"The run clears your head, but the evening is still silent."}],"why":"Reaching out is strength. A real reply eases loneliness more than any video."},{"prompt":"Later, your cousin calls and asks how college is going. What do you say?","options":[{"text":"Crushing it, honestly. Never been better","then":"\"Nice!\" he says, and the chat moves on."},{"text":"Fine. Just grinding away, you know how it is","then":"\"Respect,\" he says. The loneliness stays unsaid."},{"text":"Bit lonely, honestly. Still finding my people","then":"\"Same when I started,\" he says. \"Let's call again this weekend.\"","best":true},{"text":"Why? Did Mummy say something?","then":"\"No, just asking,\" he says, puzzled."}],"why":"Being honest about loneliness lets people show up for you."},{"prompt":"At the weekend, a floormate invites you to five-a-side football. What do you do?","options":[{"text":"Say no. You've got grinding to do","then":"The laptop hums all evening. The quiet feels loud."},{"text":"Go, play hard, and leave without talking","then":"You score twice and walk back alone, still lonely."},{"text":"Say yes and stay for chai after","then":"After the match, someone asks your name and adds you to the group.","best":true},{"text":"Say maybe and see how you feel","then":"You end up staying in."}],"why":"Showing up and staying a bit builds the connection that eases loneliness."},{"prompt":"That night, the grind videos pop up in your feed again. What do you do?","options":[{"text":"Watch just one to get fired up","then":"One turns into ten, and the room feels colder."},{"text":"Binge until you feel tough again","then":"At 2 a.m., you feel wired and more alone."},{"text":"Mute them and text someone you like talking to","then":"A reply pings back: \"Chai tomorrow?\" The feed goes quiet.","best":true},{"text":"Decide you should be over feeling lonely by now","then":"The pressure makes the loneliness heavier."}],"why":"Choosing people over content that shames feelings eases loneliness."}],"debrief":"Reaching out is strength for all genders: connection eases loneliness.","relearn":"Reaching out is strength, not weakness. Connection eases loneliness."},
  {"id":"mb-1408","cat":"tools-and-help","type":"branch","persona":"any","source":"frozen-call-branch","hook":"You finally call Tele-MANAS 14416, but when someone answers, your mind goes blank.","steps":[{"prompt":"The counsellor says hello and waits. What do you do?","options":[{"text":"Apologise and hang up in a panic","then":"You hang up, heart pounding, then dial again ten minutes later."},{"text":"Wait silently for them to figure it out","then":"After a pause, the voice asks: \"Are you there? It's okay to take a moment.\""},{"text":"Say 'Sorry. It's nothing serious, really'","then":"\"Every call matters here,\" they say. \"What made you call?\""},{"text":"Say 'I'm not okay and I needed to talk'","then":"\"I'm glad you called,\" they say gently. \"Take your time.\"","best":true}],"why":"You don't need perfect words. 'I'm not okay' is a complete opener."},{"prompt":"They ask what's been going on lately. What do you say?","options":[{"text":"That you're wasting their time","then":"\"You're not,\" they say. \"This is exactly what we're here for.\""},{"text":"Just the one thing that feels heaviest right now","then":"They listen, ask a gentle question, and you keep going.","best":true},{"text":"That you'll call back once you've figured it out","then":"\"You don't need it figured out,\" they say. \"Start anywhere.\""},{"text":"Nothing, and ask what you're supposed to say","then":"\"There's no script,\" they say. \"What's been hardest?\""}],"why":"Starting with one thing is enough. You don't need the whole story sorted."},{"prompt":"As the call ends, they mention other support nearby. What do you do?","options":[{"text":"Say you'll be fine now and skip it","then":"You hang up lighter, but with nowhere to go next time."},{"text":"Feel embarrassed and drop the idea","then":"You hang up quickly, and the next step never happens."},{"text":"Ask them to just fix everything tonight","then":"\"We'll do what we can tonight,\" they say. \"Then let's find you more support.\""},{"text":"Note it down and plan one next step","then":"You write 'campus counsellor, Tuesday' and feel a little steadier.","best":true}],"why":"Turning one call into a next step keeps support going."}],"debrief":"\"I'm not okay and I needed to talk\" is enough.","relearn":"You don't need perfect words. \"I'm not okay\" is a complete opener."},
  {"id":"mb-1409","cat":"tools-and-help","type":"branch","persona":"Meena","source":"off-campus-branch","hook":"You work long shifts in a new city, with no campus nearby and a heavy stretch building.","steps":[{"prompt":"On your tea break, the heaviness sits in your chest again. What do you do?","options":[{"text":"Decide there's no help for people like you","then":"The break ends, and the heaviness follows you back to work."},{"text":"Push through, skip the break and work on","then":"By evening, you're drained and the weight feels heavier."},{"text":"Call Tele-MANAS 14416. It reaches anywhere","then":"A kind voice answers in your language, and for the first time in weeks you feel less stuck.","best":true},{"text":"Wait till you can afford a private doctor","then":"A doctor's fee feels out of reach, so nothing changes."}],"why":"A free national line reaches you anywhere, with or without a campus."},{"prompt":"After a double shift, you're exhausted and can't face cooking. What do you do?","options":[{"text":"Skip dinner and scroll late into the night","then":"At 2 a.m., you're hungry, wired and still low."},{"text":"Eat something simple and get to bed early","then":"Rice and curd, then sleep. The morning feels a little less grey.","best":true},{"text":"Push on with chores till midnight","then":"The room is tidy, and your body aches through the next shift."},{"text":"Eat, then stay up late to finally get some me-time","then":"The late hours feel good, then the alarm feels cruel."}],"why":"Food and sleep are basic coping that protect your mood on hard days."},{"prompt":"A co-worker, Sunita, asks why you've seemed so quiet lately. What do you say?","options":[{"text":"Nothing. I'm fine","then":"She nods and moves on. You go home alone with it."},{"text":"Just tired. Everyone's tired on these shifts, no?","then":"\"True,\" she says. The talk stays on the shifts."},{"text":"Why, is my work slipping?","then":"\"No, no,\" she says. \"You just seem low.\""},{"text":"It's been a heavy stretch. Can we talk on break?","then":"Sunita nods. \"Tomorrow, tea stall, 11 o'clock. My treat.\"","best":true}],"why":"Letting one person in turns a lonely stretch into shared weight."},{"prompt":"A month on, some days are lighter and some are still heavy. What do you lean on from here?","options":[{"text":"Nothing. You've got through the worst","then":"A bad week arrives, and you have nothing ready to reach for."},{"text":"Sunita, early nights and Tele-MANAS 14416","then":"When a heavy day hits, you already know your next three steps.","best":true},{"text":"Just work. Busy is better than thinking","then":"The weeks blur into shifts, and the heaviness comes back."},{"text":"Only the helpline. People here just won't understand","then":"The line helps, but the evenings stay lonely."}],"why":"A mix of people, rest and a saved line keeps you steady for the long run."}],"debrief":"A free national line isn't only for those with a campus: it reaches anyone.","relearn":"Free national lines reach you off-campus too, not just campus."},
  {"id":"mb-1410","cat":"tools-and-help","type":"strike-rewrite","hook":"Strike the myth, write the truth.","myth":{"un":"Helplines are only for people in a life-or-death crisis.","re":"Helplines are for everyday stress too: no problem is too small.","why":"Lines like Tele-MANAS 14416 take everyday worries, not just emergencies; reaching early is welcome."},"relearn":"Helplines are for everyday stress too: no problem is too small, and you needn't be in crisis.","persona":"any","source":"not-crisis-only"},
  {"id":"mb-1411","cat":"tools-and-help","type":"strike-rewrite","hook":"Strike the myth, write the truth.","myth":{"un":"Reaching out only counts once you've completely fallen apart.","re":"You don't have to be in crisis to deserve support: reach out early.","why":"Early help is the strong, smart move; support isn't a last resort you must earn by suffering."},"relearn":"You don't have to be in crisis to deserve support; reaching out early is the strong move.","persona":"any","source":"early-counts"},
  {"id":"mb-1412","cat":"tools-and-help","type":"strike-rewrite","hook":"Rohan: strike the myth, write the truth.","myth":{"un":"Real men handle their minds alone. Getting help is weak.","re":"Help-seeking is strength for all genders; everyone has a mind to look after.","why":"Looking after your mental health is smart, not soft: the 'tough it out alone' line just isolates."},"relearn":"Help-seeking is strength for all genders; 'real men cope alone' only isolates you.","persona":"Rohan","source":"men-and-help"},
  {"id":"mb-1413","cat":"tools-and-help","type":"strike-rewrite","hook":"Strike the myth, write the truth.","myth":{"un":"You need the perfect words and a clear story before you call.","re":"\"I'm struggling and could use someone to talk to\" is enough to start.","why":"Helplines are trained to take it from a simple opener; you don't have to explain it all first."},"relearn":"You needn't have perfect words; \"I'm struggling and need to talk\" is enough to start.","persona":"any","source":"no-perfect-words"},
  {"id":"mb-1414","cat":"tools-and-help","type":"strike-rewrite","hook":"Strike the myth, write the truth.","myth":{"un":"This game can be your therapy: just keep playing instead of seeing anyone.","re":"This builds skills and points to help; heavy or lasting distress needs a professional.","why":"It's signposting and practice, never diagnosis or treatment: a pro is the right next step when it's serious."},"relearn":"This builds skills and points to help; for heavy or lasting distress, a professional is the next step.","persona":"any","source":"not-a-substitute"},
  {"id":"mb-1415","cat":"tools-and-help","type":"strike-rewrite","hook":"Strike the myth, write the truth.","myth":{"un":"Breathing and walking are too small to do anything real for stress.","re":"Slow breathing, a short walk and reaching out are genuine, healthy coping.","why":"They calm the body and lift mood in the moment: small, evidence-backed steps that actually work."},"relearn":"Slow breathing, a walk and reaching out are real, healthy coping: small steps that genuinely work.","persona":"any","source":"small-is-real"},
  {"id":"mb-1416","cat":"tools-and-help","type":"strike-rewrite","hook":"Deepak: strike the myth, write the truth.","myth":{"un":"Support like counsellors and helplines isn't really for people like me.","re":"Free lines and campus counsellors are for everyone: cost and background are no barrier.","why":"Tele-MANAS 14416 and campus counsellors are free and open to all; help-seeking belongs to you too."},"relearn":"Free lines and campus counsellors are for everyone; cost or background is never the barrier.","persona":"Deepak","source":"help-is-for-me"},
  {"id":"mb-1417","cat":"tools-and-help","type":"strike-rewrite","hook":"Strike the myth, write the truth.","myth":{"un":"If you set up a helpline and a plan, you're admitting you'll fall apart.","re":"Having a plan ready is just smart preparation, not a sign you're failing.","why":"A saved line, a person and a coping step are like a fire drill: ready in case, not a prophecy."},"relearn":"A ready plan with a line, a person and a coping step is smart preparation, not a sign you'll fail.","persona":"any","source":"plan-not-prophecy"},
];

